insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Basic Concepts","topics":["Concept of continuum","Macroscopic approach","And thermodynamic systems","Property","State","Path and process-quasi-static process","Work","Zeroth law of thermodynamics","Concept of temperature and heat","Internal energy","Specific heat capacities","Enthalpy","Concept of ideal and real gases"]},{"title":"First Law","topics":["First law of thermodynamics and its applications to closed and open systems"]},{"title":"Second Law and Entropy","topics":["Second law of thermodynamics","Kelvin planck and clausius statements of second law","Reversibility and irreversibility","Carnot theorem Carnot cycle","Reversed Carnot cycle","Efficiency","Thermodynamic temperature scale Clausius inequality","Concept of entropy","Entropy of ideal gas","Principle of increase of entropy"]},{"title":"Air Standard Cycles","topics":["Otto","Diesel","Dual","Ericsson","Atkinson","Stirling and Brayton cycles","Air Standard efficiency","Mean effective pressure"]},{"title":"Fundamentals of Vapour Power Cycles","topics":["Properties of pure substances - solid","Liquid and vapour phases","Phase rule","P-v","P-T","T-v","T-s","H-s diagrams","P-v-T surfaces","Thermodynamic properties of steam","Calculations of work done and heat transfer in non-flow and flow processes","Standard Rankine cycle","Reheat and Regeneration cycle","Heat rate","Specific steam consumption","Tonne of refrigeration"]},{"title":"Basics of Propulsion and Heat Transfer","topics":["Classification of jet engines","Basic jet propulsion arrangement","Engine station number","Thrust equation","Specific thrust","SFC","TSFC","Specific impulse","Actual cycles","Isentropic efficiencies of jet engine components","Polytropic efficiency","Conduction in parallel","Radial and composite wall","Basics of convective and radiation heat transfer","Thermodynamics: An Engineering Approach, Cengel, Y. A. and Boles, M. A, McGraw Hill Education,