insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction to Value Education Right Understanding Relationship and Physical Facility (Holistic Development and the Role of Education) Understanding Value Education Sharing about Oneself Self-exploration as the Process for Value Education Continuous Happiness and Prosperity the Basic Human Aspirations Exploring Human Consciousness Happiness and Prosperity - Current Scenario Method to Fulfill the Basic Human Aspirations","Right Understanding","Relationship and Physical Facility (Holistic Development and the Role of Education)","Understanding Value Education Sharing about Oneself","Self-exploration as the Process for Value Education","Continuous Happiness and Prosperity the Basic Human Aspirations","Exploring Human Consciousness","Happiness and Prosperity - Current Scenario","Method to Fulfill the Basic Human Aspirations"]},{"title":"Harmony in the Human Being","topics":["Understanding Human being as the Co-existence of the Self and the Body","Distinguishing between the Needs of the Self and the Body","The Body as an Instrument of the Self","Understanding Harmony in the Self","Harmony of the Self with the Body","Programme to ensure self-regulation and Health"]},{"title":"Harmony in the Family and Society","topics":["Harmony in the Family the Basic Unit of Human Interaction","''Trust'' the Foundational Value in Relationship","''Respect'' as the Right Evaluation","Other Feelings","Justice in Human-to-Human Relationship","Understanding Harmony in the Society","Vision for the Universal Human Order"]},{"title":"Harmony in the Nature/Existence","topics":["Understanding Harmony in the Nature","Interconnectedness","Self-regulation and Mutual Fulfilment among the Four Orders of Nature","Realizing Existence as Co-existence at All Levels","The Holistic Perception of Harmony in Existence","Unit 5.0: Implications of the Holistic Understanding - a Look at Professiona