insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction Of Robot Introduction To Robotics And Automation Laws Of Robot Brief History Of Robotics Basic Components Of Robot Robot Specifications Classification Of Robots Human System And Robotics Industrial Robots Robot Anatomy - Four Common Configurations Of Robot Robot Motions - Linear, Rotational, Revolving, Twisting, Cylindrical, Spherical Degrees Of Freedom Of Robot Introduction To Degrees Of Freedom Three Degrees Of Freedom Associated With Arm And Body Polar Robot Three Degrees Of Freedom Associated With Robot Wrist Joint Notation Scheme Work Volume Links And Joints Spatial Resolution Accuracy Repeatability Compliance","Introduction To Robotics And Automation","Laws Of Robot","Brief History Of Robotics","Basic Components Of Robot","Robot Specifications","Classification Of Robots","Human System And Robotics","Industrial Robots","Robot Anatomy - Four Common Configurations Of Robot","Robot Motions - Linear, Rotational, Revolving, Twisting, Cylindrical, Spherical","Degrees Of Freedom Of Robot","Introduction To Degrees Of Freedom","Three Degrees Of Freedom Associated With Arm And Body Polar Robot","Three Degrees Of Freedom Associated With Robot Wrist","Joint Notation Scheme","Work Volume","Links And Joints","Spatial Resolution","Accuracy","Repeatability","Compliance"]},{"title":"Mechanical Components And Robot Drive Systems","topics":["Drive Systems For Robots, Salient Features And Comparison","Different Types Of End Effectors, Design, Applications","Grippers","Welding And Soldering Tools","Cutting And Milling Tools","Gearing Systems And Transmissions","Bearings And Linkages In Robot Design"]},{"title":"Sensors","topics":["Sensor Evaluation And Selection","Piezoelectric Sensors","Linear Position And Displacement Sensing","Revolvers","Encoders","Velocity Measurement","Proximity, Tactile, Compliance And Range Sensing","Image Processing And Object Re