insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Sensor Classifications and Characteristics","topics":["Sensor classifications and characteristics","Overview and their working","Touch and proximity sensors: IR, Photodiodes, Tactile sensors, Collision sensors, Interaction sensors, Proximity/distance sensors"]},{"title":"Position and Velocity Measurement","topics":["Optical encoder","Potentiometer","2D and 3D cameras velocity measurement","Inertia sensors: Gyroscopes, Accelerometer"]},{"title":"Force and Torque Measurement","topics":["Force sensors: definition, types, application, advantage and disadvantage","Torque sensors: definition, types, application, advantage and disadvantage","Range sensors: IR, Ultrasonic sensors, laser ranger finder: definition, types, application, advantage and disadvantage"]},{"title":"Robotic Actuators","topics":["Hydraulic actuators: operating principle, advantage and disadvantage","Pneumatic actuators: operating principle, advantage and disadvantage","Electrical actuators: operating principle, advantage and disadvantage"]},{"title":"Introduction to Motors","topics":["DC motors: Component, types, application, advantage and disadvantage","AC motors: Component, types, application, advantage and disadvantage","Stepping motors: Component, types, application, advantage and disadvantage","Servo motors: Component, types, application, advantage and disadvantage"]},{"title":"Motion Transmission","topics":["Gear transmission: Component, application, advantage and disadvantage","Belt transmission: Component, application, advantage and disadvantage","Hydraulic drive: Component, application, advantage and disadvantage","Sensors, Actuators and Their Interfaces: A multidisciplinary introduction, Nathan Ida, 2nd Edition, 2020.","Industrial Robotics: Technology Programming and Applications, Mikell P Groover, 2nd Edition, Tata McGraw Hill Education Private Limited, 2012.","Introduction to Robotics, Analysis and Control, John J Craig, 2nd Edition-Wesley 1999.","Fundamentals of Robotics, Analysis and control, Robert J Schilling, Prentice Hall of India."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Analog Modulation","topics":["Frequency domain representation of signals","Principles of amplitude modulation systems - DSB, SSB and VSB modulations","Angle Modulation - Representation of FM and PM signals","Generation and detection of modulation AM and FM","Super heterodyne receiver"]},{"title":"Digital Modulation","topics":["Fundamentals of digital communication system","Analog vs. digital communication","Basic digital communication nomenclature","Generation and detection of modulation schemes - phase shift keying, frequency shift keying, minimum shift keying, Quadrature amplitude modulation","Power spectra, bandwidth efficiency, BER"]},{"title":"Probability & Random Processes","topics":["Review of probability and random process","Gaussian and white noise characteristics","Noise in amplitude modulation systems","Noise in frequency modulation systems","Pre-emphasis and de-emphasis","Threshold effect in angle modulation","Matched Filter"]},{"title":"Pulse Modulation - I","topics":["Sampling process","Baseband pulse transmission - inter symbol interference and nyquist criterion","Generation and detection of pulse amplitude pulse position and pulse code modulation (PCM)"]},{"title":"Pulse Modulation - II","topics":["Differential pulse code modulation","Delta modulation","Noise considerations in PCM","Digital Multiplexers"]},{"title":"Information Coding and Decoding","topics":["Coding for error detection and correction","Block coding - coding and decoding","Hamming code","Cyclic codes","Convolution coding and decoding","Viterbi algorithm","Shannon Fano and Hoffman Codes","Communication Systems, Simon Haykins & Moher, John Willey India Pvt. Ltd, 5th Edition, 2010, ISBN 9788126521517","Modern Analog and Digital Communication System, B P Lathi, Zhi Ding, Oxford University Press, 4th edition. ISBN-13 : 978-0198073802","Electronics Communication Systems, Kennedy George, Davis Bernard, Prasanna SRM, Mc-Graw Hill 5th edition, New dehli, 2011, ISBN: 9780071077828","Principle of Electronics Communication, Frezel Louis E., Mc-Graw Hill 5th edition, New dehli, 2007, ISBN: 9780073222783","An Introduction to Analog and Digital Communication, Simon Haykins, John Wiley India Pvt. Ltd., 4th edition, 2008, ISBN: 9788126536535","Communication Systems: Analog and Digital, R.P.Singh and S.Sapre, TMH 2nd edition, 2007. ISBN-978-1259004605"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Ecosystem and Biodiversity Ecosystem - definition, types - aquatic and terrestrial ecosystem Structure of a basic ecosystem Food chain and food web Cycles in ecosystem - water, carbon, nitrogen, sulphur and phosphorus Biodiversity - definition, types - genetic, species and ecosystem biodiversity Threats - Habitat loss, poaching of wild life, man-wild life conflicts - endangered and endemic species of India Conservation of biodiversity","Ecosystem - definition, types - aquatic and terrestrial ecosystem","Structure of a basic ecosystem","Food chain and food web","Cycles in ecosystem - water, carbon, nitrogen, sulphur and phosphorus","Biodiversity - definition, types - genetic, species and ecosystem biodiversity","Threats - Habitat loss, poaching of wild life, man-wild life conflicts - endangered and endemic species of India","Conservation of biodiversity","Unit 2.0: Sustainable Energy Sources Sustainable/ Renewable energy sources - solar energy, wind energy, small hydro energy, bio energy, geothermal, and new energy sources - hydrogen energy, ocean energy and tidal energy Definition of energy audit, energy conservation, energy efficiency and energy management (definition only with one/two examples) Solar Energy - (i) Solar thermal energy conversion principle and applications - solar water heater, solar dryers, solar stills distillation, solar cooker, solar ponds (ii) PV system energy conversion principle, solar cell technologies, thin film generations, solar cell, module, array, series parallel combinations and operations, applications - standalone, SPV water pump Wind Energy, wind plant and its parts, types - horizontal and vertical axis, principle of harnessing wind energy, advantages and challenges of harnessing wind energy Small hydro energy - Principle, types - Mini, Micro and Pico, advantages and disadvantages Biomass - biomass energy sources and their energy content, biological conversion technologies - thermo-chemical conversion, bio-chemical conversion and oil extraction, biogas production, types of biogas plant - floating (gobar gas) and fixed type New Energy Sources: hydrogen energy, geothermal, ocean - tidal and wave energy","Sustainable/ Renewable energy sources - solar energy, wind energy, small hydro energy, bio energy, geothermal, and new energy sources - hydrogen energy, ocean energy and tidal energy","Definition of energy audit, energy conservation, energy efficiency and energy management (definition only with one/two examples)","Solar Energy - (i) Solar thermal energy conversion principle and applications - solar water heater, solar dryers, solar stills distillation, solar cooker, solar ponds","(ii) PV system energy conversion principle, solar cell technologies, thin film generations, solar cell, module, array, series parallel combinations and operations, applications - standalone, SPV water pump","Wind Energy, wind plant and its parts, types - horizontal and vertical axis, principle of harnessing wind energy, advantages and challenges of harnessing wind energy","Small hydro energy - Principle, types - Mini, Micro and Pico, advantages and disadvantages","Biomass - biomass energy sources and their energy content, biological conversion technologies - thermo-chemical conversion, bio-chemical conversion and oil extraction, biogas production, types of biogas plant - floating (gobar gas) and fixed type","New Energy Sources: hydrogen energy, geothermal, ocean - tidal and wave energy","Unit 3.0: Environmental Pollution Environmental pollution - air, water, noise and soil Air pollution - sources of air pollution - chemical, photochemical, green house effect, ozone layer depletion and acid rain Air pollutants classification - primary and secondary pollutants Adverse effects of air pollution on human, plant and animal Air monitoring system and air pollution control Water pollution - sources of water pollution Adverse effects of water pollution Control of water pollution Physical and chemical standard of domestic water as per Indian standard Sound Pollution - causes, controlling measures, measurement of sound pollution (deciblage), industrial and non - industrial Soil Pollution - soil profile, pollutants in soil, their adverse effects, controlling measures","Environmental pollution - air, water, noise and soil","Air pollution - sources of air pollution - chemical, photochemical, green house effect, ozone layer depletion and acid rain","Air pollutants classification - primary and secondary pollutants","Adverse effects of air pollution on human, plant and animal","Air monitoring system and air pollution control","Water pollution - sources of water pollution","Adverse effects of water pollution","Control of water pollution","Physical and chemical standard of domestic water as per Indian standard","Sound Pollution - causes, controlling measures, measurement of sound pollution (deciblage), industrial and non - industrial","Soil Pollution - soil profile, pollutants in soil, their adverse effects, controlling measures"]},{"title":"Climate Change and Sustainable Development","topics":["Topics not specified in document","Ecology and Control of the Natural Environment, Izrael, Y.A., Kluwer Academic Publisher, eBook ISBN: 978-94-011-3390-6","Renewable Energy Sources and Emerging Technologies, Kothari, D.P. Singal, K.C., Ranjan, Rakesh, PHI Learning, New Delhi, 2009, ISBN-13 - 978-8120344709","Green Technologies and Environmental Sustainability, Singh, Ritu, Kumar, Sanjeev, Springer International Publishing, 2017 eBook ISBN 978-3-319-50654-8","Coping with Natural Hazards: Indian Context, K. S. Valadia Orient Longman, ISBN-10:8125027351, ISBN-13: 978-8125027355","Introduction to Engineering and Environment, Edward S. Rubin McGraw Hill Publications ISBN-10: 0071181857, ISBN-13: 978-0071181853","Environmental Science, Subrat Roy, Khanna Book Publishing Co. (P) Ltd., ISBN-978: 93-91505-65-3"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Indian Knowledge Systems","topics":["Overview of IKS","Organization of IKS","Conception and constitution of knowledge in indian tradition","The oral tradition","Models and Strategies of IKS","Unit 2.0: Overview of IKS Domains and Relevance The Vedas as the basis of IKS Overview of all the six vedangas Relevance of following IKS domains in present technical education system: Arthashastra (Indian economics and political systems) Ganita and Jyamiti (Indian mathematics, astronomy and geometry) Rasayana (Indian chemical Sciences) Ayurveda (Indian Biological Sciences / Diet & Nutrition) Jyotish Vidya (observational astronomy and calendar systems) Prakriti Vidya (Indian system of terrestrial/ material sciences/ecology and atmospheric sciences) Vastu Vidya (Indian system of aesthetics - iconography and built-environment /architecture) Nyaya Shastra (Indian systems of social ethics, logic and law) Shilpa and Natya Shastra (Indian classical arts: performing and fine arts) Sankhya and Yoga Darshna (Indian psychology, yoga and consciousness studies) Vrikshayurveda (plant science/sustainable agriculture/food preservation methods)","The Vedas as the basis of IKS","Overview of all the six vedangas","Relevance of following IKS domains in present technical education system:","Arthashastra (Indian economics and political systems)","Ganita and Jyamiti (Indian mathematics, astronomy and geometry)","Rasayana (Indian chemical Sciences)","Ayurveda (Indian Biological Sciences / Diet & Nutrition)","Jyotish Vidya (observational astronomy and calendar systems)","Prakriti Vidya (Indian system of terrestrial/ material sciences/ecology and atmospheric sciences)","Vastu Vidya (Indian system of aesthetics - iconography and built-environment /architecture)","Nyaya Shastra (Indian systems of social ethics, logic and law)","Shilpa and Natya Shastra (Indian classical arts: performing and fine arts)","Sankhya and Yoga Darshna (Indian psychology, yoga and consciousness studies)","Vrikshayurveda (plant science/sustainable agriculture/food preservation methods)","Introduction to Indian Knowledge System: Concepts and Applications, Archak, K.B. (2012), Kaveri Books, New Delhi, ISBN-13:978-9391818203","Introduction To Indian Knowledge System: Concepts and Applications, Mahadevan, B. Bhat, Vinayak Rajat, Nagendra Pavana R.N., PHI, ISBN: 9789391818203","Glimpse into Kautilya''s Arthashastra Ramachandrudu P. (2010), Sanskrit Academy, Hyderabad, ISBN:9788380171074","\"Introduction\" in Studies in Epics and Puranas, (Eds.), KM Munshi and N Chandrashekara Aiyer Bhartiya Vidya Bhavan"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Calibration and verification of various biomedical transducers and sensors","Experimentation with signal conditioning circuits","Calibration of biomedical sensors","Data acquisition systems and software","Acquisition and processing of bioelectric signals (ECG, EEG, EMG) using lab-grade equipment","Design and implementation of filtering and amplification circuits","Electrode-skin interface and electrode placement techniques","Signal processing using MATLAB or similar software","Demonstration of X-ray imaging and CT scan procedures","MRI imaging principles and safety precautions","Ultrasound imaging techniques and image interpretation","Simulations to nuclear medicine imaging experiments","Dissection and demonstration of therapeutic devices","Simulation of drug delivery systems and infusion pumps","Experimentation with neurostimulation devices","Wearable health monitoring devices","Wearable Biosensors","Demonstration of point-of-care diagnostic devices","Experimentation with nanotechnology-based biomedical instruments","Regulatory standards and ethical issues in biomedical instrumentation"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Coordinate frames and transformations in robotics using roboanalyzer/MATLAB/others","Performing position analysis, velocity analysis, acceleration analysis and dynamic force analysis using MATLAB/others","Evaluation of Joint angles of robot by inverse kinematics using C/MATLAB/others","Determination of mass moment of inertia and radius of gyration of robotic links","Forward kinematics of robots using roboanalyzer/MATLAB/others","Inverse kinematics of robots using roboanalyzer/MATLAB/others","Forward and inverse dynamics of robots using roboanalyzer/MATLAB/others","Virtual Models of Industrial Robots using roboanalyzer/MATLAB/others","Graphical modeling of scara, cartesian, cylindrical, polar robot (robo analyzer)","Graphical modeling of multi-robot cell (abb studio/robo analyzer)","Robot programming and simulation for any industrial process (Packaging, Assembly)","Robot programming and simulation for machining (cutting, welding)"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To evaluate the performance and effectiveness of an IR proximity sensor","To understand and calibrate the sensitivity of Use a capacitive touch sensor","Learn how to control the position of a servomotor","Understand the basic operation of a stepping motor","To investigate how different gear ratios affect the speed and torque of a gear transmission system","To evaluate the performance of hydraulic actuators under various operating conditions","To analyze the performance of pneumatic cylinders under various conditions","To calibrate a force sensor and determine its accuracy","To evaluate how temperature variations affect the performance of a force sensor","To calibrate a torque sensor and determine its accuracy","To study the performance of servomotor control for open & closed loop system","To study the PLC control process of bottle filling Module"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Establish simple and half duplex communication link","Establish simple and full duplex communication link","Generation of AM Modulated Wave for different Carrier Frequencies","Measurement of Modulation Index of generated the AM Wave","Use AM Demodulator circuit to detect the received signal. Calculate the S/N ratio","Use IC 566 to generate FM modulation and measure its Modulation Index","Use any software to generate AM and FM waves","Perform the generation and detection of ASK, FSK, BPSK, DBPSK signals with variable length data pattern","Verify the Sampling Theorem for different frequencies","Verify the Modulation and demodulation of PAM, PWM & PPM","Perform the generation the various data formatting schemes (Unipolar, Bipolar, Manchester, AMI etc.)","Calculate the S/N ratio and design Matched Filter for PCM System"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Frame of Reference and Oscillations","topics":["Non-Inertial frame of reference","Rotating coordinate system","Centripetal and Coriolis acceleration and its application in weather system","Harmonic Oscillator","Damped Harmonic motion - overdamped, critically damped and lightly damped oscillators","Force Oscillators and Resonance","Unit 2.0: Optics and LASER Huygens''s Principle Superposition of Waves and interference of Light by wave front-splitting and amplitude-splitting Young''s double slit experiment Michelson interferometer Fraunhofer diffraction from single slit and circular aperture Diffraction Grating and their resolving power Einstein''s theory of matter-radiations interaction Einstein''s Coefficients (A and B) Amplification by population inversion Gas Laser Helium-Neon Laser Solid State Laser (Ruby, Neodymium) Semiconductor Laser","Huygens''s Principle","Superposition of Waves and interference of Light by wave front-splitting and amplitude-splitting","Young''s double slit experiment","Michelson interferometer","Fraunhofer diffraction from single slit and circular aperture","Diffraction Grating and their resolving power","Einstein''s theory of matter-radiations interaction","Einstein''s Coefficients (A and B)","Amplification by population inversion","Gas Laser","Helium-Neon Laser","Solid State Laser (Ruby, Neodymium)","Semiconductor Laser","Unit 3.0: Quantum Mechanics and Applications Compton Effect Photoelectric Effect Wave Particle duality De Broglie''s hypothesis Heisenberg''s Uncertainty Principle Wave function and wave packets Phase and group velocities Schrodinger''s Wave Equation Normalization Expectation values Eigenvalues and Eigenfunction Application of Schrodinger Wave Equation for particle in one dimensional box - its wavefunction and eigenvalue of energy and momentum","Compton Effect","Photoelectric Effect","Wave Particle duality","De Broglie''s hypothesis","Heisenberg''s Uncertainty Principle","Wave function and wave packets","Phase and group velocities","Schrodinger''s Wave Equation","Normalization","Expectation values","Eigenvalues and Eigenfunction","Application of Schrodinger Wave Equation for particle in one dimensional box - its wavefunction and eigenvalue of energy and momentum","Unit 4.0: Vector Calculus and Electrostatics Gradient, Divergence and Curl Line, Surface and Volume integrals Gauss''s Divergence theorem and Stokes'' theorem in Cartesian Coordinate Gauss''s Law and its applications Divergence and Curl of Electrostatic fields Electrostatic Potential Boundary Conditions Poisson''s and Laplace''s equations Dielectrics Polarization Bound Charges Electric displacement Boundary Conditions in dielectrics","Gradient, Divergence and Curl","Line, Surface and Volume integrals","Gauss''s Divergence theorem and Stokes'' theorem in Cartesian Coordinate","Gauss''s Law and its applications","Divergence and Curl of Electrostatic fields","Electrostatic Potential","Boundary Conditions","Poisson''s and Laplace''s equations","Dielectrics","Polarization","Bound Charges","Electric displacement","Boundary Conditions in dielectrics","Unit 5.0: Magnetostatics and Electrodynamics Lorentz force Biot-Savart and Ampere''s circuital laws and their applications Divergence and Curl of Magneto static fields Magnetic vector potential Force and torque on a magnetic dipole Magnetic Materials Magnetization Bound currents Boundary conditions Ohm''s law Motional EMF Faraday''s Law Lenz''s law Self and mutual inductance Energy stored in magnetic field Maxwell''s equations in vacuum and nonconducting medium Continuity Equation Poynting Theorem Wave Equations: plain electromagnetic wave in vacuum and their transverse nature and Polarization","Lorentz force","Biot-Savart and Ampere''s circuital laws and their applications","Divergence and Curl of Magneto static fields","Magnetic vector potential","Force and torque on a magnetic dipole","Magnetic Materials","Magnetization","Bound currents","Boundary conditions","Ohm''s law","Motional EMF","Faraday''s Law","Lenz''s law","Self and mutual inductance","Energy stored in magnetic field","Maxwell''s equations in vacuum and nonconducting medium","Continuity Equation","Poynting Theorem","Wave Equations: plain electromagnetic wave in vacuum and their transverse nature and Polarization"]},{"title":"Introduction to Solids and Semi-Conductors","topics":["Free electron theory of metal","Fermi level","Bloch''s theorem for particle in a periodic Potential","Kroning-Penney model and origin of energy band","Electronic Materials","Quantum Physics of Atoms, Molecules, Solids, Nuclei and Particles, R. Eisberg R. Resnick, Wiley India Pvt. Ltd ISBN 978-81-265-0818-1","Theory of Vibration with Application, W.T. Thomson M. D. Dahleh, Pearson India ISBN 978-81-317-0482-0","Introduction to Electrodynamics, D.J. Griffiths, Pearson India, ISBN 978-93-325-5044-5","Electromagnetism, I.S. Grant, W. R. Phillips, Wiley India Pvt. Ltd ISBN 978-04-719-2712-9","The Feynman Lectures on Physics, R.P. Feynman R. B. Leighton, Pearson India ISBN 978-00-710-7458-2","Optics, Ajay Ghatak, McGraw Hill ISBN 978-93-901-1359-0","Physics of Vibration and Waves, H. J. Pain, Wiley India Pvt. Ltd, ISBN 978-04-700-1296-3","Concept of Modern Physics, Arthur Beiser, McGraw Hill ISBN 978-93-513-4185-7","Introduction to Solid State Physics, C. Kittle, Wiley India Pvt. Ltd, ISBN 978-81-265-7843-6"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Complex Analysis - I","topics":["Functions of complex variable","Limit","Continuity","Differentiability","Analytic function","Cauchy-Riemann Equations in Cartesian and polar form","Harmonic function and harmonic conjugate"]},{"title":"Complex Analysis - II","topics":["Line Integral","Contour integrals","Cauchy theorem","Cauchy''s Integral formula(without proof)","Taylors series","Zero of analytic functions","Singularities","Laurent''s series","Residue","Cauchy residue theorem(without Proof) and its applications"]},{"title":"Ordinary Differential Equations","topics":["Linear differential equations of nth Order with constant coefficients","Solution of Homogeneous and Non-Homogeneous Equations","Equations with variable coefficients","Cauchy-Euler Equations","Method of Variation of Parameters"]},{"title":"Sequence and Series","topics":["Introduction of Sequence and Series","Nature of series Tests of convergence of Series: Comparison test","D''Alembert ratio test","Cauchy''s Root test","Raabe''s test","Logarithmic test","Cauchy''s condensation test"]},{"title":"Laplace Transform Laplace Transform Existence theorem Properties of Laplace Transform","topics":["Laplace Transform","Existence theorem","Properties of Laplace Transform","Laplace Transform of Periodic functions","Inverse Laplace Transform","Convolution theorem","Application of Laplace Transform to solve Ordinary differential equations"]},{"title":"Fourier Series Fourier Series Fourier Series for odd and even","topics":["Fourier Series","Fourier Series for odd and even functions","Half range sine and cosine series","Parseval''s theorem","Advanced Engineering Mathematics, Kreyszig Erwin, John Wiley and Sons,10th Edition,2020 ISBN:978- 0470- 45836- 5","Advanced Engineering Mathematics, Dass H.K., S Chand and Company pvt.Ltd.,22nd Edition,2018 ISBN:978- 93- 5283- 718- 2","Higher Engineering Mathematics, Grewal B.S., Khanna Publishers,44th Edition,2023 ISBN:9788174091154","Complex Variables (Theory and Applications), Kasana H.S., PHI,2nd Edition.2015 ISBN:978- 81- 203- 2641- 5","A Text Book of Engineering Mathematics, Bali N.P., Goyal Manish Laxmi Publications,9th Edition,2014","Higher Engineering Mathematics, Ramana B.V., Tata McGraw Hill New Delhi, 11th Reprint, 2010, ISBN- 10 007063419X ISBN- 13 978- 0070634190","Differential Equations, Ross S.L., Wiley Publications,3rd edition,2016 ISBN:978- 81- 265- 1537- 0","Advanced Differential Equations, Raisinghania M.D., S.Chand and Company PVT.LTD.,18th Edition,2015 ISBN:978- 81- 219- 0893- 1","Schaum''s Outlines Complex Variables, Spiegel Murray R, Lipschutz Seymour, Schiller J John and Spellman Dennis, MC Graw Hill Education Private Ltd.2nd Edition,2010 ISBN:978- 0- 07- 008538- 1"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction to Programming Introduction to components of a computer system (disks, memory, processor, where a program is stored and executed, operating system, compilers etc.) Idea of Algorithm: steps to solve logical and numerical problems Representation of Algorithm: Flowchart/ Pseudo code with examples From algorithms to programs; source code, variables (with data types) variables and memory locations Syntax and Logical Errors in compilation, object and executable code","Introduction to components of a computer system (disks, memory, processor, where a program is stored and executed, operating system, compilers etc.)","Idea of Algorithm: steps to solve logical and numerical problems","Representation of Algorithm: Flowchart/ Pseudo code with examples","From algorithms to programs; source code, variables (with data types) variables and memory locations","Syntax and Logical Errors in compilation, object and executable code"]},{"title":"Operators, Conditional Branching and Loops","topics":["Arithmetic expressions/arithmetic operators","Relational operators","Logical operators","Bitwise operators and precedence","Writing and evaluation of conditionals and consequent branching","Iteration and loops"]},{"title":"Arrays and String","topics":["Array declaration & initialization","Bound checking arrays (1-d, 2-d)","Character arrays and strings","Unit 4.0: Function, Recursion and Pointers Functions (including using built in libraries) Parameter passing in functions, call by value Passing arrays to functions Recursion, as a different way of solving problems. Example programs, such as Finding Factorial, Fibonacci series, Ackerman function etc. Idea of pointers Defining pointers Use of Pointers in self-referential structures Idea of call by reference","Functions (including using built in libraries)","Parameter passing in functions, call by value","Passing arrays to functions","Recursion, as a different way of solving problems. Example programs, such as Finding Factorial, Fibonacci series, Ackerman function etc.","Idea of pointers","Defining pointers","Use of Pointers in self-referential structures","Idea of call by reference","Unit 5.0: User defined Data Types and File handling Structure- defining, declaring, initializing; accessing structure members Processing of structure Array of structures Structures within structure Structure and function Type definition Union- definition, declaration, accessing union members, initializing union Introduction to file handling File declaration, opening and closing a file Working with text and binary files I/O operations on file Error handling Random access to files","Structure- defining, declaring, initializing; accessing structure members","Processing of structure","Array of structures","Structures within structure","Structure and function","Type definition","Union- definition, declaration, accessing union members, initializing union","Introduction to file handling","File declaration, opening and closing a file","Working with text and binary files","I/O operations on file","Error handling","Random access to files"]},{"title":"Basic Algorithms","topics":["Searching","Basic Sorting Algorithms (Bubble, Insertion and Selection)","Finding roots of equations","Notion of order of complexity through example programs (no formal definition required)","Programming in ANSI C 4th Ed, E Balagurusamy, McGraw Hill Education India Private Limited, ISBN- 978- 9339219666, 7th Edition","The C Programming Language 2e, W. Kernighan / Dennis Ritchie, Pearson Education India, 978- 9332549449, 2nd Edition","Computer Fundamentals and Programming in C, Reema Thareja, Oxford University Press, ISBN- 978- 9354977893, 3rd Edition"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Sheet Metal Working","topics":["Sheet metal: GI sheets, aluminium, tin plate, copper, brass etc","Tools: steel rule, vernier callipers, micrometer, sheet metal gauge, scriber, divider, punches, chisels, hammers, snips, pliers, stakes etc.","Operations: scribing, bending, shearing, punching etc","Product development: hexagonal box with cap, funnel etc."]},{"title":"Joining","topics":["Classifications of joining processes","Brazing","Soldering","Mechanical Joints","Arc welding","Gas welding etc.","Unit 3.0: Pattern Making and Foundry Practice Pattern material: wood, cast iron, brass, aluminium, waxes etc. Types of patterns: split, single piece, match plate etc Tools: cope, drag, core, core prints, shovel, riddle, rammer, trowel, slick, lifter, sprue pin, bellow, mallet, vent rod, furnace etc. Moulding sands: green sand, dry sand, loam sand, facing sand etc. Sand casting: Sand preparation, mould making, melting, pouring, and cleaning","Pattern material: wood, cast iron, brass, aluminium, waxes etc.","Types of patterns: split, single piece, match plate etc","Tools: cope, drag, core, core prints, shovel, riddle, rammer, trowel, slick, lifter, sprue pin, bellow, mallet, vent rod, furnace etc.","Moulding sands: green sand, dry sand, loam sand, facing sand etc.","Sand casting: Sand preparation, mould making, melting, pouring, and cleaning"]},{"title":"Fitting Shop","topics":["Introduction to Fitting","Fitting Tools: Files and their classification, Holding Tools, Cutting Tools, Measuring and Marking Tools, Thread Making Tools, Various Fitting Power Tools","Methods Of Filing: Cross Filling and Draw Filing","Other associated operations Marking","Sawing and Chipping","Safety and Precautions in Fitting Shop","Unit 5.0: Carpentry Shop Introduction to Carpentry Shop Types of Wood Seasoning of Wood: Types of Seasoning Methods Defects in wood Structure of Wood Carpentry Tools: Measuring Tools, Marking Tools, Cutting Tools, Planning Tools, Drilling and Boring Tools, Holding Tools, Striking Tools, Auxiliary tools and materials used in Carpentry Wood working Processes Carpentry joints Wood Working Machines: Wood Working Lathe, Circular Saw, Thickness Planer, Band saw Safety and precautions in Carpentry Shop","Introduction to Carpentry Shop","Types of Wood","Seasoning of Wood: Types of Seasoning Methods","Defects in wood","Structure of Wood","Carpentry Tools: Measuring Tools, Marking Tools, Cutting Tools, Planning Tools, Drilling and Boring Tools, Holding Tools, Striking Tools, Auxiliary tools and materials used in Carpentry","Wood working Processes","Carpentry joints","Wood Working Machines: Wood Working Lathe, Circular Saw, Thickness Planer, Band saw","Safety and precautions in Carpentry Shop"]},{"title":"Smithy Shop","topics":["Introduction to Smithy Shop","Forging Tools and Equipment","Forging Operations: Drawing, Upsetting, Swaging, Punching, Drifting, Fuller, Bending","Hot Working Processes: Rolling, Drop Forging, Press Forging, Hot Extrusion, Hot Drawing","Cold Working Process","Safety and Precautions in Smithy Shop","Hajra Choudhury S.K., Hajra Choudhury A.K. And Nirjhar Roy S.K., \"Elements Of Workshop Technology\", Vol. I 2008 And Vol. Ii 2010, Media Promoters And Publishers Private Limited, Mumbai.","Kalpakjian S. And Steven S. Schmid, \"Manufacturing Engineering And Technology\", 4th Edition, Pearson Education India Edition, 2002.","Gowri P. Hariharan And A. Suresh Babu,\"Manufacturing Technology - I\" Pearson Education, 2008.","Roy A. Lindberg, \"Processes And Materials Of Manufacture\", 4th Edition, Prentice Hall India, 1998.","Rao P.N., \"Manufacturing Technology\", Vol. I And Vol. Ii, Tata Mcgrawhill House, 2017."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Overview of Chemical Engineering","topics":["Definition, history, scope and features of Chemical Engineering","Role of chemical engineers","Major inventions","Greatest achievements and famous personalities of chemical engineering"]},{"title":"Components of Chemical Engineering","topics":["Role of Chemical Engineers in Food, Medical, Energy, Environmental, Biochemical, Electronics etc","Role of Physical, Mathematics & Biological Sciences","Thermodynamics","Transport Phenomenon","Chemical Kinetics","Process Dynamics","Design and control"]},{"title":"Chemical Process Industries","topics":["Role of Computer in Chemical Engineering","Chemical Engineering Software","Relation between Chemical Engineering and other engineering disciplines","Evolution of chemical industries","Technological developments in major challenges","Chemical industries structure and segments of chemical industry","Raw material and production pattern"]},{"title":"Unit Operation","topics":["Introduction","Mechanical Separations","Fluid flow operations","Heat transfer operations","Mass transfer operations","Simultaneous heat & mass transfer operations"]},{"title":"Unit Processes in Chemical Industry","topics":["Introduction","Nitration process","Halogenations process","Alkylation''s process","Sulfonation process","Amination process","Polymerization process","Oxidation process","Hydrogenation process","Unit 6.0: Industrial Safety General aspects of industrial safety Industrial accident Direct & indirect losses due to accidents Mechanical, electrical, and chemical accidents & preventions Anatomy of fire Various steps for controlling fire hazards Various fire extinguishers used for firefighting Storage handling & transportation of dangerous materials Personal protective devices used for safety Significance of color coding Industrial safety act 1948 Material safety and data sheet","General aspects of industrial safety","Industrial accident","Direct & indirect losses due to accidents","Mechanical, electrical, and chemical accidents & preventions","Anatomy of fire","Various steps for controlling fire hazards","Various fire extinguishers used for firefighting","Storage handling & transportation of dangerous materials","Personal protective devices used for safety","Significance of color coding","Industrial safety act 1948","Material safety and data sheet","Introduction to Chemical Engineering, Anderson, L.B., Wenzel, L.A. McGraw-Hill Book Company, Inc., New York (1961).","Introduction to Chemical Engineering, Pushpavanam, S., PHI Learning Pvt. Ltd.(2012).","Introduction to Chemical Engineering, Ghosal, S.K., Sanyal, S.K., Datta, S. Tata McGraw-Hill Publishing Company Ltd., New Delhi(1997)."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Understanding the importance of cleanliness and sanitation: The course could aim to create awareness about the significance of cleanliness and sanitation in maintaining personal health, environmental sustainability, and community well-being. It could cover topics such as waste management, sanitation practices, and the impact of poor sanitation on public health.","Developing skills for effective waste management: The course could provide training on various waste management techniques, such as waste segregation, composting, recycling, and proper disposal of hazardous waste. It could also emphasize the importance of reducing waste generation and promoting sustainable waste management practices.","Promoting behavioural change towards cleanliness: The course could focus on influencing positive behavioural change among individuals and communities towards cleanliness. It could include modules on promoting good hygiene practices, creating awareness about the harmful effects of littering and open defecation, and encouraging responsible waste disposal habits.","Creating awareness about Swachh Bharat Mission initiatives: The course could provide information about the Swachh Bharat Mission initiatives and campaigns launched by the Government of India to promote cleanliness and sanitation, such as Swachh Survekshan, Swachh Bharat Abhiyan, and Clean India Campaign. It could also discuss the progress made, challenges faced, and future prospects of the Swachh Bharat Mission.","Engaging in community participation and advocacy: The course could emphasize the importance of community participation in the Swachh Bharat Mission and provide tools and strategies for engaging with local communities to promote cleanliness and sanitation. It could also encourage advocacy for policy changes and innovations to address sanitation-related issues at the community, regional, and national levels.","Increased awareness and knowledge about cleanliness and sanitation: Participants of the course may gain a deeper understanding of the importance of cleanliness and sanitation, including the impact on personal health, environmental sustainability, and community well-being. They may learn about various waste management techniques, hygiene practices, and the initiatives of the Swachh Bharat Mission.","Enhanced skills for effective waste management: Participants may acquire practical skills related to waste management, such as waste segregation, composting, recycling, and proper disposal of hazardous waste. They may also develop skills in reducing waste generation and promoting sustainable waste management practices in their communities or workplaces.","Positive behavioral change towards cleanliness: The course may influence participants to adopt positive behavioral changes towards cleanliness, such as avoiding littering, practicing good hygiene habits, and promoting responsible waste disposal. Participants may develop a sense of responsibility towards maintaining cleanliness in their surroundings and actively contribute towards creating a cleaner environment.","Increased community participation and advocacy: Participants may become actively engaged in community participation and advocacy efforts related to cleanliness and sanitation. They may collaborate with local communities, government bodies, and non-governmental organizations (NGOs) to raise awareness, implement cleanliness initiatives, and advocate for policy changes or innovations to address sanitation-related issues.","Contribution towards Swachh Bharat Mission objectives: Participants may contribute towards the objectives of the Swachh Bharat Mission, such as promoting cleanliness, ensuring proper waste management, and eliminating open defecation. They may actively participate in Swachh Bharat Mission initiatives and campaigns, and contribute towards creating a cleaner and healthier environment.","Any topics related to Swachh Bharat Mission"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Determination of the capacitance and permittivity of the given material.","Determination of e/m of electron.","Determination of Planck''s constant and Photoelectric Work Function using Photoelectric cell.","Verification of inverse square law using photocell.","Determination of Wavelength of (He-Ne) LASER using Diffraction Grating Method.","Calculation of Energy Band Gap of a semiconductor.","Determination of Dielectric constant using resonance method.","Determination of Wavelength of Sodium light by measuring the diameter of the Newton''s Ring.","Determination of curvature of convex surface of a lens by Newton''s ring.","Verification of existence of Bohr''s Energy level with Frank-Hertz apparatus.","Determination of the Earth''s horizontal magnetic field intensity and magnetic Moment of a magnet by employing magnetometer.","Verification of Faraday''s Law and Lenz''s Law of Electromagnetic Induction."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Tutorial 1: Problem solving using computers: Lab1: Familiarization with programming environment","Tutorial 2: Variable types and type conversions: Lab 2: Simple computational problems using arithmetic expressions","Tutorial 3: Branching and logical expressions: Lab 3: Problems involving if-then-else structures","Tutorial 4: Loops, while and for loops: Lab 4: Iterative problems e.g., sum of series","Tutorial 5: 1D Arrays: searching, sorting: Lab 5: 1D Array manipulation","Tutorial 6: 2D arrays and Strings Lab 6: Matrix problems, String operations","Tutorial 7: Functions, call by value: Lab 7: Simple functions","Tutorial 8 & 9: Numerical methods (Root finding, numerical differentiation, numerical integration): Lab 8 and 9: Programming for solving Numerical methods problems","Tutorial 10: Recursion, structure of recursive calls Lab 10: Recursive functions","Tutorial 11: Pointers, structures and dynamic memory allocation Lab 11: Pointers and structures","Tutorial 12: File handling: Lab 12: File operations"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Learn and apply of different fitting tools -like work holding, marking, measuring, cutting, finishing and miscellaneous. Student will also prepare the report with sketch, specifications and applications of fitting tools demonstrated.","Prepare one simple and another male-female type fitting jobs as per given drawings- 2 jobs","Learn and apply of different tin smithy tools. Student will also prepare the report with sketch, specifications and applications of tin smithy tools demonstrated.","Learn and apply of welding equipments and making minimum one model.","Learn and apply of foundry tools and making minimum one model.","Learn and apply of carpentry tools and making minimum one model.","Learn and apply of Sheet Metal tools and making minimum one model.","Learn and apply of Lathe Tools & operations for making a job.","Learn and apply the application of measuring tools.","Learn and apply any casting process for making a model"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Partial Differential Equations","topics":["Definition Of Partial Differential Equations","First Order Partial Differential Equations","Solutions Of First Order Linear Pdes","Solution To Homogenous And Non-Homogenous Linear Partial Differential Equations Of Second Order By Complimentary Function And Particular Integral Method","Unit 2.0: Second Order Linear Equations Second-Order Linear Equations And Their Classification Initial And Boundary Conditions D''Alembert''s Solution Of The Wave Equation Duhamel''s Principle For One Dimensional Wave Equation Heat Diffusion And Vibration Problems Separation Of Variables Method To Simple Problems In Cartesian Coordinates The Laplacian In Plane, Cylindrical And Spherical Polar Coordinates Solutions With Bessel Functions And Legendre Functions One Dimensional Diffusion Equation And Its Solution By Separation Of Variables","Second-Order Linear Equations And Their Classification","Initial And Boundary Conditions","D''Alembert''s Solution Of The Wave Equation","Duhamel''s Principle For One Dimensional Wave Equation","Heat Diffusion And Vibration Problems","Separation Of Variables Method To Simple Problems In Cartesian Coordinates","The Laplacian In Plane, Cylindrical And Spherical Polar Coordinates","Solutions With Bessel Functions And Legendre Functions","One Dimensional Diffusion Equation And Its Solution By Separation Of Variables","Unit 3.0: Probability Theory Probability Spaces Conditional Probability Independence Discrete Random Variables Independent Random Variables The Multinomial Distribution Poisson Approximation To The Binomial Distribution Infinite Sequences Of Bernoulli Trials Sums Of Independent Random Variables Expectation Of Discrete Random Variables Moments Variance Of A Sum Correlation Coefficient Chebyshev''s Inequality","Probability Spaces","Conditional Probability","Independence","Discrete Random Variables","Independent Random Variables","The Multinomial Distribution","Poisson Approximation To The Binomial Distribution","Infinite Sequences Of Bernoulli Trials","Sums Of Independent Random Variables","Expectation Of Discrete Random Variables","Moments","Variance Of A Sum","Correlation Coefficient","Chebyshev''s Inequality"]},{"title":"Continuous Random Variables","topics":["Continuous Random Variables And Their Properties","Distribution Functions And Densities","Normal, Exponential And Gamma Densities","Bivariate Distributions And Their Properties","Distribution Of Sums And Quotients","Conditional Densities","Bayes'' Rule"]},{"title":"Basic Statistics Basic Statistics Measures Of Central Tendency: Moments, Skewness","topics":["Basic Statistics","Measures Of Central Tendency: Moments, Skewness And Kurtosis","Probability Distributions: Binomial, Poisson And Normal","Evaluation Of Statistical Parameters For These Three Distributions","Correlation And Regression","Rank Correlation","Curve Fitting By The Method Of Least Squares","Fitting Of Straight Lines, Second Degree Parabolas And More General Curves"]},{"title":"Test Of Significance","topics":["Test Of Significance: Large Sample Test For Single Proportion, Difference Of Proportions","Tests For Single Mean, Difference Of Means, And Difference Of Standard Deviations","Test For Ratio Of Variances","Chi-Square Test For Goodness Of Fit And Independence Of Attributes","Erwin Kreyszig, Advanced Engineering Mathematics, 9th Edition, John Wiley & Sons, 2006.","N.P. Bali and Manish Goyal, A text book of Engineering Mathematics, Laxmi Publications.","P. G. Hoel, S. C. Port and C. J. Stone, Introduction to Probability Theory, Universal Book Stall.","S. Ross, A First Course in Probability, 6th Ed., Pearson Education India, 2002."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Structure Of Engineering Materials","topics":["Importance Of Material Science In Engineering","Classification Of Engineering Materials: Ceramics, Glasses, Metals, Alloys, Polymers","Classification Of Structure Of Materials: Macrostructure, Microstructure, Crystal Structure, Electronic Structure","Effect Of Structure On Properties","Space Lattices","Bragg''s Law Of X-Ray Diffraction","Powder Method","Unit 2.0: Properties Of Materials Physical Properties: Density, Color, Odour, Refractive Index Elasticity, Plasticity, Modulus Of Elasticity Chemical Properties: Acidity, Reactivity, Toxicity, Solubility, Flammability Mechanical Properties: Ductility, Malleability, Tensile Strength, Compressive Strength, Brittleness, Creep, Fatigue, Fracture Thermal Properties: Heat Capacity, Thermal Conductivity, Specific Heat, Thermal Expansion, Thermal Stability Electrical Properties: Dielectric Constant, Dielectric Strength, Resistivity And Conductivity Stress Strain Behaviour Of Metals","Physical Properties: Density, Color, Odour, Refractive Index","Elasticity, Plasticity, Modulus Of Elasticity","Chemical Properties: Acidity, Reactivity, Toxicity, Solubility, Flammability","Mechanical Properties: Ductility, Malleability, Tensile Strength, Compressive Strength, Brittleness, Creep, Fatigue, Fracture","Thermal Properties: Heat Capacity, Thermal Conductivity, Specific Heat, Thermal Expansion, Thermal Stability","Electrical Properties: Dielectric Constant, Dielectric Strength, Resistivity And Conductivity","Stress Strain Behaviour Of Metals","Unit 3.0: Engineering Materials Classification Of Engineering Materials: Metals, Composites, Ceramics, Polymers Metals: Classification, Properties, Uses, Ferrous Metals, Nonferrous Metals Polymers: Classification, Mechanism, Thermoplastics, Thermoelastic Ceramics: Glasses, Crystalline Ceramics, Types And Properties Of Ceramics Composites: Metal Composites, Polymer Composites, Ceramics Composites Introduction To Nanomaterials, Properties, Application, Synthesis & Characterization Of Nanomaterials Properties & Applications Of Carbon Nano Tubes","Classification Of Engineering Materials: Metals, Composites, Ceramics, Polymers","Metals: Classification, Properties, Uses, Ferrous Metals, Nonferrous Metals","Polymers: Classification, Mechanism, Thermoplastics, Thermoelastic","Ceramics: Glasses, Crystalline Ceramics, Types And Properties Of Ceramics","Composites: Metal Composites, Polymer Composites, Ceramics Composites","Introduction To Nanomaterials, Properties, Application, Synthesis & Characterization Of Nanomaterials","Properties & Applications Of Carbon Nano Tubes","Unit 4.0: Corrosion Introduction To Corrosion Types Of Corrosion, Atmospheric Corrosion Effect Of Acid, Alkali, Water, Steam Factor Influencing Rate Of Corrosion Concept & Mechanism Of Electrochemical Corrosion Corrosion Control: Proper Selection Of Material, Electroplating, Hot Dipping Method, Cathodic Protection Biological Aspect Corrosion, Microbial Induced Corrosion And Prevention Effect Of Aerobic And Anaerobic Bacteria On Corrosion Concept Of Bio Fouling, Effect Of Bio Fouling","Introduction To Corrosion","Types Of Corrosion, Atmospheric Corrosion","Effect Of Acid, Alkali, Water, Steam","Factor Influencing Rate Of Corrosion","Concept & Mechanism Of Electrochemical Corrosion","Corrosion Control: Proper Selection Of Material, Electroplating, Hot Dipping Method, Cathodic Protection","Biological Aspect Corrosion, Microbial Induced Corrosion And Prevention","Effect Of Aerobic And Anaerobic Bacteria On Corrosion","Concept Of Bio Fouling, Effect Of Bio Fouling"]},{"title":"Biomaterials","topics":["History & Concept Of Biomaterials","Concept, Types, Application Of Biomaterials Like Ceramics, Glasses, Polymer"]},{"title":"Nanomaterials","topics":["Concept & Classification Of Nanomaterials","Physical Method Of Fabrication Like Chemical Vapour Deposition VDM, Molecular Beam Epitaxy","Nanofabrication By Scanning Probe","Nanofabrication By Replication","Material Science & Engineering, V. Raghavan, PHI Publication New Delhi 2007 ISBN: 978-81-203-2455-8 (Fifth Edition)","Principles and Prevention of Corrosion, Denny A Jones, Prentice Hall, N. J. (second edition), (1996) ISBN: 780133599930, 0133599930","Nanoscale materials in chemistry, Kenneth J. Klabunde, Ryan M Richards, John Wiley & Sons, 2009 Second edition, ISBN: 978-0-470-22270-6","Biomaterials an Introduction, J. Park and R. S. Lakes, Springer Science, New York, 3rd Ed. 2007, ISBN-13: 978-0387378794","A textbook of Nanoscience and Nanotechnology, Pradeep, T., Tata McGraw-Hill Education, 2003 ISBN: 1259007324, 9781259007323"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction To Fundamentals Of Chemical Calculations","topics":["Dimensions And Units","Systems Of Units, Conversion Of Units","Physical Properties Of Solutions, Gases","Concentration & Composition Of Mixtures And Solutions","Ideal Gas Law, Dalton''s Law, Amagat''s Law And Raoult''s Law"]},{"title":"Material Balance Without Chemical Reactions","topics":["Law Of Conservation Of Mass","Material Balance Without Chemical Reaction Concept And Procedure","Material Balance For Different Unit Operations","Recycle And Bypass Operations","Unsteady State Operations"]},{"title":"Material Balance With Chemical Reactions","topics":["Approach To Solve Material Balance Involving Chemical Reactions","Different Chemical Reaction Terms","Material Balance For Different Unit Processes","Recycle And Bypass Operations","Unsteady State Operations"]},{"title":"Energy Balance","topics":["Law Of Conservation Of Energy","Different Forms Of Energy","Different Terms Used In Energy Balance","Energy Balance Equation, Procedure To Do Energy Balance","Hess''s Law And Calculation Of Enthalpy Change And Heat Capacity","Energy Balances For Process Involving Chemical Reaction Including Adiabatic Reactions"]},{"title":"Combustion","topics":["Types Of Fuels And Calorific Value Of Fuel","Calculation Of Air Requirement For Combustion","Combustion Numerical"]},{"title":"Psychrometry","topics":["Psychrometric Terms","Psychrometric Calculations","Chemical Process Principles Hougen O.A., Watson K. M. CBS Publishers, 2nd edition.","Basic Principles and Calculations in Chemical Engineering David Himmelblau/ James Riggs, Prentice Hall, 7th edition.","Stoichiometry Bhatt B.I. and Vora S.M, Mc Graw Hill, 3rd edition.","Stoichiometry Bhatt B.I., S.B.Thakore and S.R.Shah, Mc Graw Hill, 6th edition."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Solid Particle, Its Characterization","topics":["Particle Shape & Size","Mean Particle Size, Size Distribution","Sphericity","Particle Size Measurement Techniques","Measurement Of Surface Area Of Particle","Particles In Mixtures","Laws Of Crushing & Grinding (Rittinger''s Law, Kick''s Law, Bond''s Law)","Numerical Based On Crushing Laws"]},{"title":"Transportation Of Solid Particle","topics":["Concept Of Conveyor, Types & Application","Belt Conveyor","Bucket Conveyor","Screw Conveyor","Positive & Negative Conveyor System","Unit 3.0: Size Reduction & Screening Importance Of Size Reduction & Screening Open Circuit & Closed Circuit Operations Factor Affecting On Size Reduction & Screening Size Reduction Equipment: Jaw Crusher, Hammer Mill, Gyratory Crusher, Roll Mill, Ball Mill Derivation For Critical Speed Of Ball Mill Concept Of Screening, Capacity & Effectiveness Of Screen Concept Of Mesh Number, Ideal & Actual Screen Screen Efficiency With Derivation Differential & Cumulative Screen Analysis Factors Affecting On Screen Efficiency Screening Equipments: Grizzlies, Trommels, Vibrating Screen Numerical Based On Screening","Importance Of Size Reduction & Screening","Open Circuit & Closed Circuit Operations","Factor Affecting On Size Reduction & Screening","Size Reduction Equipment: Jaw Crusher, Hammer Mill, Gyratory Crusher, Roll Mill, Ball Mill","Derivation For Critical Speed Of Ball Mill","Concept Of Screening, Capacity & Effectiveness Of Screen","Concept Of Mesh Number, Ideal & Actual Screen","Screen Efficiency With Derivation","Differential & Cumulative Screen Analysis","Factors Affecting On Screen Efficiency","Screening Equipments: Grizzlies, Trommels, Vibrating Screen","Numerical Based On Screening","Unit 4.0: Solid-Liquid Separation Concept & Principle Of Filtration Factors Affecting On Filtration, Filter Media, Filter Aid Industrial Filtration Equipments: Plate & Frame Filter, Pressure Leaf Filter, Basket Centrifuge, Drum Filter Washing Of Cake, Cake Resistance Design Equation Of Batch Filtration Concept Of Sedimentation, Drag Force, Drag Coefficient Free Settling, Hindered Settling, Terminal Settling Velocity, Stokes Law Factors Affecting On Sedimentation, Application Batch Sedimentation Test Industrial Equipment''s: Thickeners, Clarifiers, Gravity Classifier Design Of Thickeners Area & Height Froth Flotation: Concept, Mechanism, Application, Flotation Agents, Industrial Floating Equipments","Concept & Principle Of Filtration","Factors Affecting On Filtration, Filter Media, Filter Aid","Industrial Filtration Equipments: Plate & Frame Filter, Pressure Leaf Filter, Basket Centrifuge, Drum Filter","Washing Of Cake, Cake Resistance","Design Equation Of Batch Filtration","Concept Of Sedimentation, Drag Force, Drag Coefficient","Free Settling, Hindered Settling, Terminal Settling Velocity, Stokes Law","Factors Affecting On Sedimentation, Application","Batch Sedimentation Test","Industrial Equipment''s: Thickeners, Clarifiers, Gravity Classifier","Design Of Thickeners Area & Height","Froth Flotation: Concept, Mechanism, Application, Flotation Agents, Industrial Floating Equipments"]},{"title":"Gas - Solid Separation","topics":["Cyclone Separator: Principle & Concept, Construction, Working, Types Of Cyclone Separator, Multiple Cyclone Separator","Electrostatic Separator: Principle & Concept, Construction, Working, Types, Applications Of ESP","Wet Scrubber: Principle & Concept, Construction, Working, Applications","Bag Filter: Principle & Concept, Construction, Working, Application"]},{"title":"Mixing","topics":["Importance Of Mixing & Agitation","Principle Of Mixing, Mixing Index","Criterion For Selection Of Agitators","Calculation Of Power Consumption In Agitation","Ribbon Blender, Mullar Mixer, Sigma Mixer","Principle Of Vortexing & Swirling","Agitators, Flow Patterns, Methods To Prevent Vortexing","Design Of Agitator","Unit Operations of Chemical Engineering, McCabe W. L. and Smith J. C, 5th Edition McGraw Publications.","Introduction to Chemical Engineering, Badger W. L. and Banchero J. T, McGraw Publications New York 2011.","Unit operation by Brown G.G, CBS publication, First Edition 1995, reprint 2005."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Basics Of Organic Chemistry, Engineering Materials And Catalysis Classification Of Organic Compounds Introduction To Functional Groups Effect Of Functional Group On The Properties And Reactivity Of Organic Compounds Isomerism- Types Aromaticity- Properties And Reactivity Of Aromatic Compounds Such As Benzene For Various Applications Including Petrochemical And Pharmaceuticals Paints And Varnishes: Introduction To Paints And Varnishes, Difference Between Paint And Varnishes Insulators: Characteristics, Classification, Properties Of Insulators Polymer And Monomer: Classification On The Basis Of Molecular Structure, On The Basis Of Monomers (Homo Polymer And Copolymer), On The Basis Of Thermal Behaviour (Thermoplastics And Thermosetting) Natural And Synthetic Polymers Natural Rubber And Its Vulcanization- Advantages Of Vulcanized Rubber Types Polymerization Reaction, Addition Polymerization, Condensation Polymerization Synthesis, Properties And Application Of Polyethylene, Polyvinyl Chloride, Teflon, Polystyrene, Phenol Formaldehyde, Epoxy Resin, Orion, Nylon 66, Nylon 6, Bakelite Adhesives: Characteristics, Classification And Their Uses Lubricants: Classification, Properties And Applications Catalysis: Types Of Catalysis Homocatalysis, Heterocatalysis, Organic Catalyst: Types Of Catalyst Positive, Negative And Auto- Catalyst, Catalytic Promoter And Catalytic Inhibitor, Catalytic Mechanism, Industrial Application Of Catalyst Separation And Purification Techniques: Separation Technique Such As Distillation, Chromatography","Classification Of Organic Compounds","Introduction To Functional Groups","Effect Of Functional Group On The Properties And Reactivity Of Organic Compounds","Isomerism- Types","Aromaticity- Properties And Reactivity Of Aromatic Compounds Such As Benzene For Various Applications Including Petrochemical And Pharmaceuticals","Paints And Varnishes: Introduction To Paints And Varnishes, Difference Between Paint And Varnishes","Insulators: Characteristics, Classification, Properties Of Insulators","Polymer And Monomer: Classification On The Basis Of Molecular Structure, On The Basis Of Monomers (Homo Polymer And Copolymer), On The Basis Of Thermal Behaviour (Thermoplastics And Thermosetting)","Natural And Synthetic Polymers","Natural Rubber And Its Vulcanization- Advantages Of Vulcanized Rubber","Types Polymerization Reaction, Addition Polymerization, Condensation Polymerization","Synthesis, Properties And Application Of Polyethylene, Polyvinyl Chloride, Teflon, Polystyrene, Phenol Formaldehyde, Epoxy Resin, Orion, Nylon 66, Nylon 6, Bakelite","Adhesives: Characteristics, Classification And Their Uses","Lubricants: Classification, Properties And Applications","Catalysis: Types Of Catalysis Homocatalysis, Heterocatalysis, Organic Catalyst: Types Of Catalyst Positive, Negative And Auto- Catalyst, Catalytic Promoter And Catalytic Inhibitor, Catalytic Mechanism, Industrial Application Of Catalyst","Separation And Purification Techniques: Separation Technique Such As Distillation, Chromatography","Unit 2.0: Chemical Reactions, Processes And Reaction Mechanism Reaction Mechanism, Kinetics And Thermodynamics Of Chemical Reaction Designing And Optimization, Processes Such As Synthesis, Purification And Transformation Troubleshooting Processes Environmental Impact Of Organic Processes And Greener Alternatives Reaction Mechanism And Reaction Types: Knowledge Of Reaction Intermediates, Application Of Reaction Mechanism For Designing Efficient And Safe Processes Knowledge Of Mechanism Like Nucleophilic Substitution, Electrophilic Addition And Elimination Reaction Awareness Of Oxidation, Reduction, Condensation, Hydrolysis, Polymerisation, Etc. Safety During Chemical Reaction And Processes: Safety Consideration Associated With Organic Chemicals And Their Reactivity, Toxicity And Potential Hazards Of Organic Chemicals, Proper Handling And Storage Of Chemicals","Reaction Mechanism, Kinetics And Thermodynamics Of Chemical Reaction","Designing And Optimization, Processes Such As Synthesis, Purification And Transformation","Troubleshooting Processes","Environmental Impact Of Organic Processes And Greener Alternatives","Reaction Mechanism And Reaction Types: Knowledge Of Reaction Intermediates, Application Of Reaction Mechanism For Designing Efficient And Safe Processes","Knowledge Of Mechanism Like Nucleophilic Substitution, Electrophilic Addition And Elimination Reaction","Awareness Of Oxidation, Reduction, Condensation, Hydrolysis, Polymerisation, Etc.","Safety During Chemical Reaction And Processes: Safety Consideration Associated With Organic Chemicals And Their Reactivity, Toxicity And Potential Hazards Of Organic Chemicals, Proper Handling And Storage Of Chemicals","Unit 3.0: Applied Organic Chemistry For Chemical Engineers Stereochemistry: Chiral Molecules And Its Effect, Properties And Reactivity Of Compounds, Applications Of Stereochemistry In Pharmaceutical Manufacturing Functional Group Transformations: Awareness Of Functional Group Transformations Spectroscopy Techniques: Awareness On Identification And Characterization Of Organic Compounds Through - Nuclear Magnetic Resonance (NMR), Infrared (IR), Ultraviolet Visible (UV-Vis), Mass Spectrometry","Stereochemistry: Chiral Molecules And Its Effect, Properties And Reactivity Of Compounds, Applications Of Stereochemistry In Pharmaceutical Manufacturing","Functional Group Transformations: Awareness Of Functional Group Transformations","Spectroscopy Techniques: Awareness On Identification And Characterization Of Organic Compounds Through - Nuclear Magnetic Resonance (NMR), Infrared (IR), Ultraviolet Visible (UV-Vis), Mass Spectrometry"]},{"title":"Quantum Mechanics","topics":["Behaviour Of Atoms And Molecules","Basic Concepts Of Quantum Mechanics"]},{"title":"Statistical Mechanics","topics":["Basic Concepts Of Statistical Mech