insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction To Value Education Right Understanding, Relationship And Physical Facility (Holistic Development And The Role Of Education) Understanding Value Education Sharing About Oneself Self-Exploration As The Process For Value Education Continuous Happiness And Prosperity - The Basic Human Aspirations Exploring Human Consciousness Happiness And Prosperity - Current Scenario Method To Fulfill The Basic Human Aspirations","Right Understanding, Relationship And Physical Facility (Holistic Development And The Role Of Education)","Understanding Value Education Sharing About Oneself","Self-Exploration As The Process For Value Education","Continuous Happiness And Prosperity - The Basic Human Aspirations","Exploring Human Consciousness","Happiness And Prosperity - Current Scenario","Method To Fulfill The Basic Human Aspirations"]},{"title":"Harmony In The Human Being","topics":["Understanding Human Being As The Co-Existence Of The Self And The Body","Distinguishing Between The Needs Of The Self And The Body","The Body As An Instrument Of The Self","Understanding Harmony In The Self","Harmony Of The Self With The Body","Programme To Ensure Self-Regulation And Health"]},{"title":"Harmony In The Family And Society","topics":["Harmony In The Family - The Basic Unit Of Human Interaction","Trust - The Foundational Value In Relationship","Respect - As The Right Evaluation","Other Feelings","Justice In Human-To-Human Relationship","Understanding Harmony In The Society","Vision For The Universal Human Order"]},{"title":"Harmony In The Nature/Existence","topics":["Understanding Harmony In The Nature","Interconnectedness, Self-Regulation And Mutual Fulfilment Among The Four Orders Of Nature","Realizing Existence As Co-Existence At All Levels","The Holistic Perception Of Harmony In Existence","Unit 5.0: Implications Of The Holistic Understanding - A Look At Profession