insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Linear Algebra-I","topics":["Elementary Row operations","Gauss-Jordan Method for finding the inverse of Matrix","Complex Matrix: Hermitian, Skew Hermitian and Unitary Matrix","Vector space","Sub Spaces","Linear dependence and Independences of Vectors","Linear Span","Basis","Dimension","Extension of basis of subspace","The rank of a matrix","Row and column space","Solvability of system of linear equations"]},{"title":"Linear Algebra-II","topics":["Linear Transformations","Kernel and Range of linear transformation","Matrix Representation of a linear transformation","Rank-Nullity Theorem","Eigen Value and Eigen Vectors","Properties of Eigen vectors","Eigen Bases","Orthogonal Transformation","Similarity Transformation","Matrix Diagonalization","Cayley-Hamilton Theorem"]},{"title":"Calculus for single variable","topics":["Indeterminate form","L''Hospital Rule","Rolle''s Theorem","Mean Value Theorem","Expansion of function (single variable)","Taylor and Maclaurin Series","Riemann Integration","Riemann Sum","Improper Integrals","Beta and Gamma function and their properties"]},{"title":"Multivariable Calculus (Differentiation)","topics":["Function with two or more variable","Limit, continuity and Partial differentiation","Total Differentiation","Taylor''s series and Maclaurin''s series for function with two variable","Jacobian","Maxima and Minima","Method of Lagrange''s multiplier"]},{"title":"Multivariable Calculus (Integration)","topics":["Double Integral","Change of order of integration","Triple integral","Change of Variable in a Double and Triple Integrals","Change to polar coordinate","Change to cylindrical coordinate","Change to spherical polar coordinate","Application to area and volume using double and triple integral"]},{"title":"Vector Calculus","topics":["Scalar and vector fields","Gradient","Directional derivative","Divergence","Curl and their properties","Line integral","Gr