insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Concepts of energy principles","Safety","Sustainable development in performance","What makes a structure","Principles of stability","Equilibrium","What is a structural engineer","Role of engineer","Architect","User","Builder","What are the functions","What do the engineers design","First principles of process of design"]},{"title":"Introduction to reinforced concrete structures","topics":["Basic material properties: Stress-strain relation of concrete and reinforcing steel"]},{"title":"Planning and Design Process","topics":["Materials","Loads","And Design Safety","Behaviour and Properties of Concrete and Steel","Wind and Earthquake Loads Design philosophy: assumptions and code of practice"]},{"title":"Theory of singly reinforced members in bending","topics":["Design of simply supported and continuous beams with rectangular and flanged section"]},{"title":"Limit state of collapse in shear","topics":["Design for bond","Design of one-way and two-way slab systems"]},{"title":"Design of columns under uniaxial and biaxial bending","topics":["Design of footings and staircase","Nilson, A. H. Design of Concrete Structures. 13th edition. McGraw Hill, 2004","Mc Cormac, J.C., Nelson, J.K. Jr., Structural Steel Design. 3rd edition. Prentice Hall, N.J., 2003.","Galambos, T.V., Lin, F.J., Johnston, B.G., Basic Steel Design with LRFD, Prentice Hall, 1996","Segui, W. T., LRFD Steel Design, 2nd Ed., PWS Publishing, Boston.","Salmon, C.G. and Johnson, J.E., Steel Structures: Design and Behavior, 3rd Edition, Harper & Row, Publishers, New York, 1990.","MacGregor, J. G., Reinforced Concrete: Mechanics and Design, 3rd Edition, Prentice Hall, New Jersey, 1997.","Navy, E. G., Reinforced Concrete: A Fundamental Approach, 5th Edition, Prentice Hall, New Jersey.","Wang C.K. and Salmon, C. G., Reinforced Concrete Design, 6th Edition, Addison Wesley, New York.","Navy, E. G. Prestress