insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["The objective of this Course is to introduce continuum mechanics and material modeling of engineering materials based on first energy principles: deformation and strain; momentum balance, stress and stress states; elasticity and elasticity bounds; plasticity and yield design.","What will I learn?","→ Understand the deformation and strains under different load action and response in terms of forces and moments","→ Understand the behaviour under different loading actions","→ Application of engineering principles to calculate the reactions, forces and moments","→ Understand the energy methods used to derive the equations to solve engineering problems","→ Make use of the capabilities to determine the forces and moments for design"]},{"title":"Deformation and Strain","topics":["Description Of Finite Deformation","Infinitesimal Deformation","Analysis Of Statically Determinate Trusses","Stability Of Dams, Retaining Walls And Chimneys","Stress Analysis Of Thin, Thick And Compound Cylinder"]},{"title":"Generalized state of stress and strain","topics":["Stress And Strain Tensor","Yield Criteria And Theories Of Failure","Tresca, Von-mises, Hill Criteria","Haigh-westerguard''s Stress Space"]},{"title":"Momentum Balance and Stresses","topics":["Forces And Moments Transmitted By Slender Members","Shear Force And Bending Moment Diagrams","Momentum Balance","Stress States / Failure Criterion"]},{"title":"Mechanics of Deformable Bodies","topics":["Force-deformation Relationships And Static Indeterminacy","Uniaxial Loading And Material Properties","Trusses And Their Deformations","Statically Determinate And Indeterminate Trusses"]},{"title":"Force-Stress-Equilibrium","topics":["Multiaxial Stress And Strain"]},{"title":"Displacement - Strain","topics":["Multiaxial Strain And Multiaxial Stress-strain Relationships"]},{"title":"Elasticity and Elasticity Bounds","topics":["Stress-strain-temperature Relationships And Thin-walled Pressure Vessels","Stress And Strain Transformations And Principal Stress","Failure Of Materials","Module 8: Bending - Stress and Strains; Deflections and Torsion Pure Bending Moment-curvature Relationship Beam Deflection Symmetry, Superposition, And Statically Indeterminate Beams Shear And Torsion Torsion And Twisting Thermoelasticity Energy Methods, Variational Methods Strain Energy, Elastic, Complementary And Total Strain Energy Strain Energy Of Axially Loaded Bar Beam In Bending, Shear And Torsion General Energy Theorems, Castigliano''s Theorem, Maxwell Bettie''s Reciprocal Theorem Virtual Work And Unit Load Method For Deflection Application To Problems Of Beams And Frames","Pure Bending","Moment-curvature Relationship","Beam Deflection","Symmetry, Superposition, And Statically Indeterminate Beams","Shear And Torsion","Torsion And Twisting","Thermoelasticity","Energy Methods, Variational Methods","Strain Energy, Elastic, Complementary And Total Strain Energy","Strain Energy Of Axially Loaded Bar","Beam In Bending, Shear And Torsion","General Energy Theorems, Castigliano''s Theorem, Maxwell Bettie''s Reciprocal Theorem","Virtual Work And Unit Load Method For Deflection","Application To Problems Of Beams And Frames"]},{"title":"Structural stability; Plasticity and Yield Design","topics":["Stability Of Columns","Euler''s Formula","End Conditions And Effective Length Factor","Columns With Eccentric And Lateral Load","1d-plasticity - An Energy Approach","Plasticity Models","Limit Analysis And Yield Design","Norris, C.H. and Wilber, J. B. and Utku, S. \"Elementary Structural Analysis\" McGraw Hill, Tokyo, Japan.","Timoshenko, S. and Young, D. H., \"Elements of Strength of Materials\", DVNC, New York, USA.","Kazmi, S. M. A., ''Solid Mechanics\" TMH, Delhi, India.","Hibbeler, R. C. Mechanics of Materials. 6th ed. East Rutherford, NJ: Pearson Prentice Hall, 2004","Crandall, S. H., N. C. Dahl, and T. J. Lardner. An Introduction to the Mechanics of Solids. 2nd ed. New York, NY: McGraw Hill, 1979","Gere, J. M., and S. P. Timoshenko. Mechanics of Materials. 5th ed. Boston: PWS Kent Publishing, 1970.","Ashby, M. F., and D. R. H. Jones. Engineering Materials, An Introduction to their Properties and Applications. 2nd ed. Butterworth Heinemann.","Collins, J. A. Failure of Materials in Mechanical Design. 2nd ed. John Wiley & Sons, 1993.","Courtney, T. H. Mechanical Behavior of Materials. McGraw-Hill, 1990.","Hertzberg, R. W. Deformation and Fracture Mechanics of Engineering Materials. 4th ed. John Wiley & Sons, 1996.","Nash, W. A. Strength of Materials. 3d ed. Schaum''s Outline Series, McGraw-Hill, 1994."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To introduce the students to various hydraulic engineering problems like open channel flows and hydraulic machines. At the completion of the course, the student should be able to relate the theory and practice of problems in hydraulic engineering."]},{"title":"Boundary Layer Analysis","topics":["Assumption And Concept Of Boundary Layer Theory","Boundary-layer Thickness, Displacement, Momentum & Energy Thickness","Laminar And Turbulent Boundary Layers On A Flat Plate","Laminar Sub-layer, Smooth And Rough Boundaries","Local And Average Friction Coefficients","Separation And Control"]},{"title":"Introduction to Open Channel Flow","topics":["Comparison Between Open Channel Flow And Pipe Flow","Geometrical Parameters Of A Channel","Classification Of Open Channels","Classification Of Open Channel Flow","Velocity Distribution Of Channel Section"]},{"title":"Uniform Flow","topics":["Continuity Equation, Energy Equation And Momentum Equation","Characteristics Of Uniform Flow","Chezy''s Formula, Manning''s Formula","Factors Affecting Manning''s Roughness Coefficient \"n\"","Most Economical Section Of Channel","Computation Of Uniform Flow, Normal Depth","Module 4: Non-Uniform Flow Specific Energy Specific Energy Curve Critical Flow Discharge Curve Specific Force Specific Depth Critical Depth Channel Transitions Measurement Of Discharge And Velocity - Venturi Flume, Standing Wave Flume, Parshall Flume, Broad Crested Weir Measurement Of Velocity- Current Meter, Floats, Hot-wire Anemometer Gradually Varied Flow-dynamic Equation Of Gradually Varied Flow Classification Of Channel Bottom Slopes Classification Of Surface Profile Characteristics Of Surface Profile Computation Of Water Surface Profile By Graphical, Numerical And Analytical Approaches Direct Step Method, Graphical Integration Method And Direct Integration Method","Specific Energy","Specific Energy Curve","Critical Flow","Discharge Curve Specific Force Specific Depth","Critical Depth","Channel Transitions","Measurement Of Discharge And Velocity - Venturi Flume, Standing Wave Flume, Parshall Flume, Broad Crested Weir","Measurement Of Velocity- Current Meter, Floats, Hot-wire Anemometer","Gradually Varied Flow-dynamic Equation Of Gradually Varied Flow","Classification Of Channel Bottom Slopes","Classification Of Surface Profile","Characteristics Of Surface Profile","Computation Of Water Surface Profile By Graphical, Numerical And Analytical Approaches","Direct Step Method, Graphical Integration Method And Direct Integration Method"]},{"title":"Hydraulic Jump","topics":["Theory Of Hydraulic Jump","Elements And Characteristics Of Hydraulic Jump In A Rectangular Channel","Length And Height Of Jump","Location Of Jump","Types, Applications And Location Of Hydraulic Jump","Energy Dissipation And Other Uses","Surge As A Moving Hydraulic Jump","Positive And Negative Surges"]},{"title":"Computational Fluid Dynamics and Hydroinformatics","topics":["Basic Equations Of Fluid Dynamics","Grid Generation","Introduction To Inviscid Incompressible Flow","Boundary Layer Flow As Applicable To C.F.D","Concept Of Hydro Informatics -scope Of Internet And Web Based Modeling In Water Resources Engineering","Hydraulics and Fluid Mechanics, P.M. Modi and S.M. Seth, Standard Book House","Theory and Applications of Fluid Mechanics, K. Subramanya, Tata McGraw Hill.","Open channel Flow, K. Subramanya, Tata McGraw Hill.","Open Channel Hydraulics, Ven Te Chow, Tata McGraw Hill.","Burnside, C.D., \" Electromagnetic Distance Measurement,\" Beekman Publishers, 1971."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["This course aims at providing students with a solid background on principles of structural engineering design. Students will be exposed to the theories and concepts of both concrete and steel design and analysis both at the element and system levels."]},{"title":"Introduction","topics":["Concepts Of Energy Principles, Safety, Sustainable Development In Performance","What Makes A Structure","Principles Of Stability, Equilibrium","What Is A Structural Engineer, Role Of Engineer, Architect, User, Builder","What Are The Functions","What Do The Engineers Design, First Principles Of Process Of Design"]},{"title":"Introduction to reinforced concrete structures Basic Material Properties Stress-strain Relation","topics":["Introduction to reinforced concrete structures","Basic Material Properties","Stress-strain Relation Of Concrete And Reinforcing Steel"]},{"title":"Planning and Design Process","topics":["Materials, Loads, And Design Safety","Behaviour And Properties Of Concrete And Steel","Wind And Earthquake Loads Design Philosophy","Assumptions And Code Of Practice"]},{"title":"Theory of singly reinforced members in bending Design Of Simply","topics":["Theory of singly reinforced members in bending","Design Of Simply Supported And Continuous Beams With Rectangular And Flanged Section"]},{"title":"Limit state of collapse in shear Design For Bond Design","topics":["Limit state of collapse in shear","Design For Bond","Design Of One-way And Two-way Slab Systems"]},{"title":"Design of columns and foundations","topics":["Design Of Columns Under Uniaxial And Biaxial Bending","Design Of Footings And Staircase","Nilson, A. H. Design of Concrete Structures. 13th edition. McGraw Hill, 2004","McCormac, J.C., Nelson, J.K. Jr., Structural Steel Design. 3rd edition. Prentice Hall, N.J., 2003.","Galambos, T.V., Lin, F.J., Johnston, B.G., Basic Steel Design with LRFD, Prentice Hall, 1996","Segui, W. T., LRFD Steel Design, 2nd Ed., PWS Publishing, Boston.","Salmon, C.G. and Johnson, J.E., Steel Structures: Design and Behavior, 3rd Edition, Harper & Row, Publishers, New York, 1990.","MacGregor, J. G., Reinforced Concrete: Mechanics and Design, 3rd Edition, Prentice Hall, New Jersey, 1997.","Navy, E. G., Reinforced Concrete: A Fundamental Approach, 5th Edition, Prentice Hall, New Jersey.","Wang C-K. and Salmon, C. G., Reinforced Concrete Design, 6th Edition, Addison Wesley, New York.","Navy, E. G. Prestressed Concrete: A Fundamental Approach, Prentice Hall, NJ, (2003).","Related Codes of Practice of BIS","Smith, J. C., Structural Analysis, Harper and Row, Publishers, New York.","W. McGuire, R. H. Gallagher and R. D. Ziemian. \"Matrix Structural Analysis\", 2nd Edition, John Wiley and Sons, 2000.","NBC, National Building Code, BIS (2017).","ASCE, Minimum Design Loads for Buildings and Other Structures, ASCE 7-02, American Society of Civil Engineers, Virginia, 2002.","S. U. Pillai and D. Menon, Reinforced Concrete Design, Tata McGraw-Hill, 3rd edition, 2009.","P. C. Varghese, Limit State Design of Reinforced Concrete, Prentice Hall India, 2nd edition, 2"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: Introduction Types Of Soils, Their Formation And Deposition Definitions: Soil Mechanics, Soil Engineering, Rock Mechanics, Geotechnical Engineering Scope Of Soil Engineering Comparison And Difference Between Soil And Rock Basic Definitions And Relationships-soil As Three-phase System In Terms Of Weight, Volume, Voids Ratio, And Porosity Definitions: Moisture Content, Unit Weights, Degree Of Saturation, Voids Ratio, Porosity, Specific Gravity, Mass Specific Gravity, Etc Relationship Between Volume Weight, Voids Ratio- Moisture Content, Unit Weight- Percent Air Voids, Saturation- Moisture Content, Moisture Content- Specific Gravity Etc Determination Of Various Parameters Such As: Moisture Content By Oven Dry Method, Pycrometer, Sand Bath Method, Torsional Balance Method, Nuclear Method, Alcohol Method And Sensors Specific Gravity By Density Bottle Method, Pycrometer Method, Measuring Flask Method Unit Weight By Water Displacement Method, Submerged Weight Method, Core-cutter Method, Sand-replacement Method","Types Of Soils, Their Formation And Deposition","Definitions: Soil Mechanics, Soil Engineering, Rock Mechanics, Geotechnical Engineering","Scope Of Soil Engineering","Comparison And Difference Between Soil And Rock","Basic Definitions And Relationships-soil As Three-phase System In Terms Of Weight, Volume, Voids Ratio, And Porosity","Definitions: Moisture Content, Unit Weights, Degree Of Saturation, Voids Ratio, Porosity, Specific Gravity, Mass Specific Gravity, Etc","Relationship Between Volume Weight, Voids Ratio- Moisture Content, Unit Weight- Percent Air Voids, Saturation- Moisture Content, Moisture Content- Specific Gravity Etc","Determination Of Various Parameters Such As: Moisture Content By Oven Dry Method, Pycrometer, Sand Bath Method, Torsional Balance Method, Nuclear Method, Alcohol Method And Sensors","Specific Gravity By Density Bottle Method, Pycrometer Method, Measuring Flask Method","Unit Weight By Water Displacement Method, Submerged Weight Method, Core-cutter Method, Sand-replacement Method","Module 2: Plasticity Characteristics of Soil Introduction To Definitions Of: Plasticity Of Soil, Consistency Limits-liquid Limit, Plastic Limit, Shrinkage Limit, Plasticity, Liquidity And Consistency Indices, Flow & Toughness Indices Definitions Of Activity And Sensitivity Determination Of: Liquid Limit, Plastic Limit And Shrinkage Limit Use Of Consistency Limits Classification Of Soils-introduction Of Soil Classification: Particle Size Classification, Textural Classification, Unified Soil Classification System, Indian Standard Soil Classification System Identification: Field Identification Of Soils, General Characteristics Of Soil In Different Groups","Introduction To Definitions Of: Plasticity Of Soil, Consistency Limits-liquid Limit, Plastic Limit, Shrinkage Limit, Plasticity, Liquidity And Consistency Indices, Flow & Toughness Indices","Definitions Of Activity And Sensitivity","Determination Of: Liquid Limit, Plastic Limit And Shrinkage Limit","Use Of Consistency Limits","Classification Of Soils-introduction Of Soil Classification: Particle Size Classification, Textural Classification, Unified Soil Classification System, Indian Standard Soil Classification System","Identification: Field Identification Of Soils, General Characteristics Of Soil In Different Groups","Module 3: Permeability of Soil Darcy''s Law, Validity Of Darcy''s Law Determination Of Coefficient Of Permeability: Laboratory Method: Constant-head Method, Falling-head Method Field Method: Pumping- In Test, Pumping- Out Test Permeability Aspects: Permeability Of Stratified Soils, Factors Affecting Permeability Of Soil Seepage Analysis- Introduction, Stream And Potential Functions, Characteristics Of Flow Nets, Graphical Method To Plot Flow Nets","Darcy''s Law, Validity Of Darcy''s Law","Determination Of Coefficient Of Permeability: Laboratory Method: Constant-head Method, Falling-head Method","Field Method: Pumping- In Test, Pumping- Out Test","Permeability Aspects: Permeability Of Stratified Soils, Factors Affecting Permeability Of Soil","Seepage Analysis- Introduction, Stream And Potential Functions, Characteristics Of Flow Nets, Graphical Method To Plot Flow Nets"]},{"title":"Effective Stress Principle","topics":["Introduction, Effective Stress Principle, Nature Of Effective Stress, Effect Of Water Table","Fluctuations Of Effective Stress, Effective Stress In Soils Saturated By Capillary Action, Seepage Pressure, Quick Sand Condition"]},{"title":"Compaction of Soil","topics":["Introduction, Theory Of Compaction, Laboratory Determination Of Optimum Moisture Content And Maximum Dry Density","Compaction In Field, Compaction Specifications And Field Control"]},{"title":"Stresses in soils","topics":["Introduction, Stresses Due To Point Load, Line Load, Strip Load, Uniformly Loaded Circular Area, Rectangular Loaded Area","Influence Factors, Isobars, Boussinesq''s Equation, Newmark''s Influence Chart","Contact Pressure Under Rigid And Flexible Area, Computation Of Displacements From Elastic Theory","Soil Mechanics by Craig R.F., Chapman & Hall","Fundamentals of Soil Engineering by Taylor, John Wiley & Sons","An Introduction to Geotechnical Engineering, by Holtz R.D. and Kovacs, W.D., Prentice Hall, NJ","Principles of Geotechnical Engineering, by Braja M. Das, Cengage Learning","Principles of Foundation Engineering, by Braja M. Das, Cengage Learning","Essentials of Soil Mechanics and Foundations: Basic Geotechnics by David F. McCarthy","Soil Mechanics in Engineering Practice by Karl Terzaghi, Ralph B. Peck, and Gholamreza Mesri.","Geotechnical Engineering: Principles and Practices of Soil Mechanics and Foundation Engineering (Civil and Environmental Engineering) by V.N.S."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Hydrologic Cycle","Water-budget Equation","History Of Hydrology","World Water Balance","Applications In Engineering","Sources Of Data"]},{"title":"Precipitation","topics":["Forms Of Precipitation","Characteristics Of Precipitation In India","Measurement Of Precipitation","Rain Gauge Network","Mean Precipitation Over An Area","Depth Area-duration Relationships","Maximum Intensity/depth-duration-frequency Relationship","Probable Maximum Precipitation (Pmp)","Rainfall Data In India","Module 3: Abstractions from precipitation Evaporation Process Evaporimeters Analytical Methods Of Evaporation Estimation Reservoir Evaporation And Methods For Its Reduction Evapotranspiration Measurement Of Evapotranspiration Evapotranspiration Equations Potential Evapotranspiration Over India Actual Evapotranspiration Interception Depression Storage Infiltration Infiltration Capacity Measurement Of Infiltration Modelling Infiltration Capacity Classification Of Infiltration Capacities Infiltration Indices","Evaporation Process","Evaporimeters","Analytical Methods Of Evaporation Estimation","Reservoir Evaporation And Methods For Its Reduction","Evapotranspiration","Measurement Of Evapotranspiration","Evapotranspiration Equations","Potential Evapotranspiration Over India","Actual Evapotranspiration","Interception","Depression Storage","Infiltration","Infiltration Capacity","Measurement Of Infiltration","Modelling Infiltration Capacity","Classification Of Infiltration Capacities","Infiltration Indices"]},{"title":"Runoff","topics":["Runoff Volume","Scs-cn Method Of Estimating Runoff Volume","Flow Duration Curve","Flow-mass Curve","Hydrograph","Factors Affecting Runoff Hydrograph","Components Of Hydrograph","Base Flow Separation","Effective Rainfall","Unit Hydrograph Surface Water Resources Of India","Environmental Flows"]},{"title":"Groundwater and well hydrology","topics":["Forms Of Subsurface Water","Saturated Formation","Aquifer Properties","Geologic Formations Of Aquifers","Well Hydraulics: Steady State Flow In Wells","Equilibrium Equations For Confined And Unconfined Aquifers","Aquifer Tests","Module 6: Water withdrawals and uses Water For Energy Production Water For Agriculture Water For Hydroelectric Generation Flood Control Analysis Of Surface Water Supply Water Requirement Of Crops-crops And Crop Seasons In India Cropping Pattern Duty And Delta Quality Of Irrigation Water Soil-water Relationships Root Zone Soil Water Infiltration Consumptive Use Irrigation Requirement Frequency Of Irrigation Methods Of Applying Water To The Fields: Surface, Sub-surface, Sprinkler And Trickle / Drip Irrigation","Water For Energy Production","Water For Agriculture","Water For Hydroelectric Generation","Flood Control","Analysis Of Surface Water Supply","Water Requirement Of Crops-crops And Crop Seasons In India","Cropping Pattern","Duty And Delta","Quality Of Irrigation Water","Soil-water Relationships","Root Zone Soil Water","Infiltration","Consumptive Use","Irrigation Requirement","Frequency Of Irrigation","Methods Of Applying Water To The Fields: Surface, Sub-surface, Sprinkler And Trickle / Drip Irrigation","Module 7: Distribution systems Canal Systems Alignment Of Canals Canal Losses Estimation Of Design Discharge Design Of Channels- Rigid Boundary Channels, Alluvial Channels Kennedy''s And Lacey''s Theory Of Regime Channels Canal Outlets: Non-modular, Semi-modular And Modular Outlets Water Logging: Causes, Effects And Remedial Measures Lining Of Canals, Types Of Lining Drainage Of Irrigated Lands: Necessity, Methods","Canal Systems","Alignment Of Canals","Canal Losses","Estimation Of Design Discharge","Design Of Channels- Rigid Boundary Channels, Alluvial Channels","Kennedy''s And Lacey''s Theory Of Regime Channels","Canal Outlets: Non-modular, Semi-modular And Modular Outlets","Water Logging: Causes, Effects And Remedial Measures","Lining Of Canals, Types Of Lining","Drainage Of Irrigated Lands: Necessity, Methods","Module 8: Dams and spillways Embankment Dams: Classification, Design Considerations, Estimation And Control Of Seepage, Slope Protection Gravity Dams: Forces On Gravity Dams, Causes Of Failure, Stress Analysis, Elementary And Practical Profile Arch And Buttress Dams Spillways: Components Of Spillways, Types Of Gates For Spillway Crests Reservoirs- Types, Capacity Of Reservoirs, Yield Of Reservoir, Reservoir Regulation, Sedimentation, Economic Height Of Dam, Selection Of Suitable Site","Embankment Dams: Classification, Design Considerations, Estimation And Control Of Seepage, Slope Protection","Gravity Dams: Forces On Gravity Dams, Causes Of Failure, Stress Analysis, Elementary And Practical Profile","Arch And Buttress Dams","Spillways: Components Of Spillways, Types Of Gates For Spillway Crests","Reservoirs- Types, Capacity Of Reservoirs, Yield Of Reservoir, Reservoir Regulation, Sedimentation, Economic Height Of Dam, Selection Of Suitable Site","K Subramanya, Engineering Hydrology, Mc-Graw Hill.","K N Muthreja, Applied Hydrology, Tata Mc-Graw Hill.","K Subramanya, Water Resources Engineering through Objective Questions, Tata McGraw Hill.","G L Asawa, Irrigation Engineering, Wiley Eastern","L W Mays, Water Resources Engineering, Wiley.","J D Zimmerman, Irrigation, John Wiley & Sons","C S P Ojha, R Berndtsson and P Bhunya, Engineering Hydrology, Oxford.","At the end of the course, students must be in a position to:","→ Understand the interaction among various processes in the hydrologic cycle","→ Apply the application of fluid mechanics and use of computers in solving a host of problems in hydraulic engineering","→ Study types and classes of hydrologic simulation models and design procedures for safe and effective passage of flood flows for design of hydraulic structures","→ Understand the basic aquifer parameters and estimate groundwater resources for different hydro-geological boundary conditions","→ Understand application of systems concept, advanced optimization techniques to cover the socio-technical aspects in the field of water resources","→ Apply the principles and applications of remote sensing, GPS and GIS in the context to hydrological extreme flood and drought events in water resources engineering"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: Water Sources Of Water And Quality Issues Water Quality Requirement For Different Beneficial Uses Water Quality Standards Water Quality Indices Water Safety Plans Water Supply Systems Need For Planned Water Supply Schemes Water Demand Industrial And Agricultural Water Requirements Components Of Water Supply System Transmission Of Water Distribution System Various Valves Used In W/s Systems Service Reservoirs And Design Water Treatment: Aeration, Sedimentation, Coagulation Flocculation, Filtration, Disinfection Advanced Treatments Like Adsorption, Ion Exchange, Membrane Processes","Sources Of Water And Quality Issues","Water Quality Requirement For Different Beneficial Uses","Water Quality Standards","Water Quality Indices","Water Safety Plans","Water Supply Systems","Need For Planned Water Supply Schemes","Water Demand Industrial And Agricultural Water Requirements","Components Of Water Supply System","Transmission Of Water","Distribution System","Various Valves Used In W/s Systems","Service Reservoirs And Design","Water Treatment: Aeration, Sedimentation, Coagulation Flocculation, Filtration, Disinfection","Advanced Treatments Like Adsorption, Ion Exchange, Membrane Processes"]},{"title":"Air","topics":["Composition And Properties Of Air","Quantification Of Air Pollutants","Monitoring Of Air Pollutants","Air Pollution- Occupational Hazards","Urban Air Pollution Automobile Pollution","Chemistry Of Combustion","Automobile Engines","Quality Of Fuel","Operating Conditions And Interrelationship","Air Quality Standards","Control Measures For Air Pollution, Construction And Limitations"]},{"title":"Noise","topics":["Basic Concept","Measurement And Various Control Methods"]},{"title":"Building Plumbing","topics":["Introduction To Various Types Of Home Plumbing Systems For Water Supply And Waste Water Disposal","High Rise Building Plumbing","Pressure Reducing Valves","Break Pressure Tanks","Storage Tanks","Building Drainage For High Rise Buildings","Various Kinds Of Fixtures And Fittings Used","Introduction to Environmental Engineering and Science by Gilbert Masters, Prentice Hall, New Jersey.","Introduction to Environmental Engineering by P. Aarne Vesilind, Susan M. Morgan, Thompson /Brooks/Cole; Second Edition 2008.","Peavy, H.s, Rowe, D.R, Tchobanoglous, G. Environmental Engineering, Mc-Graw Hill International Editions, New York 1985.","MetCalf and Eddy. Wastewater Engineering, Treatment, Disposal and Reuse, Tata McGraw-Hill, New Delhi.","Manual on Water Supply and Treatment. Ministry of Urban Development, New Delhi.","Plumbing Engineering. Theory, Design and Practice, S.M. Patil, 1999","Integrated Solid Waste Management, Tchobanoglous, Theissen & Vigil. McGraw Hill Publication","Manual on Sewerage and Sewage Treatment Systems, Part A, B and C. Central Public Health and Environmental Engineering Organization, Ministry of Urban Development."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Highway development and planning","topics":["Classification Of Roads","Road Development In India","Current Road Projects In India","Highway Alignment And Project Preparation"]},{"title":"Geometric design of highways","topics":["Introduction","Highway Cross Section Elements","Sight Distance","Design Of Horizontal Alignment","Design Of Vertical Alignment","Design Of Intersections","Problems"]},{"title":"Traffic engineering & control","topics":["Traffic Characteristics","Traffic Engineering Studies","Traffic Flow And Capacity","Traffic Regulation And Control","Design Of Road Intersections","Design Of Parking Facilities","Highway Lighting","Problems"]},{"title":"Pavement materials","topics":["Materials Used In Highway Construction- Soils, Stone Aggregates, Bituminous Binders, Bituminous Paving Mixes","Portland Cement And Cement Concrete: Desirable Properties, Tests, Requirements For Different Types Of Pavements","Problems"]},{"title":"Design of pavements","topics":["Introduction","Flexible Pavements, Factors Affecting Design And Performance","Stresses In Flexible Pavements","Design Of Flexible Pavements As Per IRC","Rigid Pavements- Components And Functions","Factors Affecting Design And Performance Of Cc Pavements","Stresses In Rigid Pavements","Design Of Concrete Pavements As Per IRC","Problems","Khanna, S.K., Justo, C.E.G and Veeraragavan, A, ''Highway Engineering'', Revised 10th Edition, Nem Chand & Bros, 2017","Kadiyali, L.R., '' Traffic Engineering and Transport Planning'', Khanna Publishers.","Partha Chakraborty, '' Principles Of Transportation Engineering, PHI Learning,","Fred L. Mannering, Scott S. Washburn, Walter P. Kilareski,''Principles of Highway Engineering and Traffic Analysis'', 4th Edition, John Wiley","Srinivasa Kumar, R, Textbook of Highway Engineering, Universities Press, 2011.","Paul H. Wright and Karen K. Dixon, Highway Engineering, 7th Edition, Wiley Student Edition, 2009."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["We as human beings are not an entity separate from the environment around us rather we are a constituent seamlessly integrated and co-exist with the environment around us. We are not an entity so separate from the environment that we can think of mastering and controlling it rather we must understand that each and every action of ours reflects on the environment and vice versa. Ancient wisdom drawn from Vedas about the environment and its sustenance reflects these ethos. There is a direct application of this wisdom even in modern times. Idea of an activity based course on environment protection is to sensitize the students on the above issues through following two type of activities:","Awareness Activities:","Small Group Meetings About Water Management, Promotion Of Recycle Use, Generation Of Less Waste, Avoiding Electricity Waste","Slogan Making Events","Poster Making Events","Cycle Rally","Lectures From Experts","Actual Activities:","Plantation","Gifting A Tree To See Its Full Growth","Cleanliness Drive","Drive For Segregation Of Waste","To Live Some Big Environmentalist For A Week Or So To Understand His Work","To Work In Kitchen Garden For Mess","To Know About The Different Varieties Of Plants","Shutting Down The Fans And ACs Of The Campus For An Hour Or So"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Practical Work:","Flow Visualization","Studies In Wind Tunnel","Boundary Layer","Flow Around An Aerofoil / Circular Cylinder","Uniform Flow","Velocity Distribution In Open Channel Flow","Venturi Flume","Standing Wave Flume","Gradually Varied Flow","Hydraulic Jump","Flow Under Sluice Gate","Flow Through Pipes","Turbulent Flow Through Pipes","Flow Visualization","Laminar Flow Through Pipes","Major Losses / Minor Losses In Pipe"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Practical Work:","Field Density Using Core Cutter Method","Field Density Using Sand Replacement Method","Natural Moisture Content Using Oven Drying Method","Field Identification Of Fine Grained Soils","Specific Gravity Of Soils","Grain Size Distribution By Sieve Analysis","Grain Size Distribution By Hydrometer Analysis","Consistency Limits By Liquid Limit","Consistency Limits By Plastic Limit","Consistency Limits By Shrinkage Limit","Permeability Test Using Constant-head Test Method","Permeability Test Using Falling-head Method","Compaction Test: Standard Proctor Test","Compaction Test: Modified Proctor Test","Relative Density","Consolidation Test","Triaxial Test (Uu)","Vane Shear Test","Direct Shear Test","Unconfined Compression Strength Test"]}]'::jsonb from s;
