insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Database system architecture","topics":["Data Abstraction","Data Independence","Data Definition Language (DDL)","Data Manipulation Language (DML)","Data models: Entity-relationship model","Network model","Relational and object oriented data models","Integrity constraints","Data manipulation operations","Unit 2.0: Relational query languages Relational algebra Tuple and domain relational calculus SQL3 DDL and DML constructs Open source and Commercial DBMS - MYSQL, ORACLE, DB2, SQL server Relational database design: Domain and data dependency Armstrong''s axioms Normal forms Dependency preservation Lossless design Query processing and optimization: Evaluation of relational algebra expressions Query equivalence Join strategies Query optimization algorithms","Relational algebra","Tuple and domain relational calculus","SQL3","DDL and DML constructs","Open source and Commercial DBMS - MYSQL, ORACLE, DB2, SQL server","Relational database design: Domain and data dependency","Armstrong''s axioms","Normal forms","Dependency preservation","Lossless design","Query processing and optimization: Evaluation of relational algebra expressions","Query equivalence","Join strategies","Query optimization algorithms"]},{"title":"Storage strategies","topics":["Indices","B- trees","Hashing"]},{"title":"Transaction processing","topics":["Concurrency control","ACID property","Serializability of scheduling","Locking and timestamp based schedulers","Multi- version and optimistic Concurrency Control schemes","Database recovery"]},{"title":"Database Security","topics":["Authentication","Authorization and access control","DAC, MAC and RBAC models","Intrusion detection","SQL injection"]},{"title":"Advanced topics","topics":["Object oriented and object relational databases","Logical databases","Web databases","Distributed databases","Data warehousing and data mining","\"Database System Concepts\", 6th Edition by 