insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Investigation of geographic information systems (GIS) and science (GIScience) including theory and applications areas. A major portion of the course will be based on use of a current widely-used GIS computer software system. Aspects of geographic data entry and editing, spatial analysis, and map development and display will be considered. Relationship of GIS to the Global Positioning System (GPS) and satellite generated data will be addressed."]}]'::jsonb from s;
