insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0 Overview Of Web Programming Understanding The Fundamentals Of Web Development - Including Client-Side And Server-Side Scripting Languages Introduction To Artificial Intelligence (AI): Definition, Scope And Applications Of AI In Various Fields Intersection Of Web Development And AI: Exploring How AI Technologies Enhance Web Applications And User Experiences Tools And Technologies: Introduction To Essential Tools And Technologies For Web Development And AI Integration","Overview Of Web Programming","Understanding The Fundamentals Of Web Development - Including Client-Side And Server-Side Scripting Languages","Introduction To Artificial Intelligence (AI): Definition, Scope And Applications Of AI In Various Fields","Intersection Of Web Development And AI: Exploring How AI Technologies Enhance Web Applications And User Experiences","Tools And Technologies: Introduction To Essential Tools And Technologies For Web Development And AI Integration","Unit 2.0 What Is HTML: History HTML Documents - Basic Structure Creating An HTML Document Features And Limitations Mark Up Tags Heading, Paragraphs, Line Breaks HTML Tags Formatting Tags Introduction To Elements Of HTML Working With Text Working With Lists, Tables And Frames Working With Hyperlinks Images Image Format (Quality, Size, Type, ...) Importing Images (Scanners) Working With Forms And Controls Responsive Web Design: Techniques For Creating Web Applications That Adapt To Different Screen Sizes And Devices Introduction To AI Libraries And APIs: Overview Of Popular AI Libraries And APIs For Frontend Integration","What Is HTML: History","HTML Documents - Basic Structure","Creating An HTML Document","Features And Limitations","Mark Up Tags","Heading, Paragraphs, Line Breaks","HTML Tags","Formatting Tags","Introduction To Elements Of HTML","Working With Text","Working With Lists, Tables And Frames","Working With H