insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Preform Any Ten Experiments. Write The Following Programs Using Python/Prolog","Week 1: Write A Program To Print The Multiplication Table For The Given Number. Write A Program To Find Factorial Of A Number. Write A Program To Check Whether The Given Number Is Prime Or Not.","Week 2: Write A Program To Implement Simple Calculator Program. Write A Program To Generate Calendar For The Given Month And Year. Write A Program To Illustrate Different Set Operations.","Week 3: Write A Program To Implement Simple Chat Bot.","Week 4: Write A Program To Remove Punctuations From The Given String. Write A Program To Sort The Sentence In Alphabetical Order.","Week 5: Write A Program To Implement Of Towers Of Hanoi Problem.","Week 6: Write A Program To Implement Breadth First Search.","Week 7: Write A Program To Implement Depth First Search.","Week 8: Write A Program To Implement Hill Climbing Algorithm.","Week 9: Write A Program To Implement A* Algorithm.","Week 10: Write A Program To Implement Tic- Tac- Toe Game."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Student Should Decide On A Case Study And Formulate The Problem Statement.","Conceptual Designing Using ER Diagrams (Identifying Entities, Attributes, Keys And Relationships Between Entities, Cardinalities, Generalization, Specialization Etc.) Note: Student Is Required To Submit A Document By Drawing ER Diagram To The Lab Teacher.","Converting ER Model To Relational Model (Represent Entities And Relationships In Tabular Form, Represent Attributes As Columns, Identifying Keys) Note: Student Is Required To Submit A Document Showing The Database Tables Created From ER Model.","Normalization -To Remove The Redundancies And Anomalies In The Above Relational Tables, Normalize Up To Third Normal Form.","Creation Of Tables Using SQL-Overview Of Using SQL Tool, Data Types In SQL, Creating Tables (Along With Primary And Foreign Keys), Altering Tables And Dropping Tables.","Practicing DML Commands-Insert, Select, Update, Delete.","Practicing Queries Using ANY, ALL, IN, EXISTS, NOT EXISTS, UNION, INTERSECT, CONSTRAINTS Etc.","Practicing Sub Queries (Nested, Correlated) And Joins (Inner, Outer And Equi).","Practice Queries Using COUNT, SUM, AVG, MAX, MIN, GROUP BY, HAVING, VIEWS Creation And Dropping.","Practicing On Triggers - Creation Of Trigger, Insertion Using Trigger, Deletion Using Trigger, Updating Using Trigger."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Types of learning","Common aspects of machine learning approach: model","Parameters","Bias-Variance","Test, train and validation datasets","Error function","Curse of dimensionality","Predictive analysis using regression"]},{"title":"Python Basics","topics":["Fundamental data types in Python","Looping and decision-making constructs","Functions","Classes","File handling","Database access","Output formatting","Classes","Modules","Statistics module","Numpy","Introduction to popular machine learning libraries Tensor Flow & Keras"]},{"title":"Unsupervised Learning","topics":["Clustering","K-means","GMM & EM algorithm","Eigen values and Eigen vectors","PCA unsupervised dimensionality reduction technique"]},{"title":"Supervised Learning","topics":["Classification: KNN","Bayes","Decision Tree","SVM: soft and hard margin","Kernel trick","LDA - supervised dimensionality reduction technique"]},{"title":"Ensemble and Reinforcement Learning","topics":["Bagging","Random Forest and Boosting","Q-learning and SARSA algorithms"]},{"title":"Neural Networks","topics":["Introduction","Perceptron model","Learning rules and activation functions","Multi-layer feed forward","Back-propagation","Introduction to feed-back networks","Machine Learning. Tom Mitchell, McGraw-Hill.","Machine learning: an algorithmic perspective. Marsland, Stephen. Chapman and Hall/CRC, 2011.","Introduction to artificial neural systems. Zurada, Jacek M. Vol. 8. St. Paul: West publishing company, 1992.","A Tutorial on Support Vector Machines for Pattern Recognition. Christopher Burges, Data Mining and Knowledge Discovery, 1998"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Database system architecture","topics":["Data Abstraction","Data Independence","Data Definition Language (DDL)","Data Manipulation Language (DML)","Data models: Entity-relationship model","Network model","Relational and object oriented data models","Integrity constraints","Data manipulation operations","Unit 2.0: Relational query languages Relational algebra Tuple and domain relational calculus SQL3 DDL and DML constructs Open source and Commercial DBMS - MYSQL ORACLE DB2 SQL server Relational database design: Domain and data dependency Armstrong''s axioms Normal forms Dependency preservation Lossless design Query processing and optimization: Evaluation of relational algebra expressions Query equivalence Join strategies Query optimization algorithms","Relational algebra","Tuple and domain relational calculus","SQL3","DDL and DML constructs","Open source and Commercial DBMS - MYSQL","ORACLE","DB2","SQL server","Relational database design: Domain and data dependency","Armstrong''s axioms","Normal forms","Dependency preservation","Lossless design","Query processing and optimization: Evaluation of relational algebra expressions","Query equivalence","Join strategies","Query optimization algorithms"]},{"title":"Storage strategies","topics":["Indices","B-trees","Hashing"]},{"title":"Transaction processing","topics":["Concurrency control","ACID property","Serializability of scheduling","Locking and timestamp based schedulers","Multi-version and optimistic Concurrency Control schemes","Database recovery"]},{"title":"Database Security","topics":["Authentication","Authorization and access control","DAC, MAC and RBAC models","Intrusion detection","SQL injection"]},{"title":"Advanced topics","topics":["Object oriented and object relational databases","Logical databases","Web databases","Distributed databases","Data warehousing and data mining","\"Database System Concepts\", 6th Edition by Abraham Silberschatz, Henry F. Korth, S. Sudarshan, McGraw-Hill.","\"Principles of Database and Knowledge - Base Systems\", Vol 1 by J. D. Ullman, Computer Science Press.","\"Fundamentals of Database Systems\", 5th Edition by R. Elmasri and S. Navathe, Pearson Education","\"Foundations of Databases\", Reprint by Serge Abiteboul, Richard Hull, Victor Vianu, Addison - Wesley."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Overview of Data Communication and Networking","topics":["OSI Reference Model","TCP/IP Protocol Suite","Network Architecture and Physical Topology"]},{"title":"Physical Layer","topics":["Analog and Digital Signals","Transmission Impairment","Data Rate Limits","Performance Analysis of a Network","Representation and Synchronization of Bits","Analog and Digital Transmission","Multiplexing and Spreading Techniques","Guided Transmission Media","Circuit","Packet and Virtual Circuit Switching"]},{"title":"Data Link Layer","topics":["Framing","Flow and Error Control (Noiseless and Noisy Channels Protocols)","PointToPoint Protocol","Random Access protocols (Pure/slotted ALOHA, CSMA/CD, CSMA/CA)","Controlled Access Protocol (Bit-Map, Polling and Token Passing)","Channelization (TDMA, FDMA, CDMA)","Physical Addressing and Ethernet","Connecting LANs and Virtual LANs"]},{"title":"Network Layer","topics":["Internet Protocol version 4 and 6","Address Mapping (ARP, RARP, BOOTP and DHCP)","ICMP and IGMP","Routing Algorithms"]},{"title":"Transport Layer","topics":["UDP","TCP","Congestion Control and QoS","Client-Server Model and Socket Interface"]},{"title":"Application Layer","topics":["DNS","Remote Logging","Electronic Mail (SMTP, POP)","FTP","Introduction to WWW and HTTP","B. Forouzan, \"Data Communication and Network\", McGraw-Hill Publications. 4th ed.","A. S. Tanenbaum., \"Computer Networks\", Pearson Education Asia. 5th ed.","W. Stalling, \"Data and Computer Communication\", PHI (EEE). 8th ed.","A. L. Garcia and I. Widjaja, \"Communication Networks: Fundamental Concepts and Key Architectures\", Tata McGraw-Hill. 2nd ed.","S. Sharma, \"A course in Computer Networks\", Kataria. 3rd ed."]}]'::jsonb from s;
