insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Discrete Fourier Transform (DFT)","topics":["Z-transform and DTFT","Frequency domain sampling (Sampling of DTFT)","DFT and its inverse","Zero padding","DFT as a linear transformation (matrix method)","Properties","Spectrum analysis using DFT","Filtering of long data sequences using DFT: overlap save method","Overlap add method"]},{"title":"Fast Fourier Transform (FFT)- Radix-2 FFT algorithms","topics":["Decimation-in-time (DIT-FFT) algorithm","Decimation-in-frequency (DIF-FFT) algorithm","Inverse DFT using FFT algorithms","Goertzel algorithm","Chirp-z transform algorithm"]},{"title":"Filter Concepts","topics":["Frequency response and filter characteristics","Phase delay and group delay","Zero-phase filter","Linear-phase filter","Simple FIR filters","Simple IIR filters","All pass filter","Minimum-phase system","Averaging filter","Comb filter","Digital resonator","Notch filter","Digital sinusoidal oscillator","Unit 4.0: FIR and IIR Digital Filter Desirability of linear-phase filters Frequency response of linear phase FIR filters Filter specifications: absolute specifications Relative specifications Analog filter specifications Design techniques: windowing Frequency sampling method Digital Hilbert transformer Analog filters Butterworth and Chebyshev approximation Bilinear transformation method Warping effect Spectral transformation Design of low pass High pass Band pass and band elimination filter","Desirability of linear-phase filters","Frequency response of linear phase FIR filters","Filter specifications: absolute specifications","Relative specifications","Analog filter specifications","Design techniques: windowing","Frequency sampling method","Digital Hilbert transformer","Analog filters","Butterworth and Chebyshev approximation","Bilinear transformation method","Warping effect","Spectral transformation","Design of low pass","High pass","Band pass and band elimination filter"]},{"title":"Realizations of Digital Filters","topics":["FIR filter structures: direct form","Cascade form","Linear-phase form","FIR Lattice structure","IIR filter structures: direct form-I","Direct form-II","Cascade form","Parallel form","All pole lattice structure","Lattice-ladder (pole-zero) lattice structure"]},{"title":"Multirate Signal Processing","topics":["Decimation","Interpolation","The polyphase decomposition","Digital filter banks","Nyquist filters","Two-channel QMF","Digital Signal Processing by Alan V. Oppenheim, Ronald W. Schafer, PHI","S K Mitra, Digital Signal Processing-A Computer Based Approach, Tata McGraw Hill.","Digital Signal Processing by John G. Proakis, Dimitris K Manolakis, Pearson."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Alphabet","Languages and grammars","Productions and derivation","Chomsky hierarchy of languages"]},{"title":"Regular languages and finite automata","topics":["Regular expressions and languages","Deterministic finite automata (DFA) and equivalence with regular expressions","Nondeterministic finite automata (NFA) and equivalence with DFA","Regular grammars and equivalence with finite automata","Properties of regular languages","Pumping lemma for regular languages","Minimization of finite automata"]},{"title":"Context-free languages and pushdown automata","topics":["Context-free grammars (CFG) and Context-free languages (CFL)","Chomsky and Greibach normal forms","Nondeterministic pushdown automata (PDA) and equivalence with CFG","Parse trees","Ambiguity in CFG","Pumping lemma for context-free languages","Deterministic pushdown automata","Closure properties of CFLs"]},{"title":"Context-sensitive languages","topics":["Context-sensitive grammars (CSG) and Context-sensitive languages","Linear bounded automata and equivalence with CSG"]},{"title":"Turing machines","topics":["The basic model for Turing machines (TM)","Turing recognizable (Recursively enumerable) and Turing-decidable (recursive) languages and their closure properties","Variants of Turing machines","Nondeterministic TMs and equivalence with deterministic TMs","Unrestricted grammars and equivalence with Turing machines","TMs as enumerators"]},{"title":"Undecidability","topics":["Church-Turing thesis","Universal Turing machine","The universal and diagonalization languages","Reduction between languages and Rice''s theorem","Undecidable problems about languages","John E. Hopcroft, Rajeev Motwani and Jeffrey D. Ullman, Introduction to Automata Theory, Languages, and Computation, Pearson Education Asia.","Harry R. Lewis and Christos H. Papadimitriou, Elements of the Theory of Computation, Pearson Education Asia.","Dexter C. Kozen, Automata and Computability, Undergraduate Texts in Computer Science, Springer.","Michael Sipser, Introduction to the Theory of Computation, PWS Publishing.","John Martin, Introduction to Languages and the Theory of Computation, Tata McGraw Hill."]}]'::jsonb from s;
