insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Security Concepts (7 hrs) Introduction The Need For Security Security Approaches Principles Of Security Types Of Security Attacks Security Services Security Mechanisms A Model For Network Security Cryptography Concepts And Techniques: Introduction Plain Text And Cipher Text Substitution Techniques Transposition Techniques Encryption And Decryption Symmetric And Asymmetric Key Cryptography Stenography Key Range And Key Size Possible Types Of Attacks","Introduction","The Need For Security","Security Approaches","Principles Of Security","Types Of Security Attacks","Security Services","Security Mechanisms","A Model For Network Security","Cryptography Concepts And Techniques: Introduction","Plain Text And Cipher Text","Substitution Techniques","Transposition Techniques","Encryption And Decryption","Symmetric And Asymmetric Key Cryptography","Stenography","Key Range And Key Size","Possible Types Of Attacks"]},{"title":"Block Ciphers and Symmetric Key Cryptography (7 hrs)","topics":["Symmetric Key Ciphers: Block Cipher Principles- DES","AES","Blowfish","RC5","International Data Encryption Algorithm (IDEA)","Block Cipher Operation Modes","Stream Ciphers - RC4"]},{"title":"Number Theory and Asymmetric Key Cryptography (8 hrs)","topics":["Number Theory: Prime And Relatively Prime Numbers","Modular Arithmetic","Fermat''S And Euler''S Theorems","Testing For Primality","The Chinese Remainder Theorem","Discrete Logarithms","Asymmetric Key Ciphers: Principles Of Public Key Cryptosystems","The RSA Algorithm","Diffie Hellman Key Exchange","Elgamal Encryption & Decryption","Knapsack Algorithm","Unit 4.0: Cryptographic Hash Functions, Authentication, and Digital Signatures (7 hrs) Cryptographic Hash Functions: Message Authentication Secure Hash Algorithm (SHA- 512) Message Authentication Codes: Authentication Requirements HMAC CMAC Digital Signatures Elgamal Digital Signature Scheme Key Management And Distribution: Symmetric Key Distribution Using Symmetric & Asymmetric Encryption Distribution Of Public Keys Kerberos X.509 Authentication Service Public - Key Infrastructure","Cryptographic Hash Functions: Message Authentication","Secure Hash Algorithm (SHA- 512)","Message Authentication Codes: Authentication Requirements","HMAC","CMAC","Digital Signatures","Elgamal Digital Signature Scheme","Key Management And Distribution: Symmetric Key Distribution Using Symmetric & Asymmetric Encryption","Distribution Of Public Keys","Kerberos","X.509 Authentication Service","Public - Key Infrastructure"]},{"title":"Transport Layer Security and Wireless Network Security (6 hrs)","topics":["Transport- Level Security: Web Security Considerations","Secure Socket Layer And Transport Layer Security","HTTPS","Secure Shell (SSH)","Wireless Network Security: Wireless Security","Mobile Device Security","IEEE 802.11 Wireless LAN","IEEE 802.11I Wireless LAN Security","Unit 6.0: E- Mail and IP Security: Concepts and Applications (7 hrs) E- Mail Security: Pretty Good Privacy S/MIME IP Security: IP Security Overview IP Security Architecture Authentication Header Encapsulating Security Payload Combining Security Associations Internet Key Exchange Case Studies On Cryptography And Security: Secure Multiparty Calculation Virtual Elections Single Sign On Secure Inter- Branch Payment Transactions Cross Site Scripting Vulnerability","E- Mail Security: Pretty Good Privacy","S/MIME","IP Security: IP Security Overview","IP Security Architecture","Authentication Header","Encapsulating Security Payload","Combining Security Associations","Internet Key Exchange","Case Studies On Cryptography And Security: Secure Multiparty Calculation","Virtual Elections","Single Sign On","Secure Inter- Branch Payment Transactions","Cross Site Scripting Vulnerability","Cryptography and Network Security: Principles and Practice William, Stallings, Pearson Education, 8th Edition (2022), ISBN- 13: 978- 1292437480.","Cryptography and Network Security, Atul Kahate, McGraw Hill Education India Pvt Ltd, 3rd Edition (2017), ISBN- 13: 978- 1259029882.","Cryptography and Network Security, Behrouz A. Forouzan, McGraw Hill Education, 3rd Edition (2015), ISBN- 13: 978- 0070702080.","Cryptography and Network Security, C.K. Shyamala, N. Harini, Dr. T.R. Padmanabhan, Wiley India, 1st Edition (2011), ISBN- 13: 978- 8126521793.","Information Security: Principles and Practice Mark Stamp, Wiley, 2nd Edition (2011), ISBN- 13: 978- 0470626399.","Principles of Computer Security: CompTIA Security+ and Beyond Wm. Arthur Conklin, Greg White, McGraw Hill Education, 5th Edition (2018), ISBN- 13: 978- 1260026375."]}]'::jsonb from s;
