insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to IoT Communication Protocols (6 hrs)","topics":["Overview Of IoT Communication","Need For Communication Protocols In IoT","Comparison Of IoT Communication With Traditional Communication","IoT Communication Stack (OSI & TCP/IP Model In IoT)"]},{"title":"Data Link Layer Protocols in IoT Communication (8 hrs)","topics":["Role Of Data Link Layer In IoT","PHY/MAC Layer (3GPP MTC, IEEE 802.11, IEEE 802.15)","Wireless HART","Z- Wave","Bluetooth Low Energy","Zigbee Smart Energy","RFID And NFC","DASH7"]},{"title":"Addressing and Network Layer Protocols in IoT (7 hrs)","topics":["IPv4 Vs. IPv6","6LoWPAN","6TiSCH","ND","DHCP","ICMP","And IoT Routing Protocols (RPL, CORPL, CARP)"]},{"title":"IoT Transport Layer (8 hrs)","topics":["Connection Models","Protocols","And Secure Communication: Overview Of Transport Layer In IoT","Connection- Oriented Vs. Connectionless Protocols","Transport Protocols Used In IoT: TCP","MPTCP","UDP","DCCP","SCTP","Security And Reliability In IoT Transport Layer: TLS","DTLS"]},{"title":"Session Layer in IoT Communication (7 hrs)","topics":["Role Of The Session Layer In IoT Data Exchange","Key Requirements For IoT Application Protocols (Scalability, Security, Latency)","Lightweight Protocols Vs Traditional Protocols","Protocols For IoT Communication: HTTP","CoAP","XMPP","AMQP","MQTT","DDS"]},{"title":"IoT Security & Emerging Communication Trend (6 hrs)","topics":["Security Challenges In IoT Communication","Emerging IoT Communication Technologies: LoRaWAN","5G And IoT Technologies","Edge Computing & Fog Networking For IoT Communication","Internet of Things: Architecture and Design Principles Raj Kamal McGraw Hill; 2nd Edition, (ISBN: 9789390727384).","IoT Fundamentals: Networking Technologies, Protocols, and Use Cases for the Internet of Things, David Hanes, Gonzalo Salgueiro, Patrick Grossetete, Robert Barton, Jerome Henry, Pearson Education, 1st Edition, (ISBN: 978-1587144561).","Building the Internet of Things with IPv6 and MIPv6: The Evolving World of M2M Communications, Daniel Minoli, Wiley Publications, 2016, (ISBN: 978-1-118-473474)."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to IoT and IoT Analytics (6 hrs)","topics":["Introduction To IoT","Applications","IoT Architectures And Components","Fundamental To Analytics","IoT Analytics Challenges"]},{"title":"IoT Devices and Networking Protocols (7 hrs)","topics":["Overview Of IoT Devices And Sensors","Basics Of Networking For IoT","IoT Connectivity Protocols (E.G., Wi- Fi, Bluetooth, Zigbee, LoRaWAN)","IoT Data Messaging Protocols (MQTT, CoAP, AMQP, Etc.)","Analyzing Network Data To Infer Device Characteristics"]},{"title":"IoT Analytics for the Cloud (7 hrs)","topics":["Introduction To Elastic Analytics","Decouple Key Components","Cloud Security And Analytics","Designing Data Processing For Analytics","Applying Big Data Technology To Storage"]},{"title":"Exploring IoT Data (8 hrs)","topics":["Exploring And Visualizing IoT Data","Techniques To Assess Data Quality In IoT","Preprocessing IoT Data For Analytics","Basic Time Series Analysis In IoT","Statistical Analysis For IoT Applications"]},{"title":"Machine Learning and IoT Analytics (7 hrs)","topics":["Introduction To Machine Learning For IoT","Feature Engineering With IoT Data","Validation Methods In IoT Analytics","Need Of The Bias- Variance Tradeoff","Use Cases Of Machine Learning In IoT"]},{"title":"Advanced Topics in IoT Analytics (7 hrs)","topics":["Deep Learning Techniques For IoT Analytics","Predictive Analytics And Anomaly Detection In IoT","Edge AI And On- Device Analytics","Ethical Considerations And Challenges In IoT Analytics","Empowering IoT with Big Data Analytics, Mohamed Adel Serhani, Elsevier, 1st Edition (2024), ISBN: 9780443216404.","Internet of Things and Data Analytics Handbook, Hwaiyu Geng, Wiley, 1st Edition (2017), ISBN: 97811119173649.","Innovations in Computational Intelligence, Big Data Analytics, and Internet of Things, Hounding Song, Information Age Publishing, 1st Edition (2023), ISBN: 9781648025281.","Intelligent Network Design Driven by Big Data Analytics, IoT, AI, and Cloud Computing, D. Jude Hemanth, The Institution of Engineering and Technology, 1st Edition (2023), ISBN: 9781839535338."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction to Web Development and AI (8 hrs) Overview Of Web Programming: Understanding The Fundamentals Of Web Development - Including Client- Side And Server- Side Scripting Languages Introduction To Artificial Intelligence (AI): Definition, Scope And Applications Of AI In Various Fields Intersection Of Web Development And AI: Exploring How AI Technologies Enhance Web Applications And User Experiences Tools And Technologies: Introduction To Essential Tools And Technologies For Web Development And AI Integration","Overview Of Web Programming: Understanding The Fundamentals Of Web Development - Including Client- Side And Server- Side Scripting Languages","Introduction To Artificial Intelligence (AI): Definition, Scope And Applications Of AI In Various Fields","Intersection Of Web Development And AI: Exploring How AI Technologies Enhance Web Applications And User Experiences","Tools And Technologies: Introduction To Essential Tools And Technologies For Web Development And AI Integration","Unit 2.0: Front end Development and AI Integration (8 hrs) What Is HTML: History, HTML Documents - Basic Structure - Creating An HTML Document - Features And Limitations - Mark Up Tags - Heading- Paragraphs - Line Breaks - HTML Tags - Formatting Tags Introduction To Elements Of HTML - Working With Text Working With Lists, Tables And Frames - Working With Hyperlinks - Images - Image Format (Quality, Size, Type, ...) - Importing Images (Scanners) - Working With Forms And Controls Responsive Web Design: Techniques For Creating Web Applications That Adapt To Different Screen Sizes And Devices Introduction To AI Libraries And APIs: Overview Of Popular AI Libraries And APIs For Frontend Integration","What Is HTML: History, HTML Documents - Basic Structure - Creating An HTML Document - Features And Limitations - Mark Up Tags - Heading- Paragraphs - Line Breaks - HTML Tags - Formatting Tags","Introduction To Elements Of HTML - Working With Text","Working With Lists, Tables And Frames - Working With Hyperlinks - Images - Image Format (Quality, Size, Type, ...) - Importing Images (Scanners) - Working With Forms And Controls","Responsive Web Design: Techniques For Creating Web Applications That Adapt To Different Screen Sizes And Devices","Introduction To AI Libraries And APIs: Overview Of Popular AI Libraries And APIs For Frontend Integration","Unit 3.0: Introduction to Cascading Style Sheets (8 hrs) Concept Of CSS - Creating Style Sheet, CSS Properties - CSS Styling (Background, Text Format, Controlling Fonts) - Working With Block Elements And Objects - Working With Lists And Tables - CSS Id And Class Box Model (Introduction, Border Properties, Padding Properties, Margin Properties) - CSS Advanced (Grouping, Dimension, Display, Positioning - Floating, Align, Pseudo Class - Navigation Bar - Image Sprites - Attribute Sector) - CSS Color - Creating Page Layout And Site Designs","Concept Of CSS - Creating Style Sheet, CSS Properties - CSS Styling (Background, Text Format, Controlling Fonts) - Working With Block Elements And Objects - Working With Lists And Tables - CSS Id And Class Box Model (Introduction, Border Properties, Padding Properties, Margin Properties) - CSS Advanced (Grouping, Dimension, Display, Positioning - Floating, Align, Pseudo Class - Navigation Bar - Image Sprites - Attribute Sector) - CSS Color - Creating Page Layout And Site Designs","Unit 4.0: Introduction to Web Publishing, Multimedia and Hosting (6 hrs) Creating The Web Site - Saving The Site Working On The Web Site - Creating Web Site Structure - Creating Titles For Web Pages Themes - Publishing Web Sites - Inserting Audio Files - Video Files And Acceptable Formats (MPEG, Quick Time - Video For Windows) Inserting Video Files - Screen Control Attributes (WIDTH, HEIGHT, ALIGN) - Start Control Attributes (START, FILEOPEN, LOOP, LOOPDELAY, And MOUSEOVER) - Basic Concepts Of Images: Digital Images And Digital Image Representation - Image Formats: TIFF, BMP, JPG/JPEG, GIF, And PIC.PDF Hosting Basics - Types Of Hosting","Creating The Web Site - Saving The Site Working On The Web Site - Creating Web Site Structure - Creating Titles For Web Pages Themes - Publishing Web Sites - Inserting Audio Files - Video Files And Acceptable Formats (MPEG, Quick Time - Video For Windows)","Inserting Video Files - Screen Control Attributes (WIDTH, HEIGHT, ALIGN) - Start Control Attributes (START, FILEOPEN, LOOP, LOOPDELAY, And MOUSEOVER) - Basic Concepts Of Images: Digital Images And Digital Image Representation - Image Formats: TIFF, BMP, JPG/JPEG, GIF, And PIC.PDF","Hosting Basics - Types Of Hosting"]},{"title":"Introduction to React and core concept (6 hrs)","topics":["Overview","JSX","And React Components","Props","State","And Component Lifecycle Methods"]},{"title":"React Router, State Management, Hooks (6 hrs)","topics":["Navigation And Routing In Single- Page Applications","Context API And Redux For Global State","Use State","Use Effect","And Custom Hooks","\"Building Intelligent Web Applications: How to Get Started with Artificial Intelligence- Driven Web Applications\" by Mark Watson (Year: 2019)","Web Development with Artificial Intelligence\" by Ibrahim Naji (Year: 2020)","\"Learning React: Functional Web Development with React and Redux\" by Alex Banks and Eve Porcello","\"React Design Patterns and Best Practices\" by Carlos Santana Roldán","AI for Web Development: Leverage the Power of Machine Learning and Deep Learning to Build Smart Web Applications\" by Sandeep Kumar Patel (Year: 2019)","\"Full stack React: The Complete Guide to ReactJS and Friends\" by Accomazzo, Murray, and Lerner."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Mathematical Logic and Set Theory (7 hrs)","topics":["Propositional Logic: Statements","Connectives","Well- Formed Formulas","Truth Tables","Tautologies Normal Forms","Predicate Logic: Quantifiers","Free And Bound Variables","Inference Theory","Set Theory: Operations On Sets","Principle Of Inclusion- Exclusion","Relations (Equivalence, Partial Ordering)","Hasse Diagrams"]},{"title":"Number Theory and Algebraic Structures (7 hrs)","topics":["Number Theory: Congruences","Modular Arithmetic","Fermat''S Theorem","Euler''S Theorem","Chinese Remainder Theorem","Algebraic Structures: Groups","Subgroups","Cosets","Normal Subgroups","Lagrange''S Theorem","Rings","Fields","Homomorphism & Isomorphism"]},{"title":"Probability and Statistics for IoT (7 hrs)","topics":["Counting Principles: Permutations And Combinations","Binomial Theorem","Probability: Conditional Probability","Bayes'' Theorem","Random Variables: Discrete & Continuous","Expectation","Variance","Distributions: Binomial","Poisson","Normal Distributions","Moment Generating Functions","Inequalities: Markov''S And Chebyshev''S Inequalities"]},{"title":"Graph Theory and Network Structures (7 hrs)","topics":["Graph Basics: Eulerian & Hamiltonian Graphs","Adjacency & Incidence Matrices","Graph Traversals: BFS","DFS","Shortest Path (Dijkstra''S, Floyd- Warshall)","Graph Coloring & Covering: Chromatic Number","Planar Graphs","Kuratowski''S Theorem","Trees: Spanning Trees","Prim''S & Kruskal''S Algorithms","Weighted Trees","Max- Flow Min- Cut Theorem"]},{"title":"Recurrence Relations and Generating Functions (7 hrs)","topics":["Recurrence Relations: Generating Functions","Function Of Sequences","Partial Fractions","Calculating Coefficient Of Generating Functions","Solving Homogeneous & Non- Homogeneous Recurrence Relations"]},{"title":"Linear Algebra for IoT and Data Analysis (7 hrs)","topics":["Vector Spaces: Basis","Dimension","Linea