insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Pattern Recognition","topics":["Definition","Applications of Pattern Recognition","Supervised vs. Unsupervised Learning","Statistical vs. Structural Pattern Recognition","Pattern Recognition System Design","Overview of Feature Extraction and Selection"]},{"title":"Statistical Pattern Recognition","topics":["Bayes Decision Theory","Maximum Likelihood Estimation","Bayesian Classifier","Naïve Bayes Classifier","Parametric and Non-Parametric Approaches","K-Nearest Neighbors (KNN)","Probabilistic Graphical Models"]},{"title":"Feature Extraction and Dimensionality Reduction","topics":["Feature Selection Techniques","Principal Component Analysis (PCA)","Linear Discriminant Analysis (LDA)","Independent Component Analysis (ICA)","Singular Value Decomposition (SVD)","Feature Engineering for Pattern Recognition"]},{"title":"Machine Learning for Pattern Recognition","topics":["Support Vector Machines (SVM)","Decision Trees","Random Forest","Neural Networks (MLP, CNNs)","Deep Learning Approaches","Autoencoders","Performance Evaluation Metrics (Precision, Recall, F1-score, ROC Curve)"]},{"title":"Clustering and Unsupervised Learning","topics":["K-Means Clustering","Hierarchical Clustering","DBSCAN","Gaussian Mixture Models (GMM)","Self-Organizing Maps (SOM)","Hidden Markov Models (HMM)","Applications of Clustering in Pattern Recognition"]},{"title":"Applications and Emerging Trends","topics":["Pattern Recognition in Image Processing","Speech Recognition","Biometrics","Natural Language Processing (NLP)","Object Detection and Recognition","Al-driven Pattern Recognition","Ethical Considerations in Pattern Recognition","Richard O. Duda, Peter E. Hart, David G. Stork - Pattern Classification, Wiley.","Sergios Theodoridis, Konstantinos Koutroumbas - Pattern Recognition, Academic Press.","C. M. Bishop - Pattern Recognition and Machine Learning, Springer.","S. Haykin - Neural Networks