insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Basic definitions","Linear Algebra","Statistical learning theory","Types of learning","Hypothesis space and Inductive bias","Evaluation and cross validation","Optimization"]},{"title":"Statistical Decision Theory and Learning Statistical Decision Theory Bayesian Learning","topics":["Statistical Decision Theory","Bayesian Learning (ML, MAP, Bayes estimates, Conjugate priors)","Linear Regression","Ridge Regression","Lasso","Principal Component Analysis","Partial Least Squares"]},{"title":"Linear Classification and Advanced Models Linear Classification Logistic Regression Linear","topics":["Linear Classification","Logistic Regression","Linear Discriminant Analysis","Quadratic Discriminant Analysis","Perceptron","Support Vector Machines + Kernels","Artificial Neural Networks + Back Propagation","Decision Trees","Bayes Optimal Classifier","Naive Bayes"]},{"title":"Hypothesis testing and Ensemble Methods Hypothesis testing Ensemble Methods Bagging","topics":["Hypothesis testing","Ensemble Methods","Bagging Adaboost Gradient Boosting"]},{"title":"Clustering Clustering K-means K-medoids Density-based Hierarchical Spectral","topics":["Clustering","K-means","K-medoids","Density-based Hierarchical","Spectral"]},{"title":"Advanced Learning Theory","topics":["Expectation Maximization","GMMs","Learning theory Intro to Reinforcement Learning","Bayesian Networks","Machine Learning. Tom Mitchell. First Edition, McGraw-Hill, 1997","Introduction to Machine Learning Edition 2, by Ethem Alpaydin.","J. Shavlik and T. Dietterich (Ed), Readings in Machine Learning, Morgan Kaufmann, 1990.","P. Langley, Elements of Machine Learning, Morgan Kaufmann, 1995.","Understanding Machine Learning. Shai Shalev-Shwartz and Shai Ben-David. Cambridge University Press. 2017. [SS-2017]","The Elements of Statistical Learning. Trevor Hastie, Robert Tibshirani and Jerome Friedman. Second Edition. 2009. [TH-2009]"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Formal Language and Regular Expressions","topics":["Formal Language and Regular Expressions Languages","Definition Languages regular expressions","Finite Automata - DFA","NFA","Conversion of regular expression to NFA","NFA to DFA"]},{"title":"Applications and Context Free Grammars","topics":["Applications of Finite Automata to lexical analysis","Lex tools","Context Free grammars and parsing: Context free grammars","Derivation","Parse trees","Ambiguity LL(K) grammars and LL(1) parsing"]},{"title":"Bottom up parsing and Semantics","topics":["Bottom up parsing handle pruning LR Grammar Parsing","LALR parsing","Parsing ambiguous grammars","YACC programming specification","Semantics: Syntax directed translation","S-attributed and L-attributed grammars","Intermediate code abstract syntax tree","Translation of simple statements and control flow statements"]},{"title":"Context Sensitive features and Type checking","topics":["Context Sensitive features - Chomsky hierarchy of languages and recognizers","Type checking","Type conversions","Equivalence of type expressions","Overloading of functions and operations"]},{"title":"Run time storage and Code optimization","topics":["Run time storage: Storage organization","Storage allocation strategies scope access to now local names","Parameters","Language facilities for dynamics storage allocation","Code optimization: Principal sources of optimization","Optimization of basic blocks","Peephole optimization","Flow graphs","Data flow analysis of flow graphs"]},{"title":"Code generation","topics":["Code generation Machine dependent code generation","Object code forms","Generic code generation algorithm","Register allocation and assignment","Using DAG representation of Blocks","Introduction to Theory of computation. Sipser, 2nd Edition, Thomson.","Compilers Principles, Techniques and Tools Aho, Ullman, Ravisethi, Pearson Education.","Modern Compiler Construction in C, Andrew W.Appel Cambridge University Press.","Compiler Construction, LOUDEN, Thomson.","Elements of Compiler Design, A. Meduna, Auerbach Publications, Taylor and Francis Group.","Principles of Compiler Design, V. Raghavan, TMH.","Engineering a Compiler, K. D. Cooper, L. Torczon, ELSEVIER."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Ad Hoc and Sensor Networks","topics":["Characteristics of ad hoc wireless networks","Applications of ad hoc networks","Challenges in ad hoc networks","Wireless sensor networks (WSN) - Characteristics and applications","Design issues in WSN","Sensor network architecture - Layered architecture","Cross-layer design"]},{"title":"MAC Protocols for Ad Hoc and Sensor Networks","topics":["Fundamentals of MAC design","Issues in designing MAC protocols","MAC protocols for ad hoc networks Contention-based protocols (Aloha, CSMA, MACA, MACAW)","Scheduling-based MAC protocols","MAC protocols for WSN - S-MAC, T-MAC, B-MAC, X-MAC","Energy-efficient MAC protocols"]},{"title":"Routing Protocols in Ad Hoc and Sensor Networks","topics":["Challenges in routing","Proactive vs. Reactive routing","Ad hoc routing protocols - AODV, DSR, DSDV, OLSR","Hybrid routing (ZRP)","Hierarchical routing","Geographic routing","Routing protocols for WSN Flooding, SPIN, LEACH, TEEN","Directed diffusion","Geographic and Energy-Aware Routing (GEAR)"]},{"title":"Transport and Energy Management in Wireless Sensor Networks","topics":["Issues in transport protocols","TCP over ad hoc networks","Transport protocols for WSN - CODA, RMST, PSFQ, ESRT","Energy-efficient routing in WSN","Data aggregation","Clustering techniques for WSN","Energy harvesting in sensor networks","Sleep-wake scheduling algorithms"]},{"title":"Localization, Synchronization, and Data Dissemination in WSN","topics":["Localization techniques - GPS-based localization","Range-based localization (RSSI, TOA, TDOA, AOA)","Range-free localization (Centroid, DV-Hop, APIT)","Time synchronization in WSN - RBS, TPSN","Data dissemination and query processing in WSN","Mobile sink-based data collection","Unit 6.0: Security and Emerging Trends in Ad Hoc and Sensor Networks Security issues in ad hoc and sensor networks Attack models - Eavesdropping, Sybil attack, Blackhole, Wormhole Intrusion detection in WSN Secure routing in ad hoc networks Privacy-preserving techniques Emerging trends Mobile ad hoc networks (MANETs) Vehicular ad hoc networks (VANETS) Cognitive radio sensor networks (CRSN) AI/ML applications in WSN","Security issues in ad hoc and sensor networks","Attack models - Eavesdropping, Sybil attack, Blackhole, Wormhole","Intrusion detection in WSN","Secure routing in ad hoc networks","Privacy-preserving techniques","Emerging trends Mobile ad hoc networks (MANETs)","Vehicular ad hoc networks (VANETS)","Cognitive radio sensor networks (CRSN)","AI/ML applications in WSN","C. Siva Ram Murthy, B.S. Manoj, Ad Hoc Wireless Networks: Architectures and Protocols, Pearson, 2004.","Feng Zhao, Leonidas Guibas, Wireless Sensor Networks: An Information Processing Approach, Elsevier, 2004.","Holger Karl, Andreas Willig, Protocols and Architectures for Wireless Sensor Networks, Wiley, 2005.","C. K. Toh, Ad Hoc Mobile Wireless Networks: Protocols and Systems, Pearson, 2002.","Edgar H. Callaway, Wireless Sensor Networks: Architectures and Protocols, CRC Press, 2003.","Thomas Haenselmann, Wireless Sensor Networks: Design Principles for Scalable Distributed Systems, Springer, 2007.","Kazem Sohraby, Daniel Minoli, Taieb Znati, Wireless Sensor Networks: Technology, Protocols, and Applications, Wiley, 2007."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Definition of morality and ethics in AI","AI","And society"]},{"title":"Impact of AI","topics":["Impact on society","Impact on human psychology","Impact on the legal system","Impact on the environment and the planet","And Impact on trust"]},{"title":"Ethical Initiatives in AI","topics":["International ethical initiatives","Ethical harms","And concerns","Case study: healthcare robots","Autonomous Vehicles","Warfare","And weaponization"]},{"title":"AI Standards And Regulation","topics":["Model Process for Addressing Ethical Concerns During System Design","Transparency of Autonomous Systems","Data Privacy Process","Algorithmic Bias Considerations","Ontological Standard for Ethically Driven Robotics and Automation Systems"]},{"title":"Rob ethics: Social and Ethical Implication of Robotics","topics":["Robotics- Ethics and Morality","Moral Theories-Ethics in Science and Technology","Ethical Issues in an ICT Society","Harmonization of Principles","Ethics and Professional Responsibility","Robotics Taxonomy"]},{"title":"Challenges and Opportunities","topics":["Ethical issues in artificial intelligence","Societal Issues Concerning the Application of Artificial Intelligence in Medicine","Decision-making role in industries","And National and International Strategies on AI","Eleanor Bird, Jasmin Fox-Skelly, Nicola Jenner, Ruth Larbey, Emma Weitkamp and Alan Winfield,\" The ethics of artificial intelligence: Issues and initiatives\", EPRS | European Parliamentary Research Service Scientific Foresight Unit (STOA) PE 634.452- March 2020.","Patrick Lin, Keith Abney, George A Bekey,\" Robot Ethics: The Ethical and Social Implications of Robotics\", The MIT Press- January 2014.","Towards a Code of Ethics for Artificial Intelligence (Artificial Intelligence: Foundations, Theory, and Algorithms) by Paula Boddington, November 2017.","Mark Coeckelbergh,\" AI Ethics\", The MIT Press Essential Knowledge series, April 2020."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Constitution","topics":["Meaning of the constitution law and constitutionalism","Historical perspective of the Constitution of India","Salient features and characteristics of the Constitution of India"]},{"title":"Fundamental Rights and Duties","topics":["Scheme of the fundamental rights","The scheme of the Fundamental Duties and its legal status","The Directive Principles of State Policy - Its importance and implementation"]},{"title":"Federal Structure and Government","topics":["Federal structure and distribution of legislative and financial powers between the Union and the States","Parliamentary Form of Government in India - The constitution powers and status of the President of India"]},{"title":"Amendments","topics":["Amendment of the Constitutional Powers and Procedure","The historical perspectives of the constitutional amendments in India"]},{"title":"Emergency Provisions and Local Self Government","topics":["Emergency Provisions: National Emergency","President Rule","Financial Emergency","Local Self Government - Constitutional Scheme in India"]},{"title":"Scheme of Rights","topics":["Scheme of the Fundamental Right to Equality","Scheme of the Fundamental Right to certain Freedom under Article 19","Scope of the Right to Life and Personal Liberty under Article 21","\"Constitution of India\" (for Competitive Exams) Published by Naidhruva Edutech Learning Solutions, Bengaluru. - 2022.","\"Introduction to the Constitution of India\", (Students Edition.) by Durga Das Basu (DD Basu): Prentice-Hall, 2008.","\"Constitution of India, Professional Ethics and Human Rights\" by Shubham Singles, Charles E. Haries, and et al: published by Cengage Learning India, Latest Edition - 2019.","\"The Constitution of India\" by Merunandan K B: published by Merugu Publication, Second Edition, Bengaluru.","\"Samvidhana Odu\" - for Students & Youths by Justice HN Nagamohan Dhas, Sahayana, kerekon.","M.Govindarajan, S.Natarajan, V.S.Senthilkumar, \"Engineering Ethics\", Prentice-Hall, 2004."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Cloud Computing","topics":["Definition and characteristics of cloud computing","Cloud service models (IaaS, PaaS, SaaS)","Deployment models (Public, Private, Hybrid, Multi-cloud)","Cloud computing architecture","Virtualization in cloud computing","Hypervisors (VMware, KVM, Xen)"]},{"title":"Cloud Networking Basics","topics":["Cloud network architecture","Software-Defined Networking (SDN)","Network Functions Virtualization (NFV)","Virtual Private Cloud (VPC)","Content Delivery Networks (CDN)","Cloud load balancing and traffic management"]},{"title":"Cloud Storage and Data Management","topics":["Cloud storage models (Object, Block, File storage)","Distributed file systems (Google File System, Hadoop HDFS)","Cloud database services (NoSQL, NewSQL)","Data consistency and replication","Cloud backup and disaster recovery"]},{"title":"Cloud Security and Compliance","topics":["Cloud security challenges","Identity and Access Management (IAM)","Encryption in cloud","Secure cloud networking (VPN, TLS, SSL)","Compliance standards (ISO 27001, GDPR, HIPAA)","Zero Trust security in cloud environments"]},{"title":"Cloud Deployment and Orchestration","topics":["Containerization (Docker, Kubernetes)","Serverless computing","Cloud automation (Terraform, Ansible)","Multi-cloud and hybrid cloud management","Microservices architecture in cloud","Edge computing and IoT integration"]},{"title":"Emerging Trends and Case Studies","topics":["AI and Machine Learning in cloud computing","Blockchain for cloud security","Quantum computing and cloud","Case studies on real-world cloud deployments (AWS, Azure, Google Cloud)","Future trends in cloud networking","Rajkumar Buyya, Christian Vecchiola, S. Thamarai Selvi, Mastering Cloud Computing, McGraw Hill.","Thomas Erl, Ricardo Puttini, Zaigham Mahmood, Cloud Computing: Concepts, Technology & Architecture, Pearson.","Anthony T. Velte, Toby J. Velte, Robert Elsenpeter, Cloud Computing: A Practical Approach, McGraw Hill.","Arshdeep Bahga & Vijay Madisetti, Cloud Computing: A Hands-on Approach, Universities Press.","Kai Hwang, Geoffrey Fox, Jack Dongarra, Distributed and Cloud Computing, Elsevier.","George Reese, Cloud Application Architectures: Building Applications and Infrastructure in the Cloud, O''Reilly.","Benedict Blundell, Docker and Kubernetes for Cloud Networking, Packt Publishing."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Distributed Computing","topics":["Definition","Characteristics of distributed systems","Types of distributed architectures (client-server, peer-to-peer, multi-tier)","Distributed system models","Advantages and challenges","Design issues"]},{"title":"Inter-Process Communication & Synchronization","topics":["Message passing mechanisms","Remote Procedure Call (RPC)","Remote Method Invocation (RMI)","Synchronization in distributed systems","Logical clocks (Lamport & Vector clocks)","Mutual exclusion algorithms (Ricart-Agrawala, Maekawa''s algorithm)"]},{"title":"Distributed Algorithms and Fault Tolerance","topics":["Leader election algorithms (Bully, Ring)","Distributed consensus (Paxos, RAFT)","Load balancing strategies","Distributed deadlock detection","Fault tolerance models","Checkpointing and recovery techniques"]},{"title":"Distributed File Systems and Databases","topics":["Distributed file systems (NFS, AFS, Google File System)","Distributed databases (CAP theorem, NoSQL, Replication & Consistency models)","Two-phase & three-phase commit protocols","Cloud-based storage architectures"]},{"title":"Distributed Computing Frameworks & Middleware","topics":["Hadoop ecosystem (HDFS, MapReduce, YARN)","Apache Spark","Distributed middleware (CORBA, JINI, Web services)","Edge and Fog Computing","Serverless computing"]},{"title":"Emerging Trends and Case Studies","topics":["Microservices and Kubernetes","Blockchain in distributed environments","AI and ML in distributed systems","Internet of Things (IoT) and distributed processing","Case studies on real-world distributed applications (Google Spanner, Amazon DynamoDB)","Andrew S. Tanenbaum & Maarten Van Steen, Distributed Systems: Principles and Paradigms, Pearson.","George Coulouris, Jean Dollimore, Tim Kindberg, Distributed Systems: Concepts and Design, Pearson.","Mukesh Singhal & Niranjan G. Shivaratri, Advanced Concepts in Operating Systems: Distributed, Database, and Multiprocessor Operating Systems, McGraw Hill.","Ajay D. Kshemkalyani & Mukesh Singhal, Distributed Computing: Principles, Algorithms, and Systems, Cambridge University Press.","Hagit Attiya & Jennifer Welch, Distributed Computing: Fundamentals, Simulations, and Advanced Topics, Wiley.","Tom White, Hadoop: The Definitive Guide, O''Reilly.","Martin Kleppmann, Designing Data-Intensive Applications, O''Reilly."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Network Security","topics":["Security fundamentals","Security threats and attack vectors","Vulnerability assessment","Security policies and risk management","Overview of cybersecurity frameworks"]},{"title":"Cryptography and Key Management","topics":["Symmetric key cryptography (DES, AES, RC4)","Asymmetric key cryptography (RSA, ECC)","Key exchange algorithms (Diffie-Hellman, Public Key Infrastructure PKI)","Hash functions (SHA, MD5)","Digital signatures and certificates"]},{"title":"Authentication and Access Control","topics":["User authentication methods (passwords, multi-factor authentication, biometrics)","Access control models (DAC, MAC, RBAC)","Single Sign-On (SSO)","OAuth","Kerberos authentication","Zero Trust security model"]},{"title":"Network Security Protocols","topics":["IPSec (AH, ESP)","Secure Socket Layer (SSL) and Transport Layer Security (TLS)","Virtual Private Networks (VPNs)","Wireless security protocols (WEP, WPA, WPA2)","Email security (PGP, S/MIME)"]},{"title":"Firewalls, IDS, and Security Architectures","topics":["Types of firewalls (packet filtering, stateful, proxy-based)","Intrusion Detection and Prevention Systems (IDS/IPS)","Honeypots and deception technologies","Secure network design","Zero Trust Architecture"]},{"title":"Emerging Trends and Case Studies","topics":["Cloud security challenges and solutions","IoT security threats and countermeasures","AI and ML in cybersecurity","Blockchain for security","Case studies on recent cyber-attacks and defense strategies","William Stallings, Network Security Essentials: Applications and Standards, Pearson.","Behrouz A. Forouzan, Cryptography and Network Security, McGraw Hill.","Charlie Kaufman, Radia Perlman, Mike Speciner, Network Security: Private Communication in a Public World, Pearson.","Kaufman, Perlman, and Speciner, Network Security: Private Communication in a Public World, Pearson.","Douglas R. Stinson, Cryptography: Theory and Practice, CRC Press.","Niels Ferguson & Bruce Schneier, Practical Cryptography, Wiley.","Joseph Migga Kizza, Guide to Computer Network Security, Springer."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Fundamentals of Internet & Intranet","topics":["Introduction to Internet and Intranet","Evolution of networking","Internet architecture and standards","Intranet applications in enterprises","TCP/IP model","IPv4 vs IPv6","Domain Name System (DNS)","HTTP/HTTPS protocols"]},{"title":"Web Technologies and Communication Protocols","topics":["Web architecture","Client-server model","HTTP and Restful APIs","Web services (SOAP, REST)","FTP","SMTP","IMAP","WebSockets","Secure communication protocols (TLS, SSL)","Content Delivery Networks (CDN)"]},{"title":"Intranet Design & Enterprise Networking","topics":["Intranet components","Network design principles","VLANs and VPNs for intranet","Authentication and access control","Directory services (LDAP, Active Directory)","Single Sign-On (SSO)","Proxy servers and load balancing"]},{"title":"Cloud Computing and Virtualization","topics":["Introduction to cloud computing","Intranet integration with cloud services","Virtualization technologies (VMware, Hyper-V, KVM)","Software-defined networking (SDN)","Edge computing for intranet solutions","Serverless architecture"]},{"title":"Security and Performance Optimization","topics":["Security threats in intranet and internet environments","Firewalls and IDS/IPS","Zero Trust Security model","Performance tuning and caching strategies","Content optimization (compression, minification, lazy loading)","Secure API development"]},{"title":"Emerging Trends and Case Studies","topics":["IoT and Industrial Intranet","Blockchain for secure communication","AI-driven networking","Digital Twins for enterprise intranets","Case studies on large-scale intranet implementations","Future trends in Internet and Intranet technologies","Douglas E. Comer, Internetworking with TCP/IP, Pearson.","Behrouz A. Forouzan, Data Communications and Networking, McGraw Hill.","Andrew S. Tanenbaum, Computer Networks, Pearson.","William Stallings, Data and Computer Communications, Pearson.","Randy J. Boyle, Internet & Intranet Security, Wiley.","Kai Hwang, Geoffrey Fox, Jack Dongarra, Distributed and Cloud Computing, Elsevier.","Paul Deitel, Harvey Deitel, Internet & World Wide Web: How to Program, Pearson."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction and Line Generation","topics":["Types of computer graphics","Graphic Displays- Random scan displays","Raster scan displays","Frame buffer and video controller","RGB color model","Direct coding","Lookup table; storage tube graphics display","Raster scan display","3D viewing devices","Plotters","Printers","Digitizers","Light pens etc.","Active & Passive graphics devices; Computer graphics software","Unit 2.0: Points, Lines and Transformations Points and lines Line drawing algorithms; DDA algorithm Bresenham''s line algorithm Circle generating algorithms Mid-point circle generating algorithm And parallel version of these algorithms Ellipse generating algorithm; scan line polygon Fill algorithm Boundary fill algorithm Flood fill algorithm Transformations: Basic transformation Matrix representations and homogenous coordinates Composite transformations Reflections and shearing","Points and lines","Line drawing algorithms; DDA algorithm","Bresenham''s line algorithm","Circle generating algorithms","Mid-point circle generating algorithm","And parallel version of these algorithms","Ellipse generating algorithm; scan line polygon","Fill algorithm","Boundary fill algorithm","Flood fill algorithm","Transformations: Basic transformation","Matrix representations and homogenous coordinates","Composite transformations","Reflections and shearing"]},{"title":"Windowing and Clipping","topics":["Viewing pipeline","Viewing transformations","2-D Clipping algorithms- Line clipping algorithms such as Cohen Sutherland line clipping algorithm","Liang Barsky algorithm","Line clipping against non-rectangular clip windows; Polygon clipping Sutherland Hodgeman polygon clipping","Weiler and Atherton polygon clipping","Curve clipping","Text clipping"]},{"title":"Three Dimensional","topics":["3-D Geometric Primitives","3-D Object representation","3-D Transformation","3-D viewing","Projections","3-D Clipping"]},{"title":"Curves and Surfaces","topics":["Quadric surfaces","Spheres","Ellipsoid","Blobby objects","Introductory concepts of Spline","Bspline and Bezier curves and surfaces"]},{"title":"Hidden Lines and Surfaces","topics":["Back Face Detection algorithm","Depth buffer method","A- buffer method","Scan line method","Basic illumination models- Ambient light","Diffuse reflection","Specular reflection and Phong model","Combined approach","Warn model","Intensity Attenuation","Color consideration","Transparency and Shadows","Donald Hearn and M Pauline Baker, \"Computer Graphics C Version\", Pearson Education.","Foley, Vandam, Feiner, Hughes - \"Computer Graphics principle\", Pearson Education.","Rogers, \"Procedural Elements of Computer Graphics\", McGraw Hill.","Donald Hearn and M Pauline Baker, \"Computer Graphics with OpenGL\", Pearson education."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Quantum Computing","topics":["Motivation for studying Quantum Computing","Major players in the industry (IBM, Microsoft, Rigetti, D-Wave etc.)","Origin of Quantum Computing","Overview of major concepts in Quantum Computing","Qubits and multi-qubits states","Bra-ket notation","Bloch Sphere representation","Quantum Superposition","Quantum Entanglement"]},{"title":"Math Foundation for Quantum Computing","topics":["Matrix Algebra: basis vectors and orthogonality","Inner product and Hilbert spaces","Matrices and tensors","Unitary operators and projectors","Dirac notation","Eigen values and Eigen vectors"]},{"title":"Building Blocks for Quantum Program","topics":["Architecture of a Quantum Computing platform","Details of q-bit system of information representation: Block Sphere","Multi-qubits States"]},{"title":"Quantum Operations","topics":["Quantum superposition of qubits (valid and invalid superposition)","Quantum Entanglement","Useful states from quantum algorithmic perceptive e.g. Bell State","Operation on qubits: Measuring and transforming using gates"]},{"title":"Quantum Logic gates and Circuit","topics":["Pauli","Hadamard","Phase shift","Controlled gates","Ising","Deutsch","Swap etc.","Programming model for a Quantum Computing Program: Steps performed on classical computer","Steps performed on Quantum Computer","Moving data between bits and qubits"]},{"title":"Quantum Algorithms","topics":["Basic techniques exploited by quantum algorithms","Amplitude amplification","Quantum Fourier Transform","Phase Kick-back","Quantum Phase estimation","Quantum Walks","Major Algorithms: Shor''s Algorithm","Grover''s Algorithm","Deutsch''s Algorithm","Deutsch Jozsa Algorithm","OSS Toolkits for implementing Quantum program: IBM quantum experience","Microsoft Q. Rigetti PyQuil (QPU/QVM)","Michael A. Nielsen, \"Quantum Computation and Quantum Information\", Cambridge University Press.","David McMahon, \"Quantum Computing Explained\", Wiley.","IBM Experience: [https://quantumexperience.ng](https://quantumexperience.ng),bluemix.net.","Microsoft Quantum Development Kit [https://www.microsoft.com/en-us/quantum/development-kit](https://www.microsoft.com/en-us/quantum/development-kit).","Forest SDK PyQuil: [https://pyquil.readthedocs.io/en/stable/](https://pyquil.readthedocs.io/en/stable/)."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction Overview of Block chain Public Ledgers Bitcoin Smart Contracts Block in a Block chain Transactions Distributed Consensus Public vs Private Block chain Understanding Crypto currency to Block chain Permissioned Model of Block chain Overview of Security aspects of Block chain Basic Crypto Primitives: Cryptographic Hash Function Properties of a hash function Hash pointer and Merkle tree Digital Signature Public Key Cryptography A basic crypto currency","Overview of Block chain","Public Ledgers","Bitcoin","Smart Contracts","Block in a Block chain","Transactions","Distributed Consensus","Public vs Private Block chain","Understanding Crypto currency to Block chain","Permissioned Model of Block chain","Overview of Security aspects of Block chain Basic Crypto Primitives: Cryptographic Hash Function","Properties of a hash function","Hash pointer and Merkle tree","Digital Signature","Public Key Cryptography","A basic crypto currency"]},{"title":"Understanding Block chain with Crypto currency","topics":["Bitcoin and Block chain: Creation of coins","Payments and double spending","Bitcoin Scripts","Bitcoin P2P Network","Transaction in Bitcoin Network","Block Mining","Block propagation and block relay"]},{"title":"Working with Consensus in Bitcoin","topics":["Distributed consensus in open environments","Consensus in a Bitcoin network","Proof of Work (PoW) - basic introduction","Hashcash PoW","Bitcoin PoW","Attacks on PoW and the monopoly problem","Proof of Stake","Proof of Burn and Proof of Elapsed Time","The life of a Bitcoin Miner","Mining Difficulty","Mining Pool","Unit 4.0: Understanding Block chain for Enterprises Permissioned Block chain: Permissioned model and use cases Design issues for Permissioned block chains Execute contracts State machine replication Overview of Consensus models for permissioned block chain- Distributed consensus in closed environment Paxos RAFT Consensus Byzantine general problem Byzantine fault tolerant system Lamport-Shostak-Pease BFT Algorithm BFT over Asynchronous systems","Permissioned Block chain: Permissioned model and use cases","Design issues for Permissioned block chains","Execute contracts","State machine replication","Overview of Consensus models for permissioned block chain- Distributed consensus in closed environment","Paxos","RAFT Consensus","Byzantine general problem","Byzantine fault tolerant system","Lamport-Shostak-Pease BFT Algorithm","BFT over Asynchronous systems"]},{"title":"Enterprise application of Block chain","topics":["Cross border payments","Know Your Customer (KYC)","Food Security","Mortgage over Block chain","Block chain enabled Trade","We Trade - Trade Finance Network","Supply Chain Financing","Identity on Block chain"]},{"title":"Block chain application development","topics":["Hyperledger Fabric- Architecture","Identities and Policies","Membership and Access Control","Channels","Transaction Validation","Writing smart contract using Hyperledger Fabric","Writing smart contract using Ethereum","Overview of Ripple and Corda","Melanie Swan, \"Block Chain: Blueprint for a New Economy\", O''Reilly, 2015.","Josh Thompsons, \"Block Chain: The Block Chain for Beginners- Guide to Block chain Technology and Leveraging Block Chain Programming\".","Daniel Drescher, \"Block Chain Basics\", Apress; 1st edition, 2017.","Anshul Kaushik, \"Block Chain and Crypto Currencies\", Khanna Publishing House, Delhi.","Imran Bashir, \"Mastering Block Chain: Distributed Ledger Technology, Decentralization and Smart Contracts Explained\", Packt Publishing.","Ritesh Modi, \"Solidity Programming Essentials: A Beginner''s Guide to Build Smart Contracts for Ethereum and Block Chain\", Packt Publishing.","Salman Baset, Luc Desrosiers, Nitin Gaur, Petr Novotny, Anthony O''Dowd, Venkatraman Ramakrishna, \"Hands-On Block Chain with Hyperledger: Building Decentralized Applications with Hyperledger Fabric and Composer\", Import, 2018"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Distributed Computing and Enabling Technologies","Cloud Fundamentals: Cloud Definition","Evolution","Architecture","Applications","Deployment models","And service models"]},{"title":"Virtualization","topics":["Issues with virtualization","Virtualization technologies and architectures","Internals of virtual machine monitors/hypervisors","Virtualization of data centers","And Issues with Multi-tenancy"]},{"title":"Implementation","topics":["Study of Cloud computing Systems like Amazon EC2 and S3","Google App Engine","And Microsoft Azure","Build Private/Hybrid Cloud using open source tools","SLA management"]},{"title":"Resource Management","topics":["Cloud resource provisioning plan (advance reservation, on demand plan, spot instances)","Various scheduling and load balancing techniques to improve QoS parameters","Resource Optimization algorithms","Task migration and VM migration technique"]},{"title":"Security","topics":["Vulnerability Issues and Security Threats","Application-level Security","Data level Security","And Virtual Machine level Security","Infrastructure Security","And Multi-tenancy Issues"]},{"title":"Advances","topics":["Green Cloud","Mobile Cloud Computing","Fog Computing","Internet of Things","Cloud Computing Principles and Paradigms, Rajkumar Buyya, James Broberg, Andrzej Goscinski, Wiley Publishers 2011","Cloud Computing Bible, Barrie Sosinsky, Wiley Publishers 2010","Mastering Cloud computing, Rajkumar Buyya, Christian Vacchiola, S Thamarai Selvi, McGraw Hill 2013","Cloud Security and Privacy: An Enterprise Perspective on Risks and Compliance, Tim Mather, Subra Kumaraswamy, Shahed Latif, O''Reilly 2010","Cloud Computing by Shailendra Singh 2018"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to E- Commerce","topics":["Evolution of E-commerce","Advantage and Disadvantage of E Commerce","Roadmap of E-Commerce in India","Business Models of E-Commerce: Model Based On Transaction Party: B2B, B2C, C2B, C2C"]},{"title":"E marketing","topics":["The scope of E-Marketing","Identifying Web Presence goals","Uniqueness of the web","Meeting the need of website visitors","Website Design Issues: Factors that make People Return to Your Site","Strategies for Website Development","Site Adhesion: Content, format and access: maintaining a Website","E- Advertising","E-Branding"]},{"title":"E-Payment System","topics":["Digital Payment Requirement","Digital Token based E-Payment System","Electronic Cash","Smart card and Electronics payment system: Credit and Debit Card","Virtual Currency","Digital wallet","Risk of Electronics payment system"]},{"title":"Digital Signature and E Security Digital Signature E Security: Security","topics":["Digital Signature","E Security: Security On the Internet: Network and Website Security Risk: Denial-of-Service attack","Viruses","Unauthorized access to computer Network","Security Standards: Firewall","Cryptography","Key Management","Password Systems","Digital certificates","Digital signatures","Unit 5.0: Enterprise Resource Planning (ERP) Introductory Concepts Advantages & disadvantages of ERP ERP and Related Technologies: - Business Process Reengineering Data Warehousing Data Mining Supply Chain Management ERP Implementation: ERP Implementation Life Cycle Implementation Methodology Hidden Costs Organizing Implementation Contracts with Vendors Consultants and Users Project Management and Monitoring","Introductory Concepts","Advantages & disadvantages of ERP","ERP and Related Technologies: - Business Process Reengineering","Data Warehousing","Data Mining","Supply Chain Management","ERP Implementation: ERP Implementation Life Cycle Implementation Methodology","Hidden Costs","Organizing Implementation Contracts with Vendors","Consultants and Users","Project Management and Monitoring"]},{"title":"ERP Business Modules","topics":["Introduction to basic Modules of ERP System","Business Modules in an ERP Package- Finance Manufacturing - Human Resource Management - Quality Management - Sales and Distribution","Plant Maintenance Materials","Alexis Leon, \"ERP Demystified\", Tata McGraw Hill.","E-Commerce An Indian Perspective by P.T.Joseph, PHI","K.K. Bajaj, D. Nag \"E-Commerce\", 2nd Edition, McGraw-Hill Education, New Delhi.","Bhaskar Bharat, \"Electronic Commerce-Technology and Application\", McGraw-Hill Education, New Delhi.","Mary Sumner, \"Enterprise Resource Planning\", 2005, PHI Learning India Pvt. Ltd. /Pearson Education, New Delhi.","Chan, \"E-Commerce fundamentals and Applications\", Wiley India, New Delhi.","Vinod Kumar Garg and N.K. Venkata Krishnan, \"Enterprise Resource Planning - concepts and Planning\", Prentice Hall, 1998."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["List of Experiments:","1. a) Implementation of Python Basic Libraries such as Statistics, Math, Numpy and Scipy b) Implementation of Python Libraries for ML application such as Pandas and Matplotlib.","2. a) Creation and Loading different datasets in Python b) Write a python program to compute Mean, Median, Mode, Variance, Standard Deviation using Datasets","3. a) Write a python program to compute reshaping the data, Filtering the data, merging the data and handling the missing values in datasets","4. a) Write a Python program to implement Simple Linear Regression and plot the graph. b) Implementation of Multiple Linear Regression for House Price Prediction using sklearn","5. Implementation of Logistic Regression for iris using sklearn","6. Implementation of random forest algorithm","7. Implementation of navie bayes classifier algorithm and plot the graph.","8. Implementation of SVM classification and plot the graph.","9. a) Implementation of PCA b) Implementation of LDA.","10. a) Implementation of k-means clustering. b) Implementation of hierarchical clustering"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["List of Experiments:","Experiment 1: Introduction to Wireless Network Simulation - Overview of NS2/NS3, MATLAB, and OMNET++ for ad hoc and sensor networks. Understanding network topology setup and performance analysis metrics.","Experiment 2: Simulation of Ad Hoc Routing Protocols - Implement and analyze AODV, DSR, and DSDV routing protocols. Compare throughput, end-to-end delay, and packet delivery ratio.","Experiment 3: MAC Protocol Implementation for Ad Hoc Networks - Implement and analyze contention-based MAC protocols (CSMA, MACA, MACAW). Study the impact of collision avoidance techniques in wireless communication.","Experiment 4: Energy-Efficient Routing in Wireless Sensor Networks (WSN) - Implement LEACH (Low-Energy Adaptive Clustering Hierarchy) protocol. Compare energy consumption and network lifetime.","Experiment 5: Localization Techniques in WSN - Implement range-based (RSSI, TOA, TDOA) and range-free (DV-Hop, Centroid) localization algorithms. Evaluate accuracy and error rates in node positioning.","Experiment 6: Time Synchronization in WSN - Implement RBS (Reference Broadcast Synchronization) and TPSN (Timing-sync Protocol for Sensor Networks). Analyze clock drift and synchronization accuracy.","Experiment 7: Data Aggregation in WSN - Implement data aggregation techniques using clustering methods. Compare efficiency in terms of energy saving and data redundancy.","Experiment 8: Security Attacks in Ad Hoc and Sensor Networks - Simulate wormhole, blackhole, and Sybil attacks in NS2/NS3. Implement countermeasures for secure routing.","Experiment 9: QoS-Based Routing in Ad Hoc Networks - Implement QoS-aware routing using bandwidth and delay constraints. Analyze performance trade-offs between QoS metrics.","Experiment 10: Performance Evaluation of Sleep-Wake Scheduling Algorithms - Implement duty-cycle-based sleep-wake scheduling algorithms. Compare energy efficiency and network lifetime improvement."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Details for NPTEL Course-II Lab will be provided by the department."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Basic definitions","Linear Algebra","Statistical learning theory","Types of learning","Hypothesis space and Inductive bias","Evaluation and cross validation","Optimization"]},{"title":"Statistical Decision Theory and Bayesian Learning Statistical Decision Theory Bayesian","topics":["Statistical Decision Theory","Bayesian Learning (ML, MAP, Bayes estimates, Conjugate priors)","Linear Regression","Ridge Regression","Lasso","Principal Component Analysis","Partial Least Squares"]},{"title":"Linear Classification and Advanced Methods Linear Classification Logistic Regression Linear","topics":["Linear Classification","Logistic Regression","Linear Discriminant Analysis","Quadratic Discriminant Analysis","Perceptron","Support Vector Machines + Kernels","Artificial Neural Networks + Back Propagation","Decision Trees","Bayes Optimal Classifier","Naive Bayes"]},{"title":"Hypothesis Testing and Ensemble Methods","topics":["Hypothesis testing","Ensemble Methods","Bagging","Adaboost","Gradient Boosting"]},{"title":"Clustering Clustering K-means K-medoids Density-based Hierarchical Spectral","topics":["Clustering","K-means","K-medoids","Density-based Hierarchical","Spectral"]},{"title":"Advanced Topics","topics":["Expectation Maximization","GMMs","Learning theory","Intro to Reinforcement Learning","Bayesian Networks","Machine Learning. Tom Mitchell. First Edition, McGraw- Hill, 1997","Introduction to Machine Learning Edition 2, by Ethem Alpaydin","J. Shavlik and T. Dietterich (Ed), Readings in Machine Learning, Morgan Kaufmann, 1990","P. Langley, Elements of Machine Learning, Morgan Kaufmann, 1995","Understanding Machine Learning. Shai Shalev- Shwartz and Shai Ben- David. Cambridge University Press. 2017","The Elements of Statistical Learning. Trevor Hastie, Robert Tibshirani and Jerome Friedman. Second Edition. 2009"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Data Communication Components","topics":["Representation of Data and its Flow Networks","Various Connection Topology","Protocols and Standards","OSI model","Transmission Media","LAN: Wired LAN","Wireless LANs","Connecting LAN and Virtual LAN"]},{"title":"Techniques for Bandwidth Utilization","topics":["Multiplexing - Frequency division, Time division and Wave division","Concepts on spread spectrum"]},{"title":"Data Link Layer and Medium Access Sub Layer","topics":["Error Detection and Error Correction - Fundamentals","Block coding","Hamming Distance","CRC","Flow Control and Error control protocols - Stop and Wait","Go back - N ARQ","Selective Repeat ARQ","Sliding Window","Piggybacking","Random Access","Multiple access protocols - Pure ALOHA, Slotted ALOHA, CSMA/CD, CDMA/CA"]},{"title":"Network Layer","topics":["Switching","Logical addressing - IPV4, IPV6","Address mapping - ARP, RARP, BOOTP and DHCP","Delivery, Forwarding and Unicast Routing protocols"]},{"title":"Transport Layer","topics":["Process to Process Communication","User Datagram Protocol (UDP)","Transmission Control Protocol (TCP)","SCTP Congestion Control","Quality of Service","QoS improving techniques: Leaky Bucket and Token Bucket algorithm"]},{"title":"Application Layer","topics":["Domain Name Space (DNS)","DDNS","TELNET","EMAIL","File Transfer Protocol (FTP)","WWW","HTTP","SNMP","Bluetooth","Firewalls","Basic concepts of Cryptography","Data Communication and Networking, 4th Edition, Behrouz A. Forouzan, McGraw-Hill","Data and Computer Communication, 8th Edition, William Stallings, Pearson Prentice Hall India","Computer Networks, 8th Edition, Andrew S. Tanenbaum, Pearson New International Edition","Internetworking with TCP/IP, Volume 1, 6th Edition Douglas Comer, Prentice Hall of India","TCP/IP Illustrated, Volume 1, W. Richard Stevens, Addison-Wesley, United States of America"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Ad Hoc and Sensor Networks","topics":["Characteristics of ad hoc wireless networks","Applications of ad hoc networks","Challenges in ad hoc networks","Wireless sensor networks (WSN) - Characteristics and applications","Design issues in WSN","Sensor network architecture - Layered architecture, Cross- layer design"]},{"title":"MAC Protocols for Ad Hoc and Sensor Networks","topics":["Fundamentals of MAC design","Issues in designing MAC protocols","MAC protocols for ad hoc networks - Contention- based protocols (Aloha, CSMA, MACA, MACAW)","Scheduling- based MAC protocols","MAC protocols for WSN - S- MAC, T- MAC, B- MAC, X- MAC","Energy- efficient MAC protocols"]},{"title":"Routing Protocols in Ad Hoc and Sensor Networks","topics":["Challenges in routing","Proactive vs. Reactive routing","Ad hoc routing protocols - AODV, DSR, DSDV, OLSR","Hybrid routing (ZRP)","Hierarchical routing","Geographic routing","Routing protocols for WSN - Flooding, SPIN, LEACH, TEEN, Directed diffusion","Geographic and Energy- Aware Routing (GEAR)"]},{"title":"Transport and Energy Management in Wireless Sensor Networks","topics":["Issues in transport protocols","TCP over ad hoc networks","Transport protocols for WSN - CODA, RMST, PSFQ, ESRT","Energy- efficient routing in WSN","Data aggregation","Clustering techniques for WSN","Energy harvesting in sensor networks","Sleep- wake scheduling algorithms"]},{"title":"Localization, Synchronization, and Data Dissemination in WSN","topics":["Localization techniques - GPS- based localization","Range- based localization (RSSI, TOA, TDOA, AOA)","Range- free localization (Centroid, DV- Hop, APIT)","Time synchronization in WSN - RBS, TPSN","Data dissemination and query processing in WSN","Mobile sink- based data collection","Unit 6.0: Security and Emerging Trends in Ad Hoc and Sensor Networks Security issues in ad hoc and sensor networks Attack models - Eavesdropping, Sybil attack, Blackhole, Wormhole Intrusion detection in WSN Secure routing in ad hoc networks Privacy- preserving techniques Emerging trends - Mobile ad hoc networks (MANETs), Vehicular ad hoc networks (VANETs) Cognitive radio sensor networks (CRSN) AI/ML applications in WSN","Security issues in ad hoc and sensor networks","Attack models - Eavesdropping, Sybil attack, Blackhole, Wormhole","Intrusion detection in WSN","Secure routing in ad hoc networks","Privacy- preserving techniques","Emerging trends - Mobile ad hoc networks (MANETs), Vehicular ad hoc networks (VANETs)","Cognitive radio sensor networks (CRSN)","AI/ML applications in WSN","C. Siva Ram Murthy, B.S. Manoj, Ad Hoc Wireless Networks: Architectures and Protocols, Pearson, 2004","Feng Zhao, Leonidas Guibas, Wireless Sensor Networks: An Information Processing Approach, Elsevier, 2004","Holger Karl, Andreas Willig, Protocols and Architectures for Wireless Sensor Networks, Wiley, 2005","C. K. Toh, Ad Hoc Mobile Wireless Networks: Protocols and Systems, Pearson, 2002","Edgar H. Callaway, Wireless Sensor Networks: Architectures and Protocols, CRC Press, 2003","Thomas Haenselmann, Wireless Sensor Networks: Design Principles for Scalable Distributed Systems, Springer, 2007","Kazem Sohraby, Daniel Minoli, Taieb Znati, Wireless Sensor Networks: Technology, Protocols, and Applications, Wiley, 2007"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Definition of morality and ethics in AI","AI, and society"]},{"title":"Impact of AI","topics":["Impact on society","Impact on human psychology","Impact on the legal system","Impact on the environment and the planet","Impact on trust"]},{"title":"Ethical Initiatives in AI","topics":["International ethical initiatives","Ethical harms, and concerns","Case study: healthcare robots","Autonomous Vehicles","Warfare, and weaponization"]},{"title":"AI Standards And Regulation","topics":["Model Process for Addressing Ethical Concerns During System Design","Transparency of Autonomous Systems","Data Privacy Process","Algorithmic Bias Considerations","Ontological Standard for Ethically Driven Robotics and Automation Systems"]},{"title":"Rob ethics: Social and Ethical Implication of Robotics","topics":["Robotics- Ethics and Morality","Moral Theories- Ethics in Science and Technology","Ethical Issues in an ICT Society","Harmonization of Principles","Ethics and Professional Responsibility","Robotics Taxonomy"]},{"title":"Challenges and Opportunities","topics":["Ethical issues in artificial intelligence","Societal Issues Concerning the Application of Artificial Intelligence in Medicine","Decision- making role in industries","National and International Strategies on AI","Eleanor Bird, Jasmin Fox-Skelly, Nicola Jenner, Ruth Larvey, Emma Weitkamp and Alan Winfield,\" The ethics of artificial intelligence: Issues and initiatives\", EPRS | European Parliamentary Research Service Scientific Foresight Unit (STOA) PE 634.452- March 2020","Patrick Lin, Keith Abney, George A Bekey,\" Robot Ethics: The Ethical and Social Implications of Robotics\", The MIT Press- January 2014","Towards a Code of Ethics for Artificial Intelligence (Artificial Intelligence: Foundations, Theory, and Algorithms) by Paula Boddington, November 2017","Mark Coeckelbergh,\" AI Ethics\", The MIT Press Essential Knowledge series, April 2020"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Meaning of the constitution law and constitutionalism","topics":["Historical perspective of the Constitution of India","Salient features and characteristics of the Constitution of India"]},{"title":"Scheme of the fundamental rights","topics":["The scheme of the Fundamental Duties and its legal status","The Directive Principles of State Policy – Its importance and implementation"]},{"title":"Federal structure and distribution of legislative and financial powers between","topics":["Parliamentary Form of Government in India – The constitution powers and status of the President of India"]},{"title":"Amendment of the Constitutional Powers and Procedure","topics":["The historical perspectives of the constitutional amendments in India"]},{"title":"Emergency Provisions","topics":["National Emergency","President Rule","Financial Emergency","Local Self Government – Constitutional Scheme in India"]},{"title":"Scheme of the Fundamental Right to Equality","topics":["Scheme of the Fundamental Right to certain Freedom under Article 19","Scope of the Right to Life and Personal Liberty under Article 21","\"Constitution of India\" (for Competitive Exams) - Published by Naidhruva Edutech Learning Solutions, Bengaluru. - 2022","\"Introduction to the Constitution of India\", (Students Edition.) by Durga Das Basu (DD Basu): Prentice -Hall, 2008","\"Constitution of India, Professional Ethics and Human Rights\" by Shubham Singles, Charles E. Haries, and et al: published by Cengage Learning India, Latest Edition - 2019","\"The Constitution of India\" by Merunandan K B: published by Merugu Publication, Second Edition, Bengaluru","\"Samvidhana Odu\" - for Students & Youths by Justice HN Nagamohan Dhas, Sahayana, kerekon","M.Govindarajan, S.Natarajan, V.S.Senthilkumar, \"Engineering Ethics\", Prentice -Hall, 2004"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Wireless Networks","topics":["Fundamentals of Wireless Communication: Applications, History, Transmission, Frequencies, Signals, Antennas","Signal Propagation, Multiplexing, Modulation, Spread Spectrum, Cellular Systems"]},{"title":"Medium Access Control & Telecommunication Systems","topics":["MAC Protocols: SDMA, FDMA, TDMA, CDMA","Telecommunication Systems: GSM, DECT, TETRA, UMTS, IMT-2000, Introduction to LTE (4G)"]},{"title":"Wireless LANs and PANs","topics":["Wireless LAN and PAN: IEEE 802.11 standards, Infrared vs. Radio, Infrastructure vs. Ad hoc Networks, HIPERLAN, Bluetooth, ZigBee, IoT Wireless Standards, Overview of 5G"]},{"title":"Mobile Network Layer","topics":["Mobile Network Layer: Mobile IP, DHCP, Routing in Adhoc Networks (DSDV, DSR, AODV)","Mobile TCP variants, Fast Retransmit, Time-out Freezing, Selective Retransmission"]},{"title":"Mobility Management and Applications","topics":["Mobility Management and Applications: Handoffs, File Systems, Wireless Application Protocol (WAP), Mobile OS (Android/iOS)","Case Studies - Mobile Banking, M- commerce, Location- Based Services"]},{"title":"Emerging Trends in Wireless & Mobile Computing","topics":["Emerging Trends: 5G and Beyond, Network Slicing, Massive MIMO, IoT and Wireless Sensor Networks (WSN), LoRa, NB- IoT, Sigfox, Edge Computing, 6G Concepts","Mobile Communications Jochen Schiller Pearson / Addison-Wesley, 2nd Ed., 2003. ISBN: 978-0321123817","Wireless Communications & Networks, William Stallings, Pearson, 2nd Ed., 2014 (Int''l Adaptation). Print ISBN: 978-1292027388","Mobile Computing: Technology, Applications, and Service Creation, Asoke K. Talukder, Hasan Ahmed, Roopa Yavagal, McGraw-Hill Education India, Reprint 2011 (orig. 2006). Print ISBN: 978-0070144576"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Sound","topics":["Biology of Speech Processing","Place and Manner of Articulation","Word Boundary Detection","Argmax based computations","HMM and Speech Recognition"]},{"title":"Words and Word Forms","topics":["Morphology fundamentals","Morphological Diversity of Indian Languages","Morphology Paradigms","Finite State Machine Based Morphology","Automatic Morphology Learning","Shallow Parsing","Named Entities","Maximum Entropy Models","Random Fields"]},{"title":"Structures","topics":["Theories of Parsing","Parsing Algorithms","Robust and Scalable Parsing on Noisy Text as in Web documents"]},{"title":"Hybrid of Rule Based and Probabilistic Parsing","topics":["Scope Ambiguity and Attachment Ambiguity resolution"]},{"title":"Meaning","topics":["Lexical Knowledge Networks, Wordnet Theory","Indian Language Wordnets and Multilingual Dictionaries","Semantic Roles","Word Sense Disambiguation","WSD and Multilinguality","Metaphors","Coreferences"]},{"title":"Web 2.0 Applications","topics":["Sentiment Analysis","Text Entailment","Robust and Scalable Machine Translation","Question Answering in Multilingual Setting","Cross Lingual Information Retrieval (CLIR)","Jurafsky, Dan and Martin, James, \"Speech and Language Processing\", 2nd Edition, Prentice Hall, 2008","Manning, Christopher and Heinrich, Schutze, \"Foundations of Statistical Natural Language Processing\", MIT Press, 1999","Allen James, \"Natural Language Understanding\", 2nd edition, Benjamin Cumming, 1995","Charniak, Eugene, \"Statistical Language Learning\", MIT Press, 1993"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Industry 4.0","topics":["Sensing & Actuation","Industry 4.0: Globalization and Emerging Issues","The Fourth Revolution","LEAN Production Systems","Smart and Connected business perspective"]},{"title":"Cyber Physical Systems & Emerging Technologies Cyber Physical Systems Next","topics":["Cyber Physical Systems","Next Generation Sensors","Collaborative Platform","Product Lifecycle Management","Artificial Intelligence","Big Data","Blockchain and its role in secure transactions"]},{"title":"Cloud Computing for Industry 4.0","topics":["Introduction to Cloud Technologies","Top Cloud Services Providers platforms and their real- life use cases exploration (AWS, Azure, GCP)"]},{"title":"The Role of Augmented Reality in the Age of Industry","topics":["Introduction to AR/VR","AR Hardware & Software","Industrial Applications of AR"]},{"title":"Industrial Internet of Things (IIoT) & Security","topics":["Introduction to IIoT","Industrial Internet System","Industrial Process","Key Enablers of IIoT","Blockchain for IoT Security and Data Integrity","Cybersecurity Challenges in Industry 4.0"]},{"title":"Case Studies","topics":["Real time use cases from different Industries like Oil, chemical, manufacturing, and pharmaceutical industry","Applications of UAVs in Industries","The Concept Industry 4.0, An Empirical Analysis of Technologies and Applications in Production Logistics, Christoph Jan Bartodziej, Springer Fachmedien Wiesbaden, November 2016, ISBN: 9783658165024","Industry 4.0, Entrepreneurship and Structural Change in the New Digital Landscape, Tessaleno Devezas, João Leitão, Askar Sarygulov, Springer, 1st Edition, 2017, ISBN: 9783319496047","Blockchain for Industry 4.0: Secure IoT Solutions, Seung Ho Hong, Springer, ISBN: 9789811552721"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Data Science","topics":["Concept of Data Science","Traits of Big data","Web Scraping","Analysis vs Reporting"]},{"title":"Programming Tools for Data Science","topics":["Python Toolkits: Matplotlib, NumPy, Scikit- learn, NLTK","Data Visualization: Bar Charts, Line Charts, Scatterplots","Working with data: Reading Files, Scraping the Web, Using APIs (Example: Using the Twitter APIs)","Cleaning and Munging, Manipulating Data, Rescaling, Dimensionality Reduction","Unit 3.0: Mathematical Foundations Linear Algebra: Vectors, Matrices Statistics: Describing a Single Set of Data, Correlation, Simpson''s Paradox, Correlation and Causation Probability: Dependence and Independence, Conditional Probability, Bayes''s Theorem, Random Variables, Continuous Distributions, The Normal Distribution, The Central Limit Theorem Hypothesis and Inference: Statistical Hypothesis Testing, Confidence Intervals, Phacking, Bayesian Inference","Linear Algebra: Vectors, Matrices","Statistics: Describing a Single Set of Data, Correlation, Simpson''s Paradox, Correlation and Causation","Probability: Dependence and Independence, Conditional Probability, Bayes''s Theorem, Random Variables, Continuous Distributions, The Normal Distribution, The Central Limit Theorem","Hypothesis and Inference: Statistical Hypothesis Testing, Confidence Intervals, Phacking, Bayesian Inference","Unit 4.0: Basic concept of Machine Learning Overview of Machine learning concepts - Over fitting and train/test splits Types of Machine learning - Supervised, Unsupervised, Reinforced learning Introduction to Bayes Theorem Linear Regression - model assumptions, regularization (lasso, ridge, elastic net) Classification and Regression algorithms - Naive Bayes, K- Nearest Neighbors, logistic regression, support vector machines (SVM), decision trees, and random forest Classification Errors Analysis of Time Series- Linear Systems Analysis, Nonlinear Dynamics, Rule Induction Neural Networks Learning And Generalization, Overview of Deep Learning","Overview of Machine learning concepts - Over fitting and train/test splits","Types of Machine learning - Supervised, Unsupervised, Reinforced learning","Introduction to Bayes Theorem","Linear Regression - model assumptions, regularization (lasso, ridge, elastic net)","Classification and Regression algorithms - Naive Bayes, K- Nearest Neighbors, logistic regression, support vector machines (SVM), decision trees, and random forest","Classification Errors","Analysis of Time Series- Linear Systems Analysis, Nonlinear Dynamics, Rule Induction","Neural Networks Learning And Generalization, Overview of Deep Learning"]},{"title":"Case Studies & Applications","topics":["Weather forecasting","Stock market prediction","Object recognition","Real Time Sentiment Analysis"]},{"title":"Practical Implementation & Mini Project","topics":["Hands- on Python programs: Flower classification, Loan approval prediction, Traffic prediction, Hate speech detection, Actor age prediction","Mini project for time prediction","Data Science From Scratch: First Principles with Python, Joel Grus, O''Reilly, First Edition, 2015, ISBN: 9789352130962","Machine Learning, Tom M. Mitchell McGraw Hill Education, First Edition, 2017, ISBN: 978-1259096952","Hands-On Machine Learning with Scikit-Learn, Keras & Tensor Flow, Aurélien Gérón, O''Reilly, 3rd Edition, 2022, ISBN: 978-9355421982","Python for Data Analysis, Wes McKinney, O''Reilly Media, 2nd Edition, 2017, ISBN: 978-1491957660","Practical Statistics for Data Scientists, Peter Bruce, O''Reilly; 2nd edition, 2020, ISBN: 978-1492072942"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction Overview of Block chain, Public Ledgers, Bitcoin, Smart Contracts Block in a Block chain, Transactions, Distributed Consensus Public vs Private Block chain, Understanding Crypto currency to Block chain Permissioned Model of Block chain, Overview of Security aspects of Block chain Basic Crypto Primitives: Cryptographic Hash Function, Properties of a hash function, Hash pointer and Merkle tree, Digital Signature, Public Key Cryptography, A basic crypto currency","Overview of Block chain, Public Ledgers, Bitcoin, Smart Contracts","Block in a Block chain, Transactions, Distributed Consensus","Public vs Private Block chain, Understanding Crypto currency to Block chain","Permissioned Model of Block chain, Overview of Security aspects of Block chain","Basic Crypto Primitives: Cryptographic Hash Function, Properties of a hash function, Hash pointer and Merkle tree, Digital Signature, Public Key Cryptography, A basic crypto currency"]},{"title":"Understanding Block chain with Crypto currency","topics":["Bitcoin and Block chain: Creation of coins, Payments and double spending","Bitcoin Scripts, Bitcoin P2P Network, Transaction in Bitcoin Network","Block Mining, Block propagation and block relay"]},{"title":"Working with Consensus in Bitcoin","topics":["Distributed consensus in open environments","Consensus in a Bitcoin network","Proof of Work (PoW) - basic introduction, Hashcash PoW, Bitcoin PoW","Attacks on PoW and the monopoly problem","Proof of Stake, Proof of Burn and Proof of Elapsed Time","The life of a Bitcoin Miner, Mining Difficulty, Mining Pool","Unit 4.0: Understanding Block chain for Enterprises Permissioned Block chain: Permissioned model and use cases Design issues for Permissioned block chains Execute contracts, State machine replication Overview of Consensus models for permissioned block chain- Distributed consensus in closed environment, Paxos, RAFT Consensus Byzantine general problem, Byzantine fault tolerant system Lamport- Shostak- Pease BFT Algorithm, BFT over Asynchronous systems","Permissioned Block chain: Permissioned model and use cases","Design issues for Permissioned block chains","Execute contracts, State machine replication","Overview of Consensus models for permissioned block chain- Distributed consensus in closed environment, Paxos, RAFT Consensus","Byzantine general problem, Byzantine fault tolerant system","Lamport- Shostak- Pease BFT Algorithm, BFT over Asynchronous systems"]},{"title":"Enterprise application of Block chain","topics":["Cross border payments, Know Your Customer (KYC), Food Security","Mortgage over Block chain, Block chain enabled Trade","We Trade - Trade Finance Network, Supply Chain Financing, Identity on Block chain"]},{"title":"Block chain application development","topics":["Hyperledger Fabric- Architecture, Identities and Policies, Membership and Access Control, Channels, Transaction Validation","Writing smart contract using Hyperledger Fabric, Writing smart contract using Ethereum","Overview of Ripple and Corda","Melanie Swan, \"Block Chain: Blueprint for a New Economy\", O''Reilly, 2015","Josh Thompsons, \"Block Chain: The Block Chain for Beginners- Guide to Block chain Technology and Leveraging Block Chain Programming\"","Daniel Drescher, \"Block Chain Basics\", Apress; 1st edition, 2017","Anshul Kaushik, \"Block Chain and Crypto Currencies\", Khanna Publishing House, Delhi","Imran Bashir, \"Mastering Block Chain: Distributed Ledger Technology, Decentralization and Smart Contracts Explained\", Packt Publishing","Ritesh Modi, \"Solidity Programming Essentials: A Beginner''s Guide to Build Smart Contracts for Ethereum and Block Chain\", Packt Publishing","Salman Baset, Luc Desrosiers, Nitin Gaur, Petr Novotny, Anthony O''Dowd, Venkatraman Ramakrishna, \"Hands-On Block Chain with Hyperledger: Building Decentralized Applications with Hyperledger Fabric and Composer\", Import, 2018"]}]'::jsonb from s;
