insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Concept And Overview Distributed Database System","topics":["What is Distributed Database System (DDBS)","Features of DDBS, promises of DDBS","Design issue in DDBS","Distributed DBMS architecture: Client/server System, Peer-to-Peer, Multi-Database system"]},{"title":"Distributed Database Design","topics":["Distributed database design concept","Objective of Data Distribution","Data Fragmentation, The allocation of fragment","Transparencies in Distributed Database Design"]},{"title":"Distributed Transaction And Concurrency Control","topics":["Basic concept of Transaction management","Objective Distributed transaction management","Model for Transaction management","Distributed Concurrency control: Objective, concurrency control anomalies","Distributed Serializability, Locking based algorithm"]},{"title":"Distributed Deadlock and Recovery","topics":["Introduction to Deadlock","Distributed Deadlock prevention, avoidance, detection and recovery","Two-Phase and Three-Phase Commit Protocol"]},{"title":"Distributed Query Processing And Optimization","topics":["Concepts, objective, and phases of distributed query processing","Join strategies in fragment relation","Global query optimization"]},{"title":"Heterogeneous Database and XML","topics":["Architecture of Heterogeneous Database","Database Integration: Schema Translation and schema Integration","Query processing issues in Heterogeneous database","XML for data integration, structure of XML","XML document schema, Querying and Transformation","Storage of XML data, XML application","Silberschatz A, KorthHF, Sudarshan S, Database System Concepts, McGrawHill","Ceri S, Pelagatti G, Distributed Databases – Principles and Systems, McGraw Hill"]}]'::jsonb from s;
