insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Multimedia System","topics":["Architecture and components","Multimedia distributed processing model","Synchronization, Orchestration and Quality of Service (QOS) architecture"]},{"title":"Audio and Speech","topics":["Data acquisition, Sampling and Quantization","Human Speech production mechanism","Digital model of speech production, Analysis and synthesis","Psycho-acoustics, low bit rate speech compression","MPEG audio compression"]},{"title":"Images and Video","topics":["Image acquisition and representation","Composite video signal NTSC, PAL and SECAM video standards","Bi-level image compression standards: ITU (formerly CCITT) Group III and IV standards","JPEG image compression standards","MPEG video compression standards"]},{"title":"Multimedia Communication","topics":["Fundamentals of data communication and networking","Bandwidth requirements of different media","Real time constraints: Audio latency, Video data rate","multimedia over LAN and WAN","Multimedia conferencing, Multimedia devices"]},{"title":"Hypermedia presentation","topics":["Authoring and Publishing","Linear and non-linear presentation","Structuring Information","Different approaches of authoring hypermedia documents","Hyper-media data models and standards"]},{"title":"Multimedia Information Systems","topics":["Operating system support for continuous media applications: limitations is usual OS","New OS support, Media stream protocol","File system support for continuous media","Data models for multimedia and hypermedia information","Content based retrieval of unstructured data","Handbook of Multimedia Computing, Borivoje Furht","Multimedia Systems, Standards, and Networks, A. Puri and T. Chen, Marcel Dekker","Multimedia : Computing Communications & Applications, Ralf Steinmetz, Klara Nahrstedtm","Multimedia Systems, Ralf Steinmetz and Klara Nahrstedt","Multimedia Communications: Directions and Inn