insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Security","topics":["Security Services, Mechanisms and Attacks","The OSI Security Architecture","A Model for Network Security","Symmetric Cipher Model, Substitution Techniques","Transposition Techniques, Rotor Machines, Steganography"]},{"title":"Block Ciphers","topics":["Simplified DES, Block Cipher Principles","The Data Encryption Standard","The Strength of DES, Differential and Linear Cryptanalysis","Block Cipher Design Principles","Block Cipher Modes of Operation"]},{"title":"Finite Fields and Confidentiality","topics":["Groups, Rings, and Fields, Modular Arithmetic","Euclid''s Algorithm, Finite Fields of the Form GF(p)","Polynomial arithmetic, Finite Fields of the Form GF(2 n )","Placement of Encryption Function, Traffic Confidentiality","Key Distribution, Random Number Generation"]},{"title":"Encryption Standard and Ciphers","topics":["Evaluation criteria for AES, AES cipher","Multiple encryption and Triple DES","Block cipher Modes of operation","Stream ciphers and RC4"]},{"title":"Number Theory and Public-Key Cryptography","topics":["Prime Numbers, Fermat''s and Euler''s Theorems","Testing for Primality","The Chinese Remainder Theorem","Discrete Logarithms","Principles of Public-Key Cryptosystems","The RSA Algorithm"]},{"title":"Message Authentication and Digital Signatures","topics":["Authentication Requirements, Authentication Functions","Message Authentication Codes","Hash Functions, Security of Hash Functions and MACs","Secure Hash Algorithm, HMAC","Digital Signatures, Authentication Protocols","W. Stallings : Cryptography and Network Security : Principles and Practice, 4/e Pearson Education, New Delhi, 2006","B.A. Forouzan – Cryptography and Network Security, TMH, New Delhi, 2007","B. Schneier – Applied Cryptography, John Wiley, Indian Edition, 2006"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Wireless Networks","topics":["Applications, History, Simplified Reference Model","Wireless transmission, Frequencies, Signals, Antennas","Signal propagation, Multiplexing, Modulation","Spread spectrum, Cellular Systems"]},{"title":"MAC","topics":["Motivation, SDMA, FDMA, TDMA, CDMA"]},{"title":"Telecommunication Systems","topics":["GSM, DECT, TETRA, UMTS, MT-2000"]},{"title":"Wireless LAN","topics":["Infrared Vs Radio transmission, Infrastructure","Adhoc Network, 802.11, HIPERLAN, Bluetooth","Mobile Network Layer, Mobile IP","Dynamic Host Configuration Protocol"]},{"title":"Adhoc Networks and Transport Layer","topics":["Adhoc Networks, Mobile Transport Layer","Traditional TCP, Indirect TCP, Snooping TCP","Mobile TCP, Fast retransmit / Fast recovery","Transmission / Time-out freezing, Selective retransmission","Transaction Oriented TCP"]},{"title":"Support for Mobility","topics":["File Systems, WWW, Wireless Application Protocol","Jochen Schiller, \"Mobile Communications\", Pearson Education, Asia Publications, 2000","William Stallings, \"Wireless Communication and Networks\", PHI/Pearson Education, 2002","Kaveh Pahlavan, Prasanth Krishnamoorthy, \"Principles of Wireless Networks\", PHI/Pearson Education, 2003","Hazyszt of Wesolowski, \"Mobile Communication Systems\", John Wiley and Sons Ltd, 2002"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction and Line Generation Types of computer graphics Graphic Displays- Random scan displays, Raster scan displays Frame buffer and video controller RGB color model, direct coding, lookup table Storage tube graphics display, Raster scan display 3D viewing devices, Plotters, printers, digitizers, Light pens etc. Active & Passive graphics devices Computer graphics software Points and lines, Line drawing algorithms; DDA algorithm Bresenham''s line algorithm Circle generating algorithms, Mid-point circle generating algorithm, and parallel version of these algorithms Ellipse generating algorithm Scan line polygon, fill algorithm, boundary fill algorithm, flood fill algorithm Transformations: Basic transformation, Matrix representations and homogenous coordinates Composite transformations, Reflections and shearing","Types of computer graphics","Graphic Displays- Random scan displays, Raster scan displays","Frame buffer and video controller","RGB color model, direct coding, lookup table","Storage tube graphics display, Raster scan display","3D viewing devices, Plotters, printers, digitizers, Light pens etc.","Active & Passive graphics devices","Computer graphics software","Points and lines, Line drawing algorithms; DDA algorithm","Bresenham''s line algorithm","Circle generating algorithms, Mid-point circle generating algorithm, and parallel version of these algorithms","Ellipse generating algorithm","Scan line polygon, fill algorithm, boundary fill algorithm, flood fill algorithm","Transformations: Basic transformation, Matrix representations and homogenous coordinates","Composite transformations, Reflections and shearing"]},{"title":"Windowing and Clipping","topics":["Viewing pipeline, Viewing transformations","2-D Clipping algorithms- Line clipping algorithms such as Cohen Sutherland line clipping algorithm","Liang Barsky algorithm","Line clipping against non-rectangular clip windows","Polygon clipping – Sutherland Hodgeman polygon clipping","Weiler and Atherton polygon clipping","Curve clipping, Text clipping"]},{"title":"Three Dimensional Graphics","topics":["3-D Geometric Primitives, 3-D Object representation","3-D Transformation, 3-D viewing, projections","3-D Clipping"]},{"title":"Curves and Surfaces","topics":["Quadric surfaces, Spheres, Ellipsoid, Blobby objects","Introductory concepts of Spline, B-spline and Bezier curves and surfaces"]},{"title":"Hidden Lines and Surfaces","topics":["Back Face Detection algorithm","Depth buffer method, A- buffer method, Scan line method","Basic illumination models– Ambient light, Diffuse reflection","Specular reflection and Phong model, Combined approach","Warn model, Intensity Attenuation, Color consideration","Transparency and Shadows","Donald Hearn and M Pauline Baker, \"Computer Graphics C Version\", Pearson Education","Foley, Vandam, Feiner, Hughes – \"Computer Graphics principle\", Pearson Education","Rogers, \"Procedural Elements of Computer Graphics\", McGraw Hill","Donald Hearn and M Pauline Baker, \"Computer Graphics with OpenGL\", Pearson education"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction Biology for Engineers Purpose: To convey that Biology is as important a scientific discipline as Mathematics, Physics and Chemistry Bring out the fundamental differences between science and engineering by drawing a comparison between eye and camera, Bird flying and aircraft Mention the most exciting aspect of biology as an independent scientific discipline Why we need to study biology? Discuss how biological observations of 18th Century that lead to major discoveries Examples from Brownian motion and the origin of thermodynamics by referring to the original observation of Robert Brown and Julius Mayor These examples highlight the fundamental importance of observations in any scientific inquiry","Purpose: To convey that Biology is as important a scientific discipline as Mathematics, Physics and Chemistry","Bring out the fundamental differences between science and engineering by drawing a comparison between eye and camera, Bird flying and aircraft","Mention the most exciting aspect of biology as an independent scientific discipline","Why we need to study biology?","Discuss how biological observations of 18th Century that lead to major discoveries","Examples from Brownian motion and the origin of thermodynamics by referring to the original observation of Robert Brown and Julius Mayor","These examples highlight the fundamental importance of observations in any scientific inquiry","Unit 2.0: Classification Purpose: To convey that classification per se is not what biology is all about. The underlying criterion, such as morphological, biochemical or ecological be highlighted Hierarchy of life forms at phenomenological level A common thread weaves this hierarchy Classification Discuss classification based on (a) cellularity- Unicellular or multicellular (b) ultrastructure- prokaryotes or eucaryotes (c) energy and Carbon utilization - Autotrophs, heterotrophs, lithotopes (d) Ammonia excretion - aminotelic, urocotelic, ureotelic (e) Habitat- acquatic or terrestrial (f) Molecular taxonomy- three major kingdoms of life A given organism can come under different category based on classification Model organisms for the study of biology come from different groups. E.coli, S.cerevisiae, D. Melanogaster, C. elegance, A. Thaliana, M. musculus","Purpose: To convey that classification per se is not what biology is all about. The underlying criterion, such as morphological, biochemical or ecological be highlighted","Hierarchy of life forms at phenomenological level","A common thread weaves this hierarchy Classification","Discuss classification based on (a) cellularity- Unicellular or multicellular (b) ultrastructure- prokaryotes or eucaryotes (c) energy and Carbon utilization - Autotrophs, heterotrophs, lithotopes (d) Ammonia excretion - aminotelic, urocotelic, ureotelic (e) Habitat- acquatic or terrestrial (f) Molecular taxonomy- three major kingdoms of life","A given organism can come under different category based on classification","Model organisms for the study of biology come from different groups. E.coli, S.cerevisiae, D. Melanogaster, C. elegance, A. Thaliana, M. musculus","Unit 3.0: Genetics and Biomolecules Genetics: Purpose: To convey that \"Genetics is to biology what Newton''s laws are to Physical Sciences\" Mendel''s Concept of segregation and independent Gene mapping, Gene interaction, Epistasis Meiosis and Mitosis be taught as a part of genetics. Emphasis to be give not to the mechanics of cell division nor the phases but how genetic material passes from parent to offspring Concepts of recessiveness and dominance Concept of mapping of phenotype to genes Discuss about the single gene disorders in humans Discuss the concept of complementation using human genetics Biomolecules: Purpose: To convey that all forms of life has the same building blocks and yet the manifestations are as diverse as one can imagine Molecules of life. In this context discuss monomeric units and polymeric structures Discuss about sugars, starch and cellulose. Amino acids and proteins. Nucleotides and DNA/RNA. Two carbon units and lipids","Genetics: Purpose: To convey that \"Genetics is to biology what Newton''s laws are to Physical Sciences\"","Mendel''s Concept of segregation and independent Gene mapping, Gene interaction, Epistasis","Meiosis and Mitosis be taught as a part of genetics. Emphasis to be give not to the mechanics of cell division nor the phases but how genetic material passes from parent to offspring","Concepts of recessiveness and dominance","Concept of mapping of phenotype to genes","Discuss about the single gene disorders in humans","Discuss the concept of complementation using human genetics","Biomolecules: Purpose: To convey that all forms of life has the same building blocks and yet the manifestations are as diverse as one can imagine","Molecules of life. In this context discuss monomeric units and polymeric structures","Discuss about sugars, starch and cellulose. Amino acids and proteins. Nucleotides and DNA/RNA. Two carbon units and lipids","Unit 4.0: Enzymes and Information Transfer Enzymes: Purpose: To convey that without catalysis life would not have existed on earth Enzymology: How to monitor enzyme catalysed reactions How does an enzyme catalyse reactions? Enzyme classification. Mechanism of enzyme action. Discuss at least two examples. Enzyme kinetics and kinetic parameters. Why should we know these parameters to understand biology? RNA catalysis Information Transfer: Purpose: The molecular basis of coding and decoding genetic information is universal Molecular basis of information transfer. DNA as a genetic material. Hierarchy of DNA structure- from single stranded to double helix to nucleosomes. Concept of genetic code. Universality and degeneracy of genetic code. Define gene in terms of complementation and recombination","Enzymes: Purpose: To convey that without catalysis life would not have existed on earth","Enzymology: How to monitor enzyme catalysed reactions","How does an enzyme catalyse reactions? Enzyme classification. Mechanism of enzyme action. Discuss at least two examples. Enzyme kinetics and kinetic parameters. Why should we know these parameters to understand biology? RNA catalysis","Information Transfer: Purpose: The molecular basis of coding and decoding genetic information is universal","Molecular basis of information transfer. DNA as a genetic material. Hierarchy of DNA structure- from single stranded to double helix to nucleosomes. Concept of genetic code. Universality and degeneracy of genetic code. Define gene in terms of complementation and recombination","Unit 5.0: Macromolecular Analysis and Metabolism Macromolecular Analysis: Purpose: To analyse biological processes at the reductionistic level. Proteins- structure and function. Hierarch in protein structure. Primary secondary, tertiary and quaternary structure. Proteins as enzymes, transporters, receptors and structural elements Metabolism: Purpose: The fundamental principles of energy transactions are the same in physical and biological world. Thermodynamics as applied to biological systems. Exothermic and endothermic versus endergonic and exergonic reactions. Concept of Keq and its relation to standard free energy. Spontaneity. ATP as an energy currency. This should include the breakdown of glucose to CO2 + H2O (Glycolysis and Krebs cycle) and synthesis of glucose from CO2 and H2O (Photosynthesis). Energy yielding and energy consuming reactions. Concept of Energy charge","Macromolecular Analysis: Purpose: To analyse biological processes at the reductionistic level. Proteins- structure and function. Hierarch in protein structure. Primary secondary, tertiary and quaternary structure. Proteins as enzymes, transporters, receptors and structural elements","Metabolism: Purpose: The fundamental principles of energy transactions are the same in physical and biological world. Thermodynamics as applied to biological systems. Exothermic and endothermic versus endergonic and exergonic reactions. Concept of Keq and its relation to standard free energy. Spontaneity. ATP as an energy currency. This should include the breakdown of glucose to CO2 + H2O (Glycolysis and Krebs cycle) and synthesis of glucose from CO2 and H2O (Photosynthesis). Energy yielding and energy consuming reactions. Concept of Energy charge","Unit 6.0: Microbiology Concept of single celled organisms. Concept of species and strains. Identification and classification of microorganisms. Microscopy. Ecological aspects of single celled organisms. Sterilization and media compositions. Growth kinetics Plant Physiology covering, Transpiration; Mineral nutrition Ecology covering, Ecosystems- Components, types, flow of matter and energy in an ecosystem; Community ecology- Characteristics, frequency, life forms, and biological spectrum; Ecosystem structure- Biotic and abiotic factors, food chain, food web, ecological pyramids","Concept of single celled organisms. Concept of species and strains. Identification and classification of microorganisms. Microscopy. Ecological aspects of single celled organisms. Sterilization and media compositions. Growth kinetics","Plant Physiology covering, Transpiration; Mineral nutrition Ecology covering, Ecosystems- Components, types, flow of matter and energy in an ecosystem; Community ecology- Characteristics, frequency, life forms, and biological spectrum; Ecosystem structure- Biotic and abiotic factors, food chain, food web, ecological pyramids","N. A. Campbell, J. B. Reece, L. Urry, M. L. Cain and S. A. Wasserman, \"Biology: A global approach\", Pearson Education Ltd, 2014","E. E. Conn, P. K. Stumpf, G. Bruening and R. H. Doi, \"Outlines of Biochemistry\", John Wiley and Sons, 2009","D. L. Nelson and M. M. Cox, \"Principles of Biochemistry\", W.H. Freeman and Company, 2012","G. S. Stent and R. Calendar, \"Molecular Genetics\", Freeman and company, 1978","L. M. Prescott, J. P. Harley and C. A. Klein, \"Microbiology\", McGraw Hill Higher Education, 2005"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction Definition of AI, Machine Learning, Deep Learning Human Brain vs Artificial Neuron, Biological neuron and artificial neuron analogy Neuron Models: McCulloch-Pitts neuron, Activation functions (Sigmoid, Tanh, ReLU, Leaky ReLU, Softmax) Perceptron, Multilayer Perceptrons, Back-Propagation Algorithm, XOR Problem Difficulty of training deep neural networks, Discussion on deep learning frameworks","Definition of AI, Machine Learning, Deep Learning","Human Brain vs Artificial Neuron, Biological neuron and artificial neuron analogy","Neuron Models: McCulloch-Pitts neuron, Activation functions (Sigmoid, Tanh, ReLU, Leaky ReLU, Softmax)","Perceptron, Multilayer Perceptrons, Back-Propagation Algorithm, XOR Problem","Difficulty of training deep neural networks, Discussion on deep learning frameworks"]},{"title":"Optimization & Hyperparameter Tuning","topics":["Gradient Descent, stochastic gradient, momentum, RMSProp, ADAM","Regularization for Deep Learning: Parameter Norm Penalties - L2 Parameter Regularization, Dataset Augmentation, Semi-Supervised Learning","Optimization for Training Deep Models"]},{"title":"Convolutional Neural Networks (CNN)","topics":["Convolution operation, Filters, Padding, Stride, Pooling, Normalization","Modern CNN architectures: LeNet, AlexNet, VGG, GoogLeNet, ResNet, Inception, EfficientNet","Transfer Learning & Fine-tuning, Image Augmentation"]},{"title":"Sequence Modeling","topics":["RNN, Vanishing Gradient in RNN, LSTM & GRU networks, Bidirectional RNNs","Applications: Text generation, Sentiment analysis, Time-series forecasting"]},{"title":"Attention and Transformers","topics":["Attention mechanism (Self-attention, Multi-head)","Positional Autoencoders, Encoder-Decoder architecture, Sparse Autoencoders, Denoising Autoencoders, Variational Autoencoders (VAE)","Transformer architecture, BERT, GPT"]},{"title":"Generative Models","topics":["Basics, GANs (Generative Adversarial Networks)- Generator & Discriminator, DCGAN, CycleGAN, StyleGAN","Applications of GANs","Ian Goodfellow, Yoshua Bengio, Aaron Courville, \"Deep Learning,\" MIT Press, 2016","Christopher Bishop, \"Pattern Recognition and Machine Learning,\" Springer, 2006","Aston Zhang, Zachary C. Lipton, Mu Li, Alex J. Smola, \"Dive into Deep Learning (D2L),\" 2020 (Free online book)","François Chollet, \"Deep Learning with Python,\" Manning Publications, 2018","Christoph Molnar, \"Interpretable Machine Learning,\" 2020 (For Explainable AI)"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Security in IoT","topics":["IoT security: Vulnerabilities, Attacks and Countermeasures","Security Engineering for IoT development","IoT security lifecycle"]},{"title":"Network Robustness and Malware Propagation Control in IoT Network Robustness","topics":["Network Robustness","Fusion Based Defense Scheme","Sequential Defense Scheme","Location Certificate Based Scheme","Sybil node detection scheme","Formal Modeling and Verification","Sybil Attack Detection in Vehicular Networks","Performance evaluation of various Malware Dynamics Models","Analysis of Attack Vectors on Smart Home Systems"]},{"title":"Crypto Foundations","topics":["Block ciphers, message integrity, authenticated encryption, hash functions, Merkle trees, elliptic curves","Public-key crypto (PKI), signature algorithms"]},{"title":"Privacy Preservation in IoT","topics":["Privacy Preservation Data Dissemination: Network Model, Threat Model - Problem formulation and definition - Baseline data dissemination - Spatial Privacy Graph based data dissemination - Experiment Validation","Smart building concept- Privacy Threats in Smart Building - Privacy Preserving Approaches in Smart Building - Smart Meter Privacy Preserving Approaches"]},{"title":"Trust Models for IoT","topics":["Trust Model Concepts - Public Key Infrastructures Architecture Components - Public Key Certificate Formats - Design Considerations for Digital Certificates - Public Key Reference Infrastructure for the IoT","Authentication in IoT - Computational Security for IoT"]},{"title":"Security Protocols for IoT Access Networks","topics":["Time Based Secure Key Generation - Security Access Algorithm: Unidirectional, Bidirectional Transmission - Cognitive Security - IoT Security Framework - Secure IoT Layers - Secure Communication Links in IoT - Secure Resource Management, Secure IoT Databases","William Stallings, \"Cryptography and Network Security\", Pearson Education/PHI, 2006","V.K. Jain, \"Cryptography and Network Security\", Khanna Publishing House","Gupta Sarika, \"Information and Cyber Security\", Khanna Publishing House, Delhi","Russell, Brian and Drew Van Duren. Practical Internet of Things Security, 2016,1st edition, PACKT Publishing Ltd, UK","Kim, S., Deka, G. C., & Zhang, P. (2019). Role of blockchain technology in IoT applications. Academic Press","Whitehouse O Security of things: An Implementers'' guide to cyber security for internet of things devices and beyond, 2014, 1st edition, NCC Group, UK","Hu, Fei. Security and Privacy in Internet of Things (IoTs): Models, Algorithms, and Implementations, 2016, 1st edition, CRC Press, USA"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction To Robotics and IoT","topics":["Introduction of Robotics: Definition, history, and application of robotics","Types of robots: mobile robots, autonomous robots, industrial robots","Introduction to IoT: Definition, components, and architecture","Evolution of IoT & enabling technologies (RFID, WSN, Cloud, Big Data)","Unit 2.0: IoT Sensors and Actuators Types of IoT Sensors: Temperature, humidity, pressure, proximity Actuators in IoT: DC motors, servo motors, stepper motors, solenoids Selection criteria of sensors and actuators into robotic systems Robotic perception enhancement using IoT sensors Integration of cameras, LiDAR, ultrasonic sensors with IoT Real-time control of robotic actuators using IoT data Interfacing sensors/actuators with microcontrollers (Arduino/RPi/NodeMCU)","Types of IoT Sensors: Temperature, humidity, pressure, proximity","Actuators in IoT: DC motors, servo motors, stepper motors, solenoids","Selection criteria of sensors and actuators into robotic systems","Robotic perception enhancement using IoT sensors","Integration of cameras, LiDAR, ultrasonic sensors with IoT","Real-time control of robotic actuators using IoT data","Interfacing sensors/actuators with microcontrollers (Arduino/RPi/NodeMCU)"]},{"title":"Design Principles for Connected Devices","topics":["IoT/M2M System Layers and Design Standardization","Communication technologies: Wi-Fi, BLE, ZigBee, LoRa, RFID","Data Enrichment, Data Consolidation and Device Management at Gateway","Web communication protocols (HTTP, MQTT, CoAP, WebSockets)","Message Communication Protocols; Internet Connectivity; Internet connectivity and IP addressing in IoT devices"]},{"title":"IoT Platforms and Middleware","topics":["Overview of IoT platforms: AWS IoT, Azure IoT, Google Cloud IoT","Middleware for integrating IoT devices and robotics","Hands-on experience with setting up and using IoT platforms for robotics applications","Introduction to edge computing and its relevance in robotics"]},{"title":"Data Acquisition and Processing","topics":["Data acquisition from IoT sensors and actuators in robotic systems","Data logging formats: JSON, CSV, MQTT payloads","Data processing techniques: Filtering, aggregation, normalization","Real-time data analysis in robotics applications"]},{"title":"IoT-Enabled Robotic Applications & Case Studies","topics":["Robotic Applications: Smart robotic systems using IoT; IoT-based mobile robots; Industrial IoT (IIoT) robotics applications; Healthcare & service robots with IoT; Autonomous delivery robots","Case studies: Drones, warehouse robots, smart agriculture robots; Mini-project discussion: IoT-controlled robot","Raj Kamal, \"Internet of Things: Architecture and Design Principles\", McGraw Hill, Latest Edition","K. S. Fu, R. C. Gonzalez, \"Robotics: Control, Sensing, Vision, and Intelligence\", McGraw-Hill","Claire Rowland, \"Designing Connected Products for IoT\", O''Reilly, Latest Edition","Hanes, Salgueiro, Grossetete, \"IoT Fundamentals: Networking Technologies, Protocols, and Use Cases\", Cisco Press, Latest Edition"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"IoT Ecosystem and Enabling Technologies","topics":["IoT Ecosystem, Challenges and Levels of Implementation, Enabling Technologies","Overview of Processing Elements and Peripherals"]},{"title":"Programming for Prototyping Boards","topics":["Environment: Board, IDE, shields","Programming: syntax, variables, types, operators, constructs and functions","Sketch: skeleton, compile and upload, accessing pins","Debugging: UART communication protocol and serial library"]},{"title":"Interfacing with Prototyping Boards","topics":["Circuits: design, wiring, passive components","Sensors and Actuators: Interfacing, Read/Write","Software libraries; Shields - interfacing and libraries"]},{"title":"Single Board Computers: Programming & Interfacing","topics":["SBC Architecture & Schematic Board schematic","Setup, Configure & Use, OS implications: Linux - basics, file system and processes, Shell CLI & GUI","Programming APIs - RPi. GPIO - PWM library to access pins - Tkinter GUI"]},{"title":"IoT Networking, Protocols & Cloud Integration","topics":["Networking & Internet Connectivity, Standard Internet Protocols - MQTT & CoAP","Networking Socket Interface - Cloud - Public APIs and SDK''s for accessing cloud services","Social Network APIs - Interfacing - sensors and actuators - Pi Camera, Servo - APIs for data conversion","Unit 6.0: Embedded Programming and RTOS Embedded Programming: MCU, GPIO, WDT, timers/counters - I/O - A/D - D/A, PWM, Interrupts, Memory; serial communication UART - I2C - SPI, Peripheral Interfacing OS - basics - types - tasks - process - threads (POSIX Threads), thread preemption - Preemptive Task Scheduling Policies - Priority Inversion - Task communication - Task Synchronization issues - racing and deadlock - binary and counting semaphores (Mutex example) - choosing RTOS Real World Projects: IoT Integrated Primary Health Care, Face Detection by AI, Cloud IoT Systems for Smart Agriculture, Smart Home Gadgets, Autonomous Car Features, Speed and horn intensity control","Embedded Programming: MCU, GPIO, WDT, timers/counters - I/O - A/D - D/A, PWM, Interrupts, Memory; serial communication UART - I2C - SPI, Peripheral Interfacing","OS - basics - types - tasks - process - threads (POSIX Threads), thread preemption - Preemptive Task Scheduling Policies - Priority Inversion - Task communication - Task Synchronization issues - racing and deadlock - binary and counting semaphores (Mutex example) - choosing RTOS","Real World Projects: IoT Integrated Primary Health Care, Face Detection by AI, Cloud IoT Systems for Smart Agriculture, Smart Home Gadgets, Autonomous Car Features, Speed and horn intensity control","Yamanoor, Sai, and Srihari Yamanoor. Python Programming with Raspberry Pi, 2017, 1st edition, Packt Publishing Ltd., UK","Donald Norris, The Internet of Things: Do-It-Yourself Projects with Arduino, Raspberry Pi, and BeagleBone Black, 2015, 1st edition, McGraw Hill Education, India","Marco Schwartz, Home Automation with Arduino, 3rd edition, Open Home Automation 2014. Schwartz, Marco. Internet of things with arduino cookbook, 2016, 1st edition, Packt Publishing Ltd., UK","Kooijman, Matthijs. Building Wireless Sensor Networks Using Arduino, 2015, 1st edition, Packt Publishing Ltd., UK"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Introduction fundamentals and definitions, Feature vectors, Classifiers, Supervised and Unsupervised learning, Bayesian decision theory"]},{"title":"Features","topics":["Types and traits, scaling ordering, measurements, normalization, invariance, feature properties","Dimensionality reduction of feature space, dimensionality reduction by feature selection, PCA, KPCA, ICA"]},{"title":"Parameter estimation","topics":["Maximum likelihood estimation (MLE), least squares estimation (LSE), Method of minimum variance & unbiased Estimation (MVUE); parameter free methods: KNN, Clustering","Special classifiers: linear regression, LDA, SVM, CNN"]},{"title":"Classifiers and learning","topics":["Fundamentals of classifiers, Linear Classifiers, Nonlinear Classifiers. Unsupervised and semi supervised learning: Learning from unclassified data, Characteristics analysis of different classifiers"]},{"title":"Clustering","topics":["Basic Concepts of clustering, Hierarchical agglomerative clustering, K-means partitional clustering, semi supervised learning with expectation maximization using labelled and unlabelled data"]},{"title":"Classification and Ensemble Learning Techniques","topics":["Classification with nominal features : decision tree, random forest; classifier independent concepts, Combinations of classifiers: boosting, voting, stacking","Christopher Bishop, Pattern Recognition and Machine Learning, Springer, 2nd printing edition, 2011","Richard O. Duda, Peter E. Hart, David G. Stork, Pattern Classification, John Wiley, 2nd edition, 2002","Kevin P. Murphy, Machine Learning: A Probabilistic Perspective, The MIT Press; Illustrated edition, 2012","S. Theodoridis, K. Koutroumbas, \"Pattern Recognition\", Academic Press, 4th edition, 2008"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction to Sensors Principles of sensing, classification and characteristics, Static and dynamic parameters, Environmental Parameters (EP), Sensor Characterization Electromechanical Sensors: Introduction, Resistive Potentiometer, Strain Gauge, Resistance Strain Gauge, Semiconductor Strain Gauges Inductive Sensors: Sensitivity and Linearity of the Sensor, Types; Capacitive Sensors: Electrostatic Transducer, Force/Stress Sensors Using Quartz Resonators, Ultrasonic Sensors","Principles of sensing, classification and characteristics, Static and dynamic parameters, Environmental Parameters (EP), Sensor Characterization","Electromechanical Sensors: Introduction, Resistive Potentiometer, Strain Gauge, Resistance Strain Gauge, Semiconductor Strain Gauges","Inductive Sensors: Sensitivity and Linearity of the Sensor, Types; Capacitive Sensors: Electrostatic Transducer, Force/Stress Sensors Using Quartz Resonators, Ultrasonic Sensors","Unit 2.0: Thermal and Magnetic Sensors Thermal Sensors: Gas Thermometric Sensors, Thermal Expansion Type Thermometric Sensors, Acoustic Temperature Sensor, Dielectric Constant and Refractive Index Thermosensors, Helium Low Temperature Thermometer, Nuclear and Magnetic Thermometer, Resistance Change Type Thermometric Sensors, Junction Semiconductor Types Magnetic Sensors: Working Principles, Types and Characteristics, Force & displacement Sensors","Thermal Sensors: Gas Thermometric Sensors, Thermal Expansion Type Thermometric Sensors, Acoustic Temperature Sensor, Dielectric Constant and Refractive Index Thermosensors, Helium Low Temperature Thermometer, Nuclear and Magnetic Thermometer, Resistance Change Type Thermometric Sensors, Junction Semiconductor Types","Magnetic Sensors: Working Principles, Types and Characteristics, Force & displacement Sensors"]},{"title":"Radiation Sensors","topics":["Radiation Sensors: Introduction, Basic Characteristics, Types of Photoresistors /Photodetectors, X-ray and Nuclear Radiation Sensors, Fiber Optic Sensors"]},{"title":"Smart Sensors & Interfacing","topics":["Introduction, Primary Sensors, Excitation, Amplification, Filters, Converters (ADC/DAC), Compensation, Information Coding and Processing, Data Communication, Standards for Smart Sensor Interface, Sensor Nodes & Automation Interfaces"]},{"title":"Sensors Applications","topics":["On-board Automobile Sensors, Home Appliance Sensors, Medical Diagnostic Sensors, Sensors for Manufacturing, Environmental Monitoring Sensors"]},{"title":"Actuators","topics":["Pneumatic and Hydraulic Actuation Systems, Valves and Rotary actuators, Mechanical Actuation Systems, Electrical Actuation Systems (Solenoids, Motors, Relays)","D. Patranabis-Sensors and Transducers, PHI Learning Private Limited","W. Bolton-Mechatronics, Pearson Education Limited. Reference Books","Patranabis-Sensors and Actuators-2nd Ed., PHI, 2013","Robert H. Bishop-The Mechatronics Handbook, 2nd Ed., Mechatronic Systems, Sensors and Actuators, fundamentals and modelling e- Resources & other digital material"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Self-Discovery and Analysis","topics":["Self-Analysis: SWOT Analysis, Who am I, Attributes, Importance of Self-Confidence, Self-Esteem"]},{"title":"Creative and Innovative Thinking","topics":["Creativity: Out of Box Thinking, Lateral Thinking"]},{"title":"Attitude and Motivation","topics":["Attitude: Factors Influencing Attitude, Challenges and Lessons from Attitude, Etiquette","Motivation: Factors of Motivation, Self-Talk, Intrinsic & Extrinsic Motivators"]},{"title":"Strategic Goal Setting","topics":["Goal Setting: Wish List, SMART Goals, Blue Print for Success, Short Term, Long Term, Life Time Goals"]},{"title":"Effective Time Management","topics":["Time Management: Value of Time, Diagnosing Time Management, Weekly Planner, To Do List, Prioritizing Work"]},{"title":"Interpersonal Skills and Teamwork","topics":["Interpersonal Skills: Gratitude - Understanding the relationship between Leadership Networking & Team work. Assessing Interpersonal Skills Situation description of Interpersonal Skill","Team Work - Necessity of Team Work Personally, Socially and Educationally","Soft Skills, 2015, Career Development Centre, Green Pearl Publications","Covey Sean, Seven Habits of Highly Effective Teens, New York, Fireside Publishers, 1998","Carnegie Dale, How to win Friends and Influence People, New York: Simon & Schuster, 1998"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction MOSFET, threshold voltage, current, Channel length modulation, body bias","topics":["Unit 2.0: CMOS inverter, static characteristics, noise margin, effect of process variation, supply scaling, dynamic characteristics, inverter design for a given VTC and speed, effect of input rise time and fall time, static and dynamic power dissipation, energy & power delay product, sizing chain of inverters, latch up effect- Simulation of static and dynamic characteristics, layout, post layout simulation"]},{"title":"Static CMOS design, Complementary CMOS, static properties, propagation delay, Elmore","topics":[]},{"title":"Pseudo NMOS inverter, DCVSL, PTL, DPTL & Transmission gate logic,","topics":[]},{"title":"Circuit design considerations of Arithmetic circuits, shifter, CMOS memory design","topics":[]},{"title":"BiCMOS logic - static and dynamic behaviour - Delay and","topics":["Principles of CMOS VLSI design: a system perspective by Neil H.E. Weste and Kamran Eshraghian; Addision Wesley pub","Digital integrated circuits by Demassa & Ciccone. Wiley pub","Modern VLSI Design system on silicon by Wayne Wolf: Addision Wesley Longman Publisher","Basic VLSI Design by Douglas A Pucknell & Kamran Eshraghian; PHI","Digital Integrated Circuits: A Design Perspective by Jan M Rabaey; PHI"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Sales and Marketing","topics":["Marketing: Definition, importance, and evolution of marketing concepts","Sales: Definition, role of sales in a business, and the relationship between sales and marketing","Marketing Mix (4Ps): Product, Price, Place (Distribution), and Promotion","Consumer Behavior: Understanding consumer motivations, buying decisions, and factors influencing purchasing","Unit 2.0: Market Analysis and Strategy Market Segmentation, Targeting, and Positioning (STP): Identifying target markets, developing positioning strategies Market Research: Understanding the purpose of market research, types of research methods, and data analysis Competitive Analysis: Identifying competitors, analyzing their strengths and weaknesses, and developing competitive strategies Strategic Marketing Planning: Developing marketing plans, setting objectives, and measuring performance","Market Segmentation, Targeting, and Positioning (STP): Identifying target markets, developing positioning strategies","Market Research: Understanding the purpose of market research, types of research methods, and data analysis","Competitive Analysis: Identifying competitors, analyzing their strengths and weaknesses, and developing competitive strategies","Strategic Marketing Planning: Developing marketing plans, setting objectives, and measuring performance","Unit 3.0: Sales Management and Techniques Sales Processes and Strategies: Understanding different sales strategies, lead generation, and sales techniques Sales Force Management: Recruiting, training, motivating, and managing sales personnel Customer Relationship Management (CRM): Understanding the importance of CRM, managing customer interactions, and building strong relationships Sales Communication and Negotiation: Developing effective communication skills, negotiation techniques, and closing sales","Sales Processes and Strategies: Understanding different sales strategies, lead generation, and sales techniques","Sales Force Management: Recruiting, training, motivating, and managing sales personnel","Customer Relationship Management (CRM): Understanding the importance of CRM, managing customer interactions, and building strong relationships","Sales Communication and Negotiation: Developing effective communication skills, negotiation techniques, and closing sales","Unit 4.0: Marketing Communication and Promotion Advertising: Understanding different advertising media, campaign planning, and media buying Sales Promotion: Understanding different types of sales promotions, couponing, and loyalty programs Public Relations (PR): Building positive relationships with the public, media relations, and crisis communication Digital Marketing: Understanding online marketing channels, social media marketing, SEO, and email marketing","Advertising: Understanding different advertising media, campaign planning, and media buying","Sales Promotion: Understanding different types of sales promotions, couponing, and loyalty programs","Public Relations (PR): Building positive relationships with the public, media relations, and crisis communication","Digital Marketing: Understanding online marketing channels, social media marketing, SEO, and email marketing"]},{"title":"Product, Branding, and Pricing Strategies","topics":["Product and Brand Management: Developing and managing product lines, branding strategies, and brand equity","Pricing Strategies: Understanding different pricing methods, pricing objectives, and pricing policies"]},{"title":"Distribution Channels and Ethics in Sales & Marketing","topics":["Distribution Channels: Understanding different distribution channels, logistics, and supply chain management","Ethics in Sales and Marketing: Understanding ethical issues in sales and marketing, and responsible marketing practices","K.S. Chandrasekar, Marketing Management Text And Cases, Tata Mcgraw- Hill Publication, New Delhi.2010","Govindarajan, Marketing Management Concepts, Cases, Chhallenges And Trends, Prentice Hall Of India, New Delhi. 2009","Philip Kotler, Marketing Management- Analysis Planning And Control, Prentice Hall Of India, New Delhi,","Ramaswamy. V S & Namakumari. S, Marketing Management-Planning Implementation And Control, Macmillan Business Books, New Delhi, 2002","Balaram Dogra & Karminder Ghuman, Rural Marketing: Concept & Cases, Tata Mcgraw- Hill Publishing Company, New Delhi, 2008","Ravi Shanker, Services Marketing: The Indian Perspective, Excel Books, New Delhi, 2008"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Discrete-time signals and systems","topics":["Discrete time signals and systems: Sequences; representation of signals on orthogonal basis; Representation of discrete systems using difference equations, Sampling and reconstruction of signals - aliasing; Sampling theorem and Nyquist rate"]},{"title":"Z-transform","topics":["Z-Transform, Region of Convergence, Analysis of Linear Shift Invariant systems using z-transform, Properties of z-transform for causal signals, Interpretation of stability in z-domain, Inverse z-transforms"]},{"title":"Discrete Fourier Transform","topics":["Frequency Domain Analysis, Discrete Fourier Transform (DFT), Properties of DFT, Convolution of signals, Fast Fourier Transform Algorithm, Parseval''s Identity, Implementation of Discrete Time Systems"]},{"title":"Design of Digital filters","topics":["Design of FIR Digital filters: Window method, Park-McClellan''s method. Design of IIR Digital Filters: Butterworth, Chebyshev and Elliptic Approximations; Low-pass, Bandpass, Band-stop and Highpass filters"]},{"title":"Effect of finite register length in FIR filter design, Parametric","topics":[]},{"title":"Applications of Digital Signal Processing","topics":["Correlation Functions and Power Spectra, Stationary Processes, Optimal filtering using ARMA Model, Linear Mean-Square Estimation, Wiener Filter","S. K. Mitra, \"Digital Signal Processing: A computer based approach\", McGraw Hill, 2011","A.V. Oppenheim and R. W. Schafer, \"Discrete Time Signal Processing\", Prentice Hall, 1989","J. G. Proakis and D.G. Manolakis, \"Digital Signal Processing: Principles, Algorithms and Applications\", Prentice Hall, 1997","L. R. Rabiner and B. Gold, \"Theory and Application of Digital Signal Processing\", Prentice Hall, 1992","J. R. Johnson, \"Introduction to Digital Signal Processing\", Prentice Hall, 1992","D. J. DeFatta, J. G. Lucas and W. S. Hodgkiss, \"Digital Signal Processing\", John Wiley & Sons, 1988"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Discrete Representation of Continuous Systems","topics":["Basics of Digital Control Systems. Discrete representation of continuous systems. Sample and hold circuit. Mathematical Modelling of sample and hold circuit. Effects of Sampling and Quantization. Choice of sampling frequency. ZOH equivalent"]},{"title":"Discrete System Analysis","topics":["Z-Transform and Inverse Z Transform for analyzing discrete time systems. Pulse Transfer function. Pulse transfer function of closed loop systems. Mapping from s-plane to z plane. Solution of Discrete time systems. Time response of discrete time system"]},{"title":"Stability of Discrete Time System","topics":["Stability analysis using Jury test, Stability analysis using bilinear transformation, Design of digital control system with dead beat response, Practical issues with dead beat response design"]},{"title":"State Space Approach for discrete time systems","topics":["State space models of discrete systems, State space analysis. Lyapunov Stability. Controllability, reach-ability, Re-constructibility and observability analysis. Effect of pole zero cancellation on the controllability & observability"]},{"title":"Design of Digital Control System","topics":["Design of Discrete PID Controller, Design of discrete state feedback controller. Design of set point tracker. Design of Discrete Observer for LTI System. Design of Discrete compensator"]},{"title":"Discrete output feedback control","topics":["Design of discrete output feedback control. Fast output sampling (FOS) and periodic output feedback controller design for discrete time systems","K. Ogata, \"Digital Control Engineering\", Prentice Hall, Englewood Cliffs, 1995","M. Gopal, \"Digital Control Engineering\", Wiley Eastern, 1988","G. F. Franklin, J. D. Powell and M. L. Workman, \"Digital Control of Dynamic Systems\", Addison-Wesley, 1998","B.C. Kuo, \"Digital Control System\", Holt, Rinehart and Winston, 1980"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Perform any 10 experiments from the following list:","Write a program to implement a single-layer perceptron for binary classification","Build an MLP classifier using a custom forward pass and backpropagation","Implement Backward propagation neural network","Implement Gradient Descent, SGD, and Momentum on a simple function and plot convergence","Write a program to perform manual convolution on an image using a custom filter (edge detection / blur)","Build a CNN on MNIST / CIFAR-10 using PyTorch or TensorFlow","Train, test, and report accuracy","Use a pretrained model (VGG16 / ResNet50) and fine-tune it on a small dataset","RNN / LSTM for Text Generation, sentiment analysis","Implement LSTM-based text generation on a small text corpus (e.g., nursery rhymes)","Build a Denoising Autoencoder to remove noise from images (MNIST/CIFAR-10)"]}]'::jsonb from s;
