insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Self-Analysis","topics":["Swot Analysis","Who Am I, Attributes","Importance Of Self Confidence, Self Esteem"]},{"title":"Creativity","topics":["Out Of Box Thinking","Lateral Thinking"]},{"title":"Attitude and Motivation","topics":["Factors Influencing Attitude","Challenges And Lessons From Attitude","Etiquette","Factors Of Motivation","Self-Talk","Intrinsic & Extrinsic Motivators"]},{"title":"Goal Setting and Time Management","topics":["Wish List","Smart Goals","Blueprint For Success","Short Term, Long Term, Lifetime Goals","Value Of Time","Diagnosing Time Management","Weekly Planner","To Do List","Prioritizing Work"]},{"title":"Interpersonal Skills","topics":["Gratitude Understanding The Relationship Between Leadership Networking & Team Work","Assessing Interpersonal Skills Situation Description Of Interpersonal Skill","Team Work Necessity Of Team Work Personally, Socially And Educationally","Soft Skills, 2015, Career Development Centre, Green Pearl Publications.","Covey Sean, Seven Habits of Highly Effective Teens, New York, Fireside Publishers, 1998.","Carnegie Dale, How to Win Friends and Influence People, New York: Simon & Schuster, 1998."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: Concepts and Perspectives Meaning Of History Objectivity, Determinism, Relativism, Causation, Generalization In History Moral Judgment In History Extent Of Subjectivity, Contrast With Physical Sciences, Interpretation And Speculation, Causation Versus Evidence, Concept Of Historical Inevitability, Historical Positivism Science And Technology-Meaning, Scope And Importance Interaction Of Science, Technology & Society Sources Of History On Science And Technology In India","Meaning Of History Objectivity, Determinism, Relativism, Causation, Generalization In History","Moral Judgment In History Extent Of Subjectivity, Contrast With Physical Sciences, Interpretation And Speculation, Causation Versus Evidence, Concept Of Historical Inevitability, Historical Positivism","Science And Technology-Meaning, Scope And Importance","Interaction Of Science, Technology & Society","Sources Of History On Science And Technology In India"]},{"title":"Historiography of Science and Technology in India","topics":["Introduction To The Works Of D.D. Kosambi, Dharmpal, Debiprasad Chattopadhyay, Rehman, S. Irfan Habib, Deepak Kumar, Dhruv Raina, And Others"]},{"title":"Science and Technology in Ancient India","topics":["Technology In Pre-historic Period Beginning Of Agriculture And Its Impact On Technology","Science And Technology During Vedic And Later Vedic Times","Science And Technology From 1st Century AD To C-1200"]},{"title":"Science and Technology in Medieval India","topics":["Legacy Of Technology In Medieval India","Interactions With Arabs Development In Medical Knowledge","Interaction Between Unani And Ayurveda And Alchemy","Astronomy And Mathematics: Interaction With Arabic Sciences","Science And Technology On The Eve Of British Conquest"]},{"title":"Science and Technology in Colonial India","topics":["Science And The Empire","Indian Response To Western Science","Growth Of Techno-scientific Institutions"]},{"title":"Science and Technology in a Post-Independent India","topics":["Science, Technology And Development Discourse","Shaping Of The Science And Technology Policy","Developments In The Field Of Science And Technology","Science And Technology In Globalizing India","Social Implications Of New Technologies Like The Information Technology And Biotechnology"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: Framework of Indian Economy National Income Trends And Structure Of National Income Demographic Features And Indicators Of Economic Growth Development Rural-Urban Migration And Issues Related To Urbanization Poverty Debate And Inequality, Nature, Policy And Implications Unemployment-Nature, Central And State Government''s Policies, Policy Implications Employment Trends In Organized And Unorganized Sector","National Income Trends And Structure Of National Income","Demographic Features And Indicators Of Economic Growth","Development Rural-Urban Migration And Issues Related To Urbanization","Poverty Debate And Inequality, Nature, Policy And Implications","Unemployment-Nature, Central And State Government''s Policies, Policy Implications","Employment Trends In Organized And Unorganized Sector","Module 2: Development Strategies in India Agricultural Pricing, Marketing And Financing Of Primary Sector Economic Reforms Rationale Of Economic Reforms Liberalization, Privatization And Globalization Of The Economy Changing Structure Of India''s Foreign Trade Role Of Public Sector Redefining The Role Of Public Sector Government Policy Towards Public Sector Problems Associated With Privatization Issues Regarding Deregulation-Disinvestment And Future Of Economic Reforms","Agricultural Pricing, Marketing And Financing Of Primary Sector","Economic Reforms Rationale Of Economic Reforms","Liberalization, Privatization And Globalization Of The Economy","Changing Structure Of India''s Foreign Trade","Role Of Public Sector Redefining The Role Of Public Sector","Government Policy Towards Public Sector","Problems Associated With Privatization","Issues Regarding Deregulation-Disinvestment And Future Of Economic Reforms"]},{"title":"The Economic Policy and Infrastructure Development","topics":["Energy And Transport","Social Infrastructure Education, Health And Gender Related Issues","Social Inclusion","Issues And Policies In Financing Infrastructure Development","Indian Financial System Issues Of Financial Inclusion","Financial Sector Reforms-review Of Monetary Policy Of R.B.I","Capital Market In India"]},{"title":"The Economic Policy and Industrial Sector","topics":["Industrial Sector In Pre-reforms Period","Growth And Pattern Of Industrialization","Industrial Sector In Post-reform Period Growth And Pattern Of Micro, Small, Medium Enterprises","Problems Of India''s Industrial Exports","Labor Market Issues In Labor Market Reforms And Approaches To Employment Generation","Dhingra, Ishwar C. [2006],''Indian Economy,'' Sultan Chand and Sons, New Delhi.","Datt, Ruddar and Sundaram, K.P.M. [Latest edition] ,''Indian Economy,'' S. Chand and Co, New Delhi.","Brahmananda, P.R. and V.A. Panchmukhi. [2001], Ed. ''Development Experience in Indian Economy, Inter-state Perspective,'' Bookwell, New Delhi.","Gupta,S.P. [1989],''Planning and Development in India: A Critique,'' Allied Publishers Private Limited, New Delhi.","Bhagwati, Jagdish. [2004],''In Defense of Globalization,'' Oxford University Press, U.K."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["→ Discuss The Structure Of The Legal System And How It Enforces Laws Governing The Internet","→ Evaluate The Ethical Responsibilities Of Internet Users, Service Providers, And Content Providers","→ Examine The Constitutional Considerations Concerning Free Speech And Content Controls In Cyberspace","→ Investigate A Security Breach And The Legally Required Responses To A Breach"]},{"title":"Introduction","topics":["Computers And Its Impact In Society","Overview Of Computer And Web Technology","The Internet And Online Resources","Security Of Information","Introduction To Ethical Theory And Its Application To The Internet","Definition Of Cyber Security","Search Engines, E - mails And WWW","E - commerce & M - commerce System Security","Government Regulation Of The Internet"]},{"title":"Cyber Crimes & Legal Framework","topics":["Distinction Between Cyber Crime And Conventional Crime","Cyber Criminals And Their Objectives","Kinds Of Cyber Crime: Hacking, Digital Forgery, Cyber Stalking/Harassment, Identity Theft & Fraud, Cyber Terrorism, Cyber Defamation, Computer Vandalism Etc","Cyber Crimes Against Individuals, Institution And State","Issues In Data And Software Privacy","Cyber Forensics","Module 3: Introduction to Indian Cyber Law Overview Of General Laws And Procedures In India Different Offences Under IT Act Overview Of Information Technology Act, 2000 And Information Technology (Amendment) Act, 2008 National Cyber Security Policy 2013 Offences In Cyber Space Under The Indian Penal Code, 1860 Intellectual Property Issues In Cyberspace Interface With Copyright Law Interface With Patent Law Trademarks & Domain Names Related Issues","Overview Of General Laws And Procedures In India","Different Offences Under IT Act","Overview Of Information Technology Act, 2000 And Information Technology (Amendment) Act, 2008","National Cyber Security Policy 2013","Offences In Cyber Space Under The Indian Penal Code, 1860","Intellectual Property Issues In Cyberspace","Interface With Copyright Law","Interface With Patent Law","Trademarks & Domain Names Related Issues"]},{"title":"Constitutional & Human Rights Issues in Cyberspace","topics":["Freedom Of Speech And Expression In Cyberspace","Right To Access Cyberspace","Access To Internet","Right To Privacy","Right To Data Protection","Issues With Cybercrime Using Social Networking Sites","Electronic Commerce","Digital Signatures Technical And Legal Issues","Electronic Contracts","Law Relating To Hardware And Software Layout & Design","Jonathan Rosenoer, \"Cyberlaw: the Law of the Internet\" Springer-Verlag New York Inc.","Pavan Duggal, \"Cyber Law - An exhaustive section wise Commentary on the Information Technology Act along with Rules, Regulations, Policies, Notifications etc.\", Universal Law Publishing.","Deborah E. Bouchoux, \"Intellectual Property: The Law Of Trademarks, Copyrights, Patents, And Trade Secrets\", Cengage Learning.","M. K. Bhandari, \"Law Relating to Intellectual Property Rights\", Central Law Publications.","Vivek Sood, \"Cyber Law Simplified\", McGraw Hill Education.","Prashant Mali, \"Cyber Law & Cyber Crimes Simplified\", Cyber Infomedia.","→ After The Completion Of Course, Students Are Able To Demonstrate A Critical Understanding Of The Cyber Law And Cyber-crime With Respect To IT Act"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["The Course Has Been Designed To Give Students An Extensive Overview Of Cyber Security Issues, Tools And Techniques That Are Critical In Solving Problems In Cyber Security Domains. The Course Aims At Providing Students With Concepts Of Computer Security, Cryptography, Digital Money, Secure Protocols, Detection And Other Security Techniques. The Course Will Help Students To Gauge Understanding In Essential Techniques In Protecting Information Systems, IT Infrastructure, Analysing And Monitoring Potential Threats And Attacks, Devising Security Architecture And Implementing Security Solutions. The Students Will Also Have A Wider Perspective To Information Security From National Security Perspective From Both Technology And Legal Perspective."]},{"title":"Cyber Security Concepts","topics":["Essential Terminologies: Cia, Risks, Breaches, Threats, Attacks, Exploits","Information Gathering (Social Engineering, Foot Printing & Scanning)","Open Source/ Free/ Trial Tools: Nmap, Zenmap, Port Scanners, Network Scanners","Module 2: Cryptography and Cryptanalysis Introduction To Cryptography Symmetric Key Cryptography Asymmetric Key Cryptography Message Authentication Digital Signatures Applications Of Cryptography Overview Of Firewalls Types Of Firewalls User Management VPN Security Security Protocols Security At The Application Layer PGP And S/MIME Security At Transport Layer SSL And TLS Security At Network Layer IPSec Open Source/ Free/ Trial Tools: Implementation Of Cryptographic Techniques, OpenSSL, Hash Values Calculations MD5, SHA1, SHA256, SHA 512, Steganography (Stools)","Introduction To Cryptography","Symmetric Key Cryptography","Asymmetric Key Cryptography","Message Authentication","Digital Signatures","Applications Of Cryptography","Overview Of Firewalls Types Of Firewalls","User Management","VPN Security","Security Protocols Security At The Application Layer PGP And S/MIME","Security At Transport Layer SSL And TLS","Security At Network Layer IPSec","Open Source/ Free/ Trial Tools: Implementation Of Cryptographic Techniques, OpenSSL, Hash Values Calculations MD5, SHA1, SHA256, SHA 512, Steganography (Stools)","Module 3: Infrastructure and Network Security Introduction To System Security Server Security OS Security Physical Security Introduction To Networks Network Packet Sniffing Network Design Simulation DOS/ DDOS Attacks Asset Management And Audits Vulnerabilities And Attacks Intrusion Detection And Prevention Techniques Host Based Intrusion Prevention Systems Security Information Management Network Session Analysis System Integrity Validation Open Source/ Free/ Trial Tools: DOS Attacks, DDOS Attacks, Wireshark, Cain & Abel, Iptables/ Windows Firewall, Snort, Suricata, Fail2ban","Introduction To System Security","Server Security","OS Security","Physical Security","Introduction To Networks","Network Packet Sniffing","Network Design Simulation","DOS/ DDOS Attacks","Asset Management And Audits","Vulnerabilities And Attacks","Intrusion Detection And Prevention Techniques","Host Based Intrusion Prevention Systems","Security Information Management","Network Session Analysis","System Integrity Validation","Open Source/ Free/ Trial Tools: DOS Attacks, DDOS Attacks, Wireshark, Cain & Abel, Iptables/ Windows Firewall, Snort, Suricata, Fail2ban","Module 4: Cyber Security Vulnerabilities & SafeGuards Internet Security Cloud Computing & Security Social Network Sites Security Cyber Security Vulnerabilities Overview Vulnerabilities In Software System Administration Complex Network Architectures Open Access To Organizational Data Weak Authentication Authorization Unprotected Broadband Communications Poor Cyber Security Awareness Cyber Security Safeguards Overview Access Control IT Audit Authentication Open Web Application Security Project (OWASP) Web Site Audit And Vulnerabilities Assessment Open Source/ Free/ Trial Tools: WinAudit, Zap Proxy (OWASP), Burp Suite, DWMA Kit","Internet Security","Cloud Computing & Security","Social Network Sites Security","Cyber Security Vulnerabilities Overview","Vulnerabilities In Software","System Administration","Complex Network Architectures","Open Access To Organizational Data","Weak Authentication","Authorization","Unprotected Broadband Communications","Poor Cyber Security Awareness","Cyber Security Safeguards Overview","Access Control","IT Audit","Authentication","Open Web Application Security Project (OWASP)","Web Site Audit And Vulnerabilities Assessment","Open Source/ Free/ Trial Tools: WinAudit, Zap Proxy (OWASP), Burp Suite, DWMA Kit"]},{"title":"Malware","topics":["Explanation Of Malware","Types Of Malware: Virus, Worms, Trojans, Rootkits, Robots, Adware''s, Spywares, Ransom Wares, Zombies Etc","OS Hardening (Process Management, Memory Management, Task Management, Windows Registry/ Services Another Configuration)","Malware Analysis","Open Source/ Free/ Trial Tools: Antivirus Protection, Anti Spywares, System Tuning Tools, Anti Phishing","Module 6: Security in Evolving Technology Biometrics Mobile Computing And Hardening On Android And iOS IOT Security Web Server Configuration And Security Introduction, Basic Security For HTTP Applications And Services Basic Security For Web Services Like SOAP, REST Etc Identity Management And Web Services Authorization Patterns Security Considerations Challenges Open Source/ Free/ Trial Tools: Adb For Android, Xcode For iOS, Implementation Of REST/ SOAP Web Services And Security Implementations","Biometrics","Mobile Computing And Hardening On Android And iOS","IOT Security","Web Server Configuration And Security","Introduction, Basic Security For HTTP Applications And Services","Basic Security For Web Services Like SOAP, REST Etc","Identity Management And Web Services","Authorization Patterns","Security Considerations","Challenges","Open Source/ Free/ Trial Tools: Adb For Android, Xcode For iOS, Implementation Of REST/ SOAP Web Services And Security Implementations","Module 7: Cyber Laws and Forensics Introduction Cyber Security Regulations Roles Of International Law, The State And Private Sector In Cyberspace Cyber Security Standards The INDIAN Cyberspace National Cyber Security Policy 2013 Introduction To Cyber Forensics Need Of Cyber Forensics Cyber Evidence Documentation And Management Of Crime Sense Image Capturing And Its Importance Partial Volume Image Web Attack Investigations Denial Of Service Investigations Internet Crime Investigations Internet Forensics Steps For Investigating Internet Crime Email Crime Investigations Open Source/ Free/ Trial Tools: Case Studies Related To Cyber Law, Common Forensic Tools Like Dd, Md5sum, Shalsum, Ram Dump Analysis, USB Device","Introduction","Cyber Security Regulations","Roles Of International Law, The State And Private Sector In Cyberspace","Cyber Security Standards","The INDIAN Cyberspace","National Cyber Security Policy 2013","Introduction To Cyber Forensics","Need Of Cyber Forensics","Cyber Evidence","Documentation And Management Of Crime Sense","Image Capturing And Its Importance","Partial Volume Image","Web Attack Investigations","Denial Of Service Investigations","Internet Crime Investigations","Internet Forensics","Steps For Investigating Internet Crime","Email Crime Investigations","Open Source/ Free/ Trial Tools: Case Studies Related To Cyber Law, Common Forensic Tools Like Dd, Md5sum, Shalsum, Ram Dump Analysis, USB Device","William Stallings, \"Cryptography and Network Security\", Pearson Education/PHI, 2006.","V.K. Jain, \"Cryptography and Network Security\", Khanna Publishing House.","Gupta Sarika, \"Information and Cyber Security\", Khanna Publishing House, Delhi.","Atul Kahate, \"Cryptography and Network Security\", McGraw Hill.","V.K. Pachghare, \"Cryptography and Information Security\", PHI Learning","Nina Godbole, \"Information System Security\", Wiley","Bothra Harsh, \"Hacking\", Khanna Publishing House, Delhi.","After completion of this course, the students should be able to:","→ Understand, Appreciate, Employ, Design And Implement Appropriate Security Technologies And Policies To Protect Computers And Digital Information","→ Identify & Evaluate Information Security Threats And Vulnerabilities In Information Systems And Apply Security Measures To Real Time Scenarios","→ Identify Common Trade-offs And Compromises That Are Made In The Design And Development Process Of Information Systems","→ Demonstrate The Use Of Standards And Cyber Laws To Enhance Information Security In The Development Process And Infrastructure Protection"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["The Objective Of This Course Is To Provide A Detailed Understanding Of The Concepts Of Virtual Reality And Its Applications","Module 1: Introduction to Virtual Reality Virtual Reality And Virtual Environment: Introduction Computer Graphics Real Time Computer Graphics Flight Simulation Virtual Environment Requirement Benefits Of Virtual Reality Historical Development Of VR Scientific Landmark 3D Computer Graphics: Introduction The Virtual World Space Positioning The Virtual Observer The Perspective Projection Human Vision Stereo Perspective Projection 3D Clipping Colour Theory Simple 3D Modelling Illumination Models Reflection Models Shading Algorithms Radioisity Hidden Surface Removal Realism-Stereographic Image","Virtual Reality And Virtual Environment: Introduction","Computer Graphics","Real Time Computer Graphics","Flight Simulation","Virtual Environment Requirement","Benefits Of Virtual Reality","Historical Development Of VR","Scientific Landmark","3D Computer Graphics: Introduction","The Virtual World Space","Positioning The Virtual Observer","The Perspective Projection","Human Vision","Stereo Perspective Projection","3D Clipping","Colour Theory","Simple 3D Modelling","Illumination Models","Reflection Models","Shading Algorithms","Radioisity","Hidden Surface Removal","Realism-Stereographic Image","Module 2: Geometric Modelling and Generic VR system Geometric Modelling: Introduction From 2D To 3D 3D Space Curves 3D Boundary Representation Geometrical Transformations: Introduction Frames Of Reference Modelling Transformations Instances Picking Flying Scaling The VE Collision Detection Generic VR System: Introduction Virtual Environment Computer Environment VR Technology Model Of Interaction VR Systems","Geometric Modelling: Introduction","From 2D To 3D","3D Space Curves","3D Boundary Representation","Geometrical Transformations: Introduction","Frames Of Reference","Modelling Transformations","Instances","Picking","Flying","Scaling The VE","Collision Detection","Generic VR System: Introduction","Virtual Environment","Computer Environment","VR Technology","Model Of Interaction","VR Systems","Module 3: Virtual Environment and Physical Simulation Animating The Virtual Environment: Introduction The Dynamics Of Numbers Linear And Nonlinear Interpolation The Animation Of Objects Linear And Non-linear Translation Shape & Object In Betweening Free From Deformation Particle System Physical Simulation: Introduction Objects Falling In A Gravitational Field Rotating Wheels Elastic Collisions Projectiles Simple Pendulum Springs Flight Dynamics Of An Aircraft","Animating The Virtual Environment: Introduction","The Dynamics Of Numbers","Linear And Nonlinear Interpolation","The Animation Of Objects","Linear And Non-linear Translation","Shape & Object In Betweening","Free From Deformation","Particle System","Physical Simulation: Introduction","Objects Falling In A Gravitational Field","Rotating Wheels","Elastic Collisions","Projectiles","Simple Pendulum","Springs","Flight Dynamics Of An Aircraft"]},{"title":"VR Hardware and Software","topics":["Human Factors: Introduction","The Eye","The Ear","The Somatic Senses","VR Hardware: Introduction","Sensor Hardware","Head-coupled Displays","Acoustic Hardware","Integrated VR Systems","VR Software: Introduction","Modelling Virtual World","Physical Simulation","VR Toolkits","Introduction To VRML"]},{"title":"VR Applications and The Future","topics":["VR Applications: Introduction","Engineering","Entertainment","Science","Training","The Future: Virtual Environment","Modes Of Interaction","John Vince, \"Virtual Reality Systems\", Pearson Education Asia, 2007.","Anand R., \"Augmented and Virtual Reality\", Khanna Publishing House, Delhi.","Adams, \"Visualizations of Virtual Reality\", Tata McGraw Hill, 2000.","Grigore C. Burdea, Philippe Coiffet, \"Virtual Reality Technology\", Wiley Inter Science, 2 