insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["The Course Is Designed To Impart Knowledge And Skills Related To 3D Printing Technologies, Selection Of Material And Equipment And Develop A Product Using This Technique In An Industry 4.0 Environment"]},{"title":"3D Printing (Additive Manufacturing)","topics":["Introduction","Process","Classification","Advantages","Additive V/s Conventional Manufacturing Processes","Applications"]},{"title":"CAD for Additive Manufacturing","topics":["CAD Data Formats","Data Translation","Data Loss","STL Format"]},{"title":"Additive Manufacturing Techniques","topics":["Stereo Lithography","LOM","FDM","SLS","SLM","Binder Jet Technology","Process, Process Parameter, Process Selection For Various Applications","Additive Manufacturing Application Domains: Aerospace, Electronics, Health Care, Defence, Automotive, Construction, Food Processing, Machine Tools"]},{"title":"Materials","topics":["Polymers","Metals","Non-Metals","Ceramics","Various Forms Of Raw Material Liquid, Solid, Wire, Powder","Powder Preparation And Their Desired Properties","Polymers And Their Properties","Support Materials"]},{"title":"Additive Manufacturing Equipment","topics":["Process Equipment Design And Process Parameters","Governing Bonding Mechanism","Common Faults And Troubleshooting","Process Design"]},{"title":"Post Processing and Product Quality","topics":["Post Processing Requirement And Techniques","Product Quality: Inspection And Testing","Defects And Their Causes","Lan Gibson, David W. Rosen and Brent Stucker, \"Additive Manufacturing Technologies: Rapid Prototyping to Direct Digital Manufacturing\", Springer, 2010.","Andreas Gebhardt, \"Understanding Additive Manufacturing: Rapid Prototyping, Rapid Tooling, Rapid Manufacturing\", Hanser Publisher, 2011.","Khanna Editorial, \"3D Printing and Design\", Khanna Publishing House, Delhi.","CK Chua, Kah Fai Leong, \"3D Printing and Rapid Prototyping- Principles and Applications\", World Scientific, 2017.","J.D. Majumdar and I. Manna, \"Laser-Assisted Fabrication of Materials\", Springer Series in Material Science, 2013.","L. Lu, J. Fuh and Y.S. Wong, \"Laser-Induced Materials and Processes for Rapid Prototyping\", Kluwer Academic Press, 2001.","Zhiqiang Fan And Frank Liou, \"Numerical Modelling of the Additive Manufacturing (AM) Processes of Titanium Alloy\", InTech, 2012.","After completion of this course, the students will be able to:","→ Develop CAD Models For 3D Printing","→ Import And Export CAD Data And Generate .stl File","→ Select A Specific Material For The Given Application","→ Select A 3D Printing Process For An Application","→ Produce A Product Using 3D Printing Or Additive Manufacturing (AM)"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["System, Environment, Input And Output Variables","State Variables","Static And Dynamic Systems","Hierarchy Of Knowledge About A System And Modelling Strategy"]},{"title":"Physical Modelling","topics":["Dimensions Analysis","Dimensionless Grouping Of Input And Output Variables To Find Empirical Relations","Similarity Criteria And Their Application To Physical Models","Module 3: Modeling of System with Known Structure Review Of Conservation Laws And The Governing Equation For Heat, Mass And Momentum Transfer Deterministic Model (a) Distributed Parameter Models In Terms Of Partial Identification And Their Solutions And (b) Lumped Parameter Models In Terms Of Differential And Difference Equations State Space Model Transfer Functions Block Diagram And Sub Systems Stability Of Transfer Functions Modelling For Control","Review Of Conservation Laws And The Governing Equation For Heat, Mass And Momentum Transfer","Deterministic Model (a) Distributed Parameter Models In Terms Of Partial Identification And Their Solutions And (b) Lumped Parameter Models In Terms Of Differential And Difference Equations","State Space Model","Transfer Functions Block Diagram And Sub Systems","Stability Of Transfer Functions","Modelling For Control"]},{"title":"Optimizations and Design of Systems","topics":["Summary Of Gradient Based Techniques","Nontraditional Optimizations Techniques (i) Genetic Algorithm (GA) Coding, GA Operations Elitism, Application Using MATLAB","(ii) Simulated Annealing"]},{"title":"Neural Network Modelling of Systems only with Input-output Database","topics":["Neurons","Architecture Of Neural Networks","Knowledge Representation","Learning Algorithm","Multilayer Feed Forward Network And Its Back Propagation Learning Algorithm","Application To Complex Engineering Systems And Strategy For Optimum Output"]},{"title":"Modelling Based on Expert Knowledge","topics":["Fuzzy Sets","Membership Functions","Fuzzy Inference Systems","Expert Knowledge And Fuzzy Models","Design Of Fuzzy Controllers"]},{"title":"Simulation of Engineering Systems","topics":["Monte-Carlo Simulation","Simulation Of Continuous And Discrete Processes With Suitable Examples From Engineering Problems","Theory of modeling and simulation, Zeigler B. P. Praehofer. H. and Kim I.G.","System Simulation: the Art and Science, Shannon, R. E.","Modern control Engineering, Ogata K","Neuro-Fuzzy and Soft Computing, Jang J.S.R. sun C.T and Mizutani E"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["The Objective Of This Course Is To Impart Necessary Knowledge Of The Mathematical Foundations Needed For Data Science And Develop Programming Skills Required To Build Data Science Applications"]},{"title":"Introduction to Data Science","topics":["Concept Of Data Science","Traits Of Big Data","Web Scraping","Analysis Vs Reporting"]},{"title":"Introduction to Programming Tools for Data Science","topics":["Toolkits Using Python: Matplotlib, NumPy, Scikit-learn, NLTK","Visualizing Data: Bar Charts, Line Charts, Scatterplots","Working With Data: Reading Files, Scraping The Web, Using APIs (Example: Using The Twitter APIs)","Cleaning And Munging","Manipulating Data","Rescaling","Dimensionality Reduction","Module 3: Mathematical Foundations Linear Algebra: Vectors, Matrices Statistics: Describing A Single Set Of Data, Correlation, Simpson''s Paradox, Correlation And Causation Probability: Dependence And Independence, Conditional Probability, Bayes''s Theorem, Random Variables, Continuous Distributions, The Normal Distribution, The Central Limit Theorem Hypothesis And Inference: Statistical Hypothesis Testing, Confidence Intervals, P Hacking, Bayesian Inference","Linear Algebra: Vectors, Matrices","Statistics: Describing A Single Set Of Data, Correlation, Simpson''s Paradox, Correlation And Causation","Probability: Dependence And Independence, Conditional Probability, Bayes''s Theorem, Random Variables, Continuous Distributions, The Normal Distribution, The Central Limit Theorem","Hypothesis And Inference: Statistical Hypothesis Testing, Confidence Intervals, P Hacking, Bayesian Inference","Module 4: Machine Learning Overview Of Machine Learning Concepts Over Fitting And Train/test Splits Types Of Machine Learning Supervised, Unsupervised, Reinforced Learning Introduction To Bayes Theorem Linear Regression Model Assumptions Regularization (Lasso, Ridge, Elastic Net) Classification And Regression Algorithms Naive Bayes, K-Nearest Neighbors, Logistic Regression, Support Vector Machines (SVM), Decision Trees, And Random Forest Classification Errors Analysis Of Time Series Linear Systems Analysis, Nonlinear Dynamics, Rule Induction, Neural Networks Learning And Generalization Overview Of Deep Learning","Overview Of Machine Learning Concepts Over Fitting And Train/test Splits","Types Of Machine Learning Supervised, Unsupervised, Reinforced Learning","Introduction To Bayes Theorem","Linear Regression Model Assumptions","Regularization (Lasso, Ridge, Elastic Net)","Classification And Regression Algorithms Naive Bayes, K-Nearest Neighbors, Logistic Regression, Support Vector Machines (SVM), Decision Trees, And Random Forest","Classification Errors","Analysis Of Time Series Linear Systems Analysis, Nonlinear Dynamics, Rule Induction, Neural Networks Learning And Generalization","Overview Of Deep Learning"]},{"title":"Case Studies of Data Science Application","topics":["Weather Forecasting","Stock Market Prediction","Object Recognition","Real Time Sentiment Analysis","Module 6: List of Practicals Write A Programme In Python To Predict The Class Of The Flower Based On Available Attributes Write A Programme In Python To Predict If A Loan Will Get Approved Or Not Write A Programme In Python To Predict The Traffic On A New Mode Of Transport Write A Programme In Python To Predict The Class Of User Write A Programme In Python To Identify The Tweets Which Are Hate Tweets And Which Are Not Write A Programme In Python To Predict The Age Of The Actors Mini Project To Predict The Time Taken To Solve A Problem Given The Current Status Of The User","Write A Programme In Python To Predict The Class Of The Flower Based On Available Attributes","Write A Programme In Python To Predict If A Loan Will Get Approved Or Not","Write A Programme In Python To Predict The Traffic On A New Mode Of Transport","Write A Programme In Python To Predict The Class Of User","Write A Programme In Python To Identify The Tweets Which Are Hate Tweets And Which Are Not","Write A Programme In Python To Predict The Age Of The Actors","Mini Project To Predict The Time Taken To Solve A Problem Given The Current Status Of The User","Joel Grus, \"Data Science from Scratch: First Principles with Python\", O''Reilly Media","Aurélien Géron, \"Hands-On Machine Learning with Scikit-Learn and TensorFlow: Concepts, Tools, and Techniques to Build Intelligent Systems\", 1st Edition, O''Reilly Media","Jain V.K., \"Data Sciences\", Khanna Publishing House, Delhi.","Jain V.K., \"Big Data and Hadoop\", Khanna Publishing House, Delhi.","Jeeva Jose, \"Machine Learning\", Khanna Publishing House, Delhi.","Chopra Rajiv, \"Machine Learning\", Khanna Publishing House, Delhi.","Ian Goodfellow, Yoshua Bengio and Aaron Courville, \"Deep Learning\", MIT Press http://www.deeplearningbook.org","Jiawei Han and Jian Pei, \"Data Mining Concepts and Techniques\", Third Edition, Morgan Kaufmann Publishers"]}]'::jsonb from s;
