insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["The Objective Of This Course Is To Impart Necessary And Practical Knowledge Of Components Of Internet Of Things And Develop Skills Required To Build Real-life IoT Based Projects"]},{"title":"Introduction to IoT","topics":["Architectural Overview","Design Principles And Needed Capabilities","IoT Applications","Sensing","Actuation","Basics Of Networking","M2M And IoT Technology Fundamentals Devices And Gateways","Data Management","Business Processes In IoT","Everything As A Service (XaaS)","Role Of Cloud In IoT","Security Aspects In IoT"]},{"title":"Elements of IoT","topics":["Hardware Components Computing (Arduino, Raspberry Pi), Communication, Sensing, Actuation, I/O Interfaces","Software Components Programming API''s (using Python/Node.js/Arduino) For Communication","Protocols MQTT, ZigBee, Bluetooth, CoAP, UDP, TCP"]},{"title":"IoT Application Development","topics":["Solution Framework For IoT Applications Implementation Of Device Integration","Data Acquisition And Integration","Device Data Storage Unstructured Data Storage On Cloud/local Server","Authentication, Authorization Of Devices"]},{"title":"IoT Case Studies","topics":["IoT Case Studies And Mini Projects Based On Industrial Automation","Transportation","Agriculture","Healthcare","Home Automation","Vijay Madisetti, Arshdeep Bahga, Internet of Things, \"A Hands on Approach\", University Press","Dr. SRN Reddy, Rachit Thukral and Manasi Mishra, \"Introduction to Internet of Things: A practical Approach\", ETI Labs","Pethuru Raj and Anupama C. Raman, \"The Internet of Things: Enabling Technologies, Platforms, and Use Cases\", CRC Press","Jeeva Jose, \"Internet of Things\", Khanna Publishing House, Delhi","Adrian McEwen, \"Designing the Internet of Things\", Wiley","Raj Kamal, \"Internet of Things: Architecture and Design\", McGraw Hill","Cuno Pfister, \"Getting Started with the Internet of Things\", O Reil