insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"(Lecture 8 hrs.)","topics":["Introduction","Characterization And Classification Of Signals","Typical Signal Processing Operations","Review Of Discrete-time Signal And System Analysis","Advantages And Typical Applications Of DSP"]},{"title":"(Lecture 8 hrs.)","topics":["Sampling And Quantization","Sampling And Discrete-time Processing Of Continuous Time Signals","Sampling Of Low-pass And Band-pass Signals","Uniform And Non-uniform Quantization","Lloyd-Max Algorithm","Log-companding","A-law","μ-law","Adaptive Quantization And Prediction","Module 3: (Lecture 8 hrs.) Orthogonal Transforms Properties And Applications Of DFT Implementing Linear Time Invariant Systems Using DFT Circular Convolution Linear Convolution Using DFT Fast Fourier Transform FFT Algorithms Decimation In Time Decimation In Frequency Goertzel Algorithm Application Of Transform In Speech Audio Image And Video Coding Karhunen-Loeve Transform DCT JPEG And MPEG Coding Standards","Orthogonal Transforms","Properties And Applications Of DFT","Implementing Linear Time Invariant Systems Using DFT","Circular Convolution","Linear Convolution Using DFT","Fast Fourier Transform","FFT Algorithms","Decimation In Time","Decimation In Frequency","Goertzel Algorithm","Application Of Transform In Speech","Audio","Image And Video Coding","Karhunen-Loeve Transform","DCT","JPEG And MPEG Coding Standards"]},{"title":"(Lecture 8 hrs.)","topics":["Digital Filter Design Techniques","IIR And FIR Filters","Filter Design Specifications","Design Of Digital IIR Filters","Impulse Invariant","Bilinear Transformation Techniques For Butterworth And Chebyshev Filters","Design Of FIR Filters","Windowing","Frequency Sampling Filter Design","Optimum Approximations Of FIR Filters"]},{"title":"(Lecture 6 hrs.)","topics":["Multi-rate Signal Processing","Fundamentals Of Multirate Systems","Decimation And Interpolation","Application Of Multirate DSP In Sam