insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"(Lecture 8 hrs.)","topics":["Data Warehousing And Business Analysis","Data Warehousing Components","Building A Data warehouse","Data Warehouse Architecture","DBMS Schemas For Decision Support","Data Extraction","Cleanup","Transformation Tools","Metadata","Reporting","Query Tools And Applications","Online Analytical Processing (OLAP)","OLAP And Multidimensional Data Analysis","Module 2: (Lecture 8 hrs.) Data Mining Data Mining Functionalities Data Preprocessing Data Cleaning Data Integration And Transformation Data Reduction Data Discretization And Concept Hierarchy Generation Architecture Of A Typical Data Mining Systems Classification Of Data Mining Systems Association Rule Mining Efficient And Scalable Frequent Item set Mining Methods Mining Various Kinds Of Association Rules Association Mining To Correlation Analysis Constraint-Based Association Mining","Data Mining","Data Mining Functionalities","Data Preprocessing","Data Cleaning","Data Integration And Transformation","Data Reduction","Data Discretization And Concept Hierarchy Generation","Architecture Of A Typical Data Mining Systems","Classification Of Data Mining Systems","Association Rule Mining","Efficient And Scalable Frequent Item set Mining Methods","Mining Various Kinds Of Association Rules","Association Mining To Correlation Analysis","Constraint-Based Association Mining","Module 3: (Lecture 8 hrs.) Classification And Prediction Issues Regarding Classification And Prediction Classification By Decision Tree Introduction Bayesian Classification Rule Based Classification Classification By Back propagation Support Vector Machines Associative Classification Lazy Learners Other Classification Methods Prediction Accuracy And Error Measures Evaluating The Accuracy Of A Classifier Or Predictor Ensemble Methods Model Section","Classification And Prediction","Issues Regarding Classification And Prediction","Classification By