insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["This Course Will Cover The Study Of Various Cloud Services, Deployment Model, Resource Provisioning And Scheduling Algorithms Involved In Better Implementing The Cloud-based Systems"]},{"title":"(Lecture 4 hrs.)","topics":["Introduction","Distributed Computing And Enabling Technologies","Cloud Fundamentals","Cloud Definition","Evolution","Architecture","Applications","Deployment Models","Service Models"]},{"title":"(Lecture 5 hrs.)","topics":["Virtualization","Issues With Virtualization","Virtualization Technologies And Architectures","Internals Of Virtual Machine Monitors/hypervisors","Virtualization Of Data Centers","Issues With Multitenancy"]},{"title":"(Lecture 6 hrs.)","topics":["Implementation","Study Of Cloud Computing Systems Like Amazon EC2 And S3","Google App Engine","Microsoft Azure","Build Private/Hybrid Cloud Using Open Source Tools","SLA Management"]},{"title":"(Lecture 12 hrs.)","topics":["Resource Management","Cloud Resource Provisioning Plan (advance Reservation","On Demand Plan","Spot Instances)","Various Scheduling And Load Balancing Techniques To Improve QoS Parameters","Resource Optimization Algorithms","Task Migration And VM Migration Technique"]},{"title":"(Lecture 7 hrs.)","topics":["Security","Vulnerability Issues And Security Threats","Application-level Security","Data Level Security","Virtual Machine Level Security","Infrastructure Security","Multi-tenancy Issues"]},{"title":"(Lecture 6 hrs.)","topics":["Advances","Green Cloud","Mobile Cloud Computing","Fog Computing","Internet Of Things","Cloud Computing Principles and Paradigms, Rajkumar Buyya, James Broberg, Andrzej Goscinski, Wiley Publishers 2011","Cloud Computing Bible, Barrie Sosinsky, Wiley Publishers 2010","Mastering Cloud computing, Rajkumar Buyya, Christian Vacchiola, S Thamarai Selvi, McGraw Hill 2013","Cloud Security and Privacy: An Enterprise Perspective on Risks and Compliance, Tim Mather, Subra Kumaraswamy, Shahed Latif, O''Reilly 2010","Cloud Computing by Shailendra Singh 2018","→ Articulate The Main Concepts, Key Technologies, Strengths, And Limitations Of Cloud Computing And The Possible Applications For State-of-the-art Cloud Computing","→ Identify The Architecture And Infrastructure Of Cloud Computing, Including SaaS, Paas, laas, Public Cloud, Private Cloud, Hybrid Cloud, Etc","→ Identify Problems, And Explain, Analyze, And Evaluate Various Cloud Computing Solutions","→ Provide The Appropriate Cloud Computing Solutions And Recommendations According To The Applications Used","→ Attempt To Generate New Ideas And Innovations In Cloud Computing"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["The Objective Of This Course Is To Impart Necessary Knowledge To The Learner So That He/she Can Develop And Implement Algorithm And Write Programs Using These Algorithm"]},{"title":"(Lectures 6 hrs.)","topics":["Introduction To Quantum Computing","Motivation For Studying Quantum Computing","Major Players In The Industry (IBM, Microsoft, Rigetti, D-Wave Etc)","Origin Of Quantum Computing","Overview Of Major Concepts In Quantum Computing","Qubits And Multi-qubits States","Bra-ket Notation","Bloch Sphere Representation","Quantum Superposition","Quantum Entanglement"]},{"title":"(Lectures 9 hrs.)","topics":["Math Foundation For Quantum Computing","Matrix Algebra","Basis Vectors And Orthogonality","Inner Product And Hilbert Spaces","Matrices And Tensors","Unitary Operators And Projectors","Dirac Notation","Eigen Values And Eigen Vectors","Module 3: (Lectures 8 hrs.) Building Blocks For Quantum Program Architecture Of A Quantum Computing Platform Details Of Q-bit System Of Information Representation Block Sphere Multi-qubits States Quantum Superposition Of Qubits (valid And Invalid Superposition) Quantum Entanglement Useful States From Quantum Algorithmic Perceptive E.g. Bell State Operation On Qubits Measuring And Transforming Using Gates Quantum Logic Gates And Circuit Pauli Hadamard Phase Shift Controlled Gates Ising Deutsch Swap Etc Programming Model For A Quantum Computing Program Steps Performed On Classical Computer Steps Performed On Quantum Computer Moving Data Between Bits And Qubits","Building Blocks For Quantum Program","Architecture Of A Quantum Computing Platform","Details Of Q-bit System Of Information Representation","Block Sphere","Multi-qubits States","Quantum Superposition Of Qubits (valid And Invalid Superposition)","Quantum Entanglement","Useful States From Quantum Algorithmic Perceptive E.g. Bell State","Operation On Qubits","Measuring And Transforming Using Gates","Quantum Logic Gates And Circuit","Pauli","Hadamard","Phase Shift","Controlled Gates","Ising","Deutsch","Swap Etc","Programming Model For A Quantum Computing Program","Steps Performed On Classical Computer","Steps Performed On Quantum Computer","Moving Data Between Bits And Qubits","Module 4: (Lectures 18 hrs.) Quantum Algorithms Basic Techniques Exploited By Quantum Algorithms Amplitude Amplification Quantum Fourier Transform Phase Kick-back Quantum Phase Estimation Quantum Walks Major Algorithms Shor''s Algorithm Grover''s Algorithm Deutsch''s Algorithm Deutsch - Jozsa Algorithm OSS Toolkits For Implementing Quantum Program IBM Quantum Experience Microsoft Q Rigetti PyQuil (QPU/QVM)","Quantum Algorithms","Basic Techniques Exploited By Quantum Algorithms","Amplitude Amplification","Quantum Fourier Transform","Phase Kick-back","Quantum Phase Estimation","Quantum Walks","Major Algorithms","Shor''s Algorithm","Grover''s Algorithm","Deutsch''s Algorithm","Deutsch - Jozsa Algorithm","OSS Toolkits For Implementing Quantum Program","IBM Quantum Experience","Microsoft Q","Rigetti PyQuil (QPU/QVM)","Michael A. Nielsen, \"Quantum Computation and Quantum Information\", Cambridge University Press.","David McMahon, \"Quantum Computing Explained\", Wiley","IBM Experience: https://quantumexperience.ng, bluemix.net","Microsoft Quantum Development Kit https://www.microsoft.com/en-us/quantum/development-kit","Forest SDK PyQuil: https://pyquil.readthedocs.io/en/stable/","At the end of this course, the students will be able to:","→ Explain The Working Of A Quantum Computing Program, Its Architecture And Program Model","→ Develop Quantum Logic Gate Circuits","→ Develop Quantum Algorithm","→ Program Quantum Algorithm On Major Toolkits"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"(Lecture 8 hrs.)","topics":["Consistency","Atomicity","Durability","Isolation","Flat Transactions","Providing Structure Within A Transaction","Structuring An Application As Multiple Transactions","Module 2: (Lecture 8 hrs.) Schedules And Schedule Equivalence Recoverability Cascaded Aborts And Strictness Models For Concurrency Control A Strategy For Immediate-Update Pessimistic Concurrency Controls Design Of An Immediate-Update Pessimistic Concurrency Control Objects And Semantic Commutativity Atomicity Recoverability And Compensating Operations Locking And SQL Isolation Levels Granular Locking Intention Locks And Index Locks Tuning Transactions Multi version Concurrency Controls","Schedules And Schedule Equivalence","Recoverability","Cascaded Aborts And Strictness","Models For Concurrency Control","A Strategy For Immediate-Update Pessimistic Concurrency Controls","Design Of An Immediate-Update Pessimistic Concurrency Control","Objects And Semantic Commutativity","Atomicity","Recoverability And Compensating Operations","Locking And SQL Isolation Levels","Granular Locking","Intention Locks And Index Locks","Tuning Transactions","Multi version Concurrency Controls"]},{"title":"(Lecture 8 hrs.)","topics":["Crash","Abort And Media Failure","Immediate-Update Systems And Write-Ahead Logs","Recovery In Deferred-Update Systems","Recovery From Media Failure"]},{"title":"(Lecture 8 hrs.)","topics":["Transaction Processing In A Centralized System","Transaction Processing In A Distributed System","Global Atomicity And The Transaction Manager","Remote Procedure Call","Pear-to-Pear Communication","Event Communication","Storage Architectures","Transaction Processing On The Internet","Implementing The ACID Properties","Distributed Deadlock","Global Serialization"]},{"title":"(Lecture 8 hrs.)","topics":["Authentication","Authorization And Encryption","Digital Signatures","Key Distribution And Authentication","Authorization","Authenticated RPC","Electronic Commerce","Certificates","Passport","SSO","SET Protocol","Dual Signatures","Goods Atomicity","Certified Delivery","Escrow","Michael Kifer, Arthur Bernstein and Philip M. Lewis, \"Database Systems: An Application-Oriented Approach\", Addison Wesley, 2006","Philip A. Bernstein and Eric Newcomer, \"Principles of Transaction Processing\", 2nd Edition, Morgan Kaufmann Publishers, Elsevier, 2009"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"(Lecture 6 hrs.)","topics":["Introduction","Importance Of Pattern Recognition","Features","Feature Vectors","Classifiers","Supervised Versus Unsupervised Pattern Recognition"]},{"title":"(Lecture 6 hrs.)","topics":["Bayes Decision Theory","Discriminant Functions And Services O The Normal Distribution","Bayesian Classification","Estimating Probability Density Functions","Nearest Neighbour Rules Bayesian Networks"]},{"title":"(Lecture 6 hrs.)","topics":["Linear And Nonlinear Classifiers","The Perceptron Algorithm","Least-Squares Methods","Nonlinear Classifiers","Multilayer Perceptron''s","Back Propagation Algorithm","Decision Trees","Combinations Of Classifiers","Boosting"]},{"title":"(Lecture 6 hrs.)","topics":["Feature Selection","Data Pre-processing","ROC Curves","Class Separability Measures","Feature Subset Selection","Bayesian Information Criterion"]},{"title":"(Lecture 6 hrs.)","topics":["Dimensionality Reduction","Basis Vectors","Singular Value Decomposition","Independent Component Analysis","Kernel PCA","Wavelets"]},{"title":"(Lecture 6 hrs.)","topics":["Additional Features And Template Matching","Texture","Shape And Size Characterization","Fractals","Features For Audio","Template Matching Using Dynamic Time Warping And Edit Distance","Context Dependent Classification"]},{"title":"(Lecture 6 hrs.)","topics":["Clustering","Sequential Algorithms","Hierarchical Algorithms","Functional Optimization-Based Clustering Graph Clustering","Learning Clustering","Clustering High Dimensional Data","Subspace Clustering","Cluster Validity Measure","Pattern recognition, Sergios Theodoridis","Pattern classification, second edition, duda, hart and stork, wiley","Pattern recognition, Sergios Theodoridis Konstanti Nos Koutrou M Bas","Introduction to Statistical Pattern Recognition, Fukunaga Academic Press","Pattern Recognition and Machine learning, C. M. Bishop, Springer","Statistical Methods in Bioinformatics, Ewens & Grant, Springer","The Elements of Statistical Learning, Hastie, Tibshirani, Friedman, Springer"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["This Course Will Provide A Basic Understanding Of Deep Learning And Their Applications To Solve Real World Problems. Open Source Tools Will Be Used To Demonstrate Different Applications"]},{"title":"Introduction (Lecture 4 hrs.)","topics":["Brief Introduction Of Big Data Problem","Overview Of Linear Algebra","Probability","Numerical Computation","Basics Of Machine learning/Feature Engineering"]},{"title":"Basics of Neural networks (Lecture 4 hrs.)","topics":["Neural Networks","Tools For Deep Learning Network","Shallow Vs Deep Network"]},{"title":"Feed forward Networks (Lecture 6 hrs.)","topics":["Multilayer Perceptron","Gradient","Loss Function","Gradient Descent","Stochastic Gradient Descent (SDD)","Backpropagation Algorithm","Empirical Risk Minimization","Regularization","Gradient Based Learning","Cost Function","Learning Rate","Soft Max","Sigmoid Function","Hidden Unit","ReLU","Logistic Sigmoid","Hyperbolic Tangent Architecture Design","Heuristics For Faster Training"]},{"title":"Unsupervised learning (Lecture 10 hrs.)","topics":["Deep Belief Network","Deep Boltzmann Machine (DBM)","Factor Analysis","Auto-encoders (standard, Sparse, Denoising, Contractive, Etc)","Variational Auto-encoders","Adversarial Generative Networks","Auto-encoder","Regularization Optimization For Training Deep Model"]},{"title":"Advanced topics (Lecture 10 hrs.)","topics":["Convolutional Neural Network (CNN)","Architectures","Convolution/pooling Layers","Recurrent Neural Network (RNN)/ Sequence Modeling","Long Short Term Memory Networks (LSTM)","GRU","Encoder Decoder Architectures Reinforcement Learning"]},{"title":"Practical applications (Lecture 6 hrs.)","topics":["Application Of Deep Learning To Computer Vision","Speech Recognition","Natural Language Processing","Etc","Ian Goodfellow, Yoshua Bengio and Aaron Courville, \"Deep Learning\", Book in preparation for MIT Press, 2016.","Jerome H. Friedman, Robert Tibshirani, and Trevor Hastie, \"The elements of statistical learning\", Springer Series in Statistics, 2009.","Charu C Aggarwal, \"Neural Networks and Deep Learning\", Springer.","→ Identify The Deep Learning Algorithms Which Are More Appropriate For Various Types Of Learning Tasks In Various Domains","→ Implement Deep Learning Algorithms And Solve Real-world Problems"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To Introduce Geometric Algorithms And To Give An Exposure To Algorithms And Data Structures For Geometric Problems"]},{"title":"(Lecture 6 hrs.)","topics":["Polygon Triangulation","Triangulation Theory","Area Of Polygon","Segment Intersection","Segment-triangle Intersection","Polygon Partitioning","Monotone Partitioning","Trapezoidalization","Partition Into Monotone Mountains","Linear-Time Triangulation","Convex Partitioning"]},{"title":"(Lecture 5 hrs.)","topics":["Convex Hulls In Two Dimensions","Definitions Of Convexity And Convex Hulls","Naive Algorithms For Extreme Points","Gift Wrapping","QuickHull","Graham''s Algorithm","Lower Bound","Incremental Algorithm","Divide And Conquer"]},{"title":"(Lecture 6 hrs.)","topics":["Convex Hulls In Three Dimensions","Polyhedra And Data Structures","Gift Wrapping","Preparata-Hong Algorithm","Incremental Algorithm","Randomized Incremental Algorithm"]},{"title":"(Lecture 6 hrs.)","topics":["Voronoi Diagrams","Definitions And Basic Properties","Delaunay Triangulations","Algorithms","Applications In Detail","Medial Axis","Connection To Convex Hulls","Connection To Arrangements"]},{"title":"(Lecture 6 hrs.)","topics":["Arrangements","Combinatorics Of Arrangements","Incremental Algorithm","Three And Higher Dimensions","Duality","Higher-Order Voronoi","Diagrams","Applications"]},{"title":"(Lecture 8 hrs.)","topics":["Search And Intersection","Segment-Segment Intersection","Segment- Triangle Intersection","Point In Polygon","Point In Polyhedron","Intersection Of Convex Polygons","Intersection Of Segments","Intersection Of Nonconvex Polygons","Extreme Point Of Convex Polygon","Extremal Polytope","Queries","Planar Point Location"]},{"title":"(Lecture 5 hrs.)","topics":["Motion Planning","Shortest Paths","Moving A Disk","Translating A Convex Polygon","Moving A Ladder","Robot Arm Motion","Separability","M. de Berg, M van Kreveld, M. Overmars, O. Schwarzkopf, Computational Geometry: Algorithms and Applications (2nd Edition), Springer - Verlag 2000","O''Rourke, Computational Geometry in C, 2nd ed., Cambridge Univ. Press, 1998.","Casselman, Mathematical Illustrations: A Manual of Geometry and PostScript, Springer-Verlag,. (http://www.math.ubc.ca/~cass/graphics/manual) 2005","Mulmuley, Computational Geometry: An Introduction Through Randomized Algorithms, Prentice Hall. 1994","Upon successful completion of this course, students will be able to:","→ Analyze Randomized Algorithms For Small Domain Problems","→ Use Line-point Duality To Develop Efficient Algorithms","→ Apply Geometric Techniques To Real-world Problems In Graphics","→ Solve Linear Programs Geometrically"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["→ To Understand The Competitive Advantages Of Big Data Analytics","→ To Understand The Big Data Frameworks","→ To Learn Data Analysis Methods","→ To Learn Stream Computing","→ To Gain Knowledge On Hadoop Related Tools Such As HBase, Cassandra, Pig, And Hive For Big Data Analytics"]},{"title":"(Lecture 7 hrs.)","topics":["Introduction To Big Data","Definition","Characteristic Features","Big Data Applications","Big Data Vs Traditional Data","Risks Of Big Data","Structure Of Big Data","Challenges Of Conventional Systems","Web Data","Evolution Of Analytic Scalability","Evolution Of Analytic Processes","Tools And Methods","Analysis Vs Reporting","Modern Data Analytic Tools"]},{"title":"(Lecture 9 hrs.)","topics":["HADOOP Framework","Distributed File Systems","Large-Scale File System","Organization","HDFS Concepts","Map Reduce Execution","Algorithms Using Map Reduce","Matrix-Vector Multiplication","Hadoop YARN"]},{"title":"(Lecture 10 hrs.)","topics":["Data Analysis","Statistical Methods","Regression Modelling","Multivariate Analysis","Classification","SVM & Kernel Methods","Rule Mining","Cluster Analysis","Types Of Data In Cluster Analysis","Partitioning Methods","Hierarchical Methods","Density Based Methods","Grid Based Methods","Model Based Clustering Methods","Clustering High Dimensional Data","Predictive Analytics","Data Analysis Using R"]},{"title":"(Lecture 7 hrs.)","topics":["Mining Data Streams","Streams","Concepts","Stream Data Model And Architecture","Sampling Data In A Stream","Mining Data Streams And Mining Time-series Data","Real Time Analytics Platform (RTAP) Applications","Case Studies","Real Time Sentiment Analysis","Stock Market Predictions"]},{"title":"(Lecture 9 hrs.)","topics":["Big Data Frameworks","Introduction To NoSQL","Aggregate Data Models","Hbase","Data Model And Implementations","Hbase Clients","Examples","Cassandra","Data Model","Examples","Cassandra Clients","Hadoop Integration","Pig","Grunt","Pig Data Model","Pig Latin","Developing And Testing Pig Latin Scripts","Hive","Data Types And File Formats","HiveQL Data Definition","HiveQL Data Manipulation","HiveQL Queries","At the end of this course, the students will be able to:","→ Understand How To Leverage The Insights From Big Data Analytics","→ Analyze Data By Utilizing Various Statistical And Data Mining Approaches","→ Perform Analytics On Real-time Streaming Data","→ Understand The Various NoSql Alternative Database Models","Bill Franks, -Taming the Big Data Tidal Wave: Finding Opportunities in Huge Data Streams with Advanced Analytics | |, Wiley and SAS Business Series, 2012.","David Loshin, \"Big Data Analytics: From Strategic Planning to Enterprise Integration with Tools, Techniques, NoSQL, and Graph\", 2013.","Michael Berthold, David J. Hand, -Intelligent Data Analysis | |, Springer, Second Edition, 2007.","Michael Minelli, Michelle Chambers, and Ambiga Dhiraj, \"Big Data, Big Analytics: Emerging Business Intelligence and Analytic Trends for Today''s Businesses\", Wiley, 2013.","J. Sadalage and M. Fowler, \"NoSQL Distilled: A Brief Guide to the Emerging World of Polyglot Persistence\", Addison-Wesley Professional, 2012.","Richard Cotton, \"Learning R - A Step-by-step Function Guide to Data Analysis,, O''Reilly Media, 2013."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"(Lecture 10 hrs.)","topics":["Introduction","Hard Vs. Soft Real Time Systems","A Reference Model Of Real Time System","Real-time Scheduling","Clock Driven Approach","Weighted Round-robin Approach","Priority Driven Approach","Dynamic Vs. Static System","Effective Release Times And Deadlines","EDF And LST Algorithm","Optimality And Non-Optimality Of The EDF And LST Algorithms","Off Line Vs. Online Scheduling"]},{"title":"(Lecture 6 hrs.)","topics":["Clock-Driven Scheduling","Static","Time-Driven Scheduler","General Structure Of Cyclic Schedules","Cyclic Executives","Improving The Average Response Time Of Aperiodic Jobs","Scheduling Sporadic Jobs"]},{"title":"(Lecture 7 hrs.)","topics":["Priority Driven Scheduling Of Periodic Tasks","Fixe-priority Vs. Dynamic Priority Algorithms","Maximum Schedulable Utilization","Optimality Of The RM And DM Algorithms","A Schedulability Test For Fixed-priority Tasks With Short Response Times","Sufficient Schedulability Conditions For The RM And DM Algorithms"]},{"title":"(Lecture 6 hrs.)","topics":["Scheduling Aperiodic And Sporadic Jobs In Priority-Driven Systems","Assumptions And Approaches","Deferrable Servers","Sporadic Servers","Constant Utilization","Total Bandwidth And Weighted Fair-Queueing Servers"]},{"title":"(Lecture 8 hrs.)","topics":["Resources And Resource Access Control","Resource Contention","Resource Access Control","Non-preemptive Critical Section","Basic Priority-Inheritance Protocol","Basic Priority Ceiling Protocol","Stack Based","Priority-ceiling Protocol","Preemption Ceiling Protocol"]},{"title":"(Lecture 5 hrs.)","topics":["Multiprocessor Scheduling","Resource Access Control","Synchronization","Model Of Multiprocessor & Distributed Systems","Task Assignment","Multiprocessor Priority-ceiling Protocol","Elements Of Scheduling Algorithms For End-to-End Periodic Tasks","IPS Protocols","PM Protocols","MPM Protocol","Real-Time system by Jane W. S. Liu, Pearson Education","Real-Time Systems by C. M. Krishna and K. G. Shin, McGraw Hill","After learning this subject, students will learn various types of Real Time Systems, Periodic and Aperiodic tasks, different types of scheduling algorithms in RTS(Clock Driven, Priority Driven), Priority Driven Scheduling Of Periodic Tasks, Priority Driven Scheduling of Aperiodic and Sporadic Jobs, Different protocols for resource access controls, Scheduling approach in multiprocessor Real Time Systems etc."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To Provide Conceptual Understanding Of How Block Chain Technology Can Be Used To Innovate And Improve Business Processes. The Course Covers The Technological Underpinning Of Block Chain Operations","Module 1: (Lectures 6 hrs.) Introduction Overview Of Block Chain Public Ledgers Bitcoin Smart Contracts Block In A Block Chain Transactions Distributed Consensus Public Vs Private Block Chain Understanding Crypto Currency To Block Chain Permissioned Model Of Block Chain Overview Of Security Aspects Of Block Chain Basic Crypto Primitives Cryptographic Hash Function Properties Of A Hash Function Hash Pointer And Merkle Tree Digital Signature Public Key Cryptography A Basic Cryptocurrency","Introduction","Overview Of Block Chain","Public Ledgers","Bitcoin","Smart Contracts","Block In A Block Chain","Transactions","Distributed Consensus","Public Vs Private Block Chain","Understanding Crypto Currency To Block Chain","Permissioned Model Of Block Chain","Overview Of Security Aspects Of Block Chain Basic Crypto Primitives","Cryptographic Hash Function","Properties Of A Hash Function","Hash Pointer And Merkle Tree","Digital Signature","Public Key Cryptography","A Basic Cryptocurrency","Module 2: (Lectures 10 hrs.) Understanding Block Chain With Crypto Currency Bitcoin And Block Chain Creation Of Coins Payments And Double Spending Bitcoin Scripts Bitcoin P2P Network Transaction In Bitcoin Network Block Mining Block Propagation And Block Relay Working With Consensus In Bitcoin Distributed Consensus In Open Environments Consensus In A Bitcoin Network Proof Of Work (PoW) Basic Introduction Hashcash PoW Bitcoin PoW Attacks On Pow And The Monopoly Problem Proof Of Stake Proof Of Burn And Proof Of Elapsed Time The Life Of A Bitcoin Miner Mining Difficulty Mining Pool","Understanding Block Chain With Crypto Currency","Bitcoin And Block Chain","Creation Of Coins","Payments And Double Spending","Bitcoin Scripts","Bitcoin P2P Network","Transaction In Bitcoin Network","Block Mining","Block Propagation And Block Relay","Working With Consensus In Bitcoin","Distributed Consensus In Open Environments","Consensus In A Bitcoin Network","Proof Of Work (PoW)","Basic Introduction","Hashcash PoW","Bitcoin PoW","Attacks On Pow And The Monopoly Problem","Proof Of Stake","Proof Of Burn And Proof Of Elapsed Time","The Life Of A Bitcoin Miner","Mining Difficulty","Mining Pool","Module 3: (Lectures 12 hrs.) Understanding Block Chain For Enterprises Permissioned Block Chain Permissioned Model And Use Cases Design Issues For Permissioned Block Chains Execute Contracts State Machine Replication Overview Of Consensus Models For Permissioned Block Chain Distributed Consensus In Closed Environment Paxos RAFT Consensus Byzantine General Problem Byzantine Fault Tolerant System Lamport-Shostak-Pease BFT Algorithm BFT Over Asynchronous Systems Enterprise Application Of Block Chain Cross Border Payments Know Your Customer (KYC) Food Security Mortgage Over Block Chain Block Chain Enabled Trade We Trade Trade Finance Network Supply Chain Financing Identity On Block Chain","Understanding Block Chain For Enterprises","Permissioned Block Chain","Permissioned Model And Use Cases","Design Issues For Permissioned Block Chains","Execute Contracts","State Machine Replication","Overview Of Consensus Models For Permissioned Block Chain","Distributed Consensus In Closed Environment","Paxos","RAFT Consensus","Byzantine General Problem","Byzantine Fault Tolerant System","Lamport-Shostak-Pease BFT Algorithm","BFT Over Asynchronous Systems","Enterprise Application Of Block Chain","Cross Border Payments","Know Your Customer (KYC)","Food Security","Mortgage Over Block Chain","Block Chain Enabled Trade","We Trade Trade Finance Network","Supply Chain Financing","Identity On Block Chain"]},{"title":"(Lectures 12 hrs.)","topics":["Block Chain Application Development","Hyperledger Fabric","Architecture","Identities And Policies","Membership And Access Control","Channels","Transaction Validation","Writing Smart Contract Using Hyperledger Fabric","Writing Smart Contract Using Ethereum","Overview Of Ripple And Corda","Melanie Swan, \"Block Chain: Blueprint for a New Economy\", O''Reilly, 2015","Josh Thompsons, \"Block Chain: The Block Chain for Beginners- Guide to Block Chain Technology and Leveraging Block Chain Programming\"","Daniel Drescher, \"Block Chain Basics\", Apress; 1st edition, 2017","Anshul Kaushik, \"Block Chain and Crypto Currencies\", Khanna Publishing House, Delhi.","Imran Bashir, \"Mastering Block Chain: Distributed Ledger Technology, Decentralization and Smart Contracts Explained\", Packt Publishing","Ritesh Modi, \"Solidity Programming Essentials: A Beginner''s Guide to Build Smart Contracts for Ethereum and Block Chain\", Packt Publishing","Salman Baset, Luc Desrosiers, Nitin Gaur, Petr Novotny, Anthony O''Dowd, Venkatraman Ramakrishna, \"Hands-On Block Chain with Hyperledger: Building Decentralized Applications with Hyperledger Fabric and Composer\", Import, 2018","At the end of this course, the students will be able to:","→ Understand Block Chain Technology","→ Develop Block Chain Based Solutions And Write Smart Contract Using Hyperledger Fabric And Ethereum Frameworks","→ Build And Deploy Block Chain Application For On Premise And Cloud Based Architecture","→ Integrate Ideas From Various Domains And Implement Them Using Block Chain Technology In Different Perspectives"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To Introduce Optimization Techniques Using Both Linear And Non-linear Programming","After An Adequate Introduction To Linear Algebra And Probability Theory And Optimization Techniques Students Will Learn To Frame Engineering Minima Maxima Problems In The Framework Of Optimization Problems"]},{"title":"(Lectures 10 hrs.)","topics":["Optimization Techniques","Model Formulation","Models","General L.R Formulation","Simplex Techniques","Sensitivity Analysis","Inventory Control Models"]},{"title":"(Lectures 8 hrs.)","topics":["Formulation Of A LPP","Graphical Solution Revised Simplex Method","Duality Theory","Dual Simplex Method","Sensitivity Analysis","Parametric Programming"]},{"title":"T Flow Problem Max Flow Problem CPM/PERT","topics":["T Flow Problem","Max Flow Problem","CPM/PERT"]},{"title":"(Lectures 7 hrs.)","topics":["Scheduling And Sequencing","Single Server And Multiple Server Models","Deterministic Inventory Models","Probabilistic Inventory Control Models","Geometric Programming"]},{"title":"(Lectures 8 hrs.)","topics":["Competitive Models","Single And Multi-channel Problems","Sequencing Models","Dynamic Programming","Flow In Networks","Elementary Graph Theory","Game Theory Simulation","H.A. Taha, Operations Research, An Introduction, PHI, 2008","H.M. Wagner, Principles of Operations Research, PHI, Delhi, 1982","J.C. Pant, Introduction to Optimisation: Operations Research, Jain Brothers, Delhi, 2008","Hitler Libermann Operations Research: McGraw Hill Pub. 2009","Pannerselvam, Operations Research: Prentice Hall of India 2010","Harvey M Wagner, Principles of Operations Research: Prentice Hall of India 2010","After completion of course:","→ Students Should Able To Apply The Dynamic Programming To Solve Problems Of Discreet And Continuous Variables","→ Students Should Able To Apply The Concept Of Non-linear Programming","→ Students Should Able To Carry Out Sensitivity Analysis","→ Student Should Able To Model The Real World Problem And Simulate It"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To Introduce Students To Information Retrieval Systems And To Study Theoretical Aspects As Well As Implementation Issues Of Classical And Modern Retrieval Problems. Discuss Mechanisms Of Web Search Along With The Details Of Ranking Algorithms. Introduce Basic Concepts Of Text Categorization And Recommender Systems","Module 1: (Lectures 12 hrs.) Introduction To Information Retrieval Goals And History Of IR The Impact Of The Web On IR Unstructured And Semi-structured Text Basic IR Models Inverted Index And Boolean Queries Boolean And Vector-space Retrieval Models Ranked Retrieval Text-similarity Metrics TF-IDF (term Frequency/inverse Document Frequency) Weighting Cosine Similarity Basic Tokenizing Indexing Implementation Of Vector-Space Retrieval Simple Tokenizing Stop-word Removal Stemming Inverted Indices Efficient Processing With Sparse Vectors","Introduction To Information Retrieval","Goals And History Of IR","The Impact Of The Web On IR","Unstructured And Semi-structured Text","Basic IR Models Inverted Index And Boolean Queries","Boolean And Vector-space Retrieval Models","Ranked Retrieval","Text-similarity Metrics","TF-IDF (term Frequency/inverse Document Frequency) Weighting","Cosine Similarity","Basic Tokenizing","Indexing","Implementation Of Vector-Space Retrieval","Simple Tokenizing","Stop-word Removal","Stemming","Inverted Indices","Efficient Processing With Sparse Vectors"]},{"title":"(Lectures 8 hrs.)","topics":["Experimental Evaluation Of IR","Performance Metrics","Recall","Precision","F-measure","Query Operations","Relevance Feedback","Query Expansion","Query Languages","Text Representation","Word Statistics","Porter Stemmer","Index Term Selection","Using Thesauri","Metadata And Markup Languages (SGML, HTML, XML)"]},{"title":"(Lectures 10 hrs.)","topics":["Web Search","Introduction","Spidering","Interfaces","Link Analysis Text Categorization","Categorization Algorithms","Language-Model Based Retrieval","Text Clustering","Applications To Web Search And Information Organization"]},{"title":"(Lectures 10 hrs.)","topics":["Recommender Systems","Collaborative Filtering And Content-based Recommendation Of Documents And Products","Information Extraction And Integration","Extracting Data From Text","Semantic Web","Collecting And Integrating Specialized Information On The Web","Manning, Raghavan and Schutze, \"Introduction to Information Retrieval\", Cambridge University Press.","Baeza-Yates and Ribeiro-Neto, \"Modern Information Retrieval\", Addison Wesley."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"(Lecture 8 hrs.)","topics":["Introduction To Cryptography","Cryptographic Hash Functions","SHA-256","Hash Pointers And Data Structures","Merkle Tree"]},{"title":"(Lecture 8 hrs.)","topics":["Digital Signatures","Elliptic Curve Group","Elliptic Curve Digital Signature Algorithm (ECDSA)","Public Keys As Identities","A Simple Crypto Currency"]},{"title":"(Lecture 8 hrs.)","topics":["Centralization Vs. Decentralization","Distributed Consensus","Consensus Without Identity Using A Block Chain","Incentives And Proof Of Work","Bitcoin Transactions","Bitcoin Scripts","Applications Of Bitcoin Scripts","Bitcoin Blocks","The Bitcoin Network"]},{"title":"(Lecture 8 hrs.)","topics":["Simple Local Storage","Hot And Cold Storage","Splitting And Sharing Keys","Online Wallets And Exchanges","Payment Services","Transaction Fees","Currency Exchange Markets"]},{"title":"(Lecture 8 hrs.)","topics":["Bitcoin Mining","Mining Pools","Mining Incentives And Strategies","Bitcoin And Anonymity","Anonymity Basics","Mixing","Zerocoin And Zerocash","Arvind Narayanan, Joseph Bonneau, Edward Felten, Andrew Miller and Steven Goldfeder, Bitcoin and Cryptocurrency Technologies, 2016."]}]'::jsonb from s;
