insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Vocabulary Building","topics":["Nature of Word Formation","Root Word and Morpheme","Prefix and Suffix","Foreign Expressions in English","Synonym and Antonym","Homophone and Homograph","Abbreviation and Acronym"]},{"title":"Basic Writing Skills","topics":["Parts of Speech: Types of Words","Structures of Sentence","Kind of Sentence","Phrase and Clause","Punctuation Marks","Capitalization","Tenses: Present, Past and Future","Voices: Active and Passive","Formation of Questions using Primary Auxiliaries, Modals and Wh-Words"]},{"title":"Common Errors in English","topics":["Articles","Prepositions","Modifiers","Subject-Verb Agreement","Noun-Pronoun agreement","Redundancies","Cliches","Spelling Error"]},{"title":"Principles of Appropriate Writing","topics":["Defining: Describing, Classifying and Exemplifying","Introduction, Body, and Conclusion","References, Quotations and Illustrations","Organizing the Paragraphs in a Document","7Cs of the Professional Writing: Clear, Concise, Concrete, Correct, Coherent, Complete and Courteous"]},{"title":"Practices of Formal Writing","topics":["Formal Letter: Cover-Letter and Application","Resume Writing","Report Writing","Minutes of Meeting","Memorandum","Notice","Essay Writing: Personal and Impersonal","Email Writing Etiquettes","Article Writing","Writing for Current Social Media"]},{"title":"Comprehension of Written English","topics":["Of Studies (Essay) by Sir Francis Bacon","The Sun Rising (Poem) by John Donne","The Last Leaf (Story) by O Henry","Unseen/Untaught Passage","English language and communication skills for engineers, Sanjay Kumar, Pushplata, Oxford university Press","Communicative English for Technical student, Dr. BijayBhadur Singh and Dr. KalpanaSinha, Foundation publishing House (FPM)","Communication Skill (As per VRV syllabus 2018), Sanjay Kumar and Pushplata, Oxford University Press","A course in Listening & Speaking, V. Sasi Ku