insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Node, Mesh Analysis & Theorems","topics":["Super Node and Super Mesh analysis","Superposition theorem","Thevenin theorem","Norton theorem","Maximum power transfer theorem","Reciprocity theorem","Substitution theorem","Tellegen''s theorem","Millman''s theorem","Duality principle"]},{"title":"Sinusoidal Steady State Analysis","topics":["Sinusoidal Steady-State analysis","Characteristics of Sinusoids","The Complex Forcing Function","The Phasor","Phasor relationship for R, L, and C","Impedance and Admittance","Phasor Diagrams","AC Circuit Power Analysis","Instantaneous Power","Average Power","Apparent Power and Power Factor","Complex Power"]},{"title":"Transients and Resonance in RLC Circuits","topics":["Basic RL and RC Circuits","The Source-Free RL Circuit","The Source-Free RC Circuit","The Unit-Step Function","Driven RL Circuits","Driven RC Circuits","RLC Circuits","Frequency Response","Parallel Resonance","Series Resonance","Quality Factor"]},{"title":"Topology & Coupled Circuits","topics":["Graph of a network","Trees, Co-trees, Loops","Incidence matrix","Tie-set matrix","Cut-set matrix","Mutual Inductance","Coupling Coefficient","Series and Parallel connections of coupled inductors","Ideal transformers"]},{"title":"Two Port Networks","topics":["Z parameter","Y Parameter","ABCD Parameter","Inverse ABCD Parameter","Hybrid Parameter","Inverse Hybrid Parameter","Condition of Reciprocity and Symmetry","Interrelationship of different parameter","Interconnection of two-port network"]},{"title":"Network Function","topics":["Network functions, their properties and concept of transfer impedance","Hurwitz polynomial","Positive real function and synthesis of LC, RC, RL Networks in Foster''s I and II, Cauer''s I and II forms","A William Hayt, \"Engineering Circuit Analysis\" 8th Edition, McGraw-Hill Education","M. E. Valkenburg; \"Network analysis\"; Third edition, Pearson","Circuit Theory, 