insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Bipolar Junction Transistor Amplifier Circuits","topics":["Small signal operation","Hybrid and re model","Frequency response analysis in different configurations","High frequency analysis of BJT","Miller effect","Analysis of Multistage amplifier","Frequency response of cascaded stages","Cascode amplifier","Darlington amplifier"]},{"title":"Field Effect Transistor Amplifier Circuits","topics":["Small signal operation","Frequency response analysis in different configurations","High frequency model of the MOSFET","High frequency response of CS and CE amplifiers","Unit 3.0: Feedback Amplifiers and Oscillators Classification and representation of amplifiers Feedback concept General Characteristics of negative feedback amplifiers Properties of feedback amplifier topologies Oscillators: Sinusoidal oscillators Barkhausen Criterion Analysis and design of RC phase shift oscillator Wien bridge oscillators Resonant circuit oscillators General form of oscillator circuit (Hartley & Colpitts) Crystal oscillators","Classification and representation of amplifiers","Feedback concept","General Characteristics of negative feedback amplifiers","Properties of feedback amplifier topologies","Oscillators: Sinusoidal oscillators","Barkhausen Criterion","Analysis and design of RC phase shift oscillator","Wien bridge oscillators","Resonant circuit oscillators","General form of oscillator circuit (Hartley & Colpitts)","Crystal oscillators"]},{"title":"Power Amplifier","topics":["Series-Fed Class A Amplifier","Transformer coupled Class A Amplifier","Class B amplifier Circuit and Operation","Amplifier Distortion","Push-Pull and Complementary Push-Pull Amplifiers","Power Transistor Heat Sinking","Class C and Class D Amplifier"]},{"title":"Operational Amplifier","topics":["Ideal Operational Amplifier characteristics","General operational amplifier stages and internal circuit diagrams of IC 741","DC and AC performance characteristics","Frequency response of OP-Amp","Applications of OP-Amp- Inverting and Non-inverting Amplifier","V to I and I to V converter","Logarithmic amplifier","Antilogarithmic amplifier","Instrumentation amplifier"]},{"title":"Application of Op-Amp and Special ICs","topics":["Comparator","Schmitt Trigger","555 Timer","Multivibrators","Precision rectifier","First and Second Order Active Filters","Voltage Controlled Oscillator (IC 566)","Phase Lock Loop (IC 565)","LM 3805","IC8038","Roy Choudhury. D., Shail Jain, \"Linear Integrated Circuits\", New Age International Publications, 4th Edition, 2010.","Sergio Franco, \"Design with Operational Amplifiers and Analog Integrated Circuits\", 3rd Edition, Tata McGraw-Hill, 2007.","Integrated devices & circuits by Millman & Halkias.","Electronic Devices & circuit theory by R. Boylestad.","Microelectronics by Sedra and Smith, Oxford University Press"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Number System","topics":["Binary Codes: BCD code","Excess-3 code","Gray-code","Complements: Signed magnitude","R''s complement","(r-1)''s complement"]},{"title":"Boolean Laws and Theorems","topics":["Logic Gate: Basic","Universal and Others","Truth TableLogic Functions","Conversion of Logic Functions into truth table and vice versa","SOP and POS forms of Representation","Canonical form","Minterm and maxterms","Simplification of Logic Functions by Theorems and Karnaugh''s Map","Don''t Care Conditions"]},{"title":"Combinational Circuits","topics":["Adders: Half Adder","Full Adder","Parallel Adder","Carry Look ahead Adder","Subtractors: Half subtractor","Full subtractor","Multiplexer: 2x1","4x1 and design of 8x1 multiplexer","Demultiplexer","Decoder","Encoder and comparator"]},{"title":"Sequential Circuit","topics":["Latches","Flip-Flops SR","JK","D and T Flip Flop","Race around Condition","Master-Slave flip flop","Shift Registers","Counters- Synchronous and Asynchronous: Design of Ripple Counter","Finite state machines"]},{"title":"Data Converter","topics":["Digital to Analog Converter","Binary-Weighted Resistors DAC","R-2R Ladder DAC","Analog to digital converters","Counter types ADC","Successive Approximation ADC","Dual Slope ADC","Flash ADC"]},{"title":"Logic Families & Semiconductor Memories","topics":["Characteristics of Digital ICs: Propagation delay","Power dissipation","Figure of Merit","Fan-out","Noise immunity","Wired-logic capability","Transistor-Transistor Logic","Emitter-Coupled Logic","MOS Logic","CMOS Logic","Transmission Gate","Comparison between logic families RAM","ROM","PLA","PAL","Circuit Implementation using ROM","PLA and PAL","M. Morris Mano and M. D. Ciletti, \"Digital Design\", Pearson Education.","David J. Comer, \"Digital Logic & State Machine Design\", Oxford University Press.","RP Jain, \"Modern Digital Electronics\", Tata McGraw Hill Publication.","A Anand Kumar Fundamental of digital circuits PHI 4th edition"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Vector Calculus and Coordinate System","topics":["Introduction to Vector Algebra","Coordinate Systems (rectangular, cylindrical, and spherical) and Transformation","Vector calculus-differentiation","Partial differentiation","Integration","Vector operator del","Gradient","Divergence","And curl","Integral theorems of vectors","Unit 2.0: Electrostatics Coulomb''s law Gauss''s law and its applications Electric field intensity Electrical field due to point charges Line Surface and Volume charge distributions Absolute Electric potential Potential difference Calculation of potential differences for different configurations Poisson''s and Laplace''s equation Applications (solution for some simple cases) Capacitance Electrostatic energy Conductor properties and Uniqueness Theorem","Coulomb''s law","Gauss''s law and its applications","Electric field intensity","Electrical field due to point charges","Line","Surface and Volume charge distributions","Absolute Electric potential","Potential difference","Calculation of potential differences for different configurations","Poisson''s and Laplace''s equation","Applications (solution for some simple cases)","Capacitance","Electrostatic energy","Conductor properties and Uniqueness Theorem"]},{"title":"Magnetostatics","topics":["Biot-Savart law","Ampere''s circuital law","Magnetic flux and magnetic flux density","Energy stored in magnetic field","Ampere''s force law","Magnetic vector potential","Analogy between electric and magnetic field","Maxwell''s equations in differential and integral form"]},{"title":"Maxwell''s Equations and Time-Varying Field","topics":["Faraday''s law","Transformer and motional EMF","Displacement current","Maxwell''s equations in time static and time varying field","Time harmonic field","Dielectric and Magnetic boundary condition","Unit 5.0: Electromagnetic Wave Propagation in Different Media Uniform Plane Wave Propagation