insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Communication Systems","topics":["Basic components of communication systems","Types of communication: Analog vs. Digital","Bandwidth requirements and frequency spectrum and Modulation and its necessity"]},{"title":"Amplitude Modulation (AM) Systems","topics":["Principles of amplitude modulation","AM","DSB-SC","SSB","And VSB modulation techniques","Generation and detection of AM and DSB","AM waveforms and frequency spectrum","Modulation index and power relations and AM transmitters and receivers"]},{"title":"Angle Modulation","topics":["FM and PM","Transmission FM spectra","Carson ''s rule","Narrow band","And wide band FM Generation of FM by Direct Methods","Indirect Generation of FM","The Armstrong Method","Direct Methods of Frequency Demodulation","Slope Detector","Foster Seely or Phase Discriminator","Indirect methods of FM Demodulation","FM Detector using PLL","Comparison of FM and PM"]},{"title":"Receivers","topics":["Tuned Radio Frequency (TRF) Receiver","Basic Elements of AM Super-heterodyne receiver","RF Amplifiers Characteristics Sensitivity","Selectivity","Image Frequency Rejection","Mixers Tracking and Alignment","Local Oscillator","IF Amplifier","AGC","AM Receiver using Transistors Communication Receiver","FM Receiver"]},{"title":"Noise in Communication Systems","topics":["Types of noise: thermal","Shot","And flicker noise","Signal-to-noise ratio (SNR) and its impact on system performance","Noise figure and noise temperature and Noise in AM and FM systems Pre emphasis and de-emphasis"]},{"title":"Pulse Modulation Technique","topics":["Pulse Modulation techniques - Sampling Process","PAM","PWM and PPM concepts","Methods of generation and detection","Noise performance","Electronic communication systems by George Kennedy.","Principle of communication systems by Taub and schilling.","B. P. Lathi and Z. Ding, \"Modern Digital and Analog Communication Systems\", 4th Ed., Oxford University Press, 2009.","J. G. Proakis, and M. Salehi, ''Fundamentals of Communication Systems'', Fifteenth Impression, Pearson Education Inc., India, 2013."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Electronic Materials Atomic structure and bonding in materials Crystal structure of materials Crystal systems Unit cells and space lattices Determination of structures of simple crystals by X-ray diffraction Miller indices of planes and directions Packing geometry in Metallic Ionic and Covalent solids Concept of amorphous Single and polycrystalline structures and their effect on properties of materials Insulator Semiconductor And conductor","Atomic structure and bonding in materials","Crystal structure of materials","Crystal systems","Unit cells and space lattices","Determination of structures of simple crystals by X-ray diffraction","Miller indices of planes and directions","Packing geometry in Metallic","Ionic and Covalent solids","Concept of amorphous","Single and polycrystalline structures and their effect on properties of materials","Insulator","Semiconductor","And conductor","Unit 2.0: Electronic Material Properties Polarization Dielectric constant at low frequency & high frequency Dielectric loss Piezoelectricity & Ferroelectricity Origin of magnetism in metallic and ceramic materials Para magnetism Diamagnetism Antiferromagnetism Ferromagnetism Ferrimagnetism Magnetic hysteresis Influence of temperature on magnetic behavior Domains and Hysteresis Superconductors Meissner effect Applications","Polarization","Dielectric constant at low frequency & high frequency","Dielectric loss","Piezoelectricity & Ferroelectricity","Origin of magnetism in metallic and ceramic materials","Para magnetism","Diamagnetism","Antiferromagnetism","Ferromagnetism","Ferrimagnetism","Magnetic hysteresis","Influence of temperature on magnetic behavior","Domains and Hysteresis","Superconductors","Meissner effect","Applications"]},{"title":"Measurement and Error","topics":["Sensitivity","Resolution","Accuracy and Precision","Absolute and Relative types of errors","Statistical analysis","Probability of Limiting errors","Linearity","Instruments: Current and Resistance in instruments","Analog and Digital Multimeters","Measurement of time and Frequency - Digital Frequency Meter and applications"]},{"title":"Impedance Measurement","topics":["Kelvin Bridge","Megger","Maxwell","Hay and Sheering Bridges","Q-meter","Noise and Interference reduction techniques in Measurement Systems","Wave Analyzer","Spectrum Analyzer","FFT Analyzer","Oscilloscopes: Pulse Measurements","Delayed Time Base","Analog Storage","Sampling and Digital Storage Oscilloscopes"]},{"title":"Transducers","topics":["Classification and selection of Transducers","Introduction to Strain","Load","Force","Displacement","Velocity","Acceleration","Pressure and Temperature Measurements","Introduction to Smart sensors and MEMS"]},{"title":"Introduction to Data Acquisition Systems (DAS)","topics":["Block Diagram","Specifications and various components of DAS","Applications of DAS in various fields","Bell DA, \"Electronic Instrumentation and Measurements,\" Prentice Hall2.","Sawhney A.K., \"Electrical and Electronic Measurements and Instrumentation,\" Dhanpat Rai and Sons.","\"Solid State Physics\", by Kittel, McGraw Hill.","\"Principles of Electric Engineering Materials & Devices\", by S.O. Kasp, Mc- Graw Hill.","\"Structure & properties of materials (VOL VI), Electronic Properties\", by Robert M. Rose, Lawrence A. Shepherd & John Wulf, Wiley Eastern Ltd."]}]'::jsonb from s;
