insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To represent basic signals (Unit step, unit impulse, ramp, exponential, sine and cosine)","To develop program for discrete convolution","To develop program for discrete correlation","To understand stability test","To understand sampling theorem","To design analog filters (low-pass, high pass, band pass, band stop)","To design digital filters (low-pass, high pass, band pass, band stop)","To design FIR filters using windows techniques"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Microprocessor Systems","topics":["Architecture and Pin diagram of 8085","Timing Diagram","Memory organization","Addressing modes","Interrupts","Assembly Language Programming","8085 interrupts","Additional I/O concepts and processes"]},{"title":"Interfacing of 8085","topics":["Interfacing of 8085 with 8255, 8254/8253, 8251, 8259","Generation of I/O Ports","Programmable Peripheral Interface (PPI)-Intel 8255","Sample-and-Hold Circuit and Multiplexer","Keyboard and Display Interface","Keyboard and Display Controller (8279)","Programmable Interval timers (Intel 8253/8254)","USART (8251)","PIC (8259)","DAC, ADC, LCD, Stepper Motor"]},{"title":"Introduction to 8086, 80286, 80386 and 80486 Microprocessors","topics":["8086 Architecture","Generation of physical address","Pin diagram of 8086","Minimum Mode and Maximum Mode","Bus cycle","Memory Organization","Memory Interfacing","Addressing Modes","Assembler Directives","Instruction set of 8086","Assembly Language Programming","Hardware and Software Interrupts","Introduction of 80286, 80386, and 80486 microprocessors","Module 4: Overview of Microcontroller 8051 Architecture Memory organization Special function registers Port Operation Memory Interfacing I/O Interfacing Programming 8051 resources Interrupts Programmer''s model of 8051 Operand types Operand addressing Data transfer instructions Arithmetic instructions Logic instructions Control transfer instructions Timer and Counter Programming Interrupt Programming","Architecture","Memory organization","Special function registers","Port Operation","Memory Interfacing","I/O Interfacing","Programming 8051 resources","Interrupts","Programmer''s model of 8051","Operand types","Operand addressing","Data transfer instructions","Arithmetic instructions","Logic instructions","Control transfer instructions","Timer and Counter Programming","Interrupt Programming","\"Microprocessors and Microcontrollers\", Muhammad Ali Mazidi, Pearson, 2006","\"Microprocessors and Interfacing, Programming and Hardware\", Douglas V Hall, Tata McGraw Hill, 2006","\"Microprocessor Architecture, Programming and Applications with the 8085\", Ramesh Gaonkar, PHI","\"The 8051 Microcontroller and Embedded Systems\", Muhammad Ali Mazidi, Janice Gillispie Mazidi, Rolin D. McKinlay, 2nd Edition, Pearson Education, 2008","\"The 8086 Microprocessor: Programming and Interfacing The PC\", Kenneth J. Ayala, Delmar Publishers, 2007","\"Advanced Microprocessors and Peripherals\", A K Ray, K M Bhurchandi, Tata McGraw Hill, 2007"]}]'::jsonb from s;
