insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: Control Systems Fundamentals Control Systems: Basics & Components Classifications and types of Control Systems Block diagrams & Signal flow graphs Transfer function Determination of transfer function using Block diagram reduction techniques and Mason''s Gain formula Control system components: Electrical, Mechanical, Electronic AC/DC Servo Motors, Stepper Motors, Tacho Generators, Synchros, Magnetic Amplifiers, Servo Amplifiers","Control Systems: Basics & Components","Classifications and types of Control Systems","Block diagrams & Signal flow graphs","Transfer function","Determination of transfer function using Block diagram reduction techniques and Mason''s Gain formula","Control system components: Electrical, Mechanical, Electronic","AC/DC Servo Motors, Stepper Motors, Tacho Generators, Synchros, Magnetic Amplifiers, Servo Amplifiers"]},{"title":"Time-Domain Analysis","topics":["Time domain performance specifications","Transient response of first and second order systems","Steady state errors and Static error constants in unity feedback control systems","Response with P, PI and PID controllers","Limitations of time domain analysis"]},{"title":"Frequency Domain Analysis","topics":["Polar and inverse polar plots","Frequency domain specifications and Performance of LTI systems","Logarithmic plots (Bode plots)","Gain and Phase Margins","Relative stability","Correlation with time domain performance","Closed loop frequency responses from Open loop response","Limitations of frequency domain analysis","Minimum/Non-minimum phase systems"]},{"title":"Stability and Compensation Techniques","topics":["Concepts: absolute, Asymptotic, Conditional and Marginal stability","Routh–Hurwitz and Nyquist stability criterion","Root locus technique and its application","Concepts of compensation: series/parallel/series-parallel/feedback compensation","Lag/Lead/Lag-Lead networks for compensation","Compensation using P, PI, PID controllers","Module 5: Control System Analysis using State Variable Methods State variable representation Conversion of state variable models to transfer functions Conversion of transfer functions to state variable models Solution of state equations Concepts of Controllability and Observability Stability of linear systems Equivalence between transfer function and state variable representations State variable analysis of digital control system Digital control design using state feedback","State variable representation","Conversion of state variable models to transfer functions","Conversion of transfer functions to state variable models","Solution of state equations","Concepts of Controllability and Observability","Stability of linear systems","Equivalence between transfer function and state variable representations","State variable analysis of digital control system","Digital control design using state feedback","\"Automatic Control System\", B. C. Kuo, Prentice Hall of India, 7th edition, 2001","\"Control Systems Engineering - Principles and Design\", Nagrath and Gopal, New Age Publishers","\"Control systems engineering\", Norman S. Nise, John Wiley and Sons (Asia) Singapore","\"Design of Feedback Control System\", Raymond T. Stefani, Oxford University Press","\"Modern control engineering\", K. Ogata, Pearson, 2002"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"IC Fabrication","topics":["IC classification","Fundamental of monolithic IC technology","Epitaxial growth, masking and etching, diffusion of impurities","Realization of monolithic ICs and packaging","Fabrication of diodes, capacitance, resistance and FETs"]},{"title":"Characteristics of OPAMP","topics":["Ideal OP-AMP characteristics","DC characteristics, AC characteristics","Differential amplifier","Frequency response of OP-AMP","Basic applications of Op-Amp – Inverting and Non-inverting Amplifiers","V/I and I/V converters, Summer, Differentiator and Integrator"]},{"title":"Applications of OPAMP","topics":["Instrumentation amplifier","Log and Antilog Amplifiers","First and second order active filters","Comparators, multivibrators, waveform generators","Clippers, clampers, peak detector, S/H circuit","D/A converter (R-2R ladder and weighted resistor types)","A/D converters using Op-Amps"]},{"title":"Special ICs","topics":["555 Timer IC","566 voltage controlled oscillator IC","565-phase lock loop IC","Analog multiplier ICs"]},{"title":"Application ICs","topics":["IC voltage regulators – LM78XX, 79XX Fixed voltage regulators","LM317, 723 Variable voltage regulators","Switching regulator- SMPS","LM 380 power amplifier","ICL 8038 function generator IC","\"Op-amp and Linear ICs\", David A. Bell, Oxford, 2013","\"Linear Integrated Circuits\", D. Roy Choudhary, Sheil B. Jani, II edition, New Age, 2003","\"Op-amps and Linear Integrated Circuits\", Ramakant A. Gayakward, IV edition, Pearson Education, PHI, 2000","\"Opamps and Linear Integrated Circuits Concepts and Applications\", Fiore, Cengage, 2010","\"Fundamentals of Analog Circuits\", Floyd and Buchla, Pearson, 2013","\"Integrated Electronics - Analog and Digital circuits system\", Jacob Millman, Christos C. Halkias, Tata McGraw Hill, 2003","\"Op-amp and Linear ICs\", Robert F. Coughlin, Fredrick F. Driscoll, PHI Learning, 6th edition, 2012"]}]'::jsonb from s;
