insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Probability Fundamentals","topics":["Sets and set operations","Probability space","Conditional probability and Bayes theorem","Combinatorial probability and sampling models"]},{"title":"Random Variables","topics":["Discrete random variables, probability mass function, probability distribution function","Example random variables and distributions","Continuous random variables, probability density function, probability distribution function","Example distributions"]},{"title":"Advanced Probability Concepts","topics":["Joint distributions","Functions of one and two random variables","Moments of random variables","Conditional distribution, densities and moments","Characteristic functions of a random variable","Markov, Chebyshev and Chernoff bounds"]},{"title":"Convergence and Limit Theorems","topics":["Random sequences and modes of convergence","Limit theorems","Strong and weak laws of large numbers","Central limit theorem"]},{"title":"Random Processes","topics":["Random process","Stationary processes","Mean and covariance functions","Ergodicity","Transmission of random process through LTI","Power spectral density","Markov chain and Markov processes","\"Probability and Random Processes with Applications to Signal Processing,\" H. Stark and J. Woods, Third Edition, Pearson Education","\"Probability, Random Variables and Stochastic Processes\", A. Papoulis and S. Unnikrishnan Pillai, Fourth Edition, McGraw Hill","\"Introduction to Probability Theory with Stochastic Processes\", K. L. Chung, Springer International"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Data Communication Components","topics":["Representation of data and its flow Networks","Various Connection Topology","Protocols and Standards, OSI model","Transmission Media","LAN: Wired LAN, Wireless LANs","Connecting LAN and Virtual LAN","Techniques for Bandwidth utilization: Multiplexing - Frequency division, Time division and Wave division","Concepts on spread spectrum"]},{"title":"Data Link Layer and Medium Access Sub Layer","topics":["Error Detection and Error Correction Fundamentals","Block coding, Hamming Distance, CRC","Flow Control and Error control protocols - Stop and Wait, Go back - N ARQ, Selective Repeat ARQ","Sliding Window, Piggybacking","Random Access, Multiple access protocols - Pure ALOHA, Slotted ALOHA, CSMA/CD, CDMA/CA"]},{"title":"Network Layer","topics":["Switching","Logical addressing – IPv4, IPv6","Address mapping – ARP, RARP, BOOTP and DHCP","Delivery, Forwarding and Unicast Routing protocols"]},{"title":"Transport Layer","topics":["Process to Process Communication","User Datagram Protocol (UDP)","Transmission Control Protocol (TCP)","SCTP Congestion Control","Quality of Service, QoS improving techniques: Leaky Bucket and Token Bucket algorithm","Module 5: Application Layer and Network Security Domain Name Space (DNS), DDNS, TELNET, EMAIL, FTP, WWW, HTTP, SNMP, Bluetooth, Firewalls Basic concepts of Cryptography Passive and Active Attacks, Symmetric Encryption, Encryption Algorithms Key Distribution, Traffic Padding, Message Authentication, Hash function Secure Hash function, Public-key Encryption, Digital Signature RSA Public Key Encryption algorithm, Key Management Secure Socket Layer and Transport layer Security, SSL Architecture SSL Record Protocol, Change Cipher Spec Protocol, Alert Protocol, Handshake Protocol IP level security IPSEC, Application layer security PGP, Firewall, Virtual Private Networks","Domain Name Space (DNS), DDNS, TELNET, EMAIL, FTP, WWW, HTTP, SNMP, Bluetooth, Firewalls","Basic concepts of Cryptography","Passive and Active Attacks, Symmetric Encryption, Encryption Algorithms","Key Distribution, Traffic Padding, Message Authentication, Hash function","Secure Hash function, Public-key Encryption, Digital Signature","RSA Public Key Encryption algorithm, Key Management","Secure Socket Layer and Transport layer Security, SSL Architecture","SSL Record Protocol, Change Cipher Spec Protocol, Alert Protocol, Handshake Protocol","IP level security IPSEC, Application layer security PGP, Firewall, Virtual Private Networks","\"Data Communication and Networking\", 4th Edition, Behrouz A. Forouzan, McGraw-Hill","\"Data and Computer Communication\", 8th Edition, William Stallings, Pearson Prentice Hall India","\"Computer Networks\", 8th Edition, Andrew S. Tanenbaum, Pearson New International Edition","\"Internetworking with TCP/IP\", Volume 1, 6th Edition Douglas Comer, Prentice Hall of India","\"TCP/IP Illustrated\", Volume 1, W. Richard Stevens, Addison-Wesley, United States of America","\"Network Security Bible\", by Cole, Krutz and Conley, Wiley dreamtech"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Mandatory non-credit course","We as human beings are not an entity separate from the environment around us rather we are a constituent seamlessly integrated and co-exist with the environment around us.","Small group meetings about water management, promotion of recycle use, generation of less waste, avoiding electricity waste","Slogan making events","Poster making events","Cycle rally","Lectures from experts","Plantation","Gifting a tree to see its full growth","Cleanliness drive","Drive for segregation of waste","To live with some big environmentalist for a week or so to understand his work","To work in kitchen garden for mess","To know about the different varieties of plants","Shutting down the fans and ACs of the campus for an hour or so"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["6 Credits (0L:0T:12P)","Practical entrepreneurship training and project work."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Mandatory non-credit course","The Constitution of India is the supreme law of India. Parliament of India cannot make any law which violates the Fundamental Rights enumerated under the Part III of the Constitution.","Meaning of the constitution law and constitutionalism","Historical perspective of the Constitution of India","Salient features and characteristics of the Constitution of India","Scheme of the fundamental rights","The scheme of the Fundamental Duties and its legal status","The Directive Principles of State Policy – Its importance and implementation","Federal structure and distribution of legislative and financial powers between the Union and the States","Parliamentary Form of Government in India – The constitution powers and status of the President of India","Amendment of the Constitutional Powers and Procedure","The historical perspectives of the constitutional amendments in India","Emergency Provisions: National Emergency, President Rule, Financial Emergency","Local Self Government – Constitutional Scheme in India","Scheme of the Fundamental Right to Equality","Scheme of the Fundamental Right to certain Freedom under Article 19","Scope of the Right to Life and Personal Liberty under Article 21"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: Introduction Purpose: To Convey That Biology Is As Important A Scientific Discipline As Mathematics, Physics And Chemistry Bring Out The Fundamental Differences Between Science And Engineering By Drawing A Comparison Between Eye And Camera, Bird Flying And Aircraft Mention The Most Exciting Aspect Of Biology As An Independent Scientific Discipline Why Do We Need To Study Biology Discuss How Biological Observations Of 18th Century That Lead To Major Discoveries Examples From Brownian Motion And The Origin Of Thermodynamics By Referring To The Original Observation Of Robert Brown And Julius Mayor These Examples Will Highlight The Fundamental Importance Of Observations In Any Scientific Inquiry","Purpose: To Convey That Biology Is As Important A Scientific Discipline As Mathematics, Physics And Chemistry","Bring Out The Fundamental Differences Between Science And Engineering By Drawing A Comparison Between Eye And Camera, Bird Flying And Aircraft","Mention The Most Exciting Aspect Of Biology As An Independent Scientific Discipline","Why Do We Need To Study Biology","Discuss How Biological Observations Of 18th Century That Lead To Major Discoveries","Examples From Brownian Motion And The Origin Of Thermodynamics By Referring To The Original Observation Of Robert Brown And Julius Mayor","These Examples Will Highlight The Fundamental Importance Of Observations In Any Scientific Inquiry","Module 2: Classification Purpose: To Convey That Classification Per Se Is Not What Biology Is All About The Underlying Criterion, Such As Morphological, Biochemical Or Ecological Be Highlighted Hierarchy Of Life Forms At Phenomenological Level A Common Thread Weaves This Hierarchy Classification Discuss Classification Based On (A) Cellularity- Unicellular Or Multicellular (B) Ultrastructure- Prokaryotes Or Eukaryotes (C) Energy And Carbon Utilization -Autotrophs, Heterotrophs, Lithotrophs (D) Ammonia Excretion - Ammonotelic, Uricotelic, Ureotelic (E) Habitat- Aquatic Or Terrestrial (E) Molecular Taxonomy- Three Major Kingdoms Of Life A Given Organism Can Come Under Different Categories Based On Classification Model Organisms For The Study Of Biology Come From Different Groups E.Coli, S.Cerevisiae, D. Melanogaster, C. Elegance, A. Thaliana, M. Musculus","Purpose: To Convey That Classification Per Se Is Not What Biology Is All About","The Underlying Criterion, Such As Morphological, Biochemical Or Ecological Be Highlighted","Hierarchy Of Life Forms At Phenomenological Level","A Common Thread Weaves This Hierarchy Classification","Discuss Classification Based On (A) Cellularity- Unicellular Or Multicellular (B) Ultrastructure- Prokaryotes Or Eukaryotes","(C) Energy And Carbon Utilization -Autotrophs, Heterotrophs, Lithotrophs (D) Ammonia Excretion - Ammonotelic, Uricotelic, Ureotelic","(E) Habitat- Aquatic Or Terrestrial (E) Molecular Taxonomy- Three Major Kingdoms Of Life","A Given Organism Can Come Under Different Categories Based On Classification","Model Organisms For The Study Of Biology Come From Different Groups","E.Coli, S.Cerevisiae, D. Melanogaster, C. Elegance, A. Thaliana, M. Musculus","Module 3: Genetics Purpose: To Convey That Genetics Is To Biology What Newton''s Laws Are To Physical Sciences Mendel''s Laws, Concept Of Segregation And Independent Assortment Concept Of Allele Gene Mapping, Gene Interaction, Epistasis Meiosis And Mitosis Be Taught As A Part Of Genetics Emphasis To Be Give Not To The Mechanics Of Cell Division Nor The Phases But How Genetic Material Passed From Parent To Offspring Concepts Of Recessiveness And Dominance Concept Of Mapping Of Phenotype To Genes Discuss About The Single Gene Disorders In Humans Discuss The Concept Of Complementation Using Human Genetics","Purpose: To Convey That Genetics Is To Biology What Newton''s Laws Are To Physical Sciences","Mendel''s Laws, Concept Of Segregation And Independent Assortment","Concept Of Allele","Gene Mapping, Gene Interaction, Epistasis","Meiosis And Mitosis Be Taught As A Part Of Genetics","Emphasis To Be Give Not To The Mechanics Of Cell Division Nor The Phases But How Genetic Material Passed From Parent To Offspring","Concepts Of Recessiveness And Dominance","Concept Of Mapping Of Phenotype To Genes","Discuss About The Single Gene Disorders In Humans","Discuss The Concept Of Complementation Using Human Genetics"]},{"title":"Biomolecule","topics":["Purpose: To Convey That All Forms Of Life Has The Same Building Blocks And Yet The Manifestations Are As Diverse As One Can Imagine Molecules Of Life","In This Context Discuss Monomeric Units And Polymeric Structures","Discuss About Sugars, Starch And Cellulose","Amino Acids And Proteins","Nucleotides And Dna/Rna","Two Carbon Units And Lipids"]},{"title":"Enzymes","topics":["Purpose: To Convey That Without Catalysis Life Would Not Have Existed On Earth Enzymology","How To Monitor Enzyme Catalyzed Reactions","How Does An Enzyme Catalyzed Reactions","Enzyme Classification","Mechanism Of Enzyme Action","Discuss At Least Two Examples","Enzyme Kinetics And Kinetic Parameters","Why Should We Know These Parameters To Understand Biology","Rna Catalysis"]},{"title":"Information Transfer","topics":["Purpose: The Molecular Basis Of Coding And Decoding Genetic Information Is Universal Molecular Basis Of Information Transfer","Dna As A Genetic Material","Hierarchy Of Dna Structure- From Single Stranded To Double Helix To Nucleosomes","Concept Of Genetic Code","Universality And Degeneracy Of Genetic Code","Define Gene In Terms Of Complementation And Recombination"]},{"title":"Macromolecular Analysis","topics":["Purpose: How To Analyze Biological Processes At The Reductionistic Level","Proteins- Structure And Function","Hierarchy In Protein Structure","Primary Secondary, Tertiary And Quaternary Structure","Proteins As Enzymes, Transporters, Receptors And Structural Elements","Module 8: Metabolism Purpose: The Fundamental Principles Of Energy Transactions Are The Same In Physical And Biological World Thermodynamics As Applied To Biological Systems Exothermic And Endothermic Versus Endergonic And Exergonic Reactions Concept Of Keq And Its Relation To Standard Free Energy Spontaneity Atp As An Energy Currency This Should Include The Breakdown Of Glucose To Co2 + H2o (Glycolysis And Krebs Cycle) And Synthesis Of Glucose From Co2 And H2o (Photosynthesis) Energy Yielding And Energy Consuming Reactions Concept Of Energy Charge","Purpose: The Fundamental Principles Of Energy Transactions Are The Same In Physical And Biological World","Thermodynamics As Applied To Biological Systems","Exothermic And Endothermic Versus Endergonic And Exergonic Reactions","Concept Of Keq And Its Relation To Standard Free Energy","Spontaneity","Atp As An Energy Currency","This Should Include The Breakdown Of Glucose To Co2 + H2o (Glycolysis And Krebs Cycle) And Synthesis Of Glucose From Co2 And H2o (Photosynthesis)","Energy Yielding And Energy Consuming Reactions","Concept Of Energy Charge"]},{"title":"Microbiology","topics":["Concept Of Single Celled Organisms","Concept Of Species And Strains","Identification And Classification Of Microorganisms","Microscopy","Ecological Aspects Of Single Celled Organisms","Sterilization And Media Compositions","Growth Kinetics"]},{"title":"A: Plant Physiology","topics":["Transpiration","Mineral Nutrition"]},{"title":"B: Ecology","topics":["Ecosystems: Components, Types, Flow Of Matter And Energy In An Ecosystem","Community Ecology- Characteristics, Frequency, Life Forms, And Biological Spectrum","Ecosystem Structure- Biotic And Abiotic Factors, Food Chain, Food Web, Ecological Pyramids","Biology: A Global Approach: Campbell, N. A.; Reece, J. B.; Urry, Lisa; Cain, M, L.; Wasserman, S. A.; Minorsky, P. V.; Jackson, R. B. Pearson Education Ltd","Outlines Of Biochemistry, Conn, E.E; Stumpf, P.K; Bruening, G; Doi, R.H., John Wiley And Sons","Principles Of Biochemistry (V Edition), By Nelson, D. L.; And Cox, M. M.W.H. Freeman And Company","Molecular Genetics (Second Edition), Stent, G. S.; And Calendar, R.W.H. Freeman And Company, Distributed By Satish Kumar Jain For Cbs Publisher","Microbiology, Prescott, L.M J.P. Harley And C.A. Klein 1995. 2nd Edition Wm, C. Brown Publishers"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Computer Arithmetic","Instruction Sets","Introduction To Computer Organization","Cpu Design","Micro Programmed Control: Control Memory, Address Sequencing, Micro Programming, Sequencing And Execution Of Microinstructions"]},{"title":"Memory System","topics":["Hierarchical Memory Structure","Cache Memories","Set Associative Memory","Virtual Memory","Paging","Segmentation","Input-Output Inter- Face","Asynchronous Data Transfer","Programmed I/O","Interrupts","Direct Memory Access"]},{"title":"Input-Output Organization","topics":["Basic Input/Output Structure Of Computers","Serial And Parallel Communications","Asynchronous Data Communication","Programmed I/O","Interrupt Driven I/O","Interrupt Controller","Dma","Device Drivers","Buses"]},{"title":"Introduction To Parallel Processing","topics":["Evolution Of Computer Systems (Risc Vs. Cisc)","Parallelism In Uniprocessor Systems","Architectural Classification Schemes"]},{"title":"Principles Of Pipelining And Vector Processing","topics":["Pipeline Strategy","Pipeline Performance","Controls And Data Paths","Overlapped Parallelism","Principles Of Designing Pipelined Processors","Vector Processing Requirements","Computer System Architecture By M. Morris Mano","Computer Architecture And Parallel Processing By Kai Hwang, Briggs, Mcgraw Hill","Computer Architecture By Carter, Tata Mcgraw Hill","Computer System Organization And Architecture By John D. Carpinelli, Pearson Education"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Block Diagram Of Digital Communication System","Advantages Of Digital Communication System Over Analog Communication Systems","Sampling Theorem","Signal Reconstruction In Time Domain","Practical And Flat Top Sampling","Sampling Of Band-Pass Signal","Aliasing Problem","Uniform And Non-Uniform Quantization","Signal To Quantization Ratio Of Quantized Signal"]},{"title":"Baseband Transmission","topics":["Line Coding And Its Properties","Various Types Of Pcm Waveforms","Attributes Of Pcm Waveforms","Mary Pulse Modulation Waveforms","Differential Pulse Code Modulation","Multiplexing Of Pcm Signals","Delta Modulation","Idling Noise And Slope Overload","Adaptive Delta Modulation","Adaptive Dpcm","Comparison Of Pcm And Dm"]},{"title":"Baseband Detection","topics":["Error Performance Degradation In Communication Systems","Eb/No Parameter","Matched Filter And Its Derivation","Inter-Symbol Interference (Isi)","Nyquist Criterion For Zero Isi And Raised Cosine Spectrum","Correlation Detector: Decision Threshold And Error Probability For Binary, Unipolar (On-Off ) Signalling","Module 4: Band-Pass Modulation And Demodulation Types Of Digital Modulation Waveforms For Amplitude, Frequency And Phase Shift Keying Method Of Generation And Detection Of Coherent And Non-Coherent Binary Ask, Fsk And Psk Differential Phase Shift Keying Quadrature Modulation Techniques M- Ary Fsk Minimum Shift Keying (Msk) Probability Of Error And Comparison Of Various Digital Modulation Techniques","Types Of Digital Modulation","Waveforms For Amplitude, Frequency And Phase Shift Keying","Method Of Generation And Detection Of Coherent And Non-Coherent Binary Ask, Fsk And Psk","Differential Phase Shift Keying","Quadrature Modulation Techniques","M- Ary Fsk","Minimum Shift Keying (Msk)","Probability Of Error And Comparison Of Various Digital Modulation Techniques"]},{"title":"Error","topics":["A Baseband Signal Receiver","Probability Of Error","The Optimum Filter","Matched Filter","Probability Of Error In Matched Filter","Coherent Reception","Coherent Reception Of Ask, Psk And Fsk","Non-Coherent Reception Of Ask, Fsk, Psk And Qpsk","Calculation Of Bit Error Probability Of Bpsk And Bfsk","Error Probability For Qpsk"]},{"title":"Multiple Access Techniques","topics":["Time Division Multiplexing","Frequency Division Multiplexing","Code Division Multiplexing","Introduction To Upcoming Techniques Of Transmission","Communication Systems, Simon Haykin, Wiley Publication, 4th Edition, 2004","Digital Communication Fundamentals And Applications, Bernard Sklar, Pearson Education India, 2nd Edition, 2009","Modern Electronic Communication, Miller Gary M, Prentice-Hall, 6th Edition, 1999","Digital Communications, John Proakis, Tata Mc Graw Hill, 5th Edition, 2007","Electronic Communication Systems, Fundamentals Through Advanced, Wayne Tomsi, Pearson Education, 4th Edition, 2001"]}]'::jsonb from s;
