insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Introduction To Standards Of Measurement","Errors And Their Evaluation","Calibration","Accuracy","Precision Sensitivity","Resolution","Noise, Etc","Module 2: Measurements Of Voltage, Current, Power And Energy Moving Iron, Moving Coil, Thermal, Induction And Rectifier Type Measurements Of Power Factor And Frequency Dynamometer And Moving Iron Single And Three Phase Power Factor Meters Resonance, Moving Coil And Moving Iron Frequency Meters Range Extension Of Voltmeter, Ammeter, Wattmeter And Energy Meter Voltmeter Multipliers Ammeter Shunt Current And Potential Transformers","Moving Iron, Moving Coil, Thermal, Induction And Rectifier Type","Measurements Of Power Factor And Frequency","Dynamometer And Moving Iron Single And Three Phase Power Factor Meters","Resonance, Moving Coil And Moving Iron Frequency Meters","Range Extension Of Voltmeter, Ammeter, Wattmeter And Energy Meter","Voltmeter Multipliers","Ammeter Shunt","Current And Potential Transformers"]},{"title":"Galvanometer","topics":["D'' Arsonval","Vibration And Ballistic Galvanometers"]},{"title":"Bridges","topics":["D.C. Bridges: Kelvin Double Bridge, Wheatstone Bridge And Carey-Foster Bridge","A.C. Bridges: Maxwell Bridge, Hay And Owen Bridges, Anderson Bridge, Wien Bridge, Schering Bridge And Heaviside-Campbell Bridge"]},{"title":"Potentiometer''s Principle, Standardization And Application","topics":["D.C. Potentiometers: Crompton And Vernier Potentiometers","A.C. Potentiometers: Coordinate Type And Polar Type"]},{"title":"Magnetic Measurements","topics":["Measurement Of Magnetic Flux By Ballistic Galvanometer And Fluxmeter","Determination Of B-H Curve And Hysteresis Loop","Separation Of Iron Loss Into Hysteresis And Eddy Current Losses","Measurement Of Iron Loss And Its Separation On Lloyd-Fisher Squares"]},{"title":"Digital Measurements","topics":["Digital Voltmeter And Multimeter Universal Counter And Its Uses For Measurements Of Frequency","Ratio Of Two Frequencies","Time Period And Pulse Width","Measurement System, Application And Design, E O Doeblin, Tmh","Course In Electrical And Electronic Measurement And Instrumentation, A K Sawhney, Dhanpat Rai And Sons","Electronic Measurements And Instrumentation, Rajendra Prasad, Khanna Publishers","Basic Electrical Measurements, M.B. Stout, Prentice Hall"]}]'::jsonb from s;
