insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Verification of Kirchhoff''s laws.","Verification of Superposition Theorem.","Verification of Thevenin''s Theorem.","Verification of Norton''s Theorem.","Verification of Maximum Power Transfer Theorem.","Measurement of power in 3-φ circuit by Two Watt meter method and determination of its power factor.","Star to Delta and Delta to Star conversion of the three circuit.","Determination of Efficiency by load test of a 1-φ Transformer.","To study the typical BHK house wiring.","Study of safety precautions while working on electrical installations and necessity of earthing."]}]'::jsonb from s;
