insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Indian Knowledge Systems","topics":["Overview of IKS","Organization of IKS","Conception and constitution of knowledge in indian tradition","The oral tradition","Models and Strategies of IKS"]},{"title":"Overview of IKS Domains","topics":["The vedas as the basis of IKS","Overview of all the six vedāngas"]},{"title":"Relevance in Current Technical Education System I","topics":["Relevance of following IKS domains in present technical education system: Arthashastra (Indian economics and political systems)","Ganita and Jyamiti (indian mathematics, astronomy and geometry)","Rasayana (indian chemical Sciences)"]},{"title":"Relevance in Current Technical Education System II","topics":["Ayurveda (Indian Biological Sciences / Diet & Nutrition)","Jyotish Vidya (observational astronomy and calendar systems)","Prakriti Vidya (indian system of terrestrial/ material sciences/ecology and atmospheric sciences)"]},{"title":"Relevance in Current Technical Education System III","topics":["Vastu Vidya (indian system of aesthetics-iconography and built-environment /architecture)","Nyaya Shastra (indian systems of social ethics, logic and law)"]},{"title":"Additional IKS Domains","topics":["Shilpa and Natya Shastra (indian classical arts: performing and fine arts)","Sankhya and Yoga Darshna (indian psychology, yoga and consciousness studies)","Vrikshayurveda (plant science/sustainable agriculture/food preservation methods)","Introduction to Indian Knowledge System: Concepts and Applications, Archak, K.B. (2012), Kaveri Books, New Delhi, ISBN-13:978-9391818203","Introduction To Indian Knowledge System: Concepts and Applications, Mahadevan, B. Bhat, Vinayak Rajat, Nagendra Pavana R.N., PHI, ISBN: 9789391818203.","Glimpse into Kautilya''s Arthashastra Ramachandrudu P. (2010), Sanskrit Academy, Hyderabad, ISBN:9788380171074.","\"Introduction\" in Studies in Epics and Purāṇas, (Eds.), KM Munshi and N Chandrashekara Aiyer Bhartiya Vidya Bhavan."]}]'::jsonb from s;
