insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit-1.0: Review of Vector Calculus Vector algebra: addition Subtraction Components of vectors Scalar and vector multiplications Triple products Three orthogonal coordinate systems (rectangular Cylindrical And spherical) Vector calculus- differentiation Partial differentiation Integration Vector operator del Gradient Divergence And curl; integral theorems of vectors Conversion of a vector from one coordinate system to another","Vector algebra: addition","Subtraction","Components of vectors","Scalar and vector multiplications","Triple products","Three orthogonal coordinate systems (rectangular","Cylindrical","And spherical)","Vector calculus- differentiation","Partial differentiation","Integration","Vector operator del","Gradient","Divergence","And curl; integral theorems of vectors","Conversion of a vector from one coordinate system to another"]},{"title":"Static Electric Field","topics":["Coulomb''s law","Electric field intensity","Electrical field due to point charges. Line","Surface","And Volume charge distributions","Gauss'' law and its applications. Absolute Electric potential","Potential difference","Calculation of potential differences for different configurations","Electric dipole","Electrostatic Energy","And Energy density"]},{"title":"Conductors, Dielectrics, and Capacitance","topics":["Current and current density","Ohm''s Law in Point form","Continuity of current","Boundary conditions of perfect dielectric materials","Permittivity of dielectric materials","Capacitance","Capacitance of a two-wire line","Poisson''s equation","Laplace''s equation","Solution of Laplace and Poisson''s equation","Application of Laplace''s and Poisson''s equations","Unit-4.0: Static Magnetic Fields & Time Varying Fields Static Magnetic Field: Biot-Savart Law Ampere Law Magnetic flux and magnetic flux density Scalar and Vector Magnetic potentials Steady magnetic fields produc