insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Study and verify the operation of all logic gates.","Design and verify NAND & NOR Gate as a Universal gates.","Design and verify DE Morgan''s Theorem.","Design and verify Binary to Gray & Gray to Binary Conversion.","Design and verify Half adder circuit & Half Subtractor circuit.","Design and verify Full adder circuit & Full Subtractor Circuit.","Study and verify multiplexer and De-multiplexer Circuit.","Design and verify BCD to 7-segment display.","Study of Encoder and Decoder circuit","Study of characteristics of SR, JK, T & Master-Slave Flip-Flop.","Design and verify shift register circuit","Study and verify weighted Binary DAC R-2R ladder DAC & Flash ADC","Study of Johnson counter & Binary counter.","Study of 4-bit Synchronous Up/Down mod-n counter."]}]'::jsonb from s;
