insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Fundamentals of Microprocessors and Microcontrollers","topics":["Fundamentals of Microprocessor Architecture","8-bitMicroprocessor and Microcontroller architecture","Comparison of 8-bit microcontrollers","16-bit and 32-bit microcontrollers","Definition of embedded system and its characteristics","Role of microcontrollers in embedded Systems","Overview of the 8051 family"]},{"title":"The 8086 Microprocessor","topics":["Introduction to 8086 Microprocessor","Architecture of 8086 Microprocessor","Addressing modes of 8086","Instruction set of 8086","Assembler directives","Simple assembly language programs","Procedures","Macros","Pin diagram of 8086-Minimum mode and maximum mode of operation"]},{"title":"The 8051 Architecture","topics":["Internal Block Diagram","CPU","ALU","Address","Data and control bus","Working registers","SFRs","Clock and RESET circuits","Stack and Stack Pointer","Program Counter","I/O ports","Memory Structures","Data and Program Memory","Timing diagrams and Execution Cycles","Unit-4.0: The 8051 Instruction Set and Programming Addressing modes: Introduction Instruction syntax Data types Subroutines Immediate addressing Register addressing Direct addressing Indirect addressing Relative addressing Indexed addressing Bit inherent addressing Bit direct addressing 8051 Instruction set Instruction timings Data transfer instructions Arithmetic instructions Logical instructions Branch instructions Subroutine instructions Bit manipulation instruction Assembly language programs C language programs Assemblers and compilers Programming and debugging tools","Addressing modes: Introduction","Instruction syntax","Data types","Subroutines Immediate addressing","Register addressing","Direct addressing","Indirect addressing","Relative addressing","Indexed addressing","Bit inherent addressing","Bit direct addressing","8051 Instruction set","Instruction timings","Data transfer instructions","Arithmetic instructions","Logical instructions","Branch instructions","Subroutine instructions","Bit manipulation instruction","Assembly language programs","C language programs","Assemblers and compilers","Programming and debugging tools","Unit-5.0: The 8051 Memory and I/O Interfacing Memory and I/O expansion buses Control signals Memory wait states Interfacing of peripheral devices such as General Purpose I/O ADC DAC Timers Counters Memory devices Keyboard and display devices Interfacing of sensors Transducers Actuators Data acquisition systems Standard Interfaces - RS232 USB Development aids and troubleshooting techniques Programmable Interrupt and DMA controllers","Memory and I/O expansion buses","Control signals","Memory wait states","Interfacing of peripheral devices such as General Purpose I/O","ADC","DAC","Timers","Counters","Memory devices","Keyboard and display devices","Interfacing of sensors","Transducers","Actuators","Data acquisition systems","Standard Interfaces - RS232","USB","Development aids and troubleshooting techniques","Programmable Interrupt and DMA controllers"]},{"title":"External Communication Interface","topics":["Synchronous and Asynchronous Communication","RS232","SPI","I2C","Introduction and interfacing to protocols like Blue-tooth and Zig-bee","M. A.Mazidi, J. G. Mazidi and R. D. McKinlay, \"The8051 Microcontroller and Embedded Systems: Using Assembly and C\", Pearson Education, 2007.","K. J. Ayala, \"8051 Microcontroller\", Delmar Cengage Learning, 2004.","R. Kamal, \"Embedded System\", McGraw HillEducation, 2009.","R. S. Gaonkar, \", Microprocessor Architecture: Programming and Applications with the 8085\", Penram International Publishing, 1996","D.A. Patterson and J.H. Hennessy, \"Computer Organization and Design: The Hardware/Software interface\", Morgan Kaufman Publishers, 2013.","D. V. Hall, \"Microprocessors & Interfacing\", McGraw Hill Higher Education, 1991."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Fundamentals of Mechanics","topics":["Overview of engineering mechanics","Vector and scalar quantities","Units of physical quantities","Dimensions of physical quantities","Units and Dimensions","Dimensional analysis"]},{"title":"Force Systems and Equilibrium","topics":["Force Systems Basic Concepts","Particle Equilibrium in 2-D & 3-D","Rigid Body Equilibrium","System of Forces: oplanar Concurrent Forces","Components in Space","Resultant and Moment of Forces and its Application","Couples and Resultant of Force System","Free Body Diagrams","Equations of Equilibrium of Coplanar Systems and Spatial Systems"]},{"title":"Friction and Structural Analysis","topics":["Types of Friction: Limiting","Static","Dynamic","Laws of Friction","Motion of Bodies and Wedge Friction","Equilibrium in Three Dimensions","Method of Sections and Method of Joints","Tension and Compression in Members","Simple Trusses","Zero Force Members","Beams","Types of Beams","Frames and Machines"]},{"title":"Centroid, Centre of Gravity, and Moment of Inertia","topics":["Centroid of Simple Figures from First Principle","Centroid of Composite Sections","Centre of Gravity and Its Implications","Area Moment of Inertia: Definition and Theorems Moment of Inertia of Plane Sections","Standard Sections","Composite Sections","Mass Moment Inertia of Circular Plate","Cylinder","Cone","Sphere","Hook","Unit-5.0: Virtual Work, Energy Method, and Particle Dynamics Virtual Displacements and Principle of Virtual Work Degrees of Freedom and Active Force Diagram Conservative Forces and Potential Energy Energy Equation for Equilibrium Applications of Energy Method for Equilibrium Stability of Equilibrium Review of Particle Dynamics: Rectilinear and Plane Curvilinear Motion Relative and Constrained Motion Newton''s 2nd Law Work-Kinetic Energy Power Potential Energy Impulse-Momentum and Impact","Virtual Displacements and Principle of Virtual Work","Degrees of Freedom and Active Force Diagram","Conservative Forces and Potential Energy","Energy Equation for Equilibrium","Applications of Energy Method for Equilibrium","Stability of Equilibrium","Review of Particle Dynamics: Rectilinear and Plane Curvilinear Motion","Relative and Constrained Motion","Newton''s 2nd Law Work-Kinetic Energy","Power","Potential Energy Impulse-Momentum and Impact"]},{"title":"Kinetics of Rigid Bodies","topics":["Introduction to Kinetics of Rigid Bodies Basic Terms and General Principles in Dynamics Types of Motion and Instantaneous Centre of Rotation in Plane Motion Simple Problems D''Alembert''s Principle and Its Applications in Plane Motion and Connected Bodies Work-Energy Principle and Its Application in Plane Motion of Connected Bodies Kinetics of Rigid Body Rotation","Engineering Mechanics statics and dynamics R. C. Hibbeler Pearson Publication, 12th Edition. ISBN-10:0-13-814929-1 ISBN-13:978-0-13-814929-1","Engineering Mechanics statics and dynamics, J. L. Meriam and L. G. Craige, John Willey and Son''s publication. 9th Edition. ISBN: 978-1-119-39098-5","Engineering Mechanics, S. P. Timoshenko, D. H. Young, J. V. Rao & S.Pati, McGraw-Hill publication, 5th Edition ISBN-10:9781259062667","Engineering Mechanics statics and dynamics, A. K. Dhiman, P. Dhiman & D. Kulshreshtha, McGraw-Hill publication ISBN-10:9789339219178"]}]'::jsonb from s;
