insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Basic Blocks of Communication System","topics":["Analog Modulation - Principles of Amplitude Modulation","DSBSC","SSB-SC and VSB-SC","AM Transmitters and Receivers"]},{"title":"Angle Modulation","topics":["Frequency and Phase Modulation","Transmission Bandwidth of FM Signals","Methods of Generation and Detection","FM Transmitters and Receivers"]},{"title":"Sampling Theorem and Pulse Modulation Sampling Theorem Pulse Modulation Techniques","topics":["Sampling Theorem","Pulse Modulation Techniques - PMM, PMM and PPM Concepts","PCM System","Data Transmission Using Analog Carriers (ASK, FSK, BPSK, QPSK)"]},{"title":"Error Control Coding Techniques","topics":["Linear Block Codes- Encoder and Decoder","Cyclic Codes - Encoder, Syndrome Calculator","Convolution Codes"]},{"title":"Modern Communication Systems","topics":["Microwave Communication Systems","Optical Communication System","Satellite Communication System","Mobile Communication System","Simon Haykins, ''Communication Systems'', John Wiley, 3rd Edition, 1995","D. Roddy & J. Coolen, ''Electronic Communications'', Prentice Hall of India, 4th Edition, 1999","Kennedy G, ''Electronic Communication System'', McGraw Hill, 1987","→ Understand the Basics of Communication Systems, Analog and Digital Modulation Techniques","→ Apply the Knowledge of Digital Electronics and Understand the Error Control Coding Techniques","→ Summarize Different Types of Communication Systems and Its Requirements"]}]'::jsonb from s;
