insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["This course involves completing approved online courses from platforms like MOOCs, SWAYAM, NPTEL, or other recognized online learning platforms. Students are required to select courses relevant to Electrical & Electronics Engineering and complete them as per the university guidelines.","→ To Provide Flexibility in Learning and Exposure to Diverse Topics in Electrical & Electronics Engineering","→ To Enhance Knowledge Through Online Courses from Reputed Institutions and Platforms","→ To Develop Self-Learning Skills and Discipline in Completing Online Courses","Course Selection: Students Must Choose Courses Approved by the Department/University","Duration: As per the Selected Course Requirements","Assessment: Based on the Certification and Evaluation from the Online Platform","Credits: 2 Credits Upon Successful Completion"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Power Switching Devices","topics":["Diode, Thyristor, MOSFET, IGBT: I-V Characteristics","Firing Circuit for Thyristor","Voltage and Current Commutation of a Thyristor","Gate Drive Circuits for MOSFET and IGBT"]},{"title":"Thyristor Rectifiers","topics":["Single-Phase Half-Wave and Full-Wave Rectifiers","Single-Phase Full-Bridge Thyristor Rectifier with R- Load and Highly Inductive Load","Three-Phase Full-Bridge Thyristor Rectifier with R-Load and Highly Inductive Load","Input Current Wave Shape and Power Factor"]},{"title":"DC-DC Buck Converter","topics":["Elementary Chopper with an Active Switch and Diode","Concepts of Duty Ratio and Average Voltage","Power Circuit of a Buck Converter","Analysis and Waveforms at Steady State","Duty Ratio Control of Output Voltage"]},{"title":"DC-DC Boost Converter","topics":["Power Circuit of a Boost Converter","Analysis and Waveforms at Steady State","Relation Between Duty Ratio and Average Output Voltage"]},{"title":"Single-Phase Voltage Source Inverter","topics":["Power Circuit of Single-Phase Voltage Source Inverter","Switch States and Instantaneous Output Voltage","Square Wave Operation of the Inverter","Concept of Average Voltage Over a Switching Cycle","Bipolar Sinusoidal Modulation and Unipolar Sinusoidal Modulation","Modulation Index and Output Voltage"]},{"title":"Three-Phase Voltage Source Inverter","topics":["Power Circuit of a Three-Phase Voltage Source Inverter","Switch States, Instantaneous Output Voltages","Average Output Voltages Over a Sub-Cycle","Three-Phase Sinusoidal Modulation"]},{"title":"A.C. to A.C. Converter","topics":["Classification, Principle of Operation of Step Up and Step Down Cyclo-converter","Single Phase to Single Phase Cyclo-converter with Resistive and Inductive Load","Three Phase to Single Phase Cyclo-converter","Half Wave and Full Wave, Cosine Wave Crossing Technique","Three Phase to Three Phase Cyclo-converter","Output Voltage Equation of Cyclo-converter","M. H. Rashid, \"Power Electronics: Circuits, Devices, and Applications\", Pearson Education India, 2009","N. Mohan and T. M. Undeland, \"Power Electronics: Converters, Applications and Design\", John Wiley & Sons, 2007","R. W. Erickson and D. Maksimovic, \"Fundamentals of Power Electronics\", Springer Science & Business Media, 2007","L. Umanand, \"Power Electronics: Essentials and Applications\", Wiley India, 2009","→ Understand the Differences Between Signal Level and Power Level Devices","→ Analyse Controlled Rectifier Circuits","→ Analyse the Operation of DC-DC Choppers","→ Analyse the Operation of Voltage Source Inverter"]}]'::jsonb from s;
