insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: Transmission Lines Introduction Concept Of Distributed Elements Equations Of Voltage And Current Standing Waves And Impedance Transformation Lossless And Low-loss Transmission Lines Power Transfer On A Transmission Line Analysis Of Transmission Line In Terms Of Admittances Transmission Line Calculations With The Help Of Smith Chart Applications Of Transmission Line Impedance Matching Using Transmission Lines","Introduction","Concept Of Distributed Elements","Equations Of Voltage And Current","Standing Waves And Impedance Transformation","Lossless And Low-loss Transmission Lines","Power Transfer On A Transmission Line","Analysis Of Transmission Line In Terms Of Admittances","Transmission Line Calculations With The Help Of Smith Chart","Applications Of Transmission Line","Impedance Matching Using Transmission Lines"]},{"title":"Maxwell''s Equations","topics":["Basic Quantities Of Electromagnetics","Basic Laws Of Electromagnetics: Gauss''s Law, Ampere''s Circuital Law, Faraday''s Law Of Electromagnetic Induction","Maxwell''s Equations","Surface Charge And Surface Current","Boundary Conditions At Media Interface"]},{"title":"Uniform Plane Wave","topics":["Homogeneous Unbound Medium","Wave Equation For Time Harmonic Fields","Solution Of The Wave Equation","Uniform Plane Wave","Wave Polarization","Wave Propagation In Conducting Medium","Phase Velocity Of A Wave","Power Flow And Poynting Vector"]},{"title":"Plane Waves at Media Interface","topics":["Plane Wave In Arbitrary Direction","Plane Wave At Dielectric Interface","Reflection And Refraction Of Waves At Dielectric Interface","Total Internal Reflection","Wave Polarization At Media Interface","Brewster Angle","Fields And Power Flow At Media Interface","Lossy Media Interface","Reflection From Conducting Boundary"]},{"title":"Waveguides","topics":["Parallel Plane Waveguide: Transverse Electric (TE) Mode, Transverse Magnetic (TM) Mode","Cutoff Frequency","Phase Velocity And Dispersion","Transverse Electromagnetic (TEM) Mode","Analysis Of Waveguide-general Approach","Rectangular Waveguides"]},{"title":"Antennas","topics":["Radiation Parameters Of Antenna","Potential Functions","Solution For Potential Functions","Radiations From Hertz Dipole","Near Field","Far Field","Total Power Radiated By A Dipole","Radiation Resistance And Radiation Pattern Of Hertz Dipole","Hertz Dipole In Receiving Mode","R. K. Shevgaonkar, \"Electromagnetic Waves\", Tata McGraw Hill, 2005.","D. K. Cheng, \"Field and Wave Electromagnetics\", Addison-Wesley, 1989.","M. N.O. Sadiku, \"Elements of Electromagnetics\", Oxford University Press, 2007.","C. A. Balanis, \"Advanced Engineering Electromagnetics\", John Wiley & Sons, 2012.","C. A. Balanis, \"Antenna Theory: Analysis and Design\", John Wiley & Sons, 2005.","At the end of this course, students will demonstrate the ability to:","→ Analyse transmission lines and estimate voltage and current at any point on the transmission line for different load conditions.","→ Provide solutions to real life plane wave problems for various boundary conditions.","→ Analyse the field equations for the wave propagation in special cases such as lossy and low loss dielectric media.","→ Visualize TE and TM mode patterns of field distributions in a rectangular wave-guide.","→ Understand and analyse radiation by antennas."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Breakdown in Gases","topics":["Ionization Processes And De-ionization Processes","Types Of Discharge","Gases As Insulating Materials","Breakdown In Uniform Gap, Non-uniform Gaps","Townsend''s Theory","Streamer Mechanism","Corona Discharge"]},{"title":"Breakdown in liquid and solid Insulating materials","topics":["Breakdown In Pure And Commercial Liquids","Solid Dielectrics And Composite Dielectrics","Intrinsic Breakdown","Electromechanical Breakdown And Thermal Breakdown","Partial Discharge","Applications Of Insulating Materials"]},{"title":"Generation of High Voltages","topics":["Generation Of High Voltages","Generation Of High D. C. And A.C. Voltages","Generation Of Impulse Voltages","Generation Of Impulse Currents","Tripping And Control Of Impulse Generators"]},{"title":"Measurements of High Voltages and Currents","topics":["Peak Voltage, Impulse Voltage And High Direct Current Measurement Method","Cathode Ray Oscillo Graphs For Impulse Voltage And Current Measurement","Measurement Of Dielectric Constant And Loss Factor","Partial Discharge Measurements"]},{"title":"Lightning and Switching Overvoltages","topics":["Charge Formation In Clouds","Stepped Leader","Dart Leader","Lightning Surges","Switching Overvoltages","Protection Against Over-voltages","Surge Diverters","Surge Modifiers","Module 6: High Voltage Testing of Electrical Apparatus and High Voltage Laboratories Various Standards For HV Testing Of Electrical Apparatus, IS, IEC Standards Testing Of Insulators And Bushings Testing Isolators And Circuit Breakers Testing Cables, Power Transformers And Some High Voltage Equipment High Voltage Laboratory Layout Indoor And Outdoor Laboratories Testing Facility Requirements Safety Precautions In H. V. Labs","Various Standards For HV Testing Of Electrical Apparatus, IS, IEC Standards","Testing Of Insulators And Bushings","Testing Isolators And Circuit Breakers","Testing Cables, Power Transformers And Some High Voltage Equipment","High Voltage Laboratory Layout","Indoor And Outdoor Laboratories","Testing Facility Requirements","Safety Precautions In H. V. Labs","M. S. Naidu and V. Kamaraju, \"High Voltage Engineering\", McGraw Hill Education, 2013.","C. L. Wadhwa, \"High Voltage Engineering\", New Age International Publishers, 2007.","D. V. Razevig (Translated by Dr. M. P. Chourasia), \"High Voltage Engineering Fundamentals\", Khanna Publishers, 1993.","E. Kuffel, W. S. Zaengl and J. Kuffel, \"High Voltage Engineering Fundamentals\", Newnes Publication, 2000.","R. Arora and W. Mosch \"High Voltage and Electrical Insulation Engineering\", John Wiley & Sons, 2011.","Various IS standards for HV Laboratory Techniques and Testing","At the end of the course, the student will demonstrate:","→ Understand the basic physics related to various breakdown processes in solid, liquid and gaseous insulating materials.","→ Knowledge of generation and measurement of D. C., A.C., & Impulse voltages.","→ Knowledge of tests on H. V. equipment and on insulating materials, as per the standards.","→ Knowledge of how over-voltages arise in a power system, and protection against these over-voltages."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Electrical System Components","topics":["LT Systems Wiring Components","Selection Of Cables, Wires, Switches, Distribution Box, Metering System","Tariff Structure","Protection Components- Fuse, MCB, MCCB, ELCB, Inverse Current Characteristics","Symbols","Single Line Diagram (SLD) Of A Wiring System","Contactor, Isolator, Relays, MPCB","Electric Shock And Electrical Safety Practices","Module 2: Residential and Commercial Electrical Systems Types Of Residential And Commercial Wiring Systems General Rules And Guidelines For Installation Load Calculation And Sizing Of Wire Rating Of Main Switch, Distribution Board And Protection Devices Earthing System Calculations Requirements Of Commercial Installation Deciding Lighting Scheme And Number Of Lamps Earthing Of Commercial Installation Selection And Sizing Of Components","Types Of Residential And Commercial Wiring Systems","General Rules And Guidelines For Installation","Load Calculation And Sizing Of Wire","Rating Of Main Switch, Distribution Board And Protection Devices","Earthing System Calculations","Requirements Of Commercial Installation","Deciding Lighting Scheme And Number Of Lamps","Earthing Of Commercial Installation","Selection And Sizing Of Components","Module 3: Illumination Systems Understanding Various Terms Regarding Light, Lumen, Intensity, Candle Power, Lamp Efficiency, Specific Consumption, Glare, Space To Height Ratio, Waste Light Factor, Depreciation Factor Various Illumination Schemes Incandescent Lamps And Modern Luminaries Like CFL, LED And Their Operation Energy Saving In Illumination Systems Design Of A Lighting Scheme For Residential And Commercial Premises Flood Lighting","Understanding Various Terms Regarding Light, Lumen, Intensity, Candle Power, Lamp Efficiency, Specific Consumption, Glare, Space To Height Ratio, Waste Light Factor, Depreciation Factor","Various Illumination Schemes","Incandescent Lamps And Modern Luminaries Like CFL, LED And Their Operation","Energy Saving In Illumination Systems","Design Of A Lighting Scheme For Residential And Commercial Premises","Flood Lighting"]},{"title":"Industrial Electrical Systems I","topics":["HT Connection","Industrial Substation","Transformer Selection","Industrial Loads, Motors, Starting Of Motors","SLD","Cable And Switchgear Selection","Lightning Protection","Earthing Design","Power Factor Correction - KVAR Calculations","Type Of Compensation","Introduction To PCC, MCC Panels","Specifications Of LT Breakers, MCB And Other LT Panel Components"]},{"title":"Industrial Electrical Systems II","topics":["DG Systems","UPS System","Electrical Systems For The Elevators","Battery Banks","Sizing The DG, UPS And Battery Banks","Selection Of UPS And Battery Banks"]},{"title":"Industrial Electrical System Automation","topics":["Study Of Basic PLC","Role Of In Automation","Advantages Of Process Automation","PLC Based Control System Design","Panel Metering And Introduction To SCADA System For Distribution Automation","S.L. Uppal and G.C. Garg, \"Electrical Wiring, Estimating & Costing\", Khanna publishers, 2008.","K. B. Raina, \"Electrical Design, Estimating & Costing\", New age International, 2007.","S. Singh and R. D. Singh, \"Electrical estimating and costing\", Dhanpat Rai and Co., 1997.","Web site for IS Standards.","H. Joshi, \"Residential Commercial and Industrial Systems\", McGraw Hill Education, 2008.","At the end of this course, students will demonstrate the ability to:","→ Understand the electrical wiring systems for residential, commercial and industrial consumers, representing the systems with standard symbols and drawings, SLD.","→ Understand various components of industrial electrical systems.","→ Analyze and select the proper size of various electrical system components."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Discrete Representation of Continuous Systems","topics":["Basics Of Digital Control Systems","Discrete Representation Of Continuous Systems","Sample And Hold Circuit","Mathematical Modelling Of Sample And Hold Circuit","Effects Of Sampling And Quantization","Choice Of Sampling Frequency","ZOH Equivalent"]},{"title":"Discrete System Analysis","topics":["Z-Transform And Inverse Z Transform For Analyzing Discrete Time Systems","Pulse Transfer Function","Pulse Transfer Function Of Closed Loop Systems","Mapping From S-plane To Z Plane","Solution Of Discrete Time Systems","Time Response Of Discrete Time System"]},{"title":"Stability of Discrete Time System","topics":["Stability Analysis By Jury Test","Stability Analysis Using Bilinear Transformation","Design Digital Control System With Dead Beat Response","Practical Issues With Deadbeat Response Design"]},{"title":"State Space Approach for discrete time systems","topics":["State Space Models Of Discrete Systems","State Space Analysis","Lyapunov Stability","Controllability, Reach-ability, Reconstructibility And Observability Analysis","Effect Of Pole Zero Cancellation On The Controllability & Observability"]},{"title":"Design of Digital Control System","topics":["Design Of Discrete PID Controller","Design Of Discrete State Feedback Controller","Design Of Set Point Tracker","Design Of Discrete Observer For LTI System","Design Of Discrete Compensator"]},{"title":"Discrete output feedback control","topics":["Design Of Discrete Output Feedback Control","Fast Output Sampling (FOS) And Periodic Output Feedback Controller Design For Discrete Time Systems","K. Ogata, \"Digital Control Engineering\", Prentice Hall, Englewood Cliffs, 1995.","M. Gopal, \"Digital Control Engineering\", Wiley Eastern, 1988.","G. F. Franklin, J. D. Powell and M. L. Workman, \"Digital Control of Dynamic Systems\", Addison-Wesley, 1998.","B.C. Kuo, \"Digital Control System\", Holt, Rinehart and Winston, 1980.","At the end of this course, students will demonstrate the ability to:","→ Obtain discrete representation of LTI systems.","→ Analyse stability of open loop and closed loop discrete-time systems.","→ Design and analyse digital controllers.","→ Design state feedback and output feedback controllers."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Conventional Vehicles: Basics Of Vehicle Performance, Vehicle Power Source Characterization, Transmission Characteristics, Mathematical Models To Describe Vehicle Performance","Introduction To Hybrid Electric Vehicles: History Of Hybrid And Electric Vehicles","Social And Environmental Importance Of Hybrid And Electric Vehicles","Impact Of Modern Drive-trains On Energy Supplies"]},{"title":"Hybrid Electric Drive-trains","topics":["Basic Concept Of Hybrid Traction","Introduction To Various Hybrid Drive-train Topologies","Power Flow Control In Hybrid Drive-train Topologies","Fuel Efficiency Analysis","Module 3: Electric Trains: Electric Drive-trains Basic Concept Of Electric Traction Introduction To Various Electric Drivetrain Topologies Power Flow Control In Electric Drive-train Topologies Fuel Efficiency Analysis Electric Propulsion Unit: Introduction To Electric Components Used In Hybrid And Electric Vehicles Configuration And Control Of DC Motor Drives Configuration And Control Of Induction Motor Drives Configuration And Control Of Permanent Magnet Motor Drives Configuration And Control Of Switched Reluctance Motor Drives Drive System Efficiency","Basic Concept Of Electric Traction","Introduction To Various Electric Drivetrain Topologies","Power Flow Control In Electric Drive-train Topologies","Fuel Efficiency Analysis","Electric Propulsion Unit: Introduction To Electric Components Used In Hybrid And Electric Vehicles","Configuration And Control Of DC Motor Drives","Configuration And Control Of Induction Motor Drives","Configuration And Control Of Permanent Magnet Motor Drives","Configuration And Control Of Switched Reluctance Motor Drives","Drive System Efficiency","Module 4: Energy Storage Introduction To Energy Storage Requirements In Hybrid And Electric Vehicles Battery Based Energy Storage And Its Analysis Fuel Cell Based Energy Storage And Its Analysis Super Capacitor Based Energy Storage And Its Analysis Flywheel Based Energy Storage And Its Analysis Hybridization Of Different Energy Storage Devices Sizing The Drive System: Matching The Electric Machine And The Internal Combustion Engine (ICE) Sizing The Propulsion Motor Sizing The Power Electronics Selecting The Energy Storage Technology Communications, Supporting Subsystems","Introduction To Energy Storage Requirements In Hybrid And Electric Vehicles","Battery Based Energy Storage And Its Analysis","Fuel Cell Based Energy Storage And Its Analysis","Super Capacitor Based Energy Storage And Its Analysis","Flywheel Based Energy Storage And Its Analysis","Hybridization Of Different Energy Storage Devices","Sizing The Drive System: Matching The Electric Machine And The Internal Combustion Engine (ICE)","Sizing The Propulsion Motor","Sizing The Power Electronics","Selecting The Energy Storage Technology","Communications, Supporting Subsystems"]},{"title":"Energy Management Strategies","topics":["Introduction To Energy Management Strategies Used In Hybrid And Electric Vehicles","Classification Of Different Energy Management Strategies","Comparison Of Different Energy Management Strategies","Implementation Issues Of Energy Management Strategies","Case Studies: Design Of A Hybrid Electric Vehicle (HEV), Design Of A Battery Electric Vehicle (BEV)","C. Mi, M. A. Masrur and D. W. Gao, \"Hybrid Electric Vehicles: Principles and Applications with Practical Perspectives\", John Wiley & Sons, 2011.","S. Onori, L. Serrao and G. Rizzoni, \"Hybrid Electric Vehicles: Energy Management Strategies\", Springer, 2015.","M. Ehsani, Y. Gao, S. E. Gay and A. Emadi, \"Modern Electric, Hybrid Electric, and Fuel Cell Vehicles: Fundamentals, Theory, and Design\", CRC Press, 2004.","T. Denton, \"Electric and Hybrid Vehicles\", Routledge, 2016.","At the end of this course, students will demonstrate the ability to:","→ Understand the models to describe hybrid vehicles and their performance.","→ Understand the different possible ways of energy storage.","→ Understand the different strategies related to energy storage systems."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Module 1: (Lectures 8 hrs.) Biomedical signals and Physiological transducers: Source of biomedical signal Origin of bioelectric signals Recording electrodes Electrodes for ECG EMG and EEG Physiological transducers: Pressure Temperature Photoelectric and ultrasound Transducers Measurement in Respiratory system: Physiology of respiratory system Measurement of breathing mechanics Spiro meter Respiratory therapy equipments Inhalators ventilators and Respirators Humidifiers Nebulizers Aspirators Biomedical recorders: ECG EEG and EMG","Biomedical signals and Physiological transducers: Source of biomedical signal","Origin of bioelectric signals","Recording electrodes","Electrodes for ECG","EMG and EEG Physiological transducers: Pressure","Temperature","Photoelectric and ultrasound Transducers","Measurement in Respiratory system: Physiology of respiratory system","Measurement of breathing mechanics Spiro meter","Respiratory therapy equipments Inhalators ventilators and Respirators","Humidifiers","Nebulizers Aspirators","Biomedical recorders: ECG","EEG and EMG"]},{"title":"(Lectures 8 hrs.)","topics":["Patient Monitoring systems and Audiometers: Cardiac monitor","Bed-side patient monitor","Measurement of heart rate","Blood pressure","Temperature","Respiration rate","Arrhythmia monitor","Methods of monitoring fatal heart rate","Monitoring labor activity","Audiometers: Audiometers","Blood cell counters","Oximeter","Blood flow meter","Cardiac output measurement","Blood gas analyzers"]},{"title":"(Lectures 8 hrs.)","topics":["Modern Imaging systems: Introduction","Basic principle and Block diagram of x-ray machine","X-ray Computed Tomography (CT)","Magnetic resonance imaging system (NMR)","Ultrasonic imaging system","Eco-Cardiograph","Eco Encephalography","Ophthalmic scans","MRI","Therapeutic Equipments: Cardiac pacemakers","Cardiac defibrillators","Hemodialysis machine","Surgical diathermy machine"]},{"title":"(Lectures 8 hrs.)","topics":["Patient''s safety: Precautions","Safety codes for electro medical equipment","Electric safety analyzer","Testing of biomedical equipment","Ultrasound therapy unit","Electrotherapy Equipments","Ventilators","\"Hand book of Biomedical Instrumentation\", R.S.Khandpur, TMH","\"Biomedical Instruments: Theory and Design\", Walter Welko- Witiz and Sid Doutsch, Wiley","\"Biomedical Instrumentation and Measurements\", Leslie Cromwell, Fred J. Weibell and Erich A. Pfeiffer, PHI","\"Introduction to Biomedical Equipment Technology\", Joseph J. Carr and John M. Brown, Pearson","\"Textbook of Biomedical Instrumentation System\", Shakti Chatterjee, Cengage Learning"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Course Code: 110814 | Credits: 3L: 0T: 0P - 3 Credits"]},{"title":"Introduction to Satellite Communication (Lectures 6 hrs.)","topics":["Principles and architecture of satellite Communication","Brief history of Satellite systems","Advantages","Disadvantages","Applications and frequency bands used for satellite communication"]},{"title":"Orbital Mechanics (Lectures 6 hrs.)","topics":["Orbital equations","Kepler''s laws","Apogee and Perigee for an elliptical orbit","Evaluation of velocity","Orbital period","Angular velocity etc. of a satellite","Concepts of Solar day and Sidereal day"]},{"title":"Satellite sub-systems (Lectures 6 hrs.)","topics":["Study of Architecture and Roles of various sub systems of a satellite system such as Telemetry","Tracking","Command and monitoring (TTC and M)","Attitude and orbit control system (AOCS)","Communication sub-system"]},{"title":"Typical Phenomena in Satellite Communication (Lectures 6 hrs.)","topics":["Solar Eclipse on satellite","Its effects","Remedies for Eclipse","Sun Transit Outage phenomena","Its effects and remedies","Doppler frequency shift Phenomena and expression for Doppler shift"]},{"title":"System Analysis (Lectures 6 hrs.)","topics":["Flux density and received signal power equations","Calculation of System noise temperature for satellite receiver","Noise power calculation","C/N ratio calculations in clear air and rainy conditions","Timothy Pratt, Charles W. Bostian, Jeremy E. Allnutt: \"Satellite Communications\", Wiley","Tri T. Ha: \"Digital Satellite Communications\", Tata McGraw Hill","Dennis Roddy: \"Satellite Communication\", 4th Edition, McGraw Hill"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Atomic and Molecular Structure Electromagnetic radiations Dual nature of electron and Heisenberg uncertainty Principle Photoelectric effect Planck''s theory Principles for the combination of atomic orbitals to form a molecular diagram of molecular orbitals Bent''s rule VSEPR theory (typical example) Coordination numbers and geometries Isomerism in transition metal compounds Metal Carbonyls: Synthesis and Structure","Electromagnetic radiations","Dual nature of electron and Heisenberg uncertainty Principle","Photoelectric effect","Planck''s theory","Principles for the combination of atomic orbitals to form a molecular diagram of molecular orbitals","Bent''s rule","VSEPR theory (typical example)","Coordination numbers and geometries","Isomerism in transition metal compounds","Metal Carbonyls: Synthesis and Structure"]},{"title":"Spectroscopy","topics":["Principle of rotational and vibrational spectroscopy","Selection rule for application in diatomic molecules","Elementary idea of electronic spectroscopy","UV-VIS spectroscopy with related to rules and its applications","Basic Principle of nuclear Magnetic resonance spectroscopy with applications"]},{"title":"Electrochemistry and Fuels","topics":["Nernst equation","EMF and electrochemical cell","Introduction of corrosion","Corrosion mechanism","Types of corrosion","Water line corrosion","Stress corrosion","Pitting corrosion","Lead acid storage cell","Leclanche cell","Calorific value of fuels","Proximate and ultimate analysis of coals","Fuel cells","Bio fuels"]},{"title":"Water Chemistry","topics":["Hardness of water","Estimation of water hardness by EDTA and Alkalinity method","Removal of the hardness of water: soda lime process, zeolite process, Ion exchange process","Boiler problem","Sludge and scale formation","Priming and foaming","Boiler corrosion","Caustic embrittlement","Unit 5.0: Polymer and Plastic