insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Occupational Health & Hygiene at Workplace Common occupational & Job-related diseases such as silicosis, asbestosis Occupational hygiene parameters Methods of prevention of occupational diseases Compensation of occupational diseases Occupational dermatitis Medical examination of workers, occupational health center, health records Difference between industrial hygiene and occupational health Hygiene Health hazards, control and preventions","Common occupational & Job-related diseases such as silicosis, asbestosis","Occupational hygiene parameters","Methods of prevention of occupational diseases","Compensation of occupational diseases","Occupational dermatitis","Medical examination of workers, occupational health center, health records","Difference between industrial hygiene and occupational health","Hygiene Health hazards, control and preventions"]},{"title":"Health Safety and Occupation","topics":["Scope of occupational health and safety (OHS)","Physical, mental and social well-being of workers in all occupations","Unhealthy or unsafe working conditions in industries/factories health associated risk factors"]},{"title":"Occupational Hygiene","topics":["Prevention and control methods","Types of PPE"]},{"title":"Safety Hazards Prevention & Control","topics":["Safety committee roles and functions","Emergency action plan","Level of prevention of hazards"]},{"title":"Workplace Housekeeping and Maintenance","topics":["Hose keeping principles and procedures","Physiology and comfort level","Ventilation systems"]},{"title":"Safety, Health and Welfare Act & Regulations","topics":["General Safety Provision","Community Health maintenance act","Fire safety regulation","Normal safety and health maintenance at construction site","Occupational Health and Hygiene in Industry, SK. Haldar CBS Publishers & Distributors, ISBN: 9789354664922.","Textbook of Occupational Healt