insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["(Which includes dimensioning methods, different types of line, construction of different polygon, divide the line and angle in parts, use of stencil)","Construction of Plane, Diagonal & Vernier Scales.","Construction of Ellipses, Parabolas, and Hyperbolas using the general method.","Construction of cycloid, epicycloid, hypocycloid, and involute of a circle.","Projection of Points and Lines inclined to both planes.","Projections of Planes (e.g., rectangular, triangular) in inclined positions.","Projection of Solids (prisms, pyramids, cones, and cylinders)","Drawing of Sections of Prisms, Cylinders, Pyramids, and Cones.","Development of Surfaces for prisms, pyramids, cylinders, and cones.","Construction of Isometric views of lines, planes, and simple solids.","Introduction to CAD Software.","Use of CAD software to draw basic geometric shapes, apply dimensions, and modify objects."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Frame of Reference Non-Inertial frame of reference Rotating coordinate system","topics":["Frame of Reference","Non-Inertial frame of reference","Rotating coordinate system","Centripetal and Coriolis acceleration and its application in weather system","Oscillations","Harmonic Oscillator","Damped Harmonic motion - overdamped","Critically Damped and lightly damped oscillators","Force Oscillators and Resonance","Unit 2.0 Optics Huygens''s Principle Superposition of Waves and interference of Light by wave front- splitting and amplitude-splitting Young''s double slit experiment Michelson interferometer Fraunhofer diffraction from single slit and circular aperture Diffraction Grating and their resolving power LASER Einstein''s theory of matter-radiations interaction Einstein''s Coefficients (A and B) Amplification by population inversion Different types of lasers - Gas Laser Helium-Neon Laser Solid State Laser (Ruby Neodymium) Semiconductor Laser","Optics","Huygens''s Principle","Superposition of Waves and interference of Light by wave front- splitting and amplitude-splitting","Young''s double slit experiment","Michelson interferometer","Fraunhofer diffraction from single slit and circular aperture","Diffraction Grating and their resolving power","LASER","Einstein''s theory of matter-radiations interaction","Einstein''s Coefficients (A and B)","Amplification by population inversion","Different types of lasers - Gas Laser","Helium-Neon Laser","Solid State Laser (Ruby","Neodymium)","Semiconductor Laser","Unit 3.0 Quantum Mechanics Compton Effect Photoelectric Effect Wave Particle duality De Broglie''s hypothesis Heisenberg''s Uncertainty Principle Wave function and wave packets Phase and group velocities Schrodinger''s Wave Equation Normalization Expectation values Eigenvalues and Eigenfunction Applications in One dimensions Application of Schrodinger Wave Equation for particle in one dimensional box its wavefunction and eigenvalue of energy and momentum","Quantum Mechanics","Compton Effect","Photoelectric Effect","Wave Particle duality","De Broglie''s hypothesis","Heisenberg''s Uncertainty Principle","Wave function and wave packets","Phase and group velocities","Schrodinger''s Wave Equation","Normalization","Expectation values","Eigenvalues and Eigenfunction","Applications in One dimensions","Application of Schrodinger Wave Equation for particle in one dimensional box its wavefunction and eigenvalue of energy and momentum","Unit 4.0 Vector Calculus Gradient Divergence and Curl Line Surface and Volume integrals Gauss''s Divergence theorem and Stokes'' theorem in Cartesian Coordinate Electrostatics Gauss''s Law and its applications Divergence and Curl of Electrostatic fields Electrostatic Potential Boundary Conditions Poisson''s and Laplace''s equations Dielectrics Polarization Bound Charges Electric displacement Boundary Conditions in dielectrics","Vector Calculus","Gradient","Divergence and Curl","Line","Surface and Volume integrals","Gauss''s Divergence theorem and Stokes'' theorem in Cartesian Coordinate","Electrostatics","Gauss''s Law and its applications","Divergence and Curl of Electrostatic fields","Electrostatic Potential","Boundary Conditions","Poisson''s and Laplace''s equations","Dielectrics","Polarization","Bound Charges","Electric displacement","Boundary Conditions in dielectrics","Unit 5.0 Magnetostatics Lorentz force Biot-Savart and Ampere''s circuital laws and their applications Divergence and Curl of Magneto static fields Magnetic vector potential Force and torque on a magnetic dipole Magnetic Materials Magnetization Bound currents Boundary conditions Electrodynamics and Electromagnetic Waves Ohm''s law Motional EMF Faraday''s Law Lenz''s law Self and mutual inductance Energy stored in magnetic field Maxwell''s equations in vacuum and nonconducting medium Continuity Equation Poynting Theorem Wave Equations: plain electromagnetic wave in vacuum and their transverse nature and Polarization","Magnetostatics","Lorentz force","Biot-Savart and Ampere''s circuital laws and their applications","Divergence and Curl of Magneto static fields","Magnetic vector potential","Force and torque on a magnetic dipole","Magnetic Materials","Magnetization","Bound currents","Boundary conditions","Electrodynamics and Electromagnetic Waves","Ohm''s law","Motional EMF","Faraday''s Law","Lenz''s law","Self and mutual inductance","Energy stored in magnetic field","Maxwell''s equations in vacuum and nonconducting medium","Continuity Equation","Poynting Theorem","Wave Equations: plain electromagnetic wave in vacuum and their transverse nature and Polarization"]},{"title":"Introduction to Solids and Semi-Conductors Free electron theory of metal","topics":["Introduction to Solids and Semi-Conductors","Free electron theory of metal","Fermi level","Bloch''s theorem for particle in a periodic Potential","Kroning-Penney model and origin of energy band","Electronic Materials","Metals","Semiconductors and insulators","Intrinsic and extrinsic semiconductors","Carrier transport","Diffusion and drift","P-N junction","Quantum Physics of Atoms, Molecules, Solids, Nuclei and Particles, R. Eisberg R. Resnick, Wiley India Pvt. Ltd ISBN 978-81-265-0818-1","Theory of Vibration with Application, W.T. Thomson M. D. Dahleh, Pearson India ISBN 978-81-317-0482-0","Introduction to Electrodynamics, D.J. Griffiths, Pearson India, ISBN 978-93-325- 5044-5","Electromagnetism, I.S. Grant, W. R. Phillips, Wiley India Pvt. Ltd ISBN 978-04-719- 2712-9","The Feynman Lectures on Physics, R.P. Feynman R. B. Leighton, Pearson India ISBN 978-00-710-7458-2","Optics, Ajay Ghatak, McGraw Hill ISBN 978-93-901-1359-0","Physics of Vibration and Waves, H. J. Pain, Wiley India Pvt. Ltd, ISBN 978-04-700- 1296-3","Concept of Modern Physics, Arthur Beiser, McGraw Hill ISBN 978-93-513-4185-7","Introduction to Solid State Physics, C. Kittle, Wiley India Pvt. Ltd, ISBN 978-81- 265-7843-6"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Complex Analysis - I","topics":["Functions of complex variable","Limit","Continuity","Differentiability","Analytic function","Cauchy-Riemann Equations in Cartesian and polar form","Harmonic function and harmonic conjugate"]},{"title":"Complex Analysis - II","topics":["Line Integral","Contour integrals","Cauchy theorem","Cauchy''s Integral formula(without proof)","Taylors series","Zero of analytic functions","Singularities","Laurent''s series","Residue","Cauchy residue theorem(without Proof) and its applications"]},{"title":"Ordinary Differential Equations","topics":["Linear differential equations of nth Order with constant coefficients","Solution of Homogeneous and Non-Homogeneous Equations","Equations with variable coefficients","Cauchy- Euler Equations","Method of Variation of Parameters"]},{"title":"Sequence and Series","topics":["Introduction of Sequence and Series","Nature of series Tests of convergence of Series: Comparison test","D''Alembert ratio test","Cauchy''s Root test","Raabe''s test","Logarithmic test","Cauchy''s condensation test"]},{"title":"Laplace Transform Laplace Transform Existence theorem Properties of Laplace Transform","topics":["Laplace Transform","Existence theorem","Properties of Laplace Transform","Laplace Transform of Periodic functions","Inverse Laplace Transform","Convolution theorem","Application of Laplace Transform to solve Ordinary differential equations"]},{"title":"Fourier Series Fourier Series Fourier Series for odd and even","topics":["Fourier Series","Fourier Series for odd and even functions","Half range sine and cosine series","Parseval''s theorem","Advanced Engineering Mathematics, Kreyszig Erwin, John Wiley and Sons, 10th Edition, 2020 ISBN:978-0470-45836-5","Advanced Engineering Mathematics, Dass H.K., S Chand and Company pvt.Ltd., 22nd Edition, 2018 ISBN:978-93-5283-718-2","Higher Engineering Mathematics, Grewal B.S., Khanna Publishers, 44th Edition, 2023 ISBN:9788174091154","Complex Variables (Theory and Applications), Kasana H.S., PHI, 2nd Edition.2015 ISBN:978-81-203-2641-5","A Text Book of Engineering Mathematics, Bali N.P., Goyal Manish Laxmi Publications, 9th Edition, 2014","Higher Engineering Mathematics, Ramana B.V., Tata McGraw Hill New Delhi, 11th Reprint, 2010, ISBN-10 007063419X ISBN-13 978-0070634190","Differential Equations, Ross S.L., Wiley Publications, 3rd edition, 2016 ISBN:978-81- 265-1537-0","Advanced Differential Equations, Raisinghania M.D., S.Chand and Company PVT.LTD., 18th Edition, 2015 ISBN:978-81-219-0893-1","Schaum''s Outlines Complex Variables, Spiegel Murray R, Lipschutz Seymour, Schiller J John and Spellman Dennis, MC Graw Hill Education Private Ltd.2nd Edition, 2010 ISBN:978-0-07-008538-1"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction to Programming Introduction to components of a computer system (disks Memory Processor Where a program is stored and executed Operating system Compilers etc.) Idea of Algorithm: steps to solve logical and numerical problems Representation of Algorithm: Flowchart/ Pseudo code with examples From algorithms to programs Source code Variables (with data types) variables and memory locations Syntax and Logical Errors in compilation Object and executable code","Introduction to components of a computer system (disks","Memory","Processor","Where a program is stored and executed","Operating system","Compilers etc.)","Idea of Algorithm: steps to solve logical and numerical problems","Representation of Algorithm: Flowchart/ Pseudo code with examples","From algorithms to programs","Source code","Variables (with data types) variables and memory locations","Syntax and Logical Errors in compilation","Object and executable code"]},{"title":"Operators, Conditional Branching and Loops","topics":["Arithmetic expressions/arithmetic operators","Relational operators","Logical operators","Bitwise operators and precedence","Writing and evaluation of conditionals and consequent branching","Iteration and loops"]},{"title":"Arrays and String","topics":["Array declaration & initialization","Bound checking arrays (1-d","2-d)","Character arrays and strings","Unit 4.0: Function, Recursion and Pointers Functions (including using built in libraries) Parameter passing in functions Call by value Passing arrays to functions Recursion As a different way of solving problems Example programs Such as Finding Factorial Fibonacci series Ackerman function etc. Idea of pointers Defining pointers Use of Pointers in self- referential structures Idea of call by reference","Functions (including using built in libraries)","Parameter passing in functions","Call by value","Passing arrays to functions","Recursion","As a different way of solving problems","Example programs","Such as Finding Factorial","Fibonacci series","Ackerman function etc.","Idea of pointers","Defining pointers","Use of Pointers in self- referential structures","Idea of call by reference","Unit 5.0: User defined Data Types and File handling Structure- defining Declaring Initializing Accessing structure members Processing of structure Array of structures Structures within structure Structure and function Type definition Union- definition Declaration Accessing union members Initializing union Introduction File declaration Opening and closing a file Working with text and binary files I/O operations on file Error handling Random access to files","Structure- defining","Declaring","Initializing","Accessing structure members","Processing of structure","Array of structures","Structures within structure","Structure and function","Type definition","Union- definition","Declaration","Accessing union members","Initializing union","Introduction","File declaration","Opening and closing a file","Working with text and binary files","I/O operations on file","Error handling","Random access to files"]},{"title":"Basic Algorithms","topics":["Searching","Basic Sorting Algorithms (Bubble","Insertion and Selection)","Finding roots of equations","Notion of order of complexity through example programs (no formal definition required)","Programming in ANSI C 4th Ed,E Balagurusamy, McGraw Hill Education India Private Limited, ISBN-978-9339219666, 7th Edition","The C Programming Language 2e, W. Kernighan / Dennis Ritchie, Pearson Education India, 978-9332549449, 2nd Edition","Computer Fundamentals and Programming in C,ReemaThareja, Oxford University Press, ISBN-978-9354977893, 3rd Edition"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Sheet Metal Working","topics":["Sheet material: GI sheets","Aluminium","Tin plate","Copper","Brass etc","Tools: steel rule","Vernier callipers","Micrometer","Sheet metal gauge","Scriber","Divider","Punches","Chisels","Hammers","Snips","Pliers","Stakes etc","Operations: scribing","Bending","Shearing","Punching etc","Product development: hexagonal box with cap","Funnel etc"]},{"title":"Joining","topics":["Classifications of joining processes","Brazing","Soldering","Mechanical Joints","Arc welding","Gas welding etc","Unit 3.0: Pattern Making and Foundry Practice Pattern material: wood Cast iron Brass Aluminium Waxes etc Types of patterns: split Single piece Match plate etc Tools: cope Drag Core Core prints Shovel Riddle Rammer Trowel Slick Lifter Sprue pin Bellow Mallet Vent rod Furnace etc Moulding sands: green sand Dry sand Loam sand Facing sand etc Sand casting: Sand preparation Mould making Melting Pouring Cleaning","Pattern material: wood","Cast iron","Brass","Aluminium","Waxes etc","Types of patterns: split","Single piece","Match plate etc","Tools: cope","Drag","Core","Core prints","Shovel","Riddle","Rammer","Trowel","Slick","Lifter","Sprue pin","Bellow","Mallet","Vent rod","Furnace etc","Moulding sands: green sand","Dry sand","Loam sand","Facing sand etc","Sand casting: Sand preparation","Mould making","Melting","Pouring","Cleaning"]},{"title":"Fitting Shop","topics":["Introduction to Fitting","Fitting Tools: Files and their classification","Holding Tools","Cutting Tools","Measuring and Marking Tools","Thread Making Tools","Various Fitting Power Tools","Methods Of Filing: Cross Filling and Draw Filing","Other associated operations Marking","Sawing and Chipping","Safety and Precautions in Fitting Shop","Unit 5.0: Carpentry Shop Introduction to Carpentry Shop Types of Wood Seasoning of Wood: Types of Seasoning Methods Defects in wood Structure of Wood Carpentry Tools Measuring