insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to solid, liquid and gaseous fuels Stoichiometry Exhaust gas","topics":["Introduction to solid, liquid and gaseous fuels","Stoichiometry","Exhaust gas analysis","First law analysis of combustion reactions","Heat calculations using enthalpy tables","Adiabatic flame temperature","Chemical equilibrium and equilibrium composition calculations using free energy"]},{"title":"Thermodynamic cycles: Air standard Otto, Diesel and Dual Cycles Air","topics":["Thermodynamic cycles: Air standard Otto, Diesel and Dual Cycles","Air standard Brayton cycle","Effect of reheat, regeneration and intercooling","Combined gas and vapor power cycles","Vapor power cycles Rankine cycle with superheat, reheat and regeneration","Exergy analysis","Supercritical and ultra-super-critical Rankine cycle","Gas power cycles"]},{"title":"Refrigeration System: Simple Vapor compression refrigeration cycle and Vapor Absorption","topics":["Refrigeration System: Simple Vapor compression refrigeration cycle and Vapor Absorption Cycle","Refrigerants and their properties"]},{"title":"Reciprocating compressors Staging of reciprocating compressors Optimal stage pressure ratio","topics":["Reciprocating compressors","Staging of reciprocating compressors","Optimal stage pressure ratio","Effect of intercooling","Minimum work for multistage reciprocating compressors"]},{"title":"Analysis of steam turbines Velocity and pressure compounding of steam","topics":["Analysis of steam turbines","Velocity and pressure compounding of steam turbines"]},{"title":"Basics of compressible flow Stagnation properties Isentropic flow of a","topics":["Basics of compressible flow","Stagnation properties","Isentropic flow of a perfect gas through a nozzle","Choked flow","Subsonic and supersonic flows","Normal shocks","Use of ideal gas tables for isentropic flow and normal shock flow","Flow of steam and refrigerant through nozzle","Super 