insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Properties of Fluid","topics":["Definition of fluid","Newton''s law of viscosity","Units and dimensions","Physical properties of fluids","Control volume","Continuity equation and momentum equation","Incompressible flow","Bernoulli''s equation and its applications"]},{"title":"Dimensional Analysis","topics":["Dimensionally homogeneous equations","Buckingham Pi Theorem","Calculation of dimensionless parameters","Similitude and complete similarity","Model scales","Basic boundary layer theory and analysis"]},{"title":"Fluid Kinematics","topics":["Different approaches","Reynolds transport theorem","Flow visualization","Types of flow","Strain rate, stream line, streak line, path lines and stream tubes","Continuity equation in Cartesian coordinates in 3D forms","Velocity and acceleration of fluid particles","Velocity potential function and stream function"]},{"title":"Momentum Equation","topics":["Momentum equation","Nervier Stoke equation","Development of Euler''s equation","Bernoulli''s equation and application","Steady and unsteady flow through orifice","Orifice placed in pipe","Venturimeter","Flow over triangular and rectangular notches","Pitot tube"]},{"title":"Laminar and Turbulent Flow","topics":["Viscous/Laminar flow","Plane Poiseuille flow and Coutte flow","Laminar flow through circular pipes","Loss of head and power absorbed in viscous flow","Turbulent flow - Reynolds experiment","Frictional losses in pipe flow","Shear stress in turbulent flow","Major and minor losses (Darcy''s and Chezy''s equation)","Flow through siphon pipes","Branching pipes and equivalent pipe","Unit 6.0: Rotodynamic Machines & Hydraulic Turbines Euler''s equation Theory of Rotodynamic machines Various efficiencies Velocity components at entry and exit of the rotor Velocity triangles Centrifugal pumps - working principle, work done by the impeller and performance curves Cavitation in pumps Reciprocating pump working principle Classification of water turbines Heads and efficiencies Velocity triangles Axial, radial and mixed flow turbines Pelton wheel, Francis turbine and Kaplan turbines - working and design principles","Euler''s equation","Theory of Rotodynamic machines","Various efficiencies","Velocity components at entry and exit of the rotor","Velocity triangles","Centrifugal pumps - working principle, work done by the impeller and performance curves","Cavitation in pumps","Reciprocating pump working principle","Classification of water turbines","Heads and efficiencies","Velocity triangles","Axial, radial and mixed flow turbines","Pelton wheel, Francis turbine and Kaplan turbines - working and design principles","S.S. Rattan, Fluid Mechanics & Hydraulic Machines, Khanna Book Publishing, 2019.","P.J. Pritchard, A.T. McDonald and R.W. Fox, \"Introduction to Fluid Mechanics,\" Wiley India, 2012.","F.M. White, \"Fluid Mechanics,\" Tata McGraw Hill, 2011.","S. K. Som, G. Biswas and S. Chakraborty, \"Introduction to Fluid Mechanics and Fluid Machines,\" Tata McGraw Hill, 2017.","R. K. Bansal, \"A Textbook of Fluid Mechanics and Hydraulic Machines,\" Laxmi Publication, 2005.","Mechanics of Fluids, Shames, McGraw Hill Book Co., New Delhi, 1988."]}]'::jsonb from s;
