insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Mechanisms Definition and types of joints Lower and higher pairs Classification of mechanisms based on function and constraints Common mechanisms such as slider crank and 4-bar mechanisms and their inversions Quick return mechanism Straight line generators Rocker mechanisms Universal joints Steering mechanisms, etc. Basic Kinematic Concepts and Definitions Degree of freedom and Grübler''s formula Grashof''s rule and rotatability limits Mechanical advantage","Definition and types of joints","Lower and higher pairs","Classification of mechanisms based on function and constraints","Common mechanisms such as slider crank and 4-bar mechanisms and their inversions","Quick return mechanism","Straight line generators","Rocker mechanisms","Universal joints","Steering mechanisms, etc.","Basic Kinematic Concepts and Definitions","Degree of freedom and Grübler''s formula","Grashof''s rule and rotatability limits","Mechanical advantage"]},{"title":"Geometric Design of Mechanisms","topics":["Kinematic Analysis of Simple Mechanisms Displacement","Velocity, and acceleration analysis","Velocity analysis using instantaneous centers","Position, velocity and acceleration analysis using loop closure equations","Coincident points","Coriolis component of acceleration","Unit 3.0: Belt, Rope and Chain drives & Brakes Types of belt drives Velocity ratio, Slip, Creep, Length of belt Power transmitted Ratio of tensions Angle of contact Centrifugal tension, Maximum tension, Initial tension V belt drive, Ratio of Tensions in V belt and Rope drives Kinematics of chain drive Classifications of chains, Chain length Types of brakes, Block brake, Band brake, Band and Block brake Internal expanding brake Condition of self-locking Power transmitted and Heat generated","Types of belt drives","Velocity ratio, Slip, Creep, Length of belt","Power transmitted","Ratio of tensions","Angle of contact","Centrifugal tension, Maximum tension, Initial tension","V belt drive, Ratio of Tensions in V belt and Rope drives","Kinematics of chain drive","Classifications of chains, Chain length","Types of brakes, Block brake, Band brake, Band and Block brake","Internal expanding brake","Condition of self-locking","Power transmitted and Heat generated"]},{"title":"Gears & Gear Train","topics":["Gear terminology","Involute and Cycloidal gear profiles","Gear parameters","Fundamental law of gearing and conjugate action","Spur gear contact ratio and interference/undercutting","Analysis of simple, compound, reverted and epicyclic gear train with problems"]},{"title":"Balancing of rotating masses","topics":["Balancing of rotating masses in the same plane by a single revolving mass","Balancing of several rotating masses in the same plane","Balancing of several rotating masses in different planes by two revolving masses in suitable planes"]},{"title":"Governors","topics":["Watt, Porter, Proel & Hartnell Governors","Effect of friction","Controlling force","Governor effort and power","Sensitivity and isochronisms","Thomas Bevan, \"Theory of Machines,\" CBS Publishers & Distributors, 2005.","W. L. Cleghorn, \"Mechanisms of Machines,\" Oxford University Press, 2005.","R. L. Norton, \"Kinematics and Dynamics of Machinery,\" Tata McGraw Hill, 2009.","A. Ghosh and A.K. Mallick, \"Theory of Mechanisms and Machines,\" Affiliated East-West Pvt. Ltd, New Delhi, 1988."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Basics of project Management: concept Project Environment Types of Projects","topics":["Basics of project Management: concept","Project Environment","Types of Projects","Project life Cycle","Project proposals","Monitoring project program"]},{"title":"Project appraisal and project selection Identification of investment opportunities Source","topics":["Project appraisal and project selection","Identification of investment opportunities","Source of new project ideas","Preliminary screening of projects","Feasibility studies and reports"]},{"title":"Market feasibility: Market survey Categories of Market survey Steps involved","topics":["Market feasibility: Market survey","Categories of Market survey","Steps involved in conducting market survey","Demand forecasting techniques","Sales projections"]},{"title":"Technical feasibility: Production technology Materials and inputs Plant capacity Site","topics":["Technical feasibility: Production technology","Materials and inputs","Plant capacity","Site selection","Plant layout","Site preparation","Managerial Feasibility","Project organization and responsibilities","Development of program evaluation & Review Technique (PERT)","Benefits of PERT"]},{"title":"Capital Investment Financial Analysis: capital Expenditure criteria and Investment strategies","topics":["Capital Investment Financial Analysis: capital Expenditure criteria and Investment strategies","Appraisal Techniques (Non DCF and DCF)","Risk analysis","Cost of project and means of financing","Estimation of cash flows","Estimation of Capital costs and operating costs","Forecasting income","Preparation of detailed financial projections","Breakeven point"]},{"title":"Project Management: Project implementation and review Project planning Project control","topics":["Project Management: Project implementation and review","Project planning","Project control","Human aspects of project management","Prerequisites for successful project implementation","Project review","Gido: Effective Project Management, 2e, Thomson, 2007.","Prasanna odelin, \"Projects, Planning, Analysis, Selection, Financing, Implementation and Review\", TataMcGraw Hill Company Pvt. Ltd, New Delhi 1998.","Damodaran, \"Corporate Finance\", Johy Wiley Publications.","Erhardt & Brigham, \"Principles of Corporate Finance\", Thomson 2006.","Singh M.K, \"Project Evaluation and Management\".","Prasad 1.1.K, \"Principles and Practice of Cost accounting\", B. Pahwa, IIPS, Project Financing.","Clifford F. Gray, Erik V. Larson, \"Project Management, the Managerial Emphasis\", McGraw Hill 2000."]}]'::jsonb from s;
