insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["→ To familiarize with the terminology associated with refrigeration systems and air conditioning.","→ To understand basic refrigeration processes.","→ To understand the basics of psychometric and practice of applied psychometrics.","→ To acquire the skills required to model, analyze and design different refrigeration as well as air conditioning processes and components."]},{"title":"Air refrigeration system","topics":["Refrigeration Machine","Heat Pump","Coefficient Of Performance","Ideal Refrigeration Cycle","Bell Coleman, Refrigeration Cycle","Open And Closed Systems","Application Of Air Refrigeration In Air-crafts"]},{"title":"Various compression systems","topics":["Simple Vapour Compression Refrigeration Cycle","Merits And Refrigerants Demerits Of This System Over Air Refrigeration System","Factors Affecting The Performance Of A Vapour Compression Refrigeration System","Subcooling And Superheating Of Vapour","Wet And Dry Compression","Multistage Vapour Compression System","Intercooler","Flash Chamber","Accumulator And Heat Exchanger"]},{"title":"Vapour absorption system","topics":["Simple And Modified Vapour Absorption Refrigeration System","Electrolux Refrigerator","Cop Of Heat Operated Refrigeration System"]},{"title":"Special refrigeration system","topics":["Absorption","Cascade","Vortex","Thermoelectric And Steam Jet Refrigeration System"]},{"title":"Refrigerants","topics":["Classification And Nomenclature Of Refrigerants","Primary And Secondary Refrigerants","Properties Of Some Common Refrigerants","Physical, Chemical And Thermodynamics Properties","Selection Of Refrigerants","Leakage Of Refrigerants And Methods Of Detection"]},{"title":"Psychometry","topics":["Properties Of Air Vapour Mixture","Wet Bulb, Dew Point & Dry Bulb Temperatures","Humidity","Specific Humidity","Humidity Ratio","Degree Of Saturation","Relative Humidity","Total Heat Psychometric Relation","Psychrometric Charts And Its Uses","Psychrometric Processes","Evaporative Cooling"]},{"title":"Air conditioning","topics":["General Principle And Requirement For Comfort And Air Conditioning","Thermodynamics Of Human Body","Estimation Of Heating And Cooling Loads","Capacity Of Cooling Coils","Humidification And Dehumidification Unit And Conditioner","Central Air Conditioner","Year Around Air Condition","Humidity And Temperature Control","Industrial Application Of Air Conditioning System"]},{"title":"Concept of enthalpy potential","topics":["Air Washers","Cooling Towers","Evaporative Condensers","Cooling And Dehumidifying Coils","Gosney, W.B, Principles of Refrigeration, Cambridge University Press, 1982.","Stoecker, W.F. and Jones, J.W., Refrigeration and Air conditioning, Tata McGraw Hill, 1986.","Arora, C.P., Refrigeration and Air conditioning, Tata McGraw Hill, 2nd Edition, 2000.","Kuehn, T.H., Ramsey, J.W. and Threlkeld, J.L., Thermal Environmental Engineering, 3rd Edition, Prentice Hall, 1998.","A student who has done the course will have a good understanding of the working principles of refrigeration and air-conditioning systems.","Note: Refrigeration Data Books are permitted for examination."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Practical:","Determination Of The Cop Of A Vapour Compression System","Determination Of The Cop Of Vapour Absorption Apparatus","Determination Of The Cop Of A Heat Pump","To Find The Performance Parameter Of The Cooling Tower","To Study Various Components Of A Room Air Conditioner And Determine Its Performance For Different Psychometric Conditions","Determination Of Cop Of An Electrolux Refrigerator","To Study The Compressor And Throttling Valve Used In The Refrigerator"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To provide an overview of how computers can be utilized in mechanical component design."]},{"title":"Fundamentals of Computer Graphics","topics":["Product Cycle","Sequential And Concurrent Engineering","Computer Aided Design","Cad System Architecture","Computer Graphics","Coordinate Systems","2d And 3d Transformations","Viewing Transformation"]},{"title":"Geometric Modeling","topics":["Representation Of Curves","Hermite Curves","Bezier Curves","B-spline Curves","Rational Curves","Techniques Of Surface Modelling","Surface Patch","Coons And Bicubic Patches","Bezier And B-spline Surfaces","Solid Modelling Techniques","Csg And B-rep"]},{"title":"Visual realism","topics":["Hidden Line-surface-solid Removal Algorithms","Shading","Colouring","Computer Animation"]},{"title":"Assembly of parts and CAD standards","topics":["Assembly Modelling","Interferences Of Positions And Orientation","Tolerance Analysis","Mass Property Calculations","Mechanism Simulation And Interference Checking","Cad Standards Graphical Kernel System (Gks)","Standards For Exchange Images","Open Graphics Library (Opengl)","Data Exchange Standards Iges, Step, Cals Etc","Communication Standards","Ibrahim Zeid, Mastering CAD CAM, Tata McGraw Hill Publishing Co.2007.","C. McMahon and J. Browne, CAD/CAM Principles, II edition, Pearson Education, 1999.","W. M. Neumann and R.F. Sproul, Principles of Computer Graphics, McGraw Hill, 1989.","D. Hearn and M.P. Baker, Computer Graphics, Prentice Hall Inc., 1992.","Upon completion of this course, the students can use computer and CAD software for modelling mechanical components."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Practical:","Initiating The Graphics Package; Setting The Paper Size, Space; Setting The Limits, Units; Use Of Snap And Grid Commands","Drawing Of Primitives (Line, Arc, Circle, Ellipse, Triangle Etc.)","Drawing A Flange","Drawing A Bushing Assembly","Dimensioning The Drawing And Adding Text","Setting The Layers And Application Of Layers","Isometric And Orthographic Projections","Viewing In Three Dimensions","Removal Of Hidden Lines Shading And Rendering"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["→ To illustrate the principle of mathematical modeling of engineering problems.","→ To introduce the basics and application of the Finite Element Method."]},{"title":"Historical Background Mathematical Modeling Of Field Problems In Engineering Governing","topics":["Historical Background","Mathematical Modeling Of Field Problems In Engineering","Governing Equations","Discrete And Continuous Models","Boundary And Initial Value Problems","Weighted Residual Methods","Variational Formulation Of Boundary Value Problems","Ritz Technique","Basic Concept Of Finite Element Method"]},{"title":"One Dimensional Second Order Equation Discretization Linear And Higher Order","topics":["One Dimensional Second Order Equation","Discretization","Linear And Higher Order Elements","Derivation Of Shape Functions","Stiffness Matrix And Force Vectors","Assembly Of Elemental Matrices","Solution Of Problems From Solid Mechanics And Heat Transfer","Longitudinal Vibration And Mode Shapes","Fourth Order Beam Equation","Transverse Deflections And Natural Frequencies"]},{"title":"Two Dimensional Equations Variational Formulation Finite Element Formulation Triangular Elements","topics":["Two Dimensional Equations","Variational Formulation","Finite Element Formulation","Triangular Elements Shape Functions","Elemental Matrices And Rhs Vectors","Application To Thermal Problems","Torsion Of Non-circular Shafts","Quadrilateral And Higher Order Elements","Plane Stresses And Plane Strain Problems","Body Forces And Thermal Loads","Plate And Shell Elements"]},{"title":"Natural Coordinate Systems Isoparametric Elements And Shape Functions Numerical Integration","topics":["Natural Coordinate Systems","Isoparametric Elements And Shape Functions","Numerical Integration And Application To Plane Stress Problems","Matrix Solution Techniques","Solution Of Dynamic Problems","Introduction To Fe Software","Reddy J.N., An Introduction to Finite Element Method, 3 rd ed., Tata McGraw Hill, 2005.","Seshu P., Text Book of Finite Element Analysis, Prentice Hall, New Delhi, 2007.","Rao S.S., The Finite Element Method in Engineering, 3 rd ed., Butterworth Heinemann, 2004.","Chandrupatla & Belegundu, Introduction to Finite Elements in Engineering, 3 rd edPrentice Hall, 1990.","Upon completion of the course, students will understand the FEM formulation and its application to simple structural and thermal problems."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Practical:","Use these software for experiments: ANSYS, SIMULIA, ABAQUS, MATLAB etc.","Force And Stress Analysis Using Link Elements In Trusses, Cables Etc","Stress And Deflection Analysis In Beams With Different Support Conditions","Stress Analysis Of Flat Plates And Simple Shells","Stress Analysis Of Axi-symmetric Components","Thermal Stress And Heat Transfer Analysis Of Plate","Thermal Stress Analysis Of Cylindrical Shells","Vibration Analysis Of Spring-mass Systems","Model Analysis Of Beams"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To understand the construction and working principle of various parts of an automobile."]},{"title":"Types Of Automobiles Vehicle Construction And Layouts Car Body Style","topics":["Types Of Automobiles","Vehicle Construction And Layouts","Car Body Style","Chassis, Frame And Body","Vehicle Aerodynamics","Ic Engines-components, Function And Materials","Variable Valve Timing (Vvt)","Front Engine Front Wheel Drive","Front Engine Rear Wheel Drive","Four Wheel Drive"]},{"title":"Engine auxiliary systems","topics":["Electronic Injection For Si And Ci Engines"]},{"title":"njector System","topics":["Rotary Distributor Type And Common Rail Direct Injection System","Transistor Based Coil Ignition & Capacitive Discharge Ignition Systems","Turbo Chargers (Wgt, Vgt)","Engine Emission Control By 3-way Catalytic Converter System","Emission Norms (Euro & Bs)"]},{"title":"Transmission systems","topics":["Clutch Types","Cone Clutch","Single Plate, Multi Plate, Diaphragm Spring & Centrifugal Clutch","Electromagnetic Clutch & Construction","Gear Boxes Manual And Automatic Gear Shift Mechanisms","Overdrive Principles","Transfer Box","Transaxles","Flywheel","Torque Converter","Propeller Shaft","Slip Joints","Universal Joints","Differential And Rear Axle","Hotchkiss Drive And Torque Tube Drive"]},{"title":"Steering and Suspension","topics":["Steering Geometry And Types Of Steering Gear Box","Power Steering","Types Of Front Axle","Types Of Suspension Systems","Constructional Details & Characteristics Of Leaf Spring","Pneumatic And Hydraulic Braking Systems","Anti Lock Braking System (Abs)","Electronic Brake Force Distribution (Ebd) And Traction Control"]},{"title":"Axles and Alignment","topics":["Caster","Camber","King Pin Inclination Toe In Toe Out","Full Floating, Three Quarter Floating & Semi Floating Rear Axles"]},{"title":"Alternative energy sources","topics":["Natural Gas","Lpg","Biodiesel","Bio-ethanol","Gasohol And Hydrogen Fuels In Automobiles","Modifications Needed","Performance, Combustion & Emission Characteristics Of Alternative Fuels In Si And Ci Engines","Electric And Hybrid Vehicles","Application Of Fuel Cells","Kirpal Singh, Automobile Engineering, 7 th ed., Standard Publishers, New Delhi, 1997.","Jain K.K. and Asthana R.B., Automobile Engineering, Tata McGraw Hill, New Delhi, 2002.","Heitner J., Automotive Mechanics, 2nd ed., East-West Press, 1999.","Heisler H., Advanced Engine Technology, SAE International Publ., USA, 1998.","Upon completion of this course, students will understand the function of each automobile component and also have a clear idea about the overall vehicle performance."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Practical:","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Automotive Clutches","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Automotive Transmission Systems","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Automotive Drivelines & Differentials","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Multi-cylinder: Diesel And Petrol Engines","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Fuels Supply Systems","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Engine Cooling & Lubricating Systems","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Automotive Suspension Systems","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Automotive Steering Systems","To Study And Prepare A Report On The Constructional Details, Working Principles And Operation Of The Automotive Brake Systems"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To understand the methodology and applications of Operations Research in decision-making processes."]},{"title":"Introduction","topics":["Features of Operations Research (OR)","Methodology of OR","Scopes and Objectives of OR models in OR"]},{"title":"Inventory and Linear Programming","topics":["Inventory classification","Different cost associated to Inventory","Economic order quantity","Inventory models with deterministic demands","ABC analysis","Introduction and assumptions of LPP","Mathematical formulation of LPP","Graphical Method","Simplex Method"]},{"title":"Transportation and Assignment Problems","topics":["Transportation Problems: Introduction","Northwest Corner Method","Least Cost Method","Vogel''s Approximation Method","Test for Optimality","Assignment Problems: Introduction","Hungarian Assignment Method","Unbalanced Assignment Problems"]},{"title":"Sequencing and Network Analysis","topics":["Sequencing: Introduction","Formulation of Sequencing Problem","Johnson''s Rule","Network Analysis: Introduction","PERT and CPM","Time-Cost Trade-off (Project Crashing)","Resource Leveling"]},{"title":"Dynamic Programming and Simulation","topics":["Dynamic Programming: Introduction","Deterministic Dynamic Programming","Probabilistic Dynamic Programming","Simulation: Introduction","Monte Carlo Simulation","Simulation of Inventory and Queuing System"]},{"title":"Queuing and Replacement Theory","topics":["Queuing Theory: Introduction","General Structure of Queuing System","Operating Characteristics of Queuing System","Queuing Models","Replacement Theory: Introduction","Replacement Policies: Gradually Deteriorating Equipment","Items that Fail Suddenly","Operations Research: An Introduction by Hamdy A. Taha","Introduction to Operations Research by Frederick S. Hillier and Gerald J. Lieberman","Operations Research by S. D. Sharma","Operations Research: Theory and Applications by J. K. Sharma","Upon completion of this course, students will be able to apply various Operations Research techniques for optimization and decision-making in engineering and management problems."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Details for Project-II will be provided by the department. This component carries 6 credits."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Pre-requisite: Heat Transfer and Numerical Analysis Techniques.","Objective: To introduce the CFD techniques and tools for modelling, simulating and analysing practical engineering problems with hands on experience using commercial software packages used in industry.","Outcome: Students are able to understand the use of different CFD techniques and tools for modelling, simulation and analysis of complex engineering problems."]},{"title":"Introduction (Lectures 9 hrs.)","topics":["Philosophy Of Computational Fluid Dynamics","Computational Fluid Dynamics As A Research Tool","Computational Fluid Dynamics As A Design Tool","The Impact Of Computational Fluid Dynamics On Automobile And Engine Applications","Industrial Manufacturing Applications","Environmental Engineering Applications"]},{"title":"Governing equations of Computational Fluid Dynamics (Lectures 8 hrs.)","topics":["Models Of The Flow","The Substantial Derivative","Divergence Of Velocity","Continuity Equation","Momentum Equation","Energy Equation","Physical Boundary Conditions"]},{"title":"Partial differential equations (Lectures 6 hrs.)","topics":["General Method Of Determining The Classification Of Partial Differential Equations","The Impact Of Different Equation On Computational Fluid Dynamics","Hyperbolic Equations","Parabolic Equations","Elliptic Equations"]},{"title":"Basic aspects of Discretization (Lectures 6 hrs.)","topics":["Introduction To Finite Differences","Difference Equations","Explicit And Implicit Approaches"]},{"title":"Grids with appropriate transformation (Lectures 5 hrs.)","topics":["General Transformation Of The Equations","Matrices And Jacobians","Stretched (compressed) Grids"]},{"title":"Some Simple Computational Fluid Dynamics Techniques (Lectures 8 hrs.)","topics":["Lax-Wendroff Technique","Mac Cormack''s Technique","Relaxation Technique","Pressure Correction Technique","Etc","John D. Anderson, Jr. \"Computational Fluid Dynamics\", McGraw-Hill, Inc.","Date, A. W., \"Introduction to Computational Fluid Dynamics\", Cambridge University Press, 2005.","Sengupta, T. P. \"Fundamental of Computational Fluid Dynamics\", Orient Longman, Hyderabad, India, 200"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Objectives: This course is directed towards creating safety awareness, identifying hazards and mitigation of accidents along with introduction of legal requirements and following up action.","Outcome: After reading the course an engineer may develop confidence of over safe operations."]},{"title":"(Lectures 3 hrs.)","topics":["Need","Modern Safety Concepts","OSHA Norms"]},{"title":"(Lectures 6 hrs.)","topics":["Safety Management Function","Cost Analysis Of Accidents","System Safety Analysis"]},{"title":"(Lectures 12 hrs.)","topics":["Hazards Identification And Control","Pressure Hazard","Fire Hazard","Electrical Hazard"]},{"title":"(Lectures 11 hrs.)","topics":["Hazard In Construction Industry","Hazard Due To Acceleration And Fall","Mechanical Hazard","Hazard Due To Heat And Temperature"]},{"title":"(Lectures 4 hrs.)","topics":["Safe Practices Rules","Personal Protective Equipment"]},{"title":"Ergonomics (Lectures 6 hrs.) Ergonomics","topics":["Ergonomics","Safety Management - John V. Grimaldi & Rollin H Simmonds.","Ergonomics At Work - Osborne, D. J, John Wiley & Sons.","Industrial Safety Handbook - Handey, W, McGraw Hill.","Designer''s Guide To OSHA - McGraw Hill.","Handbook Of Occupational Safety And Health - John Wiley & Sons.","Industrial Accident Prevention - Heinrich, Hetal, McGraw Hill."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Objective: To understand how the material removal by using various energy and to know how the new materials and complex parts are produced with high accuracy by using new technology."]},{"title":"Introduction (Lectures 4 hrs.)","topics":["Historical Background Of Non-conventional Machining Processes","Classification","Basic Fundamentals Of Various Process And Related Comparison"]},{"title":"Mechanical Machining Process (Lectures 7 hrs.)","topics":["Principle And Working And Applications Of Mechanical Machining Processes Such As Ultrasonic Machining","Water Jet Cutting"]},{"title":"Thermal and Chemical Machining Process (Lectures 7 hrs.)","topics":["Principle And Working And Applications Of Thermal And Chemical Machining Processes Such As Electro-discharge Machining","Electro-chemical Machining"]},{"title":"Non-conventional welding process (Lectures 10 hrs.)","topics":["Principle And Working And Application Of Non-conventional Welding Processes Such As Laser Beam Welding","Electron Beam Welding","Ultrasonic Welding","Plasma Arc Welding","Explosive Welding","Cladding Under Water Welding","Metallising"]},{"title":"Non-conventional forming process (Lectures 10 hrs.)","topics":["Principle, Working And Applications Of High Energy Forming Processes Such As Explosive Forming","Electro-magnetic Forming","Electro-discharge Forming","Water Hammer Forming","Explosive Compaction"]},{"title":"Introduction to Micro Manufacturing (Lectures 4 hrs.)","topics":["Micro Manufacturing Fundamentals","Significance","Application Of NCMPs For Micro Manufacturing","Micro To Nano Finishing Processing Information","C. Pandey and H.S. Shah, Modern Machining Processes, Tata McGraw-Hill Publishing Co. Ltd, New Delhi, 1980.","Ghosh and A.K. Mallik, Manufacturing Science, 2nd edition, Affiliated East West Press, New Delhi.","F. Benedict, Nontraditional Manufacturing Processes, Marcel Dekker Inc., New York (ISBN 08247-7352-7), 1987.","K. Jain, Advanced Machining Processes, Allied Publishers, 2009.","A. Mc Geough, Micromachining of Engineering Materials, Taylor & Francis, 2001.","Outcome: Students will be able to understand the fundamentals of various non-conventional machining processes and their influence on performance and their applications."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Objectives: To understand the principles of management and their application to the functioning of an organization.","Module 1: (Lectures 8 hrs.) Definition Of Management Science Or Art Manager Vs Entrepreneur Types Of Managers Managerial Roles And Skills Evolution Of Management- Scientific Human Relations System And Contingency Approaches Types Of Business Organizations Sole Proprietorship Partnership Company Public And Private Enterprises Organization Culture And Environment Current Trends And Issues In Management","Definition Of Management","Science Or Art","Manager Vs Entrepreneur","Types Of Managers Managerial Roles And Skills","Evolution Of Management- Scientific","Human Relations","System And Contingency Approaches","Types Of Business Organizations","Sole Proprietorship","Partnership","Company","Public And Private Enterprises","Organization Culture And Environment","Current Trends And Issues In Management"]},{"title":"(Lectures 6 hrs.)","topics":["Nature And Purpose Of Planning","Types Of Planning","Objectives","Setting Objectives","Policies","Strategic Management","Planning Tools And Techniques","Decision Making Steps & Processes"]},{"title":"(Lectures 10 hrs.)","topics":["Nature And Purpose Of Organizing","Formal And Informal Organization","Organization Structure","Types","Line And Staff Authority","Departmentalization","Delegation Of Authority","Centralization And Decentralization","Job Design","Human Resource Management","HR Planning","Recruitment Selection","Training & Development","Performance Management","Career Planning And Management"]},{"title":"(Lectures 8 hrs.)","topics":["Directing","Individual And Group Behavior","Motivation","Motivation Theories","Motivational Techniques","Job Satisfaction","Job Enrichment","Leadership","Types & Theories Of Leadership","Effective Communication"]},{"title":"(Lectures 8 hrs.)","topics":["Controlling","System And Process Of Controlling","Budgetary And Non-budgetary Control Techniques","Use Of Computers And IT In Management Control","Productivity Problems And Management","Control And Performance","Direct And Preventive Control","Reporting","Upon completion of this course, the students will get a clear understanding of management functions in an organization.","Robins S.P. and Coulter M., Management, Prentice Hall India, 10th, 2009.","Stoner JAF, Freeman RE and Gilbert DR, Management, 6th, Pearson Education, 2004.","Tripathy PC & Reddy PN, Principles of Management, Tata McGraw Hill, 1999."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Objectives: To learn about the design procedures for mechanical power transmission components."]},{"title":"(Lectures 4 hrs.)","topics":["Flexible Transmission Elements- Design Of Flat Belts & Pulleys","Selection Of V-belts And Pulleys","Selection Of Hoisting Wire Ropes And Pulleys","Design Of Chains And Sprockets"]},{"title":"(Lectures 10 hrs.)","topics":["Gear Transmission- Speed Ratios And Number Of Teeth","Force Analysis","Tooth Stresses","Dynamic Effects","Fatigue Strength","Factor Safety","Gear Materials","Design Of Straight Tooth Spur Gear And Parallel Axis Helical Gears Based On Strength And Wear Considerations","Pressure Angle In The Normal And Transverse Plane","Equivalent Number Of Teeth And Forces For Helical Gears"]},{"title":"(Lectures 10 hrs.)","topics":["Straight Bevel Gear- Tooth Terminology","Tooth Forces And Stresses","Equivalent Number Of Teeth","Estimating The Dimensions Of A Pair Of Straight Bevel Gears","Worm Gear","Merits & Demerits","Terminology","Thermal Capacity","Materials","Forces & Stresses","Efficiency","Estimating The Size Of Worm Gear Pair","Cross Helical Gears","Terminology","Helix Angles","Sizing Of A Pair Of Helical Gears"]},{"title":"(Lectures 10 hrs.)","topics":["Gear Box- Geometric Progression","Standard Step Ratio","Ray Diagram","Kinematics Layout","Design Of Sliding Mesh Gear Box- Design Of Multi-speed Gear Box For Machine Tool Applications","Constant Mesh Gear Box","Speed Reducer Unit","Variable Speed Gear Box","Fluid Couplings","Torque Converters For Automotive Applications"]},{"title":"(Lectures 8 hrs.)","topics":["Cam Design","Types: Pressure Angle And Undercutting Base Circle Determination","Forces And Surface Stresses","Design Of Plate Clutches","Axial Clutches","Cone Clutches","Internal Expanding Rim Clutches","Electromagnetic Clutches","Band And Block Brakes","External Shoe Brakes","Internal Expanding Shoe Brake","Upon completing this course the students will be able to design transmission systems for engines and machines.","Shigley J., Mischke C., Budynas R. and Nisbett K., Mechanical Engineering Design, 8th, Tata McGraw Hill, 2010.","Jindal U.C., Machine Design: Design of Transmission System, Dorling Kindersley, 2010.","Maitra and Prasad L., Handbook of Mechanical Design, 2nd ed., Tata McGraw Hill, 2001."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Objectives: To facilitate the understanding of total quality management principles and processes."]},{"title":"(Lectures 8 hrs.)","topics":["Introduction","Need For Quality","Evolution Of Quality","Definitions Of Quality","Product Quality And Service Quality","Basic Concepts Of TQM","TQM Framework","Contributions Of Deming, Juran And Crosby","Barriers To TQM","Quality Statements","Customer Focus","Customer Orientation & Satisfaction","Customer Complaints","Customer Retention","Costs To Quality"]},{"title":"(Lectures 8 hrs.)","topics":["TQM Principles","Leadership","Strategic Quality Planning","Quality Councils- Employee Involvement","Motivation","Empowerment","Team And Teamwork","Quality Circles","Recognition And Reward","Performance Appraisal","Continuous Process Improvement","PDCA Cycle","5S","Kaizen","Supplier Partnership","Partnering","Supplier Rating & Selection"]},{"title":"(Lectures 8 hrs.)","topics":["The Seven Traditional Tools Of Quality","New Management Tools","Six Sigma- Concepts","Methodology","Applications To Manufacturing","Service Sector Including IT","Bench Marking Process","FMEA- Stages","Types"]},{"title":"(Lectures 8 hrs.)","topics":["TQM Tools And Techniques","Control Charts","Process Capability","Concepts Of Six Sigma","Quality Function Development (QFD)","Taguchi Quality Loss Function","TPM- Concepts","Improvement Needs","Performance Measures"]},{"title":"(Lectures 8 hrs.)","topics":["Quality Systems","Need For ISO 9000","ISO 9001-9008","Quality System- Elements","Documentation","Quality Auditing","QS 9000","ISO 14000-concepts","Requirements And Benefits","TQM Implementation In Manufacturing And Service Sectors","Upon completion of this course, the students will be able to use the tools and techniques of TQM in manufacturing and service sectors.","Bester field D.H. et al., Total quality Management, 3rd, Pearson Education Asia, 2006.","Evans J.R. and Lindsay W.M., The management and Control of Quality, 8th, first Indian edition, Cengage Learning, 2012.","Janakiraman B. and Gopal R.K., Total Quality Management, Prentice Hall India, 2006.","Suganthi L. and Samuel A., Total Quality Management, Prentice Hall India, 2006."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Objectives: To understand the energy data from industries and carry out energy audit for energy savings."]},{"title":"(Lectures 8 hrs.)","topics":["Introduction To Energy & Power Scenario Of World","National Energy Consumption Data","Environmental Aspects Associated With Energy Utilization","Energy Auditing- Need","Types","Methodology And Barriers","Role Of Energy Managers","Instruments Of Energy Auditing"]},{"title":"(Lectures 10 hrs.)","topics":["Components Of EB Billing","HT And LT Supply","Transformers","Cable Sizing","Concept Of Capacitors","Power Factor Improvement","Harmonics","Electric Motors- Motor Efficiency Computation","Energy Efficient Motors","Illumination- Lux","Lumens","Types Of Lighting","Efficacy","LED Lighting And Scope Of Energy Conservation In Lighting"]},{"title":"(Lectures 10 hrs.)","topics":["Thermal Systems","Boilers","Furnaces And Thermic Fluid Heaters- Efficiency Computation And Energy Conservation Measures","Steam Distribution And Usage","Steam Traps","Condensate Recovery","Flash Steam Utilization","Insulation & Refractories"]},{"title":"(Lectures 6 hrs.)","topics":["Energy Conservation In Major Utilities","Pumps","Fans","Blowers","Compressed Air Systems","Refrigeration & Air Conditioning System","Cooling Towers","DG Sets"]},{"title":"(Lectures 6 hrs.)","topics":["Energy Economics- Discount Period","Payback Period","Internal Rate Of Return","Net Present Value","Life Cycle Costing- ESCO Concept","Upon completion of this course, the students will be able to perform of energy auditing for the energy consumption of industries.","Witte L.C., Schmidt P.S. and Brown D.R., Industrial Energy Management and Utilization, Hemisphere Publ., Washington, 1988.","Callaghn P.W., Design and Management for Energy Conservation, Pergamon Press, Oxford.","Murphy W.R. and McKay G., Energy Management, Butterworths, London, 1987.","Energy Manager Training Manual, Bureau of Energy Efficiency (BEE) under Ministry of Power, GOI, 2004 (available at energymanagertraining.com)."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Objectives: To understand the features of compressible isentropic flows and irreversibility like shocks. To provide a basic knowledge of jet and rocket propulsion technologies."]},{"title":"(Lectures 12 hrs.)","topics":["Compressible Flow","Definition","Mach Waves And Mach Cone","Stagnation States","Mass, Momentum And Energy Equations Of One-dimensional Flow","Isentropic Flow Through Variable Area Ducts","Nozzles And Diffusers","Subsonic And Supersonic Flow In Variable Area Ducts","Choked Flow","Area-Mach Number Relations For Isentropic Flow"]},{"title":"(Lectures 8 hrs.)","topics":["Non-isentropic Flow In Constant Area Ducts","Rayleigh And Fanno Flows","Normal Shock Relations","Oblique Shock Relations","Isentropic And Shock Tables"]},{"title":"(Lectures 10 hrs.)","topics":["Theory Of Jet Propulsion","Thrust Equation","Thrust Power And Propulsive Efficiency","Operating Principle And Cycle Analysis Of Ramjet","Turbojet","Turbofan And Turboprop Engines"]},{"title":"(Lectures 10 hrs.)","topics":["Types Of Rocket Engines","Propellants & Feeding Systems","Ignition And Combustion","Theory Of Rocket Propulsion","Performance Study","Staging","Terminal And Characteristic Velocity","Space Flights","Upon completion of this course, the students will be able to apply gas dynamics principles to jet and space propulsion systems.","Ahmed El-Sayed, Aircraft Propulsion and Gas Turbine Engines, CRC Press, 2008.","S. Mukunda, \"Understanding Aerospace Chemical Propulsion\", Interline Publishing, 2004.","Hill P. and Peterson C., Mechanics & Thermodynamics of Propulsion, Addison Wesley.","Zucrow N. J., Aircraft and Missile Propulsion, Vol.1& II, John Wiley.","Sutton G.P., Rocket Propulsion Elements, John Wiley, New York, 1986."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Atomic and Molecular Structure Electromagnetic radiations Dual nature of electron and Heisenberg uncertainty Principle Photoelectric effect Planck''s theory Principles for the combination of atomic orbitals to form a molecular diagram of molecular orbitals Bent''s rule VSEPR theory (typical example) Coordination numbers and geometries Isomerism in transition metal compounds Metal Carbonyls: Synthesis and Structure","Electromagnetic radiations","Dual nature of electron and Heisenberg uncertainty Principle","Photoelectric effect","Planck''s theory","Principles for the combination of atomic orbitals to form a molecular diagram of molecular orbitals","Bent''s rule","VSEPR theory (typical example)","Coordination numbers and geometries","Isomerism in transition metal compounds","Metal Carbonyls: Synthesis and Structure"]},{"title":"Spectroscopy","topics":["Principle of rotational and vibrational spectroscopy","Selection rule for application in diatomic molecules","Elementary idea of electronic spectroscopy","UV-VIS spectroscopy with related to rules and its applications","Basic Principle of nuclear Magnetic resonance spectroscopy with applications"]},{"title":"Electrochemistry and Fuels","topics":["Nernst equation","EMF and electrochemical cell","Introduction of corrosion","Corrosion mechanism","Types of corrosion","Water line corrosion","Stress corrosion","Pitting corrosion","Lead acid storage cell","Leclanche cell","Calorific value of fuels","Proximate and ultimate analysis of coals","Fuel cells","Bio fuels"]},{"title":"Water Chemistry","topics":["Hardness of water","Estimation of water hardness by EDTA and Alkalinity method","Removal of the hardness of water: soda lime process, zeolite process, Ion exchange process","Boiler problem","Sludge and scale formation","Priming and foaming","Boiler corrosion","Caustic embrittlement","Unit 5.0: Polymer and Plastics Polymerization techniques (free radical, ionic, and co-ordination mechanism) Preparation properties and technical application of phenol-formaldehyde resins Elastomers Synthetic rubbers (Buna-S, Buna-N, neoprene) Inorganic polymers Silicones Adhesives Epoxy resins Structural difference between thermoplastic and thermosetting Plastics Importance of commercially important thermoplastics and thermosets Poly ethylene Polyvinyl chloride Polystyrene","Polymerization techniques (free radical, ionic, and co-ordination mechanism)","Preparation properties and technical application of phenol-formaldehyde resins","Elastomers","Synthetic rubbers (Buna-S, Buna-N, neoprene)","Inorganic polymers","Silicones","Adhesives","Epoxy resins","Structural difference between thermoplastic and thermosetting Plastics","Importance of commercially important thermoplastics and thermosets","Poly ethylene","Polyvinyl chloride","Polystyrene"]},{"title":"Organic Reactions and Synthesis of A Drug Molecule","topics":["Introduction to intermediate and reaction involving Substitution, addition, elimination, oxidation-reduction","Diets Elder cyclization and epoxide ring opening reactions","Synthesis of commonly used drug molecules like aspirin","University Chemistry, B.H. Mahan, Pearson","Chemistry, principles and application, M.J. Sienko and R.A. Plane, McGraw Hill International","Fundamentals of molecular Spectroscopy, C.N. Banwell, McGraw Hill International","Engineering Chemistry (NPTEL Web- Book), B.L. Tembe, Kamaluddin and M.S. Krishnan, NPTEL","Physical Chemistry, P.W. Atkins, Oxford University Press","A text book of engineering chemistry, S. Chawala, Dhanpat Rai Publication","General Chemistry Part 1, R. Sarkar, New Central Book agency"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Linear Algebra-I","topics":["Elementary Row operations","Gauss-Jordan Method for finding the inverse of Matrix","Complex Matrix: Hermitian, Skew Hermitian and Unitary Matrix","Vector space","Sub Spaces","Linear dependence and Independences of Vectors","Linear Span","Basis","Dimension","Extension of basis of subspace","The rank of a matrix","Row and column space","Solvability of system of linear equations"]},{"title":"Linear Algebra-II","topics":["Linear Transformations","Kernel and Range of linear transformation","Matrix Representation of a linear transformation","Rank-Nullity Theorem","Eigen Value and Eigen Vectors","Properties of Eigen vectors","Eigen Bases","Orthogonal Transformation","Similarity Transformation","Matrix Diagonalization","Cayley-Hamilton Theorem"]},{"title":"Calculus for single variable","topics":["Indeterminate form","L''Hospital Rule","Rolle''s Theorem","Mean Value Theorem","Expansion of function (single variable)","Taylor and Maclaurin Series","Riemann Integration","Riemann Sum","Improper Integrals","Beta and Gamma function and their properties"]},{"title":"Multivariable Calculus (Differentiation)","topics":["Function with two or more variable","Limit, continuity and Partial differentiation","Total Differentiation","Taylor''s series and Maclaurin''s series for function with two variable","Jacobian","Maxima and Minima","Method of Lagrange''s multiplier"]},{"title":"Multivariable Calculus (Integration)","topics":["Double Integral","Change of order of integration","Triple integral","Change of Variable in a Double and Triple Integrals","Change to polar coordinate","Change to cylindrical coordinate","Change to spherical polar coordinate","Application to area and volume using double and triple integral"]},{"title":"Vector Calculus","topics":["Scalar and vector fields","Gradient","Directional derivative","Divergence","Curl and their properties","Line integral","Green''s theorem in plane (without proof)","Surface integral","Stoke''s theorem (without proof)","Volume Integral","Gauss-Divergence theorem (without proof)","AICTE''s Prescribed Textbook: Mathematics-I (Calculus & Linear Algebra), Reena Garg, Khanna Book Publishing Co. ISBN-10 9391505171","Advanced Engineering Mathematics, Chandrika Prasad & Reena Garg, Khanna Book Publishing Co., 2021. ISBN 10: 9386173522 / ISBN 13: 9789386173522.","Higher Engineering Mathematics, B.V. Ramana, Tata McGraw Hill New Delhi, 11th Reprint, 2010, ISBN-10 007063419X ISBN-13978-0070634190.","Advanced Engineering Mathematics, Srklyengar Rk Jain, Narosa, 5th Edition, ISBN-10 8184875606 ISBN-13978-8184875607","Advanced Engineering Mathematics, Erwin Kreyszig, 9th Edition, John Wiley & Sons, 2006."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Engineering Drawing","topics":["Principles of Engineering Graphics and Their Significance","Usage of Drawing Instruments","Lettering","Conic Sections including the Rectangular Hyperbola (General Method Only)","Cycloid, Epicycloid, Hypocycloid and Involute","Scales Plain, Diagonal and Vernier Scales"]},{"title":"Orthographic Projections","topics":["Principles of Orthographic Projections","Conventions","Projections of Points and Lines Inclined to Both Planes","Projections of Planes Inclined Planes Auxiliary Planes"]},{"title":"Projections of Regular Solids","topics":["Types of Solids","Projects of Solids (Prism, pyramids, cone, and cylinder): Inclined to Both the Planes","Auxiliary Views","Draw Simple Annotation, Dimensioning and Scale"]},{"title":"Sections and Sectional Views of Right Angular Solids","topics":["Section of Solids (Prism, Cylinder, Pyramid, Cone)","Auxiliary Views","Development of Surfaces Of Right Regular Solids: Prism, Pyramid, Cylinder And Cone","Draw The Sectional Orthographic Views of Geometrical Solids, Objects From Industry And Dwellings (Foundation To Slab Only)"]},{"title":"Isometric Projections","topics":["Isometric Views","Compound Solids","Principles of Isometric Projection Isometric Scale","Conventions","Isometric Views of Lines, Planes, Simple and Conversion of Isometric Views to Orthographic Views And Vice-Versa","Conventions","Unit 6.0: Overview of Computer Graphics Listing the Computer Technologies that Impact on Graphical Communication Demonstrating Knowledge of the Theory of CAD Software Menu System, Toolbars (Standard, Object Properties, Draw, Modify And Dimension) Drawing Area (Background, Crosshairs, Coordinate System) Dialog Boxes And Windows Shortcut Menus (Button Bars) The Command Line (Where Applicable) The Status Bar Different Methods of Zoom as Used in CAD Select and Erase Objects Isometric Views of Lines, Planes, Simple And Compound Solids","Listing the Computer Technologies that Impact on Graphical Communication","Demonstrating Knowledge of the Theory of CAD Software","Menu System, Toolbars (Standard, Object Properties, Draw, Modify And Dimension)","Drawing Area (Background, Crosshairs, Coordinate System)","Dialog Boxes And Windows","Shortcut Menus (Button Bars)","The Command Line (Where Applicable)","The Status Bar","Different Methods of Zoom as Used in CAD","Select and Erase Objects","Isometric Views of Lines, Planes, Simple And Compound Solids","Engineering Drawing, N.D. Bhatt, Charotar Publishing House, 53rd Edition, ISBN: 978-9380358277","A Textbook of Engineering Drawing, R.K. Dhawan, S. Chand Publishing, Revised Edition, ISBN: 978-8121929571","Engineering Drawing and Graphics, K. Venugopal, V. Prabhu Raja, New Age International Publishers, 3rd Edition, ISBN: 978-8122430120","Engineering Graphics with AutoCAD, D.M. Kulkarni, A.P. Rastogi, A.K. Sarkar, PHI Learning Pvt. Ltd., 1st Edition, ISBN: 978-8120337834"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Encouraging creativity and innovation: The course could aim to foster a culture of creativity and innovation among engineering students. It could provide opportunities for students to generate and develop new ideas, think critically, and come up with innovative solutions to real-world problems. This objective could be achieved through brainstorming sessions, design thinking exercises, and hands-on projects.","Enhancing problem-solving skills: The course could focus on enhancing the problem-solving skills of engineering students. It could provide training on various problem-solving techniques, such as root cause analysis, critical thinking, and decision-making. Students may learn how to identify and analyse complex problems, develop feasible solutions, and implement them effectively.","Developing project management skills: The course could aim to develop project management skills among engineering students. It could cover topics such as project planning, scheduling, budgeting, and risk management. Students may learn how to manage resources, communicate effectively, and work collaboratively in a project-based environment.","Promoting interdisciplinary collaboration: The course could encourage interdisciplinary collaboration among engineering students. It could provide opportunities for students from different engineering disciplines to work together on innovative projects. This could foster cross-disciplinary learning, encourage diverse perspectives, and promote teamwork and collaboration skills.","Facilitating practical application of engineering concepts: The course could focus on the practical application of engineering concepts and principles. It could provide students with opportunities to apply their theoretical knowledge to real-world projects, prototypes, or simulations. Students may learn how to translate engineering theories into practical solutions and develop hands-on experience in implementing innovative projects.","Developed innovative projects: Students may have successfully developed innovative projects that demonstrate their creativity, problem-solving skills, and technical competence. These projects could be prototypes, models, simulations, or practical solutions to real-world problems, showcasing their ability to apply engineering concepts in a creative and innovative manner.","Improved critical thinking and problem-solving skills: Students may have honed their critical thinking and problem-solving skills through various course activities, such as brainstorming, design thinking, and project development. They may have learned to analyse complex problems, identify viable solutions, and make informed decisions based on technical, economic, and social considerations.","Enhanced project management and teamwork skills: Students may have gained practical experience in managing projects, including planning, scheduling, budgeting, and risk management. They may have learned how to work effectively in a team, collaborate with diverse team members, and communicate project progress and results professionally.","Increased interdisciplinary knowledge and collaboration: Students may have gained exposure to interdisciplinary concepts and collaborated with peers from different engineering disciplines. They may have learned to appreciate diverse perspectives, leverage interdisciplinary knowledge, and work collaboratively to develop innovative solutions that integrate multiple domains of engineering.","Cultivated a mindset of innovation and entrepreneurship: Students may have developed a mindset of innovation and entrepreneurship, recognizing the importance of creativity, adaptability, and continuous improvement in engineering practice. They may have learned to identify opportunities, think critically, and take risks to develop and implement innovative projects with commercial or societal potential.","Any topics related to innovative project."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["To estimate hardness of water by alkalinity method","To estimate hardness of water by EDTA method","To remove hardness of water by ion exchange method","Determination of pH of a given acid solution using a standard sodium hydroxide solution","Determination of surface tension and viscosity","Chemical analysis of salt (Acid radical and basic radical)","Adsorption of acetic acid by charcoal","Test of adulteration of fat butter, sugar, turmeric powder, chilli powder and pepper","Saponification/ acid value of an oil","Identification of organic substances and their functional groups","Potentiometric determination of redox potentials and emf","Synthesis of drug/ polymer like ASPRIN/ Urea- formaldehyde resin","Thin layer chromatography","Analysis of flue gas by orsat apparatus"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Dimensioning methods, different types of line, construction of different polygon, divide the line and angle in parts, use of stencil","Construction of Plane, Diagonal & Vernier Scales","Construction of Ellipses, Parabolas, and Hyperbolas using the general method","Construction of cycloid, epicycloid, hypocycloid, and involute of a circle","Projection of Points and Lines inclined to both planes","Projections of Planes (e.g., rectangular, triangular) in inclined positions","Projection of Solids (prisms, pyramids, cones, and cylinders)","Drawing of Sections of Prisms, Cylinders, Pyramids, and Cones","Development of Surfaces for prisms, pyramids, cylinders, and cones","Construction of Isometric views of lines, planes, and simple solids","Introduction to CAD Software","Use of CAD software to draw basic geometric shapes, apply dimensions, and modify objects"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Frame of Reference and Oscillations","topics":["Non-Inertial frame of reference","Rotating coordinate system","Centripetal and Coriolis acceleration and its application in weather system","Harmonic Oscillator","Damped Harmonic motion: overdamped, critically Damped and lightly damped oscillators","Force Oscillators and Resonance","Unit 2.0: Optics and LASER Huygens''s Principle Superposition of Waves and interference of Light by wave front-splitting and amplitude-splitting Young''s double slit experiment Michelson interferometer Fraunhofer diffraction from single slit and circular aperture Diffraction Grating and their resolving power Einstein''s theory of matter-radiations interaction Einstein''s Coefficients (A and B) Amplification by population inversion Different types of lasers: Gas Laser, Helium-Neon Laser, Solid State Laser (Ruby, Neodymium), Semiconductor Laser","Huygens''s Principle","Superposition of Waves and interference of Light by wave front-splitting and amplitude-splitting","Young''s double slit experiment","Michelson interferometer","Fraunhofer diffraction from single slit and circular aperture","Diffraction Grating and their resolving power","Einstein''s theory of matter-radiations interaction","Einstein''s Coefficients (A and B)","Amplification by population inversion","Different types of lasers: Gas Laser, Helium-Neon Laser, Solid State Laser (Ruby, Neodymium), Semiconductor Laser","Unit 3.0: Quantum Mechanics Compton Effect Photoelectric Effect Wave Particle duality de Broglie''s hypothesis Heisenberg''s Uncertainty Principle Wave function and wave packets Phase and group velocities Schrodinger''s Wave Equation Normalization Expectation values Eigenvalues and Eigenfunction Application of Schrodinger Wave Equation for particle in one dimensional box: its wavefunction and eigenvalue of energy and momentum","Compton Effect","Photoelectric Effect","Wave Particle duality","de Broglie''s hypothesis","Heisenberg''s Uncertainty Principle","Wave function and wave packets","Phase and group velocities","Schrodinger''s Wave Equation","Normalization","Expectation values","Eigenvalues and Eigenfunction","Application of Schrodinger Wave Equation for particle in one dimensional box: its wavefunction and eigenvalue of energy and momentum","Unit 4.0: Vector Calculus and Electrostatics Gradient, Divergence and Curl Line, Surface and Volume integrals Gauss''s Divergence theorem and Stokes'' theorem in Cartesian Coordinate Gauss''s Law and its applications Divergence and Curl of Electrostatic fields Electrostatic Potential Boundary Conditions Poisson''s and Laplace''s equations Dielectrics Polarization Bound Charges Electric displacement Boundary Conditions in dielectrics","Gradient, Divergence and Curl","Line, Surface and Volume integrals","Gauss''s Divergence theorem and Stokes'' theorem in Cartesian Coordinate","Gauss''s Law and its applications","Divergence and Curl of Electrostatic fields","Electrostatic Potential","Boundary Conditions","Poisson''s and Laplace''s equations","Dielectrics","Polarization","Bound Charges","Electric displacement","Boundary Conditions in dielectrics","Unit 5.0: Magnetostatics and Electrodynamics Lorentz force Biot-Savart and Ampere''s circuital laws and their applications Divergence and Curl of Magneto static fields Magnetic vector potential Force and torque on a magnetic dipole Magnetic Materials Magnetization Bound currents Boundary conditions Ohm''s law Motional EMF Faraday''s Law Lenz''s law Self and mutual inductance Energy stored in magnetic field Maxwell''s equations in vacuum and nonconducting medium Continuity Equation Poynting Theorem Wave Equations: plain electromagnetic wave in vacuum and their transverse nature and Polarization","Lorentz force","Biot-Savart and Ampere''s circuital laws and their applications","Divergence and Curl of Magneto static fields","Magnetic vector potential","Force and torque on a magnetic dipole","Magnetic Materials","Magnetization","Bound currents","Boundary conditions","Ohm''s law","Motional EMF","Faraday''s Law","Lenz''s law","Self and mutual inductance","Energy stored in magnetic field","Maxwell''s equations in vacuum and nonconducting medium","Continuity Equation","Poynting Theorem","Wave Equations: plain electromagnetic wave in vacuum and their transverse nature and Polarization"]},{"title":"Solids and Semi-Conductors","topics":["Free electron theory of metal","Fermi level","Bloch''s theorem for particle in a periodic Potential","Kroning-Penney model and origin of energy band","Metals, semiconductors and insulators","Intrinsic and extrinsic semiconductors","Carrier transport, diffusion and drift","P-N junction","Quantum Physics of Atoms, Molecules, Solids, Nuclei and Particles, R. Eisberg R. Resnick, Wiley India Pvt. Ltd ISBN 978-81-265-0818-1","Theory of Vibration with Application, W.T. Thomson M. D. Dahleh, Pearson India ISBN 978-81-317-0482-0","Introduction to Electrodynamics, D.J. Griffiths, Pearson India, ISBN 978-93-325-5044-5","Electromagnetism, I.S. Grant, W. R. Phillips, Wiley India Pvt. Ltd ISBN 978-04-719-2712-9","The Feynman Lectures on Physics, R.P. Feynman R. B. Leighton, Pearson India ISBN 978-00-710-7458-2","Optics, Ajay Ghatak, McGraw Hill ISBN 978-93-901-1359-0","Physics of Vibration and Waves, H. J. Pain, Wiley India Pvt. Ltd, ISBN 978-04-700-1296-3","Concept of Modern Physics, Arthur Beiser, McGraw Hill ISBN 978-93-513-4185-7","Introduction to Solid State Physics, C. Kittle, Wiley India Pvt. Ltd, ISBN 978-81-265-7843-6"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Complex Analysis - I","topics":["Functions of complex variable","Limit, Continuity, Differentiability","Analytic function","Cauchy-Riemann Equations in Cartesian and polar form","Harmonic function and harmonic conjugate"]},{"title":"Complex Analysis - II","topics":["Line Integral","Contour integrals","Cauchy theorem","Cauchy''s Integral formula (without proof)","Taylors series","Zero of analytic functions","Singularities","Laurent''s series","Residue","Cauchy residue theorem (without Proof) and its applications"]},{"title":"Ordinary Differential Equations","topics":["Linear differential equations of nth Order with constant coefficients","Solution of Homogeneous and Non-Homogeneous Equations","Equations with variable coefficients","Cauchy-Euler Equations","Method of Variation of Parameters"]},{"title":"Sequence and Series","topics":["Introduction of Sequence and Series","Nature of series Tests of convergence of Series","Comparison test","D''Alembert ratio test","Cauchy''s Root test","Raabe''s test","Logarithmic test","Cauchy''s condensation test"]},{"title":"Laplace Transform Laplace Transform Existence theorem Properties of Laplace Transform","topics":["Laplace Transform","Existence theorem","Properties of Laplace Transform","Laplace Transform of Periodic functions","Inverse Laplace Transform","Convolution theorem","Application of Laplace Transform to solve Ordinary differential equations"]},{"title":"Fourier Series Fourier Series Fourier Series for odd and even","topics":["Fourier Series","Fourier Series for odd and even functions","Half range sine and cosine series","Parseval''s theorem","Advanced Engineering Mathematics, Kreyszig Erwin, John Wiley and Sons, 10th Edition, 2020 ISBN: 978-0470-45836-5","Advanced Engineering Mathematics, Dass H.K., S Chand and Company pvt. Ltd., 22nd Edition, 2018 ISBN: 978-93-5283-718-2","Higher Engineering Mathematics, Grewal B.S., Khanna Publishers, 44th Edition, 2023 ISBN: 9788174091154","Complex Variables (Theory and Applications), Kasana H.S., PHI, 2nd Edition, 2015 ISBN: 978-81-203-2641-5","A Text Book of Engineering Mathematics, Bali N.P., Goyal Manish Laxmi Publications, 9th Edition, 2014","Higher Engineering Mathematics, Ramana B.V., Tata McGraw Hill New Delhi, 11th Reprint, 2010, ISBN-10 007063419X ISBN-13 978-0070634190","Differential Equations, Ross S.L., Wiley Publications, 3rd edition, 2016 ISBN: 978-81-265-1537-0","Advanced Differential Equations, Raisinghania M.D., S.Chand and Company PVT.LTD., 18th Edition, 2015 ISBN: 978-81-219-0893-1","Schaum''s Outlines Complex Variables, Spiegel Murray R, Lipschutz Seymour, Schiller J John and Spellman Dennis, MC Graw Hill Education Private Ltd. 2nd Edition, 2010 ISBN: 978-0-07-008538-1"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction to Programming Introduction to components of a computer system (disks, memory, processor, where a program is stored and executed, operating system, compilers etc.) Idea of Algorithm: steps to solve logical and numerical problems Representation of Algorithm: Flowchart/ Pseudo code with examples From algorithms to programs; source code Variables (with data types) variables and memory locations Syntax and Logical Errors in compilation Object and executable code","Introduction to components of a computer system (disks, memory, processor, where a program is stored and executed, operating system, compilers etc.)","Idea of Algorithm: steps to solve logical and numerical problems","Representation of Algorithm: Flowchart/ Pseudo code with examples","From algorithms to programs; source code","Variables (with data types) variables and memory locations","Syntax and Logical Errors in compilation","Object and executable code"]},{"title":"Operators, Conditional Branching and Loops","topics":["Arithmetic expressions/arithmetic operators","Relational operators","Logical operators","Bitwise operators and precedence","Writing and evaluation of conditionals and consequent branching","Iteration and loops"]},{"title":"Arrays and String","topics":["Array declaration & initialization","Bound checking arrays (1-d, 2-d)","Character arrays and strings","Unit 4.0: Function, Recursion and Pointers Functions (including using built in libraries) Parameter passing in functions Call by value Passing arrays to functions: Recursion, as a different way of solving problems Example programs, such as Finding Factorial, Fibonacci series, Ackerman function etc. Idea of pointers Defining pointers Use of Pointers in self- referential structures Idea of call by reference","Functions (including using built in libraries)","Parameter passing in functions","Call by value","Passing arrays to functions: Recursion, as a different way of solving problems","Example programs, such as Finding Factorial, Fibonacci series, Ackerman function etc.","Idea of pointers","Defining pointers","Use of Pointers in self- referential structures","Idea of call by reference","Unit 5.0: User defined Data Types and File handling Structure: defining, declaring, initializing; accessing structure members, processing of structure, array of structures, structures within structure, structure and function, type definition Union: definition, declaration, accessing union members, initializing union Introduction, file declaration, opening and closing a file, working with text and binary files, I/O operations on file, error handling, random access to files","Structure: defining, declaring, initializing; accessing structure members, processing of structure, array of structures, structures within structure, structure and function, type definition","Union: definition, declaration, accessing union members, initializing union","Introduction, file declaration, opening and closing a file, working with text and binary files, I/O operations on file, error handling, random access to files"]},{"title":"Basic Algorithms","topics":["Searching","Basic Sorting Algorithms (Bubble, Insertion and Selection)","Finding roots of equations","Notion of order of complexity through example programs (no formal definition required)","Programming in ANSI C 4th Ed, E Balagurusamy, McGraw Hill Education India Private Limited, ISBN-978-9339219666, 7th Edition","The C Programming Language 2e, W. Kernighan / Dennis Ritchie, Pearson Education India, 978-9332549449, 2nd Edition","Computer Fundamentals and Programming in C, Reema Thareja, Oxford University Press, ISBN-978-9354977893, 3rd Edition"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Sheet Metal Working","topics":["Sheet material: GI sheets, aluminium, tin plate, copper, brass etc","Tools: steel rule, vernier callipers, micrometer, sheet metal gauge, scriber, divider, punches, chisels, hammers, snips, pliers, stakes etc.","Operations: scribing, bending, shearing, punching etc","Product development: hexagonal box with cap, funnel etc"]},{"title":"Joining","topics":["Classifications of joining processes","Brazing, Soldering, and Mechanical Joints","Arc welding, Gas welding etc","Unit 3.0: Pattern Making and Foundry Practice Pattern material: wood, cast iron, brass, aluminium, waxes etc. Types of patterns: split, single piece, match plate etc Tools: cope, drag, core, core prints, shovel, riddle, rammer, trowel, slick, lifter, sprue pin, bellow, mallet, vent rod, furnace etc Moulding sands: green sand, dry sand, loam sand, facing sand etc. Sand casting: Sand preparation, mould making, melting, pouring, and cleaning","Pattern material: wood, cast iron, brass, aluminium, waxes etc.","Types of patterns: split, single piece, match plate etc","Tools: cope, drag, core, core prints, shovel, riddle, rammer, trowel, slick, lifter, sprue pin, bellow, mallet, vent rod, furnace etc","Moulding sands: green sand, dry sand, loam sand, facing sand etc.","Sand casting: Sand preparation, mould making, melting, pouring, and cleaning"]},{"title":"Fitting Shop","topics":["Introduction to Fitting","Fitting Tools: Files and their classification, Holding Tools, Cutting Tools, Measuring and Marking Tools, Thread Making Tools, Various Fitting Power Tools","Methods Of Filing: Cross Filling and Draw Filing","Other associated operations Marking, Sawing and Chipping","Safety and Precautions in Fitting Shop","Unit 5.0: Carpentry Shop Introduction to Carpentry Shop Types of Wood Seasoning of Wood: Types of Seasoning Methods Defects in wood Structure of Wood Carpentry Tools: Measuring Tools, Marking Tools, Cutting Tools, Planning Tools, Drilling and Boring Tools, Holding Tools, Striking Tools, Auxiliary tools and materials used in Carpentry Wood working Processes Carpentry joints Wood Working Machines: Wood Working Lathe, Circular Saw, Thickness Planer, Band saw Safety and precautions in Carpentry Shop","Introduction to Carpentry Shop","Types of Wood","Seasoning of Wood: Types of Seasoning Methods","Defects in wood","Structure of Wood","Carpentry Tools: Measuring Tools, Marking Tools, Cutting Tools, Planning Tools, Drilling and Boring Tools, Holding Tools, Striking Tools, Auxiliary tools and materials used in Carpentry","Wood working Processes","Carpentry joints","Wood Working Machines: Wood Working Lathe, Circular Saw, Thickness Planer, Band saw","Safety and precautions in Carpentry Shop"]},{"title":"Smithy Shop","topics":["Introduction to Smithy Shop","Forging Tools and Equipment","Forging Operations: Drawing, Upsetting, Swaging, Punching, Drifting, Fullering, Bending","Hot Working Processes: Rolling, Drop Forging, Press Forging, Hot Extrusion, Hot Drawing","Cold Working Process","Safety and Precautions in Smithy Shop","Hajra Choudhury S.K., Hajra Choudhury A.K. And Nirjhar Roy S.K., \"Elements Of Workshop Technology\", Vol. I 2008 And Vol. II 2010, Media Promoters And Publishers Private Limited, Mumbai.","Kalpakjian S. And Steven S. Schmid, \"Manufacturing Engineering And Technology\", 4th Edition, Pearson Education India Edition, 2002.","Gowri P. Hariharan And A. Suresh Babu,\"Manufacturing Technology – I\" Pearson Education, 2008.","Roy A. Lindberg, \"Processes And Materials Of Manufacture\", 4th Edition, Prentice Hall India, 1998.","Rao P.N., \"Manufacturing Technology\", Vol. I And Vol. II, Tata Megrawhill House, 2017."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Energy Resources","topics":["Renewable or non-conventional sources of energy, their origin and various forms: solar, wind","Biogas and biomass energy, their merits & demerits, major applications: brief description","Non-renewable or conventional sources of energy: the fossil fuel","Coal, petroleum and natural gas"]},{"title":"Review of Basic Concepts Of Thermodynamics","topics":["Thermodynamics system, properties, state, processes and cycles","Heat, work and internal energy"]},{"title":"Steam Generators","topics":["Types of boilers, water-tube and fire-tube boilers: their merits and demerits","Boiler mountings and accessories: simple description"]},{"title":"Basic Concept of Refrigeration And Air Conditioning","topics":["Principles of working of vapour compression, vapour absorption and air refrigeration","Principles of air conditioning systems"]},{"title":"Prime Movers","topics":["Simple steam turbine, gas-turbine, IC engines (SI and CI), their brief description and principles of working","Power Plant: principles of working of thermal, hydel and nuclear power plants, work output and efficiency"]},{"title":"Engineering Materials and Their Properties","topics":["Ferrous and non-ferrous metals","Mechanical properties e.g. strength, hardness, resilience etc","Heat Treatment of Steel: Annealing, tempering, quenching, case-hardening etc","Basic Mechanical Engineering, By T J Prabhu","Element of Mechanical engineering, J.K .Kitlur, G.D.Gokak","Basic Mechanical Engineering, By Sadhu Singh","Element of Mechanical engineering, S. N. Lal"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Understanding the importance of cleanliness and sanitation: The course could aim to create awareness about the significance of cleanliness and sanitation in maintaining personal health, environmental sustainability, and community well-being. It could cover topics such as waste management, sanitation practices, and the impact of poor sanitation on public health.","Developing skills for effective waste management: The course could provide training on various waste management techniques, such as waste segregation, composting, recycling, and proper disposal of hazardous waste. It could also emphasize the importance of reducing waste generation and promoting sustainable waste management practices.","Promoting behavioural change towards cleanliness: The course could focus on influencing positive behavioural change among individuals and communities towards cleanliness. It could include modules on promoting good hygiene practices, creating awareness about the harmful effects of littering and open defecation, and encouraging responsible waste disposal habits.","Creating awareness about Swachh Bharat Mission initiatives: The course could provide information about the Swachh Bharat Mission initiatives and campaigns launched by the Government of India to promote cleanliness and sanitation, such as Swachh Survekshan, Swachh Bharat Abhiyan, and Clean India Campaign. It could also discuss the progress made, challenges faced, and future prospects of the Swachh Bharat Mission.","Engaging in community participation and advocacy: The course could emphasize the importance of community participation in the Swachh Bharat Mission and provide tools and strategies for engaging with local communities to promote cleanliness and sanitation. It could also encourage advocacy for policy changes and innovations to address sanitation-related issues at the community, regional, and national levels.","Upon completion, students may have:","Increased awareness and knowledge about cleanliness and sanitation: Participants of the course may gain a deeper understanding of the importance of cleanliness and sanitation, including the impact on personal health, environmental sustainability, and community well-being. They may learn about various waste management techniques, hygiene practices, and the initiatives of the Swachh Bharat Mission.","Enhanced skills for effective waste management: Participants may acquire practical skills related to waste management, such as waste segregation, composting, recycling, and proper disposal of hazardous waste. They may also develop skills in reducing waste generation and promoting sustainable waste management practices in their communities or workplaces.","Positive behavioral change towards cleanliness: The course may influence participants to adopt positive behavioral changes towards cleanliness, such as avoiding littering, practicing good hygiene habits, and promoting responsible waste disposal. Participants may develop a sense of responsibility towards maintaining cleanliness in their surroundings and actively contribute towards creating a cleaner environment.","Increased community participation and advocacy: Participants may become actively engaged in community participation and advocacy efforts related to cleanliness and sanitation. They may collaborate with local communities, government bodies, and non-governmental organizations (NGOs) to raise awareness, implement cleanliness initiatives, and advocate for policy changes or innovations to address sanitation-related issues.","Contribution towards Swachh Bharat Mission objectives: Participants may contribute towards the objectives of the Swachh Bharat Mission, such as promoting cleanliness, ensuring proper waste management, and eliminating open defecation. They may actively participate in Swachh Bharat Mission campaigns, initiatives, and activities, and make a positive impact on their communities and society at large.","Any topics related to Swatch Bharat Mission."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Determination of the capacitance and permittivity of the given material.","Determination of e/m of electron.","Determination of Planck''s constant and Photoelectric Work Function using Photoelectric cell.","Verification of inverse square law using photocell.","Determination of Wavelength of (He-Ne) LASER using Diffraction Grating Method.","Calculation of Energy Band Gap of a semiconductor.","Determination of Dielectric constant using resonance method.","Determination of Wavelength of Sodium light by measuring the diameter of the Newton''s Ring.","Determination of curvature of convex surface of a lens by Newton''s ring.","Verification of existence of Bohr''s Energy level with Frank-Hertz apparatus.","Determination of the Earth''s horizontal magnetic field intensity and magnetic Moment of a magnet by employing magnetometer.","Verification of Faraday''s Law and Lenz''s Law of Electromagnetic Induction."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Tutorial 1: Problem solving using computers. Lab 1: Familiarization with programming environment.","Tutorial 2: Variable types and type conversions. Lab 2: Simple computational problems using arithmetic expressions.","Tutorial 3: Branching and logical expressions. Lab 3: Problems involving if-then-else structures.","Tutorial 4: Loops, while and for loops. Lab 4: Iterative problems e.g., sum of series.","Tutorial 5: 1D Arrays: searching, sorting. Lab 5: 1D Array manipulation.","Tutorial 6: 2D arrays and Strings. Lab 6: Matrix problems, String operations.","Tutorial 7: Functions, call by value. Lab 7: Simple functions.","Tutorial 8 & 9: Numerical methods (Root finding, numerical differentiation, numerical integration). Lab 8 and 9: Programming for solving Numerical methods problems.","Tutorial 10: Recursion, structure of recursive calls. Lab 10: Recursive functions.","Tutorial 11: Pointers, structures and dynamic memory allocation. Lab 11: Pointers and structures.","Tutorial 12: File handling. Lab 12: File operations."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Learn and apply of different fitting tools –like work holding, marking, measuring, cutting, finishing and miscellaneous. Student will also prepare the report with sketch, specifications and applications of fitting tools demonstrated.","Prepare one simple and another male-female type fitting jobs as per given drawings (2 jobs)","Learn and apply of different tin smithy tools. Student will also prepare the report with sketch, specifications and applications of tin smithy tools demonstrated.","Learn and apply of welding equipments and making minimum one model.","Learn and apply of foundry tools and making minimum one model.","Learn and apply of carpentry tools and making minimum one model.","Learn and apply of Sheet Metal tools and making minimum one model.","Learn and apply of Lathe Tools & operations for making a job.","Learn and apply the application of measuring tools.","Learn and apply any casting process for making a model."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Demonstrate & study of steam boilers and its mounting & accessories.","Demonstrate & study the working of SI internal combustion Engines & its components.","To learn the mechanical properties of engineering materials.","To learn the working of steam power plant.","To learn the working of vapour compression refrigeration system.","To learn the working of impulse steam turbines.","To study the working of gas turbines.","To learn the working of reaction steam turbines.","To learn the working of vapour absorption refrigeration system.","Demonstrate & study the working of CI internal combustion Engines & its components."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Partial Differential Equations - I","topics":["Definition of Partial Differential Equations","First order partial differential equations","Solutions of first order linear PDEs","Solution to homogenous and non-homogenous linear partial differential equations of second order by complimentary function and particular integral method","Unit 2.0: Partial Differential Equations - II Second-order linear equations and their classification Initial and boundary conditions D''Alembert''s solution of the wave equation Duhamel''s principle for one dimensional wave equation Heat diffusion and vibration problems Separation of variables method to simple problems in Cartesian coordinates The Laplacian in plane, cylindrical and spherical polar coordinates Solutions with Bessel functions and Legendre functions One dimensional diffusion equation and its solution by separation of variables","Second-order linear equations and their classification","Initial and boundary conditions","D''Alembert''s solution of the wave equation","Duhamel''s principle for one dimensional wave equation","Heat diffusion and vibration problems","Separation of variables method to simple problems in Cartesian coordinates","The Laplacian in plane, cylindrical and spherical polar coordinates","Solutions with Bessel functions and Legendre functions","One dimensional diffusion equation and its solution by separation of variables","Unit 3.0: Probability - I Probability spaces, conditional probability, independence Discrete random variables, Independent random variables The multinomial distribution Poisson approximation to the binomial distribution Infinite sequences of Bernoulli trials Sums of independent random variables Expectation of Discrete Random Variables Moments, Variance of a sum Correlation coefficient, Chebyshev''s Inequality","Probability spaces, conditional probability, independence","Discrete random variables, Independent random variables","The multinomial distribution","Poisson approximation to the binomial distribution","Infinite sequences of Bernoulli trials","Sums of independent random variables","Expectation of Discrete Random Variables","Moments, Variance of a sum","Correlation coefficient, Chebyshev''s Inequality"]},{"title":"Probability - II","topics":["Continuous random variables and their properties","Distribution functions and densities","Normal, exponential and gamma densities","Bivariate distributions and their properties","Distribution of sums and quotients","Conditional densities, Bayes'' rule"]},{"title":"Basic Statistics","topics":["Measures of Central tendency: Moments, skewness and Kurtosis","Probability distributions: Binomial, Poisson and Normal","Evaluation of statistical parameters for these three distributions","Correlation and regression","Rank correlation","Curve fitting by the method of least squares","Fitting of straight lines, second degree parabolas and more general curves"]},{"title":"Test of Significance","topics":["Large sample test for single proportion, difference of proportions","Tests for single mean, difference of means, and difference of standard deviations","Test for ratio of variances","Chi-square test for goodness of fit and independence of attributes","Erwin Kreyszig, Advanced Engineering Mathematics, 9th Edition, John Wiley & Sons, 2006.","N.P. Bali and Manish Goyal, A text book of Engineering Mathematics, Laxmi Publications.","P. G. Hoel, S. C. Port and C. J. Stone, Introduction to Probability Theory, Universal Book Stall.","S. Ross, A First Course in Probability, 6th Ed., Pearson Education India, 2002."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Engineering Material Introduction Classification of Engineering Materials Structure","topics":["Introduction","Classification of Engineering Materials","Structure of Metals and Alloys","Iron-carbon phase diagram"]},{"title":"Heat Treatment of Iron & Steel","topics":["Different types of Steel","Properties and uses of Steel","Different types of Heat Treatment Techniques viz. Hardening, Annealing, Normalizing & Tempering","Uses in Mining Industry"]},{"title":"Wire Rope","topics":["Types and Construction","Wire Rope Lays","Non-Stranded Ropes","Selection of Wire Ropes","Ropes used for different purposes","Mass & Strength of Wire Ropes"]},{"title":"Construction Materials I","topics":["Types and uses","Cement: Classification & Properties","Quick Setting Cement","Resin Capsule","R.C.C.","Shot Encapsulization","Shotcreting etc"]},{"title":"Construction Materials II","topics":["Brick & Stone Masonries","Hollow blocks","Application of Fly Ash in Mining"]},{"title":"Engineering Behavior of Materials","topics":["Introduction","Stress-Strain Curves of typical Engineering Materials","Elastic and Plastic Deformation","Fracture, Fatigue and Creep","Engineering Materials: Properties and Selection, Kenneth G. Budinski, Michael K. Budinski, Prentice Hall & 0137128428, 9780137128426.","Principles of Materials Science and Engineering, Smith, William F, New York : McGraw-Hill & 0070585210.","Introduction to engineering materials, B. K. Agrawal, McGraw-Hill.","Elements of Mining Technology, Vol. 1, 8th Edition, D. J. Deshmukh Denett & Company and 8189904337, 9788189904333.","Engineering Materials, Surendra Singh, Stosius Inc/Advent Books Division & 8122000525, 9788122000528."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Exploratory Drilling","topics":["Drilling machines used for exploratory drilling viz. Rotary & Percussive, their attachments","Core Barrels","Conditions of applicability of drilling methods","Borehole Survey","Directional drilling","Underground methods of exploratory drilling"]},{"title":"Drivage of Inclines/Drifts/Adits","topics":["Types of Openings","Selection of Openings","Location of Openings","Drilling, blasting, loading and transportation of muck during drivage of inclines, adits, drifts","Ventilation, lighting and drainage","Extension of centerline","Organization and cycle of operations","Mechanised methods of drivages of inclines, adits, drifts"]},{"title":"Shaft Sinking","topics":["Drilling, blasting, loading and transportation of muck","Ventilation, lighting and drainage","Extension of center line","Shaft lining and its design","Special methods of shaft sinking","Shaft boring","Deepening and widening of shafts","Upward drivage","Organization and cycle of operations"]},{"title":"Introduction to Underground Mining I","topics":["Definition of important terms","Mine development","Activities involved in the development of a mine","Stages in the life of a mine"]},{"title":"Introduction to Underground Mining II","topics":["Introduction to unit operations in underground mining","Introduction to various Underground Mining methods","Selection of method of mining based on different conditions"]},{"title":"Introduction to Surface Mining","topics":["Definition of important terms","Advantages and disadvantages of surface mining","Mineral deposits amenable to surface mining","Various surface mining methods","Introduction to unit operations in surface mining","Mining Engineers'' Handbook, Volume 1 and 2, third edition, Edited by Peele, Robert, and John A. Church, John Wiley & Sons, New York.","Elements of Mining Technology Vol. 1, 8th Edition D. J. Deshmukh, Denett & Company and 8189904337, 9788189904333.","Elements of Mining Technology Vol. 3, 8th Edition D. J. Deshmukh, Denett & Company and 8189904353, 9788189904357.","Modern Coal Mining Technology, Samir Kumar Das, Lovely Prakashan.","Principles and Practices of Modern Coal Mining, R. D. Singh, New Age International and 8122409741, 9788122409741.","Surface Mining, G.B. Mishra Dhanbad Publishers.","SME Mining Engineering Handbook 3rd Edition, Edited by Peter Darling SME & 978-0-87335-264-2."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Mine Atmosphere","topics":["Composition of Mine Atmosphere","Mine Gases, their Origin, Occurrence, Physiological effects and Detection","System for Monitoring of Mine Environment by Tube bundle apparatus and Tele-monitoring systems with related Case Studies","Analysis of Mine air by Haldane Apparatus, Gas Chromatograph","Methane Drainage","Unit 2.0: Heat, Humidity and Dust Heat and Humidity in Mine Atmosphere, Their Sources and Effects Cooling Power of Mine Air Assessment of Comfort Conditions Heat Stress Air Conditioning of Mines Spot Coolers Mine Dust: Classification and Physiological Effects Measurement of Dust Concentration Dynamics of Small Particles and its importance in mining Sampling of Air Borne Dust Prevention and Suppression of Dust","Heat and Humidity in Mine Atmosphere, Their Sources and Effects","Cooling Power of Mine Air","Assessment of Comfort Conditions","Heat Stress","Air Conditioning of Mines","Spot Coolers","Mine Dust: Classification and Physiological Effects","Measurement of Dust Concentration","Dynamics of Small Particles and its importance in mining","Sampling of Air Borne Dust","Prevention and Suppression of Dust"]},{"title":"Theory of Ventilation","topics":["Objects and Standards of Ventilation","Flow of Air in Ducts and Mine Roadways","Resistance of Air Ways","Laws of Ventilation","Chezy''s and Atkinson''s Equations","Equivalent Resistance and Equivalent Orifice of Mine"]},{"title":"Mine Ventilation and Ventilation Devices","topics":["Natural Ventilation Pressure and its Measurements","Thermodynamics of Natural Ventilation","Distribution and Control of Air Current","Doors, Regulators, Stopping and their Types","Air Crossings","Air Locks"]},{"title":"Flame Safety Lamps","topics":["Constructional details of Flame Safety Lamp","Types of Portable Lamps, their Maintenance and Examination","Gas Testing by Flame Safety Lamp","Lamp Room Design and Organization"]},{"title":"Mine Illumination","topics":["Lighting from Mains","Photometry and Illumination Surveys","DGMS Standards of Illumination for Underground and Open Cast Working","Mine Environment and Ventilation, G. B. Misra, Oxford University Press & 0195622324, 9780195622324.","Subsurface Ventilation and Environmental Engineering, M.J. McPherson, Springer Science & Business Media, 9401115508, 9789401115506.","Elements of Mining Technology Vol. 2, 8th Edition, D. J. Deshmukh, Denett & Company and 8189904345, 9788189904340.","Mine Ventilation Engineering, C. J. Hall, Society for Mining Metallurgy & 0895202735."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Geology","topics":["Geology: Definition, its branches, and scope emphasising mining engineering","Internal structure of the earth","The basic idea on Plate Tectonics","Brief study of important landforms"]},{"title":"Introduction to Minerals","topics":["Minerals: Definition","Physical Properties of Minerals","Classification of Minerals","Study of important Rock-forming minerals concerning their physical properties","Significance of Rock-forming minerals"]},{"title":"Petrology and Indian Geology","topics":["Rocks: Definition and types of rocks","Origin, Textures, Structures and Classification of Rocks","Petrographic Description of Common Rocks","Significance of Rocks","Standard Geological Time Scale","Brief on important Geological Units of India and their Economic significance"]},{"title":"Structural Geology","topics":["Concept of Rock Deformation","Attitudes of strata: Dip and strike","Study of Unconformity","Folds, Joints, Faults and their Influence in Mining Operations","Concept of geological maps, its importance","Contours and important terminology used for map","Topography and its representations","Making a geological section from the Geological maps and its description"]},{"title":"Economic Geology","topics":["Genetic Classification of Mineral Deposits and its Distribution and Morphology of Minerals Deposits","Mode of Occurrence, Origin, Distribution, Association and Industrial uses of important Metallic Minerals and Non-Metallic Minerals","Coal and Petroleum deposits of India"]},{"title":"Prospecting and Exploration","topics":["Introduction: Prospecting and Exploration: their definitions and classification of methods","Methods and Guides: Elementary methods of Geological, Geophysical, and Geochemical prospecting","Guides to Ores: Ringed Targets, Intersection Loci, Physiographical, Mineralogical, Stratigraphical and Structural Guides to Ores","Textbook of Physical Geology, 2018, G.B. Mahapatra, CBS Publishers & Distributors Pvt Ltd, India & 8123901100, 9788123901107.","Earth Materials, 1st publication, 2010, Kevin Hefferan, John O''Brien, John Wiley & Sons & 1444391216, 9781444391213.","Rutley''s elements of mineralogy, 27th Edition, 1988, C.D. Gribble Unwin, Hyman Ltd. & 9401168326, 9789401168328.","Economic Geology, 2nd Edition, 2019, Umeswar Prasad, CBS Publication & 9788123904603, 978-8123904603.","Courses in Mining Geology, 4th edition, 2017, R. N. P. Arogyaswamy, Oxford & IBH & 812040937X, 9788120409378.","Mineralogy, 3rd Edition, 2011, Dexter Perkins, Pearson Publication & 0321663063, 978-0321663061.","Geology of India (Vol. I) 2008, M. Ramakrishnan & R. Vaidyanadhan, Geological Society of India & 8185867984, 9788185867984.","Geology of India (Vol. II) 2008, M. Ramakrishnan & R. Vaidyanadhan, Geological Society of India & 818586778X, 9788185867786."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Basics Programming Syntax, Conditional and Iterative Statements Procedure oriented vs. Object-Oriented approach of programming Python character set, Python tokens, variables, concept of Lvalue and Rvalue, use of comments Data types: number (integer, floating point, complex), Boolean, sequence (string, list, tuple), none, mapping (dictionary), mutable and immutable data types Operators: arithmetic operators, relational operators, logical operators, assignment operator, augmented assignment operators Expressions, statement, type conversion & input/output: precedence of operators, expression, evaluation of expression Conditional statements: simple if statement, if-else statement, if-elif-else statement Iterative statements: while loop, for loop, range function, break and continue statements, nested loops","Procedure oriented vs. Object-Oriented approach of programming","Python character set, Python tokens, variables, concept of Lvalue and Rvalue, use of comments","Data types: number (integer, floating point, complex), Boolean, sequence (string, list, tuple), none, mapping (dictionary), mutable and immutable data types","Operators: arithmetic operators, relational operators, logical operators, assignment operator, augmented assignment operators","Expressions, statement, type conversion & input/output: precedence of operators, expression, evaluation of expression","Conditional statements: simple if statement, if-else statement, if-elif-else statement","Iterative statements: while loop, for loop, range function, break and continue statements, nested loops","Unit 2.0: String, List, Tuples, Set and Dictionary String: indexing, string operations (concatenation, repetition, membership & slicing), traversing a string using loops, built-in functions Lists: introduction, indexing, list operations: concatenation, repetition, membership & slicing, traversing a list, built-in list functions Linear search on list of numbers and counting the frequency of elements in a list Tuples: Creating, initializing, accessing elements, tuple assignment, performing operations on tuples, tuple methods and built-in functions, nested tuples Set: Creating set, traversing, adding, removing data in set, performing set operations like join, Union intersection, difference Dictionary: accessing items in a dictionary using keys, mutability of dictionary: adding a new item, modifying an existing item, built-in dictionary functions","String: indexing, string operations (concatenation, repetition, membership & slicing), traversing a string using loops, built-in functions","Lists: introduction, indexing, list operations: concatenation, repetition, membership & slicing, traversing a list, built-in list functions","Linear search on list of numbers and counting the frequency of elements in a list","Tuples: Creating, initializing, accessing elements, tuple assignment, performing operations on tuples, tuple methods and built-in functions, nested tuples","Set: Creating set, traversing, adding, removing data in set, performing set operations like join, Union intersection, difference","Dictionary: accessing items in a dictionary using keys, mutability of dictionary: adding a new item, modifying an existing item, built-in dictionary functions","Unit 3.0: Python Functions, Modules and Packages Functions: types of function (built-in functions, functions defined in module, user defined functions) Creating user defined function, arguments and parameters, default parameters, positional parameters Lambda functions, returning value, scope of a variable: global scope, local scope Modules and Packages: Importing module using ''import'' Regular Expressions, Exception Handling PyPI Python Package Index, Pip Python package manager Importing Libraries and Functions","Functions: types of function (built-in functions, functions defined in module, user defined functions)","Creating user defined function, arguments and parameters, default parameters, positional parameters","Lambda functions, returning value, scope of a variable: global scope, local scope","Modules and Packages: Importing module using ''import''","Regular Expressions, Exception Handling","PyPI Python Package Index, Pip Python package manager","Importing Libraries and Functions","Unit 4.0: Object-Oriented Programming (OOP) OOPs Object oriented programming concepts and approach Abstraction, encapsulation, class, object Class method vs static method in Python Class and static variable Constructor and destructors in python Inheritance: types of inheritance: single, multiple, multilevel, hierarchical Polymorphism: Polymorphism with class method, polymorphism with inheritance, method overriding, overloading","OOPs Object oriented programming concepts and approach","Abstraction, encapsulation, class, object","Class method vs static method in Python","Class and static variable","Constructor and destructors in python","Inheritance: types of inheritance: single, multiple, multilevel, hierarchical","Polymorphism: Polymorphism with class method, polymorphism with inheritance, method overriding, overloading","Unit 5.0: Exception and File Handling in Python Exception Handling: syntax errors, exceptions, need of exception handling, user-defined exceptions, raising exceptions, handling exceptions, catching exceptions Try - except - else clause, Try - finally clause, recovering and continuing with finally Built-in exception classes File Handling: text file and binary file, file types, open and close files Reading and writing text files, reading and writing binary files, file access modes","Exception Handling: syntax errors, exceptions, need of exception handling, user-defined exceptions, raising exceptions, handling exceptions, catching exceptions","Try - except - else clause, Try - finally clause, recovering and continuing with finally","Built-in exception classes","File Handling: text file and binary file, file types, open and close files","Reading and writing text files, reading and writing binary files, file access modes","Unit 6.0: Data Analysis with Pandas Pandas data structures: Series, Declaration, selecting elements, assigning values, Filtering values, operations, mathematical functions, evaluating values, handling missing data, creating series from dictionaries, adding two series Data Frame: Defining, selecting elements, assigning values, membership, deleting a column, filtering Index Objects: Indexing, Re-indexing, Dropping, sorting and ranking, Descriptive Statistics Data Loading: Reading and Writing csv, xls, text data files Data Cleaning and Preparation: Handling missing data, removing duplicates, replacing values Vectorized String Methods, Hierarchical Indexing, Merging and Combining, Data aggregation and Grouping","Pandas data structures: Series, Declaration, selecting elements, assigning values, Filtering values, operations, mathematical functions, evaluating values, handling missing data, creating series from dictionaries, adding two series","Data Frame: Defining, selecting elements, assigning values, membership, deleting a column, filtering","Index Objects: Indexing, Re-indexing, Dropping, sorting and ranking, Descriptive Statistics","Data Loading: Reading and Writing csv, xls, text data files","Data Cleaning and Preparation: Handling missing data, removing duplicates, replacing values","Vectorized String Methods, Hierarchical Indexing, Merging and Combining, Data aggregation and Grouping","Introduction to Computing and Problem-Solving using Python, E. Balagurusamy, McGraw Hill Education (India) Pvt. Ltd. 1st Edition /2016, ISBN-10: 9352602587 ISBN-13: 978-9352602582.","Core Python Applications Programming, Wesley J. Chun, 3rd Edition, Pearson Education, 2016, ISBN-10: 0132678209 ISBN-13: 978-0132678209.","Python Cookbook, David Beazley, Brian Jones., Third Edition, Orelly Publication, 2013, ISBN 978-1449340377.","Python Data Analytics, Fabio Nelli, Apress, 2015, ISBN: 9781484209585.","Python for Data Analysis: Data Wrangling with Pandas, Numpy, and IPython, Wes McKinney, O''REILLY, 2017, Second Edition ISBN-10: 1491957662 ISBN-13: 78-1491957660."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction to Value Education Right Understanding, Relationship and Physical Facility (Holistic Development and the Role of Education) Understanding Value Education Sharing about Oneself Self-exploration as the Process for Value Education Continuous Happiness and Prosperity: the Basic Human Aspirations Exploring Human Consciousness, Happiness and Prosperity: Current Scenario Method to Fulfill the Basic Human Aspirations","Right Understanding, Relationship and Physical Facility (Holistic Development and the Role of Education)","Understanding Value Education Sharing about Oneself","Self-exploration as the Process for Value Education","Continuous Happiness and Prosperity: the Basic Human Aspirations","Exploring Human Consciousness, Happiness and Prosperity: Current Scenario","Method to Fulfill the Basic Human Aspirations"]},{"title":"Harmony in the Human Being","topics":["Understanding Human being as the Co-existence of the Self and the Body","Distinguishing between the Needs of the Self and the Body","The Body as an Instrument of the Self","Understanding Harmony in the Self","Harmony of the Self with the Body","Programme to ensure self-regulation and Health"]},{"title":"Harmony in the Family and Society","topics":["Harmony in the Family: the Basic Unit of Human Interaction","''Trust'': the Foundational Value in Relationship","''Respect'': as the Right Evaluation","Other Feelings","Justice in Human-to-Human Relationship","Understanding Harmony in the Society","Vision for the Universal Human Order"]},{"title":"Harmony in the Nature/Existence","topics":["Understanding Harmony in the Nature","Interconnectedness, self-regulation and Mutual Fulfilment among the Four Orders of Nature","Realizing Existence as Co-existence at All Levels","The Holistic Perception of Harmony in Existence","Unit 5.0: Implications of the Holistic Understanding – a Look at Professional Natural Acceptance of Human Values Definitiveness of (Ethical) Human Conduct A Basis for Humanistic Education Humanistic Constitution and Universal Human Order Competence in Professional Ethics Holistic Technologies, Production Systems and Management Models: Typical Case Studies Strategies for Transition towards Value-based Life and Profession","Natural Acceptance of Human Values","Definitiveness of (Ethical) Human Conduct","A Basis for Humanistic Education","Humanistic Constitution and Universal Human Order","Competence in Professional Ethics","Holistic Technologies, Production Systems and Management Models: Typical Case Studies","Strategies for Transition towards Value-based Life and Profession"]},{"title":"Competence in Professional Ethics","topics":["Holistic Technologies, Production Systems and Management Models: Typical Case Studies","Strategies for Transition towards Value-based Life and Profession","A Foundation Course in Human Values and Professional Ethics, R R Gaur, R Asthana, G P Bagaria, 2nd Revised Edition, Excel Books, New Delhi, 2019. ISBN 978-93-8703447.","Jeevan Vidya: Ek Parichaya, A Nagaraj, Jeevan Vidya Prakashan, Amarkantak, 1999.","Human Values, A.N. Tripathi, New Age Intl. Publishers, New Delhi, 2004.","The Story of Stuff (Book)","The Story of My Experiments with Truth – by Mohandas Karamchand Gandhi","Small is Beautiful – E. F Schumacher","Slow is Beautiful – Cecile Andrews","Economy of Permanence – J C Kumarappa","Bharat Mein Angreji Raj – Pandit Sunderlal","Rediscovering India – by Dharampal","Hind Swaraj or Indian Home Rule – by Mohandas K. Gandhi","India Wins Freedom – Maulana Abdul Kalam Azad","Vivekananda – Romain Rolland (English)","Gandhi – Romain Rolland (English)"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Indian Knowledge Systems","topics":["Overview of IKS","Organization of IKS","Conception and constitution of knowledge in indian tradition","The oral tradition","Models and Strategies of IKS"]},{"title":"Overview of IKS Domains","topics":["The vedas as the basis of IKS","Overview of all the six vedangas"]},{"title":"Relevance in Current Technical Education System I","topics":["Relevance of following IKS domains in present technical education system: Arthashastra (Indian economics and political systems)","Ganita and Jyamiti (indian mathematics, astronomy and geometry)","Rasayana (indian chemical Sciences)"]},{"title":"Relevance in Current Technical Education System II","topics":["Ayurveda (Indian Biological Sciences / Diet & Nutrition)","Jyotish Vidya (observational astronomy and calendar systems)","Prakriti Vidya (indian system of terrestrial/ material sciences/ecology and atmospheric sciences)"]},{"title":"Relevance in Current Technical Education System III","topics":["Vastu Vidya (indian system of aesthetics-iconography and built-environment /architecture)","Nyaya Shastra (indian systems of social ethics, logic and law)"]},{"title":"Shilpa and Natya Shastra","topics":["Shilpa and Natya Shastra (indian classical arts: performing and fine arts)","Sankhya and Yoga Darshna (indian psychology, yoga and consciousness studies)","Virkshayurveda (plant science/sustainable agriculture/food preservation methods)","Introduction to Indian Knowledge System: Concepts and Applications, Archak, K.B. (2012), Kaveri Books, New Delhi, ISBN-13: 978-9391818203","Introduction To Indian Knowledge System: Concepts and Applications, Mahadevan, B. Bhat, Vinayak Rajat, Nagendra Pavana R.N., PHI, ISBN: 9789391818203.","Glimpse into Kautilya''s Arthashastra Ramachandrudu P. (2010), Sanskrit Academy, Hyderabad, ISBN: 9788380171074.","\"Introduction\" in Studies in Epics and Puranas, (Eds.), KM Munshi and N Chandrashekara Aiyer Bhartiya Vidya Bhavan."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Megascopic identification and description of Rock Forming Minerals.","Megascopic identification and description of important Rocks.","Practices on Basic Concept of Contours, Attitude of Beds, Width of Outcrop, True and Apparent Dips.","Study of ecological Maps, preparation and description of Geological Cross Sections.","Megascopic identification, description and distribution of Ore Forming Minerals and Industrial Minerals.","Plotting of important Mineral deposits / mine locations on map of India."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Experiment 1: a) Download and Install IDLE. Write and execute Python program to- b) Calculate the Area of a Triangle where its three sides a, b, c are given. s=(a+b+c)/2, Area=square root of s(s-a)(s-b)(s-c) (write program without using function) c) Swap Two Variables d) Solve quadratic equation for real numbers.","Experiment 2: Write and execute Python program to- a) Check if a Number is Positive, Negative or zero. b) Check whether the given year is a Leap Year. c) Print all Prime Numbers in an Interval. d) Display the multiplication Table based on the given input. e) Print the Fibonacci sequence. f) Find the Factorial of a Number.","Experiment 3: Write and execute Python program to- a) Check whether the string is Palindrome b) Reverse words in a given String in Python c) Identify in a strings the name, position and counting of vowels. d) Count the Number of matching characters in a pair of string (set) e) Python program for removing i-th character from a string","Experiment 4: Write and execute Python program to- a) Find largest number in a given list without using max(). b) Find the common numbers from two lists. c) Create a list of even numbers and another list of odd numbers from a given list. d) To find number of occurrences of given number without using built-in methods.","Experiment 5: Write and execute Python program to- a) Find the index of an item of a tuple. b) Find the length of a tuple. c) To reverse a tuple. d) Write a Python program to sort a list of tuple by its float element. Sample data: [(''item1'', ''12.20''), (''item2'', ''15.10''), (''item3'', ''24.5'')] Expected Output: [(''item3'', ''24.5''), (''item2'', ''15.10''), (''item1'', ''12.20'')]","Experiment 6: Write and execute Python program to- a) Create an intersection of sets. b) Create a union of sets. c) Create set difference. d) Check if two given sets have no elements in common.","Experiment 7: Write and execute Python program to- a) Write a Python script to concatenate two dictionaries to create a new one b) Write a Python script to merge two Python dictionaries. c) Write a Python program to combine two dictionary adding values for common keys. d1 = {''a'': 100, ''b'': 200, ''c'':300} d2 = {''a'': 300, ''b'': 200, ''d'':400} Sample output: d({''a'': 400, ''b'': 400, ''d'': 400, ''c'': 300})","Experiment 8: Write and execute Python program to- a) Write a Python function for reversing a string and call it. b) Write a Python function for calculating compound interest and call it. c) Write a Python function for calculating the factorial of a number and call it to calculate ln/(lr)*!(n-r)) where symbol ''!'' stands for factorial.","Experiment 9: Write program using OOP approach to – a) Create an instance of a specified class and display the namespace of the said instance. b) Create a Python class named Student with two attributes: student_id, student_name. Add a new attribute: student_class. Create a function to display all attributes and their values in the Student class. c) Create a Python class named Student with two instances student1, student2 and assign values to the instances'' attributes. Print all the attributes of the student1, student2 instances. d) Write programs to demonstrate use of following types of inheritance: i. Single inheritance ii. Multiple inheritance iii. Multilevel inheritance e) Demonstrate use of polymorphism with following situations: i. Polymorphism in operator ii. Polymorphism in user defined method iii. Polymorphism in built-in function iv. Polymorphism with class method v. Polymorphism with method overriding","Experiment 10: a) Using exception handling feature such as try…except, try finally- write minimum three programs to handle following types of exceptions. i. TypeError ii. NameError iii. IndexError iv. KeyError v. ValueError vi. IOError vii. ZeroDivisionError b) Write Python program to demonstrate file operations.","Experiment 11: Working with a Series using Pandas a) Create a series using list and dictionary. b) Create a series using NumPy functions in Pandas. c) Print the index and values of series. d) Print the first and last few rows from the series.","Experiment 12: Working with Data Frame Rows a) Slicing Data Frame using loc and iloc. b) Filter multiple rows using isin. c) Select first n rows and last n rows. d) Select rows randomly n rows and fractions of rows (use df. sample method). e) Count the number of rows with each unique value of variables. f) Select alargest and nsmallest values. g) Order/sort the rows.","Experiment 13: Merge and combine data a) Perform the append, concat and combine first operations on Data Frames. b) Apply different types of merge on data. c) Use a query method to filter Data Frame with multiple conditions."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Internship I is of a minimum duration of two weeks which can be completed in an Industry/Institute in consultation with concerned Engineering College/Institute. After completion of Internship a detailed report of the Internship mentioning the training undertaken along with certificate should be submitted."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction","topics":["Status of Surface Mining in India","Selection Between Surface Mining and Underground Mining","Preliminary Evaluation of Surface Mining Prospects","Different Stripping Ratios - Concepts and Significance","Surface Mining Equipment Systems - Classification","Applicability","Advantages and Disadvantages"]},{"title":"Unit Operations of Surface","topics":["Drill and Blast Operations - Concept","Application","Selection","Limitation","Types of Loading Equipment","Their Selection and Limitations Such as - Shovels","Draglines","Bucket Wheel Excavators","Continuous Surface Miners","Front End Loaders","Scrappers","Etc"]},{"title":"Mode of Transport","topics":["Type and Mode of Transport and Their Selection Criteria - Dumpers","Conveyors","Pipe Line Transport System","Operation","Application","Limitations","Types of Dumps and Their Formation - Internal and External Dumps","Design of Dumps"]},{"title":"Mine Development and Mine Expansion","topics":["Opening up of Mine - Ore Access and Box Cut Operation (Location, Geometry, Design etc of Box Cut)","Pit Expansion and Push Back Operation","Types of Push Back Operation and Factors Affecting the Push Back Operation"]},{"title":"Production Benches","topics":["Geometrical Parameters of the Benches","Bench Height","Bench Slope","Bench Width etc With Regard to the Geometry of the Deposits and Overlying Rocks","Formation Parameters and Factors Affecting Their Selection"]},{"title":"Selective Mining Technique","topics":["Application of Continuous Surface Miner","Economics of Surface Miner Technology","Mining Methods and Equipment System for Nonstratified Deposit","High-Wall Mining Operations in Surface Mine","Mining of Dimension Stones - Mining Methods and Equipment System","Surface Mining [Edited by] Eugene P. Pfleider. American Institute of Mining, Metallurgical and Petroleum Engineers, 1968, New York","Surface Mining by Bruce A Kennedy; Society for Mining, Metallurgy, and Exploration (U.S.), Publisher: Littleton, Colo.: Society for Mining, Metallurgy, and Exploration, 1990","Surface Mining Equipment Hardcover -1982 by James W. Martin","Surface Mining by G B Mishra","Introductory Mining Engineering - Howard L. Hartman and Jan M. Mutamansky, 2002","SME Mining Engineering Hand Book (Third Edition)- Peter Darling, 2011","Open Pit Mine Planning & Design - W.Hustrulid and M. Kuchta","Surface Mining (Second Edition)- Bruce A. Kennedy","South African Colliery Manager''s Association (SCMA) Hand book - 2005","Technical Literatures of Various Mining Software Deployed in Global Surface Mining Operation","Technical Research Papers on Subject","SME Handbook by H L Hartman"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Applicability of Mining Method","topics":["Introduction - Coal and Characteristics of Coal Deposits","Choice of Methods of Mining Coal Seams","Factors Affecting Choice of Mining Methods","In-Seam and Horizon Mining","Underground Coal Mining Methods","Comparison of Underground Mining Methods"]},{"title":"Opening of Coal Seams","topics":["Types of Mine Entries (Shaft, Incline, Adit)","Relative Advantages and Disadvantages","Location of Entries"]},{"title":"Operations of Shaft Sinking","topics":["Shaft Sinking Operations: Ground Breaking and Muck Disposal Tools and Equipment","Lining","Ventilation","Sinking in Difficult and Water-Bearing Ground","An Overview of Mechanized Shaft Sinking"]},{"title":"Bord & Pillar Development","topics":["General Principle of Bord & Pillar Development","Their Choice","Suitability","Advantages and Disadvantages","Open and Panel Systems","Layout of Bord & Pillar Panel","Size of Panel and Statutory Provisions","Concurrent Development Activities Like Support","Track Laying","Lighting","Transportation of Materials and Minerals in and out of the Mine etc"]},{"title":"Pillar Extraction","topics":["Preparatory Arrangement for Depillaring Operation","Statutory Provision for Depillaring","Principle and Designing of Pillar Extraction","Size of a District","Factors Affecting Choice of Pillar Extraction","Depillaring with Caving","Stowing","Mechanized Depillaring Operation","Organization and Safety","Unit-6.0 - Longwall Method of Mining Longwall Methods of Working Their Choice Suitability Advantages and Disadvantages Shape & Size of Development Roadways and Gate Roads and Their Maintenance Support Systems of Longwall Face and Gate Roads Layout of the Workings for the Required Output Length and Orientation of Longwall Faces Advancing and Retreating Longwall Faces Longwall Face and Gate Road Machineries Mechanized Longwall Faces with Shearers AFC Power Support and Gate Road Machineries","Longwall Methods of Working","Their Choice","Suitability","Advantages and Disadvantages","Shape & Size of Development Roadways and Gate Roads and Their Maintenance","Support Systems of Longwall Face and Gate Roads","Layout of the Workings for the Required Output","Length and Orientation of Longwall Faces","Advancing and Retreating Longwall Faces","Longwall Face and Gate Road Machineries","Mechanized Longwall Faces with Shearers","AFC","Power Support and Gate Road Machineries","Principles and Practices of Coal Mining by R.D Singh","Underground Winning of Coal by T N Singh","SME Mining Engineering Handbook","Longwall Mining by Peng and Chiang","Coal Mine Ground Control: Syed Pen"]}]'::jsonb from s;
