insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction Classification Of Mine Hazards: Physical, Chemical, Mechanical, Environmental, And Human-Related Common Causes Of Accidents In Mines: Roof Fall, Inundation, Explosion, Fire, Machinery Accidents, Etc Accident Statistics And Trends In Indian And Global Mining Sectors Accident Investigation, Root Cause Analysis, And Reporting Procedures DGMS Accident Classification And Definitions (Serious, Fatal, Dangerous Occurrence)","Classification Of Mine Hazards: Physical, Chemical, Mechanical, Environmental, And Human-Related","Common Causes Of Accidents In Mines: Roof Fall, Inundation, Explosion, Fire, Machinery Accidents, Etc","Accident Statistics And Trends In Indian And Global Mining Sectors","Accident Investigation, Root Cause Analysis, And Reporting Procedures","DGMS Accident Classification And Definitions (Serious, Fatal, Dangerous Occurrence)","Unit 2.0: Mine Fires, Explosions, And Inundations (9 hrs) Causes And Types Of Mine Fires: Surface, Underground, Spontaneous Heating Detection, Prevention, And Control Of Mine Fires Learn About Fire Detection, Alarm Systems, And Communication Protocols Explosion Hazards: Firedamp, Coal Dust, And Their Preventive Measures Practice Use Of Firefighting Equipment: Extinguishers, Hoses, And Self-Breathing Apparatus (SBA) Inundation: Causes, Precautions During Working Near Old, Waterlogged Areas, Protective Barriers, And Drainage Methods Case Studies Of Major Mine Disasters (E.G., Chasnala, Raniganj, New Kenda)","Causes And Types Of Mine Fires: Surface, Underground, Spontaneous Heating","Detection, Prevention, And Control Of Mine Fires","Learn About Fire Detection, Alarm Systems, And Communication Protocols","Explosion Hazards: Firedamp, Coal Dust, And Their Preventive Measures","Practice Use Of Firefighting Equipment: Extinguishers, Hoses, And Self-Breathing Apparatus (SBA)","Inundation: Causes, Precautions During Working Near Old, Waterlogged Areas, Protective Barriers, And Drainage Methods","Case Studies Of Major Mine Disasters (E.G., Chasnala, Raniganj, New Kenda)","Unit 3.0: Mine Gases, Ventilation Emergencies, And Environmental Hazards Introduction To Mine Gases, Properties, Detection, And Physiological Effects Of Mine Gases (CH₄, CO, CO₂, H₂S, NOx, Etc) Ventilation System Failures And Emergency Response Heat, Humidity, Noise, Dust, And Vibration Hazards: Control And Monitoring Gas Detection Equipment, Alarms, And Continuous Monitoring Systems Occupational Health Hazards And Environmental Management In Mines","Introduction To Mine Gases, Properties, Detection, And Physiological Effects Of Mine Gases (CH₄, CO, CO₂, H₂S, NOx, Etc)","Ventilation System Failures And Emergency Response","Heat, Humidity, Noise, Dust, And Vibration Hazards: Control And Monitoring","Gas Detection Equipment, Alarms, And Continuous Monitoring Systems","Occupational Health Hazards And Environmental Management In Mines","Unit 4.0: Mine Rescue Organization And Equipment Outline Rescue Team Structure And Roles: Captain, Gasman, Mapman, First Aiders Roles And Responsibilities Of Rescue Personnel And Team Composition Types Of Breathing Apparatus: Self-Contained, Self-Rescuer, Oxygen Apparatus, And Maintenance Rescue Tools And Communication Systems Rescue Operations In Fire, Explosion, And Inundation: Procedures And Protocols First Aid In Mine Accidents And Casualty Handling","Outline Rescue Team Structure And Roles: Captain, Gasman, Mapman, First Aiders","Roles And Responsibilities Of Rescue Personnel And Team Composition","Types Of Breathing Apparatus: Self-Contained, Self-Rescuer, Oxygen Apparatus, And Maintenance","Rescue Tools And Communication Systems","Rescue Operations In Fire, Explosion, And Inundation: Procedures And Protocols","First Aid In Mine Accidents And Casualty Handling"]},{"title":"Mine Safety Management","topics":["Principles Of Mine Safety Management Systems (MSMS)","Risk Assessment, Risk Matrix, And Control Hierarchy","Statutory Provisions: Mines Act, Coal Mines Regulations, Metalliferous Mines Regulations Related To Safety"]},{"title":"Emergency Planning","topics":["Emergency Preparedness, Disaster Management, And Mock Drills","Accident Prevention Through Behaviour-Based Safety (BBS)","Documentation And Reporting Of Safety Performance Indicators","Mine Disasters And Mine Rescue S. Ghatak CRC Press, S","Mine Disasters And Mine Rescue M. A. Ramlu Universities Press, Second Edition, 8173715734978-8173715730","Mine Environment And Ventilation M. A. Ramlu Oxford & IBH","Principles Of Mining Safety And Health J. L. Weeks MaGraw-Hill","Mine Safety And Rescue Engineering D. MacDonaldSME 9783838373812","Mine Health And Safety Management M. Karmis Society For Mining, Metallurgy, And Exploration, 2001. 0873352009","Mine Rescue Rules And Guidelines DGMS Government Of India Publications","Accident Reports And Safety Guidelines DGMS Circulars Government Of India Publications"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Advanced Surface Mining Methods","topics":["Review Of Surface Mining Methods: Open Pit, Strip, Terrace And Mountaintop Removal","Advanced Stripping Techniques, Multi-Bench And Deep-Pit Mining","Continuous Vs. Discontinuous Mining Systems","Case Studies: Large Open-Pit Mines (Coal, Iron Ore, Limestone, Metal Mines In India And Abroad)"]},{"title":"Mine Planning And Design","topics":["Open-Pit Layout: Ultimate Pit Limit (UPL), Pit Slope, Bench Parameters","Haul Road Design: Geometric And Structural Design, Safety Considerations","Dump And Stockpile Design","Mine Design Software Overview (I.E. SURPAC, GEOVIA, Datamine)","Pit Optimization Using Lerchs–Grossmann And Floating Cone Methods"]},{"title":"Equipment Selection And Performance Evaluation (8 hrs)","topics":["Advanced Surface Mining Machinery: Shovels, Draglines, Bucket Wheel Excavators, Surface Miners, Highwall Miners","Equipment Selection Based On Productivity And Cost Models","Truck–Shovel–Crusher System Optimization","Maintenance And Reliability Analysis Of Surface Equipment","Automation And AI In Surface Mining Equipment"]},{"title":"Production Planning, Scheduling And Optimization (9 hrs)","topics":["Short-Term And Long-Term Mine Planning","Production Scheduling Using Linear Programming And Network Analysis (PERT/CPM)","Grade Control And Blending Strategies","Simulation And Digital Twins In Surface Mining","Economic Evaluation Of Surface Mines: NPV, IRR, Cash Flow Analysis"]},{"title":"Environmental And Safety Management I","topics":["Slope Stability And Ground Control In Surface Mines","Dust, Noise, Vibration Control, And Water Management","Land Reclamation And Mine Closure Planning"]},{"title":"Environmental And Safety Management II","topics":["Drone-Based Monitoring, Slope Radar, And Remote Sensing Applications","Sustainable And Responsible Mining Practices (SDG Alignment)","Introductory Mining Engineering H. L. Hartm