insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Advanced Mining Legislation (Indian Context) (7 hrs)","topics":["Advance Topics Of Mines Act, 1952, Mines Rules, 1955 And Mines Rescue Rules, 1985","Overview Of Directorate General Of Mines Safety (DGMS): Power And Functions","Latest Amendments And Notifications"]},{"title":"Coal Mine Regulations 2017 And Metalliferous Mines Regulations 1961","topics":["Statutory Roles And Responsibilities Of Officers, Employee And Worker As Per The Regulations","Appointments, Qualifications & Duties As Per CMR 2017 / MMR 1961 Working Permissions, Exemptions, And Relaxations"]},{"title":"Safety In Opencast Mines","topics":["Statutory Rules And Regulations For Slope Stability","Safety In Blasting (Including Misfires, Oversize Handling) HEMM Safety: Shovels, Dumpers, Draglines, Dozers","Mine Illumination & Fatigue Management Guidelines","Environmental & Community Safety: Dust, Vibration, Fly Rock"]},{"title":"Safety In Underground Mines","topics":["Roof And Side Support Laws","Explosives Handling Rules","Ventilation Standards (Regulation-Driven)","Fire Protection Regulations","Inundation Control & Statutory Precautions","Haulage And Winding Safety: Code Of Practices","Electrical Safety In Underground Mines (IS Standards + Regulations)"]},{"title":"Modern Approaches Of Safety In The Mines (7 hrs)","topics":["Automation & Digital Safety Tools: IoT Sensors, Proximity Warning Systems, Real-Time Gas Monitoring, Drone Based Safety Inspections, Slope Stability Radar (SSR), Ground Penetrating Radar (GPR) For Mining","Behaviour-Based Safety (BBS)","Hazard Identification & Risk Assessment (HIRA)","Mine Emergency Preparedness & Disaster Management"]},{"title":"Unit","topics":["Legislation In Indian Mines: A Critical Appraisal – Vol.I& II (Revised) Prasad And RakeshLovely Prakashan","The Coal Mines Regulations 2017 CH.Sharma Brilliant Publisher","The Mines Rules, 1955 CH.Sharma Brilliant Publisher","The Mines Act, 1952 CH.Sharma Brilliant Publisher","Encyclopaedia Of Mining Law D. D. Seth Law Publishers (India) Pvt. Ltd., Allahabad","Mine Safety & Legislation G. B. Misra Lovely Prakashan","Mine Legislation & General Safety S. K. Das Lovely Prakashan"]}]'::jsonb from s;
