insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Occupational Health & Safety (7 hrs)","topics":["Concept And Importance Of Occupational Health & Safety (OHS)","Evolution Of Mine Safety In India","Role Of Directorate General Of Mines Safety (DGMS)","Safety Statistics In Indian Mining Industry","Accident Causation Theories (Heinrich''s Theory, Domino Theory, Swiss Cheese Model)","Safety Culture And Behavioural Safety","Unit- 2.0: Mine Hazards and Risk Assessment (9 hrs) Physical Hazards: Noise Vibration Heat Stress Illumination And Radiation Hazard Chemical Hazards: Dust (Coal Dust, Silica Dust) Toxic Gas (CO, NOx, $SO_{2}$ CH4, H2S) Fumes And Explosive Exposure Biological Hazards: Fungal Infections Vector-borne Diseases Risk Assessment: Hazard Identification & Risk Assessment (HIRA) Job Safety Analysis (JSA) Fault Tree Analysis (FTA) Risk Matrix And Risk Control Hierarchy","Physical Hazards: Noise","Vibration","Heat Stress","Illumination And Radiation Hazard","Chemical Hazards: Dust (Coal Dust, Silica Dust)","Toxic Gas (CO, NOx, $SO_{2}$ CH4, H2S)","Fumes And Explosive Exposure","Biological Hazards: Fungal Infections","Vector-borne Diseases","Risk Assessment: Hazard Identification & Risk Assessment (HIRA)","Job Safety Analysis (JSA)","Fault Tree Analysis (FTA)","Risk Matrix And Risk Control Hierarchy"]},{"title":"Occupational Diseases in Mining (9 hrs)","topics":["Causes","Symptoms","And Preventive Measures Of The Following: (a) Pneumoconiosis","(b) Silicosis","(c) Asbestosis","Impact Of Coal Dust Exposure And Recommended Monitoring And Prevention Methods","Coal Workers'' Pneumoconiosis","Noise Induced Hearing Loss (NIHL)","Heat Stroke And Fatigue","Ergonomic Disorders"]},{"title":"Mine Safety Legislation and Standards (8 hrs)","topics":["The Mines Act 1952","Mines Rules 1955","Coal Mines Regulations (CMR)","Metalliferous Mines Regulations (MMR)","DGMS Circulars","ILO Convention C176","ISO 45001 Occupational Health & Safety Management System"]},{"title":"Safety in Underground and Surface Mines (5 hrs)","topics":["Roof Falls And Ground Control","Mine Ventilation And Gas Monitoring","Explosion And Fire Hazards","Electrical Safety","Surface Mines","Slope Stability","Haul Road Safety","Blasting Safety","Machinery Safety"]},{"title":"Accident Investigation & Safety Management (4 hrs)","topics":["Accident Reporting Procedures","Investigation Techniques","Root Cause Analysis (RCA)","Safety Audit","Emergency Preparedness And Disaster Management","Mine Rescue Organisation","Occupational Safety with Reference to Mining Industry, Ankit Kumar and Swathi Dash LAP Lambert Academic Publishing, 6200275416, 978-6200275417.","A Study of Mine Management, Legislation And General Safety, L C Kaku, Lovely, Prakashan, 8179561593, 978-8179561591","Elements of Mining Technology (Safety Sections), DJ Deshmukh, Lovely Prakashan.","Mine Safety & Legislation, G. B. Misra, Lovely Prakashan","Occupational Health and Safety, Mihaela Rotaru & Lucian-Ionel Cioca (Eds.), Bentham Science Publishers, 2024, 978-981-5165-53-1","Occupational Health and Safety Management: A Practical Approach, Charles D. Reese, CRC Press, 3rd edition, 978-1-4822-3134-2.","Handbook of Occupational Safety and Health, Dan Petersen, Wiley, 3rd edition, 978-1-118-94726-5","Introduction to Health and Safety at Work, Phil Hughes & Ed Ferrett, Routledge, 3rd Edition, 978-0-7506-8503-0.","Handbook of Mine Safety: Compliance, Strategies and Examples W. David Yates, D.J. Schmutz & Kim B. Redding Routledge, 2023, 978-1-0328-2484-0","Fundamental Principles of Occupational Health and Safety ILO, ILO Publications 2nd edition.","Health and Safety at Work by Jeremy Stranks, London: Kogan Page 2016, 9780749478186, 0749478187.","Mine Safety: a morden approach, B.S. Dhillon, Springer eBooks, 9781849961158","Industrial Accident Prevention, H.W. Heinrich, McGraw-Hill Inc., US, 1980, 8th Edition, 0070280614, 978-0070280618","Practical Loss Control Leadership, Frank E. Bird Intl Loss Control Inst., 1986, 0880610549, 978-0880610544."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Fundamentals of Remote Sensing (8 hrs)","topics":["Definition And Scope Of Remote Sensing","Electromagnetic Spectrum","EMR Interaction With Atmosphere And Earth Surface","Spectral Signatures Of Rocks","Minerals","Vegetation","Water","Resolution Concepts: Spatial","Spectral","Radiometric","Temporal","Passive And Active Remote Sensing","Platforms: Ground","Airborne","Satellite"]},{"title":"Satellite Systems and Data Acquisition (8 hrs)","topics":["Orbit Types (Geostationary & Polar)","Sensors: Optical","Thermal And Microwave","Multispectral And Hyperspectral Imaging","Data Format And Metadata","Data Sources (Bhuvan, USGS Earth Explorer)"]},{"title":"Digital Image Processing (9 hrs)","topics":["Image Characteristics (Raster Data Structure)","Image Pre-processing: Radiometric And Geometric Correction","Image Enhancement: Contrast Stretching And Histogram Equalization","Image Transformations: Band Ratios And Principal Component Analysis (PCA)","Image Classification: Supervised And Unsupervised Classification","Accuracy Assessment"]},{"title":"GIS Integration and Mining Applications (8 hrs)","topics":["Introduction To GIS","Vector And Raster Data Models","Spatial Analysis And Overlay Techniques","DEM And Terrain Analysis","Change Detection Analysis","Mine Environmental Monitoring"]},{"title":"Advanced Applications in Mining I (5 hrs)","topics":["UAV/Drone-based Remote Sensing","LiDAR Applications In Mining"]},{"title":"Advanced Applications in Mining II (4 hrs)","topics":["Hyperspectral Mineral Mapping","InSAR For Subsidence Monitoring","Integration With Mine Planning Software","Remote Sensing and Image Interpretation Thomas M. Lillesand John Wiley & Sons Inc. (7th Edition), 9781118343289, 978-1118343289","Remote Sensing: Principles and Interpretation, Floyd F. Sabins, W.H.Freeman & Co Ltd, 2nd Edition, 071671793X, 978-0716717935","Introductory Digital Image Processing: A Remote Sensi