insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction (7 hrs)","topics":["Introduction To Autonomation (or Jidoka)","Automation In Production Systems Used In Mining","Principles And Strategies Of Automation","Ways To Enhance Productivity And Levels Of Automation","Essential Elements Of An Automated System Used In Mining","Role Of Automation In The Mining Industry"]},{"title":"Autonomous Mining Systems (7 hrs)","topics":["Autonomous Haulage Systems","Automated Drilling And Drill Rig System","Automation In Tunnelling Projects Of Mining","Automation In The Monitoring Of Environments In Longwall And Continuous Mining Systems","Automation Of The Transportation System In Surface Mining","Unit- 3.0: Fleet Management System (FMS) (9 hrs) FMS-Aim Objectives Operation Setup Workflow And Different Types Of FMS TDS (Technical Data Sheet) CMMS (Computerised Maintenance Management System) ERP (Enterprise Resource Planning) For Mining Industry Mining Supply Chain With A FMS Robotics & Armchair Mining Use Of Robotics In Mining For Production And Disaster Management Purpose Advantages And Disadvantages Of FMS","FMS-Aim","Objectives","Operation","Setup","Workflow And Different Types Of FMS","TDS (Technical Data Sheet)","CMMS (Computerised Maintenance Management System)","ERP (Enterprise Resource Planning) For Mining Industry","Mining Supply Chain With A FMS","Robotics & Armchair Mining","Use Of Robotics In Mining For Production And Disaster Management Purpose","Advantages And Disadvantages Of FMS","Unit- 4.0: Automated Communication and Tracking Technologies (9 hrs) Proximity Sensors And Control System Radar Systems RFID (Radio Frequency Identification) In Mining Engineering SCADA (Supervisory Control And Data Acquisition) And Image Processing Geo-fencing CCD (Charge-Coupled Device) Camera Data Logging Systems In Mining Engineering GNSS/GPS (Global Navigation Satellite System)/Vision-Based Systems","Proximity Sensors And Control System","Radar Systems","RFID (Radio Frequency Identification) In Mining Engineering","SCADA (Supervisory Control And Data Acquisition) And Image Processing","Geo-fencing","CCD (Charge-Coupled Device) Camera","Data Logging Systems In Mining Engineering","GNSS/GPS (Global Navigation Satellite System)/Vision-Based Systems"]},{"title":"Virtual Reality Applications I (4 hrs)","topics":["VR-Principles","Types And 13 (Three I''s) Of Virtual Reality","Mining Equipment Concept Development","Mine Safety Applications","Mining Operations Simulation"]},{"title":"Virtual Reality Applications II (3 hrs)","topics":["Importance Of Sensor Networking In Mining And Other Safety-critical Industries","Development Of Mining Operation Simulations Based On VR Technologies","Challenges For VR In The Mining Industry","Human Systems Integration for Mining Automation Robin Burgess Limerick, Tim Horberry, Danellie Lynas, Andrew Hill, Joel M. Haight, CRC Press, 1st Edition (2025), ISBN-9781032447094.","Automation in Mining, Mineral and Metal Processing, Dominique Sauter, D. Theilliol (IFAC Proceedings) Elsevier, ISBN: 9780080441795."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to liberal Arts (7 hrs)","topics":["Definition And Significance Of Liberal Arts","Historical Development And Evolution Of Liberal Arts","Overview Of Interdisciplinary Approaches In Liberal Arts","Modern Interdisciplinary Innovators"]},{"title":"Liberal arts education and its benefits (6 hrs)","topics":["Liberal Arts Education And Its Benefits: STEM To STEAM","Utilitarianism","Deontology","Virtue Ethics In Engineering Context"]},{"title":"Critical Thinking I (8 hrs)","topics":["The Role Of Critical Thinking In Liberal Arts Education","Arguments In Liberal Arts Disciplines","Information Assumptions","And Biases","Formal Logic Principles And Applications"]},{"title":"Critical Thinking II (8 hrs)","topics":["Critical Thinking And Interpretation","Logical Conclusions From The Evidence","Fallacies In Engineering Decision-making","Media Literacy And Critical Thinking In The Digital Age"]},{"title":"Creativity I (8 hrs)","topics":["Creative Thinking Skills In Education","Ideation Techniques","Whole Brain Approach","Technology Lifecycle And Adoption Curves"]},{"title":"Creativity II (5 hrs)","topics":["Characteristics Of Creative And Innovative Individuals","Lifecycle And Adoption Curves","Liberal Arts and Sciences: Thinking Critically, Creatively, and Ethically Ed. D., Christopher a Ulloa Chaves Trafford Publishing, 2014, ISBN: 1490736999, 9781490736990.","Art of Creative Thinking Rod Judkins Hachette Book Publishing 2015, ISBN: 9781444794489.","Introduction to Creativity and Innovation for Engineers Stuart Walesh, Pearson, 2017. ISBN: 9781292159287.","The Reflective Practitioner Donald A. Schön Basic Books, 1984, ISBN: 9781857423198.","The Innovator''s Dilemma Clayton Christensen Harvard Business Review Press, 1997, ISBN 0875845851."]}]'::jsonb from s;
