insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Control problem","topics":["Industrial Control Examples","Mathematical models of physical systems","Control hardware and their models","Synchros","AC and DC servomotors","Concepts of Control Systems -Open Loop and closed control systems and their differences -examples of control systems Classification of control systems","Benefits of Feedback","Block diagram algebra","Signal flow graph"]},{"title":"Time Response Analysis","topics":["Standard test signals","Time response of first and second order systems for standard test inputs","Application of initial and final value theorem","Design specification for second order systems based on time response","Steady state errors and error Cons"]},{"title":"Stability & Root Locus","topics":["Concept of Stability","Routh-Hurwitz stability criteria","Absolute and Relative Stability Analysis","Root Locus Technique: The root locus concept","Construction of root loci","Effects of adding poles and zeros to G(s) H(S) on the root loci"]},{"title":"Frequency Response Analysis","topics":["Relationship between time and frequency response","Polar plots","Nyquist plot and application of Nyquist criterion to find the stability","Gain and phase margins","Bode diagrams -Frequency domain specifications"]},{"title":"Introduction to Controller Design","topics":["Lag. Lead and lag-lead networks","Effects of lag","Lead. and lag-lead compensation on frequency response analysis","Proportional","Integral and Derivative Controllers and their applications"]},{"title":"State Variable Analysis","topics":["Concept of state variables","State Space model","Diagonalization of state matrix","State transition matrix","Solution of state equations","Eigen values and stability analysis","Concept of Controllability and Observability","Control Systems Engineering by S. Palani","Modern Control Engineering by Katsuhiko Ogata","Control Systems Engineering by I. J. Na