insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Measurement Systems","topics":["Introduction","Significance of measurement","Block diagram of measurement system","Methods of measurements","Elements and their functions of measurement systems","And applications"]},{"title":"Characteristics of measurement systems-static and dynamic","topics":["Static characteristics- accuracy","Precision","Sensitivity","Reproducibility","Drift","Static error","Dead zone","Linearity","Resolution","Hysteresis","Loading effects","Dynamic characteristics- Speed of response","Measuring lag","Fidelity","Dynamic error","Calibration"]},{"title":"Errors in Measurement and their Statistical Analysis","topics":["Types of Error- Gross","Systematic (Instrumental, Environmental, Observational error)","And random error","Statistical treatment of data measurement tests","Histogram","Arithmetic mean","Dispersion measurement","Range","Deviation","Average deviation","Standard deviation","Variance","Noise","Signal to noise ratio"]},{"title":"Thermal Sensors","topics":["Temperature sensors","Thermo-resistive sensors- Resistance Temperature Detectors","Thermistor","Thermoelectric sensors- Thermocouple","Electric Sensors- Capacitive position","Proximity","And displacement sensors","LVDT"]},{"title":"Force, Pressure, Humidity, and Moisture Sensors","topics":["Force sensor- Strain gauge","Semiconductor strain gauge","Strain gauge accelerometers","Pressure sensors- Mechanical pressure sensors","Piezoresistive pressure sensor","Capacitive pressure sensor","Resistive humidity sensor","Capacitive moisture sensors","Thermal conduction moisture sensors"]},{"title":"MEMS and Smart sensors and Actuators","topics":["Introduction","MEMS sensors","MEMS actuators","Applications","Nano sensors and actuators","Smart sensors and actuators","Light dependent resistor","Wireless sensors and actuators and issues associated with their use","RFIDs and embedded sensors","A.K. Sawhney: \"A Co