insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Atomic and Molecular Structure Electromagnetic radiations Dual nature of electron and Heisenberg uncertainty Principle Photoelectric effect Planck''s theory Principles for the combination of atomic orbitals to form a molecular diagram of molecular orbitals Bent''s rule VSEPR theory (typical example) coordination numbers and geometries Isomerism in transition metal compounds Metal Carbonyls: Synthesis and Structure","Electromagnetic radiations","Dual nature of electron and Heisenberg uncertainty Principle","Photoelectric effect","Planck''s theory","Principles for the combination of atomic orbitals to form a molecular diagram of molecular orbitals","Bent''s rule","VSEPR theory (typical example) coordination numbers and geometries","Isomerism in transition metal compounds","Metal Carbonyls: Synthesis and Structure"]},{"title":"Spectroscopy","topics":["Principle of rotational and vibrational spectroscopy","Selection rule for application in diatomic molecules","Elementary idea of electronic spectroscopy","UV-VIS spectroscopy with related to rules and its applications","Basic Principle of nuclear Magnetic resonance spectroscopy with applications"]},{"title":"Electrochemistry and Fuels","topics":["Nernst equation","EMF and electrochemical cell","The introduction of corrosion","Corrosion mechanism","Types of corrosion","Water line corrosion","Stress corrosion","Pitting corrosion","Lead acid storage cell","Leclanche cell","Calorific value of fuels","Proximate and ultimate analysis of coals","Fuel cells","Bio fuels"]},{"title":"Water Chemistry","topics":["Hardness of water","Estimation of water hardness by EDTA and Alkalinity method","Removal of the hardness of water: soda lime process, zeolite process, Ion exchange process","Boiler problem","Sludge, and scale formation","Priming and foaming","Boiler corrosion, and Caustic embrittlement","Unit 5.0: Polymer and P