insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Indian Knowledge Systems","topics":["Overview of IKS","Organization of IKS","Conception and constitution of knowledge in Indian tradition","The oral tradition","Models and Strategies of IKS"]},{"title":"Overview of IKS Domains","topics":["The Vedas as the basis of IKS","Overview of all the six Vedangas"]},{"title":"Relevance in Current Technical Education System I","topics":["Relevance of following IKS domains in present technical education system: Arthashastra (Indian economics and political systems)","Ganita and Jyamiti (Indian mathematics, astronomy and geometry)","Rasayana (Indian chemical Sciences)"]},{"title":"Relevance in Current Technical Education System II","topics":["Ayurveda (Indian Biological Sciences / Diet & Nutrition)","Jyotish Vidya (observational astronomy and calendar systems)","Prakriti Vidya (Indian system of terrestrial/material sciences/ecology and atmospheric sciences)"]},{"title":"Relevance in Current Technical Education System III","topics":["Vastu Vidya (Indian system of aesthetics-iconography and built-environment /architecture)","Nyaya Shastra (Indian systems of social ethics, logic and law)"]},{"title":"Traditional Sciences and Arts","topics":["Shilpa and Natya Shastra (Indian classical arts: performing and fine arts)","Sankhya and Yoga Darshna (Indian psychology, yoga and consciousness studies)","Virkshayurveda (plant science/sustainable agriculture/food preservation methods)","Introduction to Indian Knowledge System: Concepts and Applications, Archak, K.B. (2012), Kaveri Books, New Delhi, ISBN-13:978-9391818203","Introduction To Indian Knowledge System: Concepts and Applications, Mahadevan, B. Bhat, Vinayak Rajat, Nagendra Pavana R.N., PHI, ISBN: 9789391818203","Glimpse into Kautilya''s Arthashastra Ramachandrudu P. (2010), Sanskrit Academy, Hyderabad, ISBN:9788380171074","\"Introduction\" in Studies in Epics and Purāṇas, (Eds.), KM Munshi and N Chandrashekara Aiyer Bhartiya Vidya Bhavan"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Identify the type of semiconductor material and calculate the mobility, conductivity and carrier concentration of majority carrier using Hall Effect","Resistivity measurement of a semiconductor using four probe methods","To study the characteristics of an n-channel JFET and determine pinch-off voltage and saturation current","To analyze the I-V characteristics and switching behavior of a MOSFET","Measure the I-V characteristics of tunnel diode","Plot the I-V characteristics of a solar cell","Study of UJT Relaxation Oscillator","Study the characteristics of SCR","To study the behavior of a BJT under CE configuration and determine key transistor parameters","To examine the current flow and voltage behavior of a BJT in CB configuration","Demonstrate the I-V characteristics of Zener diode"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Write a program to demonstrate use of variables, data types, constants, typecasting, and simple arithmetic operations","Develop a program to check whether a number is prime, palindrome, or Armstrong using conditional and loop statements","Create a menu-driven program using switch to perform basic arithmetic operations, and print patterns using nested for loops","Write a program to demonstrate passing parameters to functions by value and by reference","Develop a program with overloaded functions to calculate area of different shapes (circle, rectangle, triangle)","Write a program to define a structure and a class to store student details and display them","Implement a class with constructors (default & parameterized) and destructor to manage object lifecycle","Create a class Account with private data members and use getter/setter methods for data access and modification","Overload binary + and unary - operators for a Complex class","Develop a program that demonstrates single and multiple inheritance using base and derived classes","Write a program to demonstrate runtime polymorphism using virtual functions","Create a function template to sort an array of different data types and a class template for a stack","Implement a program using pointers to objects and demonstrate the use of this pointer","Write a program using try, catch, and throw to handle division by zero and invalid input exceptions","Develop a program to read and write student records using file operations"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Internship I is of a minimum duration of two weeks which can be completed in an Industry/Institute in consultation with concerned Engineering College/ Institute. After completion of internship a detailed report of the internship mentioning the training undertaken along with certificate should be submitted."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Small Signal Amplifiers","topics":["CB, CE, CC Configurations","Hybrid Model For Transistor At Low Frequencies","RC Coupled Amplifiers","Mid Band Model","Gain And Impedance","Comparisons Of Different Configurations","Emitter Follower","Darlington Pair (Derive Voltage Gain, Current Gain, Input And Output Impedance)","Hybrid-Model At High Frequencies (Pi - Model)"]},{"title":"Multistage Amplifiers-I","topics":["Cascade And Cascode Amplifiers","Calculations Of Gain, Impedance And Bandwidth","Design Of Multistage Amplifiers"]},{"title":"Multistage Amplifiers-II","topics":["Feedback Amplifiers: Feedback Concept","Classification Of Feedback Amplifiers","Properties Of Negative Feedback Amplifiers","Impedance Considerations In Different Configurations","Analysis Of Feedback Amplifiers"]},{"title":"Field Effect Transistor","topics":["Introduction","Classification","FET Characteristics","Operating Point","Biasing","FET Small Signal Model","Enhancement And Depletion Type MOSFETs","FET Amplifier Configurations (CD, CG And CS)"]},{"title":"Oscillators","topics":["Barkhausen Criterion","Sinusoidal Oscillators","The RC Phase-Shift Oscillator","Resonant Circuit Oscillators","A General Form Of Oscillator Circuit","The Wien-Bridge Oscillator","Crystal Oscillators","Hartley, Colpitt''s And Clapp''s Oscillator"]},{"title":"Power Amplifiers","topics":["Power Dissipations In Transistors","Amplifiers Classification (Class-A, Class-B, Class-C, Class-AB)","Efficiency Analysis","Push-Pull And Complementary Push-Pull Amplifiers","Cross Over Distortion And Harmonic Distortion In Push-Pull Amplifier","Tuned Amplifiers (Single, Double And Stagger Tuned Amplifier)","Electronic Devices And Circuit Theory, Boylestad And Nashelsky, PEARSON Publication","Electronic Devices And Circuits, Salivahanan, Suresh Kumar, Vallavaraj, TMH 1999","Integrated Electronics, Analog And Digital Circuits And Systems, J. Millman And Halkias, TMH, 2000","Micro Electronic Circuits, Sedra And Smith, Oxford University Press, 2000","Electronic Devices And Circuits, David A Bell, Oxford University Press, 2000"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction To The Communication System","topics":["Block Diagram Of Communication System","Comparative Study Of Analog And Digital Communication"]},{"title":"Modulation And Demodulation","topics":["Modulation (Upward Frequency Translation) And Demodulation (Downward Frequency Translation)","The Need For Modulation","Broad Classification Of Modulation [Linear (Amplitude-AM) And Exponential (Frequency-FM And Phase-PM)]"]},{"title":"Generation And Demodulation Of DSB And SSB","topics":["Generation Of Double Side Band (DSB) With Carrier","Double Side Band With Suppressed Carrier (DSB-SC)","Single Side Band With Suppressed Carrier","Demodulation Of Double Side Band With Carrier -Incoherent Detector Or Envelope Detector","Peak Diode Detector","Coherent Or Synchronous Detection Of DSBSC And Single Side Band With Suppressed Carrier"]},{"title":"Superhetrodyne Receivers","topics":["Characteristics","Intermediate Frequency And Its Advantages","Image Rejection Of The Receiver"]},{"title":"FM Signal Generation And Demodulation","topics":["Generation Of FM Signals (Direct And Indirect Methods)","Demodulation"]},{"title":"Noise And Analog Pulse Modulation","topics":["Different Types Of Noise","SNR In AM, FM And PM System","Use Of Emphasis Circuit In FM For SNR Optimization","Analog Pulse Modulation: PAM, PWM, PPM And Demodulation","Comparative Study Of Various Analog Pulse Modulation","Electronic Communication System, By Kennedy, TMH","Communication System, By Haykin, Wiley","Communication System, By Bruce Carlson, TMH","Modern Digital And Analog Communication, B.P. Lathi, Oxford"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Digital Principle","topics":["Analog Vs Digital","Number System","Computer Codes","Digital Signals","Waveforms Positive And Negative Logic","Logic Gate: Basic, Universal And Others","Truth Table","Logic Functions","IC Chips","Timing Diagram","Electrical Analogy"]},{"title":"Boolean Laws And Theorems","topics":["Logic Functions","Conversion Of Logic Functions Into Truth Table And Vice Versa","SOP And POS Forms Of Representation","Canonical Form","Minterms And Maxterms","Simplification Of Logic Functions By Theorems And Karnaugh''s Map","Don''t Care Conditions"]},{"title":"Analysis And Synthesis Of Combinational Logic Circuits","topics":["Comparators","Multiplexers","Encoder","Decoder","7 Segment Display","Half Adder And Full Adder","Subtractors","Serial And Parallel Adders","BCD Adder"]},{"title":"Sequential Circuit Blocks And Latches","topics":["Flip-Flops-Race Around Condition","Master-Slave And Edge Triggered SR, JK, D And T Flip Flop","Shift Registers","Counters-Synchronous And Asynchronous: Design Of Ripple Counter"]},{"title":"Timing Circuit","topics":["Multivibrators","Monostable And Astable Timer: LM555"]},{"title":"Integrated Circuit Logic Families And Building Blocks","topics":["Integrated Circuit Logic Families: RTL, DTL, TTL, CMOS, III./I2L (Integrated Injection Logic And Emitter Coupled Logic)","Use Of Building Blocks: Designing Larger Systems Such As Digital-To-Analog Converters (DAC): Weighted Resistors And R-2R","Analog-To-Digital (ADC) Converter, Counter And Succession","Digital Fundamentals, Floyd And Jain, Pearson","Digital Logic And Computer Design, M. Morris Mano, Pearson","Fundamentals Of Digital Circuits, A. Anand Kumar, PHI","Digital Systems, Ronald J. Tocci, Neal S. Widmer, Pearson"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Introduction To Vector Algebra And Electrostatics Introduction To Vector Algebra Coordinate Systems And Transformation Vector Calculus Electrostatics: Coulomb''s Law Gauss''s Law And Its Applications The Potential Functions Equipotential Surface Poisson''s And Laplace''s Equation Applications (Solution For Some Simple Cases) Capacitance Electrostatic Energy Conductor Properties And Boundary Conditions Between Dielectrics And Dielectric-Conductor Interface Uniqueness Theorem","Introduction To Vector Algebra","Coordinate Systems And Transformation","Vector Calculus","Electrostatics: Coulomb''s Law","Gauss''s Law And Its Applications","The Potential Functions","Equipotential Surface","Poisson''s And Laplace''s Equation","Applications (Solution For Some Simple Cases)","Capacitance","Electrostatic Energy","Conductor Properties And Boundary Conditions Between Dielectrics And Dielectric-Conductor Interface","Uniqueness Theorem"]},{"title":"Magnetostatics","topics":["Biot-Savart Law","Ampere''s Circuital Law","Curl","Stoke''s Theorem","Magnetic Flux And Magnetic Flux Density","Energy Stored In Magnetic Field","Ampere''s Force Law","Magnetic Vector Potential","Analogy Between Electric And Magnetic Field","Unit 3.0: Maxwell''s Equations And Electromagnetic Waves Maxwell''s Equations Equation Of Continuity For Time Varying Field Inconsistency Of Ampere''s Circuital Law Maxwell''s Equations In Differential And Integral Form Electromagnetic Waves: Solution Of Wave Equation In Free Space Uniform Plane Wave Propagation Uniform Plane Waves The Wave Equation For Conducting Medium Wave Propagation In Lossless Medium And In Conductive Medium Conductors And Dielectrics Polarization","Maxwell''s Equations","Equation Of Continuity For Time Varying Field","Inconsistency Of Ampere''s Circuital Law","Maxwell''s Equations In Differential And Integral Form","Electromagnetic Waves: Solution Of Wave Equation In Free Space","Uniform Plane Wave Propagation","Uniform Plane Waves","The Wave Equation For Conducting Medium","Wave Propagation In Lossless Medium And In Conductive Medium","Conductors And Dielectrics","Polarization"]},{"title":"Reflections And Refractions","topics":["Reflection By A Perfect Conductor With Normal As Well As Oblique Incidence","Reflection And Refraction By Perfect Dielectrics With Normal And Oblique Incidence","Surface Impedance"]},{"title":"Poynting Vector","topics":["Poynting Theorem","Instantaneous, Average And Complex Poynting Vector","Power Loss In A Plane Conductor"]},{"title":"Transmission Lines","topics":["Transmission Line Theory","Low Loss Radio-Frequency And UHF Transmission Line","UHF Line As A Transformer","Voltage Step Up Of The Quarter Wave Transformer","Transmission Line Chart (Smith Chart)","Time-harmonic Electromagnetic Fields, R. F. Harrington, Wiley-IEEE Press, 2001","Fields And Waves In Communication Electronics, Ramo, S., Whinnery, J.R., And Van Duzer, T., 3rd Ed., John Wiley And Sons, 1994","Advanced Engineering Electromagnetics, Balanis, C.E., Wiley India Pvt. Ltd., Reprint, 2008","Microwave Engineering, Pozar, D.M., 3rd Ed., John Wiley And Sons, 2004"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Basics Of Semiconductor Physics Semiconductor Carrier Modelling- Bonding Model Energy Band Model Carriers Band Gap Carrier Properties (Effective Mass, Intrinsic Carrier Concentration, Doping) Density Of States Fermi Function Equilibrium Carrier Concentration (Formula For N And P And NP Product) Charge Neutrality Relationship Determination Of Fermi Level Carrier Concentration Temperature Dependence Carrier Action - Drift Mobility Drift Current Resistivity Diffusion Current Total Current Relation Between The Diffusion Constants And Mobility (Einstein''s Relationship) Recombination-Generation (Band-To-Band, R-G Centres, Auger, Impact Ionization) Equation Of State Continuity Equation Minority Carrier Diffusion Equation","Semiconductor Carrier Modelling- Bonding Model","Energy Band Model","Carriers","Band Gap","Carrier Properties (Effective Mass, Intrinsic Carrier Concentration, Doping)","Density Of States","Fermi Function","Equilibrium Carrier Concentration (Formula For N And P And NP Product)","Charge Neutrality Relationship","Determination Of Fermi Level","Carrier Concentration","Temperature Dependence","Carrier Action - Drift","Mobility","Drift Current","Resistivity","Diffusion Current","Total Current","Relation Between The Diffusion Constants And Mobility (Einstein''s Relationship)","Recombination-Generation (Band-To-Band, R-G Centres, Auger, Impact Ionization)","Equation Of State","Continuity Equation","Minority Carrier Diffusion Equation","Unit 2.0: PN Junction Diode Step Junction Built-In Potential Depletion Width Depletion Approximation Electrostatic Relationship (Charge Density, Depletion Width, Potential, Electric Field) For Va = 0, Va I 0 And Va I 0 Ideal Diode Equation (Qualitative And Quantitative Derivation: Band Model, Assumptions, Approximation, Boundary Condition) Deviation From Ideal (R-G Current, Series Resistance, High Level Injection) Junction Breakdown (Avalanche And Zener) Reverse Bias Junction Capacitance Forward Bias Diffusion Capacitance Qualitative Understanding Of Turn On And Turn-Off Transients Zener Diode Tunnel Diode Varactor Diode Schottky Diode","Step Junction","Built-In Potential","Depletion Width","Depletion Approximation","Electrostatic Relationship (Charge Density, Depletion Width, Potential, Electric Field) For Va = 0, Va I 0 And Va I 0","Ideal Diode Equation (Qualitative And Quantitative Derivation: Band Model, Assumptions, Approximation, Boundary Condition)","Deviation From Ideal (R-G Current, Series Resistance, High Level Injection)","Junction Breakdown (Avalanche And Zener)","Reverse Bias Junction Capacitance","Forward Bias Diffusion Capacitance","Qualitative Understanding Of Turn On And Turn-Off Transients","Zener Diode","Tunnel Diode","Varactor Diode","Schottky Diode"]},{"title":"Physics And Technologies Of BJT","topics":["Operational Considerations","Modes And Configurations","Performance Parameters (Emitter Efficiency, Base Transport Factor, Common Base Current Gain, Common Emitter Current Gain And Their Derivation For An Ideal Transistor","Deviation From Ideal (Base Width Modulation Punch Through, Avalanche Breakdown, Geometrical Effects, R-G Current)","Small Signal Modelling"]},{"title":"Physics And Technologies Of FET","topics":["JUNCTION FET (Theory Of Operation, I-V Relationship)","MOS CAPACITOR (Energy Band Diagram, Gate-Voltage Relationship, Capacitance-Voltage Characteristics)","MOSFET (Theory Of Operation, Threshold Voltage, I-V Characteristics)","NON IDEAL MOS (M-S Work Function Difference, Oxide Charges, Threshold Adjustment And Considerations)"]},{"title":"Introduction To UJT, SCR, Triac And Diac","topics":["UJT, SCR, Triac And Diac (Construction, Working, Characteristics And Application)","UJT Relaxation Oscillator"]},{"title":"Optoelectronic Devices","topics":["Photo Diodes (PIN And Avalanche)","Solar Cell","LED","Solid State LASER Diodes","Semiconductor Device Fundamentals, By R. F. Pierret, Addison-Wesley Publishing Company, 1996","Semiconductor Physics And Devices: Basic Principles, By Donald A. Neamen, 3rd Edition, 2003","Physics Of Semiconductor Devices, S. M. Sze, 2nd Edition, 1981"]}]'::jsonb from s;
