insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"IC Fabrication","topics":["IC classification","Fundamental of monolithic IC technology","Epitaxial growth","Masking and etching","Diffusion of impurities","Realization of monolithic ICs and packaging","Fabrication of diodes, capacitance, resistance and FETs"]},{"title":"Characteristics of OPAMP","topics":["Ideal OP-AMP characteristics","DC characteristics","AC characteristics","Differential amplifier","Frequency response of OP-AMP"]},{"title":"Basic applications of Op-Amp","topics":["Inverting and Non-inverting Amplifiers","V/I and I/V converters","Summer","Differentiator and Integrator"]},{"title":"Applications of OPAMP","topics":["Instrumentation amplifier","Log and Antilog Amplifiers","First and second order active filters","Comparators","Multivibrators","Wave-form generators","Clippers","Clampers","Peak detector","S/H circuit","D/A converter (R-2R ladder and weighted resistor types)","A/D converters using Op-Amps"]},{"title":"Special ICs","topics":["Functional block, characteristics and application circuits with 555 Timer IC","566 voltage controlled oscillator IC","565 phase lock loop IC","Analog multiplier ICs"]},{"title":"Application ICs","topics":["IC voltage regulators - LM78XX, 79XX Fixed voltage regulators","LM317, 723 Variable voltage regulators","Switching regulator- SMPS- LM 380 power amplifier","ICL 8038 function generator IC","\"Op-amp and Linear ICs\", David A. Bell, Oxford, 2013","\"Linear Integrated Circuits\", D. Roy Choudhary, Sheil B. Jani, II edition, New Age, 2003","\"Op-amps and Linear Integrated Circuits\", Ramakant A. Gayakward, IV edition, Pearson Education, PHI, 2000","\"Opamps and Linear Integrated Circuits Concepts and Applications\", Fiore, Cengage, 2010","\"Fundamentals of Analog Circuits\", Floyd and Buchla, Pearson, 2013","\"Integrated Electronics - Analog and Digital circuits system\", Jacob Millman, Christos C. Halkias, Tata McGraw Hill, 2003","\"Op-amp and Linear ICs\", Robert F. Coughlin, Fredrick F. Driscoll, PHI Learning, 6th edition, 2012."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to Microprocessor Systems","topics":["Architecture and Pin diagram of 8085","Timing Diagram","Memory organization","Addressing modes","Interrupts","Assembly Language Programming","8085 interrupts","Additional I/O concepts and processes"]},{"title":"Interfacing of 8085 with 8255, 8254/8253, 8251, 8259","topics":["Introduction","Generation of I/O Ports","Programmable Peripheral Interface (PPI)"]},{"title":"Intel 8255, Sample-and-Hold Circuit and Multiplexer, Keyboard and Display Interface","topics":["Keyboard and Display Controller (8279)","Programmable Interval timers (Intel 8253/8254)","USART (8251)","PIC (8259)","DAC, ADC, LCD, Stepper Motor"]},{"title":"Introduction to 8086, 80286, 80386 and 80486 Microprocessor","topics":["8086 Architecture","Generation of physical address","Pin diagram of 8086","Minimum Mode and Maximum mode","Bus cycle","Memory Organization","Memory Interfacing","Addressing Modes","Assembler Directives"]},{"title":"Instruction set of 8086","topics":["Assembly Language Programming","Hardware and Software Interrupts","Introduction of 80286, 80386, and 80486 microprocessor","Unit 6.0: Overview of Microcontroller 8051 Introduction to 8051 Microcontroller Architecture Memory organization Special function registers Port Operation Memory Interfacing I/O Interfacing Programming 8051 resources Interrupts Programmer''s model of 8051 Operand types Operand addressing Data transfer instructions Arithmetic instructions Logic instructions Control transfer instructions Timer and Counter Programming Interrupt Programming","Introduction to 8051 Microcontroller","Architecture","Memory organization","Special function registers","Port Operation","Memory Interfacing","I/O Interfacing","Programming 8051 resources","Interrupts","Programmer''s model of 8051","Operand types","Operand addressing","Data transfer instructions","Arithmetic instructions","Logic instructions","Control transfer instructions","Timer and Counter Programming","Interrupt Programming","\"Microprocessors and Microcontrollers\", Muhammad Ali Mazidi, Pearson, 2006","\"Microprocessors and Interfacing, Programming and Hardware\", Douglas V Hall, TataMcGraw Hill, 2006","\"MicroProcessor Architecture, Programming and Applications with the 8085\", Ramesh Gaonkar, PHI","\"The 8051 Microcontroller and Embedded Systems\", Muhammad Ali Mazidi, Janice GillispieMazidi, Rolin D. MCKinlay, 2nd Edition, Pearson Education, 2008","\"The 8086 Microprocessor: Programming and Interfacing The PC\", Kenneth J. Ayala, Delmar Publishers, 2007","\"Advanced Microprocessors and Peripherals\", A K Ray, K M Bhurchandi, Tata McGraw Hill, 2007"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Introduction to RF and HF Circuits","topics":["Overview of RF and HF circuit applications","Introduction to passive components in high-frequency environments"]},{"title":"Impedance Matching and Resonant Circuits","topics":["Principles of impedance matching","Design and analysis of resonant circuits"]},{"title":"RF Amplifiers and Filters","topics":["Basic configurations of RF amplifiers","Design and analysis of RF filters"]},{"title":"RF Power Amplification and Mixing","topics":["Principles and design of RF power amplifiers","Functioning of mixers in RF systems"]},{"title":"Oscillators in RF Systems","topics":["Design and analysis of RF oscillators"]},{"title":"Practical applications of RF and HF circuits in wireless communication","topics":["Hans L. Hartnagel, Rudiger Quay, Ulrich L.Rohde, Matthias Rudolph. Fundamentals of RF and Microwave Techniques and Technologies.Springer, 2023.","Robert Sobot. Wireless Communication Electronics Introduction to RF Circuits and Design Techniques.Springer,2021.","Duran Leblebici, Yusuf Leblebici. Fundamentals of High Frequency CMOS Analog Integrated Circuits.Springer,2021."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"System & Architectural Design","topics":["Defining a system specification","Performance analysis","Cost analysis","Identifying various functional blocks/modules","Categorizing them in terms of digital, analog, RF and mixed signal blocks"]},{"title":"Functional verification, logic design","topics":["Verifying the functionality of blocks","Behavioral description","Logic minimization","Synthesis","Verification and testing"]},{"title":"Circuit Optimization and Physical Design","topics":["Optimization of synthesized blocks for various performance metric"]},{"title":"Introduction to placement and route","topics":["Layout Vs Schematic (LVS) verification","Design for Manufacturability"]},{"title":"Tape Out","topics":["Post layout simulations","Process Voltage Testing","Process Design Kit","Design Rule Check","GDSII Metalorganic CVD (MOCVD)","Plasma Enhanced CVD etc."]},{"title":"Fabrication and Packaging","topics":["CMOS process flow","Dicing","Various types of packaging","Sneh Saurabh, \"Introduction to VLSI Design flow\", Cambridge University Press.","N. H. E. Weste and C. Harris, \"Principles of CMOS VLSI Design: A System Perspective, 3rd Edition, Pearson Education 2007","M. Morris Mano and Michel D. Ciletti, Digital Design with an introduction to HDL, VHDL and Verilog, Sixth edition Pearson education"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Unit 1.0: Control Systems: Basics & Components Introduction to basic terms Classifications and types of Control Systems Block diagrams & Signal flow graphs Transfer function Determination of transfer function using Block diagram reduction techniques and Mason''s Gain formula Control system components: Electrical, Mechanical, Electronic, AC/DC Servo Motors, Stepper Motors, Tacho Generators, Synchros, Magnetic Amplifiers, Servo Amplifiers","Introduction to basic terms","Classifications and types of Control Systems","Block diagrams & Signal flow graphs","Transfer function","Determination of transfer function using Block diagram reduction techniques and Mason''s Gain formula","Control system components: Electrical, Mechanical, Electronic, AC/DC Servo Motors, Stepper Motors, Tacho Generators, Synchros, Magnetic Amplifiers, Servo Amplifiers"]},{"title":"Time-Domain Analysis","topics":["Time domain performance specifications","Transient response of first and second order systems","Steady state errors and Static error constants in unity feedback control systems","Response with P, PI and PID controllers","Limitations of time domain analysis"]},{"title":"Frequency Domain Analysis","topics":["Polar and inverse polar plots","Frequency domain specifications and Performance of LTI systems","Logarithmic plots (Bode plots)","Gain and Phase Margins","Relative stability","Correlation with time domain performance","Closed loop frequency responses from Open loop response","Limitations of frequency domain analysis","Minimum/Non-minimum phase systems"]},{"title":"Stability and Compensation Techniques","topics":["Concepts, absolute, Asymptotic, Conditional and Marginal stability","Routh-Hurwitz and Nyquist stability criterion"]},{"title":"Root locus technique and its application","topics":["Concepts of compensation, series/parallel/series-parallel/feedback compensation","Lag/Lead/Lag-Lead networks for compensation","Compensation using P, PI, PID controllers","Unit 6.0: Control System Analysis using State Variable Methods State variable representation Conversion of state variable models to transfer functions Conversion of transfer functions to state variable models Solution of state equations Concepts of Controllability and Observability Stability of linear systems Equivalence between transfer function and state variable representations State variable analysis of digital control system Digital control design using state feedback","State variable representation","Conversion of state variable models to transfer functions","Conversion of transfer functions to state variable models","Solution of state equations","Concepts of Controllability and Observability Stability of linear systems","Equivalence between transfer function and state variable representations","State variable analysis of digital control system","Digital control design using state feedback","\"Automatic Control System\", B. C. Kuo, Prentice Hall of India, 7th edition, 2001","\"Control Systems Engineering - Principles and Design\", Nagraath and Gopal New Age Publishers","\"Control systems engineering\", Norman S. Nise, John Wiley and Sons (Asia) Singapore","\"Design of Feedback Control System\", Raymond T. Stefani, Oxford University Press","\"Modern control engineering\", K. Ogata, Pearson, 2002."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Study of sampling theorem, effect of undersampling","Study of Quantization of Continuous-Amplitude, Discrete-Time Analog Signals","Study of Different Types of Companding Techniques","Study of properties of Linear Time-Invariant System","Study of convolution Series and Parallel System","Study of Discrete Fourier Transform (DFT) and its inverse","Study of Transform domain properties and its use","Study of FIR filter design using window method: Lowpass and highpass filter","Study of FIR filter design using window method: Bandpass and Bandstop filter","Study of Infinite Impulse Response (IIR) filter"]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Write a program using 8085 Microprocessor for Decimal, Hexadecimal addition and subtraction of two Numbers.","Write a program using 8085 Microprocessor for addition and subtraction of two BCD numbers.","To perform multiplication and division of two 8 bit numbers using 8085.","To find the largest and smallest number in an array of data using 8085 instruction set.","To write a program to arrange an array of data in ascending and descending order.","To convert given Hexadecimal number into its equivalent ASCII number and vice versa using 8085 instruction set.","To write a program to initiate 8251 and to check the transmission and reception of character.","To interface 8253 programmable interval timer to 8085 and verify the operation of 8253 in six different modes.","To interface DAC with 8085 to demonstrate the generation of square, saw tooth and triangular wave.","Serial communication between two 8085 through RS-232 C port."]}]'::jsonb from s;
insert into public.syllabus_versions (syllabus_id,version,units) select id,1,'[{"title":"Unit","topics":["Measurement of parameters of Op-Amp. Voltage Follower, Inverting and Non Inverting Amplifiers, Level Translators using Op-Amp.","Arithmetic Circuits: Summer, Integrator Differentiator Op-Amp.","Active filters: LP, HP and BP using Op-Amp.","Op-Amp Oscillators: Astable, Monostable.","Triangle and Square wave Generators. Schmitt Trigger using Op-Amp.","Voltage Controlled Oscillator Using LM 566.","IC Regulators and current boosting.","Applications of 555 Timer.","Measurement of propagation delay, fan-out, Noise margin and transfer Characteristics of TTL and CMOS IC gates and open collector / drain gates.","Designing code converters using logic gates and standard code converters. Parity generator and checker circuit.","Flip-Flop conversions and latches using gates and ICs.","Designing Synchronous, Asynchronous up/down counters","Shift registers and ring counters using IC Flip-Flops & Standards IC counters.","Full adders, subtractors using logic gates and multiple bits IC Adder/Subtractor and arithmetic Circuits.","Mux - Demux applications.","Interfacing counters with 7-segment LED/LCD display units."]}]'::jsonb from s;
